    /** A Prize effect and its reactions finish before the remaining parent awards or attack text resume. */
    private final class PrizeEffectFrame {
        final List<PrizeClaim> claims=List.copyOf(prizeClaims);
        final List<PrizeWindow> windows=List.copyOf(prizeWindows);
        final List<UUID> promotions=List.copyOf(replacements);
        final List<QueuedAbility> triggers=List.copyOf(triggeredAbilities);
        final Set<Knockout> damage=Set.copyOf(pendingEffectKnockouts),direct=Set.copyOf(pendingDirectKnockouts);
        final AttackCheckpoint attack=attackCheckpoint;
        final EffectPrizeResume effect=effectPrizeResume;
        final boolean attackEnd=endingResumableAttack,cardEnd=endingResumableCardTurn,promotionEnd=endingPromotionTurn,
            end=turnEndInProgress,start=turnStartInProgress,checkup=resolvingCheckup,continueTurn=resumeCurrentTurnAfterReplacement,
            defer=deferEmptyActiveSettlement;
        final UUID cardEndId=endTurnAfterCardResolution;
    }
    private final java.util.Deque<PrizeEffectFrame> prizeEffectFrames=new java.util.ArrayDeque<>();
    private boolean startingPrizeEffect;
    private void resolvePrizeEffect(Runnable effect) {
        requirePhase(MatchPhase.PRIZE_SELECTION);
        require(pendingResolution==null&&knockoutCheckpoint==null&&!advancingResolution,"奖赏效果不能覆盖正在进行的结算");
        prizeEffectFrames.addFirst(new PrizeEffectFrame());
        prizeClaims.clear();prizeWindows.clear();replacements.clear();triggeredAbilities.clear();
        pendingEffectKnockouts.clear();pendingDirectKnockouts.clear();attackCheckpoint=null;effectPrizeResume=null;
        endingResumableAttack=false;endingResumableCardTurn=false;endingPromotionTurn=false;
        turnEndInProgress=false;turnStartInProgress=false;resolvingCheckup=false;resumeCurrentTurnAfterReplacement=true;
        deferEmptyActiveSettlement=true;endTurnAfterCardResolution=null;phase=MatchPhase.TURN;
        startingPrizeEffect=true;
        try {resolveEffectProgram(effect);} finally {startingPrizeEffect=false;}
        drainTriggeredAbilities();
    }
    private void resumePrizeEffect() {
        var frame=prizeEffectFrames.removeFirst();
        prizeClaims.addAll(frame.claims);prizeWindows.addAll(frame.windows);replacements.addAll(frame.promotions);
        triggeredAbilities.addAll(frame.triggers);pendingEffectKnockouts.addAll(frame.damage);pendingDirectKnockouts.addAll(frame.direct);
        attackCheckpoint=frame.attack;effectPrizeResume=frame.effect;endingResumableAttack=frame.attackEnd;
        endingResumableCardTurn=frame.cardEnd;endingPromotionTurn=frame.promotionEnd;
        turnEndInProgress=frame.end;turnStartInProgress=frame.start;resolvingCheckup=frame.checkup;
        resumeCurrentTurnAfterReplacement=frame.continueTurn;deferEmptyActiveSettlement=frame.defer;
        endTurnAfterCardResolution=frame.cardEndId;phase=MatchPhase.PRIZE_SELECTION;preparePrizeClaims();
    }
