    private HistorySource historySource(EffectOrigin origin){
        if(origin==null||origin.kind()==EffectOrigin.Kind.RULE)return null;
        String card=null;
        if(origin.kind()==EffectOrigin.Kind.ATTACK||origin.kind()==EffectOrigin.Kind.ABILITY){
            try{card=battlefield.topCard(origin.controller(),origin.sourceId()).definitionId();}catch(IllegalArgumentException|IllegalStateException absent){return null;}
        }else card=historyInstances.get(origin.sourceId());
        return card==null?null:new HistorySource(origin.controller(),card);
    }
    private void rememberHistoryKnockouts(List<Knockout> knocked,HistorySource source){
        if(source==null)return;
        for(var ko:knocked)if(!ko.owner().equals(source.owner()))historyKoSources.putIfAbsent(ko,source);
    }
    private KnockoutCheckpoint knockoutCheckpoint;
    private boolean knockoutTopToHandAllowed(UUID owner,UUID pokemonId,long entry,EffectEventBindings event) {
        return knockoutCardsToHandAllowed(owner,pokemonId,entry,event,true);
    }
    private boolean knockoutCardsToHandAllowed(UUID owner,UUID pokemonId,long entry,EffectEventBindings event,boolean opponentOnly) {
        var checkpoint=knockoutCheckpoint;
        var subject=new EffectTargetResolution.PokemonTarget(owner,pokemonId);
        var knockout=new Knockout(owner,pokemonId);
        return checkpoint!=null&&checkpoint.confirmed.contains(knockout)
            &&checkpoint.attackDamage.contains(knockout)&&checkpoint.attacker!=null
            &&(!opponentOnly||!checkpoint.attacker.owner().equals(owner))
            &&event!=null&&subject.equals(event.triggerPokemon())&&event.triggerEntrySequence()==entry
            &&checkpoint.attacker.equals(event.attackingPokemon())
            &&checkpoint.attackerEntrySequence==event.attackerEntrySequence()
            &&(event.sourcePokemon()==null||subject.equals(event.sourcePokemon())&&event.sourceEntrySequence()==entry)
            &&sameFieldEntry(owner,pokemonId,entry);
    }
