    private long deckDiscardMovement;
    private long handDiscardMovement;
    /** Exists only while a genuine deck-discard reaction holds a completed non-attack effect's KO checkpoint. */
    private boolean deckDiscardCheckpointPending;
    private final Set<Knockout> deckDiscardDeferredKnockouts=new LinkedHashSet<>(),deckDiscardDeferredDirectKnockouts=new LinkedHashSet<>();
    private boolean hasDeckDiscardReaction() {
        return triggeredAbilities.stream().anyMatch(e->e.deckDiscardSource()!=null)
            || pendingResolution!=null&&pendingResolution.triggered()!=null&&pendingResolution.triggered().deckDiscardSource()!=null;
    }
    private boolean hasHandDiscardReaction() {
        return triggeredAbilities.stream().anyMatch(e->e.handDiscardSource()!=null)
            || pendingResolution!=null&&pendingResolution.triggered()!=null&&pendingResolution.triggered().handDiscardSource()!=null;
    }
    private boolean hasDiscardReaction() {return hasDeckDiscardReaction()||hasHandDiscardReaction();}
    private boolean deckDiscardCheckpointHeld() {return deckDiscardCheckpointPending||hasDiscardReaction();}
    /** Keep existing damage/KO reactions first, then this one narrow event before KO commitment and ordinary events. */
    private void prioritizeDeckDiscardReactions() {
        if(triggeredAbilities.isEmpty())return;
        var first=triggeredAbilities.getFirst();var trigger=first.ability().eventPolicy().trigger();
        if(first.deckDiscardSource()!=null||first.handDiscardSource()!=null
            ||trigger==EffectTrigger.ON_DAMAGE||trigger==EffectTrigger.ON_KNOCKOUT)return;
        var entry=triggeredAbilities.stream().filter(e->e.deckDiscardSource()!=null||e.handDiscardSource()!=null).findFirst().orElse(null);
        if(entry==null)return;
        var batch=triggeredAbilities.stream().filter(e->(e.deckDiscardSource()!=null||e.handDiscardSource()!=null)
            &&e.batch()==entry.batch()).toList();
        triggeredAbilities.removeAll(batch);triggeredAbilities.addAll(0,batch);
    }
    private void resumeDeckDiscardCheckpoint() {
        require(deckDiscardCheckpointPending&&!hasDiscardReaction(),"弃牌反应尚未完成");
        deckDiscardCheckpointPending=false;
        pendingEffectKnockouts.addAll(deckDiscardDeferredKnockouts);pendingDirectKnockouts.addAll(deckDiscardDeferredDirectKnockouts);
        deckDiscardDeferredKnockouts.clear();deckDiscardDeferredDirectKnockouts.clear();
        try {finishEffectCheckpoint();}finally {clearEffectCheckpoint();}
    }
    private EffectOrigin effectOrigin(UUID executor) {
        if (resolvingOrigin != null) return resolvingOrigin;
        if (pendingResolution != null && advancingResolution) {
            var pending=pendingResolution;
            if(pending.triggered()!=null)return pending.triggered().origin();
            if (pending.attack() != null) return new EffectOrigin(EffectOrigin.Kind.ATTACK,pending.actor(),pending.attack().pokemonId());
            return pending.ability() == null
                ? new EffectOrigin(EffectOrigin.Kind.TRAINER,pending.actor(),pending.card().instanceId())
                : new EffectOrigin(EffectOrigin.Kind.ABILITY,pending.actor(),pending.ability().pokemonId());
        }
        return EffectOrigin.rule(executor);
    }
    private void withOrigin(EffectOrigin origin, Runnable action) {
        var previous=resolvingOrigin;resolvingOrigin=origin;
        try { action.run(); } finally { resolvingOrigin=previous; }
    }
    private boolean matchesAttackSource(dev.hua.ptcglive.engine.effect.AttackSourceFilter filter, EffectOrigin origin) {
        return matchesAttackSource(filter,origin,false);
    }
    private boolean matchesAttackSource(dev.hua.ptcglive.engine.effect.AttackSourceFilter filter, EffectOrigin origin,boolean damage) {
        if(origin.kind()!=EffectOrigin.Kind.ATTACK)return false;
        if(damage&&attackCheckpoint!=null&&attackCheckpoint.damageSource!=null
            &&attackCheckpoint.attacker.owner().equals(origin.controller())&&attackCheckpoint.attacker.pokemonId().equals(origin.sourceId()))
            return filter.matches(attackCheckpoint.damageSource.facts());
        var views=new ArrayList<>(battlefield.printedBenchView(origin.controller()));
        if(battlefield.hasActive(origin.controller()))views.add(battlefield.printedActiveView(origin.controller()));
        var source=views.stream().filter(v->v.pokemonId().equals(origin.sourceId())).findFirst().orElse(null);
        if(source==null)return false;
        var profile=battlefield.pokemonProfile(origin.controller(),source.pokemonId());
        boolean special=battlefield.attachedEnergy(origin.controller(),source.pokemonId()).stream().anyMatch(c->!definition(c).basicEnergy());
        if(!filter.dynamicRestricted())return filter.matches(currentFieldDefinition(origin.controller(),source.pokemonId()),profile.pokemonName(),special,profile);
        return filter.matches(new dev.hua.ptcglive.engine.effect.AttackSourceFilter.Facts(currentFieldDefinition(origin.controller(),source.pokemonId()),profile.pokemonName(),special,profile,
            currentEnergyUnits(origin.controller(),source.pokemonId()),Set.copyOf(source.conditions()),hasPossessedAbilities(origin.controller(),source.pokemonId()),
            battlefield.pokemonView(origin.controller(),source.pokemonId()).hitPoints()-source.damage()));
    }
    private boolean preventsImpact(UUID owner,UUID pokemon,EffectOrigin origin,EffectProtection.Impact impact) {
        if(origin.kind()==EffectOrigin.Kind.ABILITY&&!origin.controller().equals(owner)&&abilityGuardTool(owner,pokemon))return true;
        if(battlefield.preventsImpact(owner,pokemon,origin,impact,filter->matchesAttackSource(filter,origin,impact==EffectProtection.Impact.DAMAGE)))return true;
        if(stadiumPreventsBenchImpact(owner,pokemon,origin,impact))return true;
        if(impact==EffectProtection.Impact.DAMAGE&&origin.kind()==EffectOrigin.Kind.ATTACK
            &&origin.controller().equals(owner)&&Objects.equals(origin.sourceId(),pokemon)
            &&hasToolPassiveRule(owner,pokemon,"prevent_self_attack_damage"))return true;
        if(!Set.of(EffectOrigin.Kind.ATTACK,EffectOrigin.Kind.ABILITY,EffectOrigin.Kind.TRAINER).contains(origin.kind()))return false;
        if(attachedEnergyRule(owner,pokemon,e->e.type().equals("passive_effect_guard")
            &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.protection(e).blocks(origin,owner,impact,filter->matchesAttackSource(filter,origin,impact==EffectProtection.Impact.DAMAGE))))return true;
        if(origin.kind()==EffectOrigin.Kind.ATTACK&&!toolEffectsDisabled(owner,pokemon)) {
            for(var tool:battlefield.printedPokemonView(owner,pokemon).attachedTools()) {
                var profile=combat.trainer(tool.definitionId()).orElse(null);
                if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                    new ServerConditionContext(owner,pokemon),e->dev.hua.ptcglive.engine.effect.PassiveRuleProgram.plasmaMirrorGuard(e)
                        &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.protection(e).blocks(origin,owner,impact,
                            filter->matchesAttackSource(filter,origin,impact==EffectProtection.Impact.DAMAGE))))return true;
            }
        }
        if(origin.kind()==EffectOrigin.Kind.ATTACK&&impact==EffectProtection.Impact.OTHER_EFFECTS
            &&!origin.controller().equals(owner)&&battlefield.hasActive(owner)) {
            UUID host=battlefield.printedActiveView(owner).pokemonId();
            if(!toolEffectsDisabled(owner,host))for(var tool:battlefield.printedPokemonView(owner,host).attachedTools()) {
                var profile=combat.trainer(tool.definitionId()).orElse(null);
                if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                    new ServerConditionContext(owner,host),dev.hua.ptcglive.engine.effect.PassiveRuleProgram::activeToolFieldAttackGuard))return true;
            }
        }
        if(origin.kind()==EffectOrigin.Kind.ATTACK&&impact==EffectProtection.Impact.OTHER_EFFECTS&&!toolEffectsDisabled(owner,pokemon)) {
            for(var tool:battlefield.printedPokemonView(owner,pokemon).attachedTools()) {
                var profile=combat.trainer(tool.definitionId()).orElse(null);
                if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                    new ServerConditionContext(owner,pokemon),e->dev.hua.ptcglive.engine.effect.PassiveRuleProgram.selfAttackEffectsGuard(e)
                        &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.protection(e).blocks(origin,owner,impact)))return true;
            }
        }
        if(impact==EffectProtection.Impact.OTHER_EFFECTS&&handPlayedSupporter(origin)&&!toolEffectsDisabled(owner,pokemon)) {
            for(var tool:battlefield.printedPokemonView(owner,pokemon).attachedTools()) {
                    var profile=combat.trainer(tool.definitionId()).orElse(null);
                    if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                        new ServerConditionContext(owner,pokemon),e->dev.hua.ptcglive.engine.effect.PassiveRuleProgram.selfSupporterEffectsGuard(e)
                            &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.protection(e).blocks(origin,owner,impact)))return true;
                }
        }
        for(var host:publicFieldTargets(owner))for(var ability:battlefield.pokemonProfile(owner,host.pokemonId()).abilities())
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.containsGuard(ability.effectProgram())
                &&activeAbilities(owner,host.pokemonId()).contains(ability)
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(owner,pokemon),
                    e->e.type().equals("passive_effect_guard")&&(e.target()==EffectTarget.ALL_OWN_POKEMON
                        ||e.target()==EffectTarget.OWN_BENCH&&(!battlefield.hasActive(owner)||!battlefield.printedActiveView(owner).pokemonId().equals(pokemon))
                        ||e.target()==EffectTarget.SELF&&host.pokemonId().equals(pokemon))
                        &&(!"true".equals(e.arguments().get("source_active_only"))
                            ||battlefield.hasActive(owner)&&battlefield.printedActiveView(owner).pokemonId().equals(host.pokemonId()))
                        &&trainerProtectionMatches(e,origin)
                        &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.protection(e).blocks(origin,owner,impact,filter->matchesAttackSource(filter,origin,impact==EffectProtection.Impact.DAMAGE))))return true;
        return false;
    }
    private boolean handPlayedSupporter(EffectOrigin origin) {
        return handPlayedTrainer(origin,Set.of(dev.hua.ptcglive.rules.TrainerCategory.SUPPORTER));
    }
    private boolean stadiumProtectedFrom(EffectOrigin origin) {
        return stadiumHasPassiveRule("prevent_item_supporter_effects")&&handPlayedTrainer(origin,
            Set.of(dev.hua.ptcglive.rules.TrainerCategory.ITEM,dev.hua.ptcglive.rules.TrainerCategory.SUPPORTER));
    }
    private boolean handPlayedTrainer(EffectOrigin origin,Set<dev.hua.ptcglive.rules.TrainerCategory> categories) {
        if(origin.kind()!=EffectOrigin.Kind.TRAINER)return false;
        if(categories.contains(dev.hua.ptcglive.rules.TrainerCategory.SUPPORTER)&&rememberedGxSupporter(origin))return true;
        var pending=pendingResolution;
        if(pending!=null)return pending.consumesHandCard()
            &&categories.contains(pending.category())
            &&pending.actor().equals(origin.controller())&&pending.card()!=null
            &&pending.card().instanceId().equals(origin.sourceId());
        var legacy=resolvingHandTrainer;
        return legacy!=null&&legacy.instanceId().equals(origin.sourceId())
            &&legacy.ownerId().equals(origin.controller())
            &&categories.contains(definition(legacy).trainerCategory());
    }
    private boolean rememberedGxSupporter(EffectOrigin origin) {
        return players.values().stream().flatMap(p->p.gxPermissions.stream())
            .anyMatch(p->p.turn()==turnNumber&&p.handPlayedSupporter()&&p.origin().equals(origin));
    }
    private boolean trainerProtectionMatches(EffectDefinition effect,EffectOrigin origin) {
        if(!"TRAINER".equals(effect.arguments().get("source")))return true;
        if(origin.kind()!=EffectOrigin.Kind.TRAINER)return false;
        String category;
        if(stadium!=null&&stadium.instanceId().equals(origin.sourceId()))category=dev.hua.ptcglive.rules.TrainerCategory.STADIUM.name();
        else if(rememberedGxSupporter(origin))category=dev.hua.ptcglive.rules.TrainerCategory.SUPPORTER.name();
        else {
            if(pendingResolution==null||pendingResolution.card()==null||!pendingResolution.card().instanceId().equals(origin.sourceId()))return false;
            category=definitions.find(pendingResolution.card().definitionId()).orElseThrow().trainerCategory().name();
        }
        return java.util.Arrays.asList(effect.arguments().getOrDefault("trainer_categories","").split("\\|",-1)).contains(category);
    }
    private boolean activePokemonLocksTrainer(UUID owner,CardDefinition trainer) {
        if(!battlefield.hasActive(owner))return false;
        var active=battlefield.printedActiveView(owner);
        for(var ability:activeAbilities(owner,active.pokemonId()))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(owner,active.pokemonId()),effect->{
                    if(!effect.type().equals("passive_trainer_play_lock"))return false;
                    if("true".equals(effect.arguments().get("source_active_only"))
                        &&!battlefield.printedActiveView(owner).pokemonId().equals(active.pokemonId()))return false;
                    var categories=Set.of(effect.arguments().get("trainer_categories").split("\\|",-1));
                    return categories.contains(trainer.trainerCategory().name())
                        ||categories.contains("ACE_SPEC")&&trainer.specialDeckLimits().containsKey("ACE SPEC");
                }))return true;
        return false;
    }
    /** Attached Energy guards survive Ability/Tool suppression and disappear under an Energy override. */
    private boolean attachedEnergyRule(UUID owner,UUID pokemon,java.util.function.Predicate<EffectDefinition> rule) {
        for(var card:battlefield.attachedEnergy(owner,pokemon))
            if(dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(effectiveEnergyCard(owner,card).passiveProgram(),new ServerConditionContext(owner,pokemon),rule))return true;
        return false;
    }
    private boolean energyPreventsCondition(UUID owner,UUID pokemon,SpecialCondition condition) {
        var host=battlefield.printedPokemonView(owner,pokemon);
        for(var card:battlefield.attachedEnergy(owner,pokemon)) {
            var energy=effectiveEnergyCard(owner,card);var rule=energy.attachmentRule();
            if(rule.discardIfInvalid()&&!rule.allows(currentFieldDefinition(owner,host.pokemonId()),combat.fieldPokemon(host.topCardId()).orElseThrow()))continue;
            if(dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(energy.passiveProgram(),new ServerConditionContext(owner,pokemon),
                e->e.type().equals("special_condition_immunity")&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.immuneConditions(e).contains(condition)))return true;
        }
        return false;
    }
    /** Continuous cure from every enabled source, including attachments and removal of suppression. */
    private void settleEnergyConditionImmunity() {
        for(UUID owner:players.keySet())if(battlefield.hasActive(owner)) {
            var active=battlefield.printedActiveView(owner);
            var cured=active.conditions().stream().filter(c->passivelyPreventsSpecialConditions(owner,c)).collect(java.util.stream.Collectors.toSet());
            if(!cured.isEmpty()) {
                battlefield.clearSpecialConditions(owner,active.pokemonId(),cured);
                recordReplay(owner,"持续效果解除异常状态："+cured);
            }
        }
    }
    private boolean restoredPokemon(CardInstance card) {
        return definition(card).category()==CardCategory.POKEMON&&combat.pokemon(card.definitionId())
            .map(p->p.printedRules()==dev.hua.ptcglive.engine.field.PokemonPrintedRules.RESTORED).orElse(false);
    }
    private List<CardInstance> restoredHandCandidates(UUID owner) {
        return state(owner).hand.stream().filter(this::restoredPokemon)
            .filter(c->definition(c).effectSupport()==EffectSupport.SUPPORTED).toList();
    }
    private boolean removesWeakness(UUID owner,UUID pokemon) {
        if(attachedEnergyRule(owner,pokemon,e->e.type().equals("no_weakness")))return true;
        if(stadium!=null) {
            var profile=combat.trainer(stadium.definitionId()).orElse(null);
            if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                hostConditionContext(stadiumController,owner,pokemon),e->e.type().equals("no_weakness")
                    &&(e.target()==EffectTarget.ALL_OWN_POKEMON&&stadiumController.equals(owner)
                        ||e.target()==EffectTarget.ALL_OPPONENT_POKEMON&&!stadiumController.equals(owner))))return true;
        }
        if(!toolEffectsDisabled(owner,pokemon))for(var tool:battlefield.printedPokemonView(owner,pokemon).attachedTools()) {
            var profile=combat.trainer(tool.definitionId()).orElse(null);
            if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                new ServerConditionContext(owner,pokemon),e->e.type().equals("no_weakness")&&e.target()==EffectTarget.SELF))return true;
        }
        for(UUID controller:players.keySet())for(var host:publicFieldTargets(controller))for(var ability:activeAbilities(controller,host.pokemonId()))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),hostConditionContext(controller,owner,pokemon),
                    e->e.type().equals("no_weakness")&&(!e.arguments().containsKey("restored_only")||restoredPokemon(battlefield.topCard(owner,pokemon)))&&(e.target()==EffectTarget.SELF&&controller.equals(owner)&&host.pokemonId().equals(pokemon)
                        ||e.target()==EffectTarget.ALL_OWN_POKEMON&&controller.equals(owner)
                        ||e.target()==EffectTarget.ALL_OPPONENT_POKEMON&&!controller.equals(owner))))return true;
        return false;
    }
    private boolean stadiumHasPassiveRule(String type) {return stadiumPassiveRule(type)!=null;}
    private int checkupPoisonBonus(UUID owner) {
        if(!battlefield.hasActive(owner))return 0;
        UUID active=battlefield.printedActiveView(owner).pokemonId();
        int bonus=0;
        if(stadium!=null&&stadiumController!=null) {
            EffectTarget scope=stadiumController.equals(owner)?EffectTarget.ALL_OWN_POKEMON:EffectTarget.ALL_OPPONENT_POKEMON;
            var program=combat.trainer(stadium.definitionId()).orElseThrow().ongoingProgram();
            if(dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(program,new ServerConditionContext(owner,active),
                effect->effect.type().equals("checkup_poison_bonus")&&effect.target()==scope
                    &&(!"DARKNESS".equals(effect.arguments().get("excluded_type"))||!currentPokemonTypes(owner,active).contains(EnergyType.DARKNESS))))bonus+=2;
        }
        UUID opponent=other(owner).id;
        if(battlefield.hasActive(opponent)) {
            UUID source=battlefield.printedActiveView(opponent).pokemonId();
            for(var ability:activeAbilities(opponent,source))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(opponent,source),
                    effect->effect.type().equals("checkup_poison_bonus")&&effect.target()==EffectTarget.ALL_OPPONENT_POKEMON
                        &&"true".equals(effect.arguments().get("source_active_only")))) {
                bonus+=5;break;
            }
        }
        return bonus;
    }
    private boolean activeAdditionalOrder(UUID owner) {
        if(!battlefield.hasActive(owner))return false;
        UUID active=battlefield.printedActiveView(owner).pokemonId();
        return activeAbilities(owner,active).stream().anyMatch(ability->ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
            &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(owner,active),
                effect->effect.type().equals("cafe_master_turn_continues")));
    }
    private int sleepRecoveryCoins(UUID owner) {
        if(!battlefield.hasActive(owner))return 1;
        if(stadiumHasPassiveRule("sleep_recovery_two_coins"))return 2;
        UUID active=battlefield.printedActiveView(owner).pokemonId();
        if(battlefield.printedActiveView(owner).conditions().contains(SpecialCondition.ASLEEP)
            &&twoCoinSleepEntries.getOrDefault(owner,0L)==battlefield.pokemonEntrySequence(owner,active))return 2;
        for(var ability:activeAbilities(owner,active))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
            &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(owner,active),
                effect->effect.type().equals("sleep_recovery_two_coins")&&effect.target()==EffectTarget.SELF))return 2;
        return 1;
    }
    private EffectDefinition stadiumPassiveRule(String type) {
        if(stadium==null)return null;
        for(var binding:combat.trainer(stadium.definitionId()).orElseThrow().ongoingProgram().triggers())
            if(binding.trigger()==EffectTrigger.PASSIVE)
                for(var effect:binding.effects()) {
                    var found=findEffectType(effect,type);if(found!=null)return found;
                }
        return null;
    }
    private static EffectDefinition findEffectType(EffectDefinition effect,String type) {
        if(effect.type().equals(type))return effect;
        for(var child:effect.effects()) {var found=findEffectType(child,type);if(found!=null)return found;}
        return null;
    }
    private static boolean programHasRule(EffectProgram program,String type) {
        return program.triggers().stream().flatMap(binding->binding.effects().stream()).anyMatch(effect->effectHasRule(effect,type));
    }
    private static boolean effectHasRule(EffectDefinition effect,String type) {
        return effect.type().equals(type)||effect.effects().stream().anyMatch(child->effectHasRule(child,type));
    }
    private boolean stadiumPreventsAttackDamage(UUID owner,UUID pokemon,EffectOrigin origin) {
        var rule=stadiumPassiveRule("stadium_attack_guard");
        if(rule==null||rule.arguments().containsKey("bench_only")||origin.kind()!=EffectOrigin.Kind.ATTACK||origin.controller().equals(owner)
            ||attackCheckpoint==null||attackCheckpoint.damageSource==null)return false;
        var recipient=fieldCardDefinition(battlefield.printedPokemonView(owner,pokemon).topCardId());
        if(recipient.pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.RULE_BOX))return false;
        var attacker=attackCheckpoint.damageSource.facts().card().pokemonFamilies();
        return attacker.contains(dev.hua.ptcglive.rules.PokemonFamily.EX)
            ||attacker.contains(dev.hua.ptcglive.rules.PokemonFamily.V);
    }
    private boolean stadiumPreventsBenchImpact(UUID owner,UUID pokemon,EffectOrigin origin,EffectProtection.Impact impact) {
        var rule=stadiumPassiveRule("stadium_attack_guard");
        if(rule==null||!rule.arguments().containsKey("bench_only")||origin.kind()!=EffectOrigin.Kind.ATTACK
            ||battlefield.hasActive(owner)&&battlefield.printedActiveView(owner).pokemonId().equals(pokemon))return false;
        return ("ANY".equals(rule.arguments().get("from"))||!origin.controller().equals(owner))
            &&(impact==EffectProtection.Impact.DAMAGE||"DAMAGE_AND_EFFECTS".equals(rule.arguments().get("scope")));
    }
    private boolean unrecoverableFromDiscard(UUID recoveringPlayer,CardInstance card) {
        return unrecoverableFromDiscard(recoveringPlayer,card,effectOrigin(recoveringPlayer));
    }
    private boolean unrecoverableFromDiscard(UUID recoveringPlayer,CardInstance card,EffectOrigin origin) {
        return unrecoverableFromDiscard(recoveringPlayer,card,CardEffectDestination.HAND,origin);
    }
    private boolean unrecoverableFromDiscard(UUID recoveringPlayer,CardInstance card,CardEffectDestination destination,EffectOrigin origin) {
        if(discardCardReturnForbidden(card))return true;
        if(!origin.controller().equals(recoveringPlayer)||!Set.of(EffectOrigin.Kind.ABILITY,EffectOrigin.Kind.TRAINER).contains(origin.kind()))return false;
        var sourceId=historyInstances.get(origin.sourceId());var sourceCard=sourceId==null?null:definitions.find(sourceId).orElse(null);
        boolean itemOrSupporter=origin.kind()==EffectOrigin.Kind.TRAINER&&sourceCard!=null
            &&(ruleset.trainerClassification().matches(sourceCard,dev.hua.ptcglive.rules.TrainerCategory.ITEM)
                ||ruleset.trainerClassification().matches(sourceCard,dev.hua.ptcglive.rules.TrainerCategory.SUPPORTER));
        UUID opponent=other(recoveringPlayer).id;
        for(var host:publicFieldTargets(opponent))for(var ability:activeAbilities(opponent,host.pokemonId()))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()&&ability.effectSupport()==EffectSupport.SUPPORTED
                &&ability.effectProgram().triggers().stream().flatMap(binding->binding.effects().stream())
                    .anyMatch(effect->dev.hua.ptcglive.engine.effect.DiscardRecoveryRule.blocks(effect,destination,definition(card).category(),itemOrSupporter)))return true;
        return false;
    }
    private boolean discardCardReturnForbidden(CardInstance card) {
        return combat.trainer(card.definitionId()).map(profile->programHasRule(profile.effectProgram(),"unrecoverable_from_discard")).orElse(false);
    }
    private boolean deckDiscardPrevented(UUID owner,DeckDiscardCause cause) {
        if(cause==null||cause.controller().equals(owner)||!battlefield.hasActive(owner))return false;
        String source=switch(cause.kind()) {
            case POKEMON_ATTACK -> "ATTACK";
            case POKEMON_ABILITY -> "ABILITY";
            case ITEM -> "ITEM";
            case SUPPORTER -> "SUPPORTER";
        };
        UUID active=battlefield.printedActiveView(owner).pokemonId();
        if(toolEffectsDisabled(owner,active))return false;
        for(var tool:battlefield.printedPokemonView(owner,active).attachedTools()) {
            var profile=combat.trainer(tool.definitionId()).orElse(null);
            if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                new ServerConditionContext(owner,active),effect->effect.type().equals("prevent_deck_discard")
                    &&Set.of(effect.arguments().get("sources").split("\\|",-1)).contains(source)))return true;
        }
        return false;
    }
    private boolean setupActiveAllowed(CardInstance card) {
        return setupActiveAllowed(card.definitionId());
    }
    private boolean setupActiveAllowed(String definitionId) {
        if(definitions.find(definitionId).orElseThrow().basicPokemon())return true;
        return combat.pokemon(definitionId).stream().flatMap(profile->profile.abilities().stream())
            .anyMatch(ability->ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.effectSupport()==EffectSupport.SUPPORTED
                &&programHasRule(ability.effectProgram(),"setup_active_override"));
    }
    private boolean containsEffectType(EffectDefinition effect,String type) {
        return effect.type().equals(type)||effect.effects().stream().anyMatch(child->containsEffectType(child,type));
    }
    private boolean retainConfusionOnEvolution(UUID owner,UUID pokemon) {
        return stadiumHasPassiveRule("retain_confusion_on_evolution")
            &&battlefield.pokemonView(owner,pokemon).conditions().contains(SpecialCondition.CONFUSED);
    }
    private void clearEvolutionConditions(UUID owner,UUID pokemon) {
        var target=new EffectTargetResolution.PokemonTarget(owner,pokemon);
        if(stadiumAbilityImmunity.keySet().stream().anyMatch(candidate->candidate.target().equals(target))) {
            var remaining=new LinkedHashMap<>(stadiumAbilityImmunity);remaining.keySet().removeIf(candidate->candidate.target().equals(target));
            stadiumAbilityImmunity=Map.copyOf(remaining);
        }
        for(var player:players.values()) {
            var active=player.activeAbilitySuppression;
            if(active!=null&&active.unaffected()!=null&&active.unaffected().target().equals(target))
                player.activeAbilitySuppression=new TimedActiveAbilitySuppression(active.turn(),null,null);
            var global=player.globalAbilitySuppression;
            if(global!=null&&global.unaffected().keySet().stream().anyMatch(candidate->candidate.target().equals(target))) {
                var remaining=new LinkedHashMap<>(global.unaffected());remaining.keySet().removeIf(candidate->candidate.target().equals(target));
                player.globalAbilitySuppression=new TimedGlobalAbilitySuppression(global.endingPlayer(),Map.copyOf(remaining));
            }
        }
        var removed=java.util.EnumSet.noneOf(SpecialCondition.class);
        removed.addAll(battlefield.pokemonView(owner,pokemon).conditions());
        removed.removeAll(retainedConditionsOnEvolution(owner,pokemon));
        if(!removed.isEmpty())battlefield.clearSpecialConditions(owner,pokemon,removed);
    }
    private java.util.Set<SpecialCondition> retainedConditionsOnEvolution(UUID owner,UUID pokemon) {
        var retained=java.util.EnumSet.noneOf(SpecialCondition.class);
        if(stadiumHasPassiveRule("retain_conditions_on_evolution")
            &&!preventsImpact(owner,pokemon,new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId()),EffectProtection.Impact.OTHER_EFFECTS))
            retained.addAll(battlefield.pokemonView(owner,pokemon).conditions());
        if(retainConfusionOnEvolution(owner,pokemon))retained.add(SpecialCondition.CONFUSED);
        if(battlefield.pokemonView(owner,pokemon).conditions().contains(SpecialCondition.POISONED)) {
            UUID opponent=other(owner).id;
            for(var host:publicFieldTargets(opponent))for(var ability:activeAbilities(opponent,host.pokemonId()))
                if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()&&ability.effectSupport()==EffectSupport.SUPPORTED
                    &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),hostConditionContext(opponent,owner,pokemon),
                        effect->effect.type().equals("retain_poison_on_evolution")&&effect.target()==EffectTarget.ALL_OPPONENT_POKEMON)) {
                    retained.add(SpecialCondition.POISONED);return retained;
                }
        }
        return retained;
    }
    private boolean preventsDamageCounterPlacement(UUID owner,UUID pokemon,EffectOrigin origin) {
        if(!origin.controller().equals(owner)&&Set.of(EffectOrigin.Kind.ATTACK,EffectOrigin.Kind.ABILITY).contains(origin.kind())
            &&hasToolPassiveRule(owner,pokemon,"prevent_opponent_attack_ability_counters"))return true;
        if(stadiumHasPassiveRule("prevent_bench_damage_counters")
            &&Set.of(EffectOrigin.Kind.ATTACK,EffectOrigin.Kind.ABILITY).contains(origin.kind())
            &&!origin.controller().equals(owner)
            &&battlefield.benchView(owner).stream().anyMatch(view->view.pokemonId().equals(pokemon)))return true;
        if(origin.kind()!=EffectOrigin.Kind.ATTACK||origin.controller().equals(owner)
            ||battlefield.benchView(owner).stream().noneMatch(view->view.pokemonId().equals(pokemon)))return false;
        for(var host:publicFieldTargets(owner))for(var ability:activeAbilities(owner,host.pokemonId()))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()&&ability.effectSupport()==EffectSupport.SUPPORTED
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(owner,host.pokemonId()),
                    effect->effect.type().equals("prevent_bench_damage_counters")&&effect.target()==EffectTarget.OWN_BENCH
                        &&matchesAttackSource(dev.hua.ptcglive.engine.effect.AttackSourceFilter.from(effect.arguments()),origin)))return true;
        return false;
    }
    private void applyBenchEntryStadium(UUID owner,CardInstance card,PokemonChangeTriggerPolicy.Source source) {
        benchEntryStadiumReaction(owner,card,source).run();
    }
    /** Capture the entry-time Stadium and subject; queued reactions cannot adopt a later field. */
    private Runnable benchEntryStadiumReaction(UUID owner,CardInstance card,PokemonChangeTriggerPolicy.Source source) {
        if(turnNumber<=0||stadium==null||stadiumController==null
            ||!definition(card).basicPokemon())return ()->{};
        var rule=stadiumPassiveRule("bench_entry_damage_counters");
        if(rule==null)return ()->{};
        if("DARKNESS".equals(rule.arguments().get("excluded_type"))) {
            if(!owner.equals(currentPlayer)||currentPokemonTypes(owner,card.instanceId()).contains(EnergyType.DARKNESS))return ()->{};
        } else if(source!=PokemonChangeTriggerPolicy.Source.HAND)return ()->{};
        var stadiumOrigin=new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId());
        UUID pokemon=battlefield.printedPokemonView(owner,card.instanceId()).pokemonId(),actor=currentPlayer;
        long entry=battlefield.pokemonEntrySequence(owner,pokemon);
        return ()->{if(sameFieldEntry(owner,pokemon,entry))
            withOrigin(stadiumOrigin,()->placeDamageCountersByEffect(actor,owner,pokemon,2));};
    }
    private EffectDefinition weaknessOverrideAura(UUID owner,UUID pokemon) {
        UUID opponent=other(owner).id;
        for(var host:publicFieldTargets(opponent))for(var ability:activeAbilities(opponent,host.pokemonId())) {
            if(ability.kind()!=AbilityDefinition.Kind.PASSIVE||!ability.composed()||ability.effectSupport()!=EffectSupport.SUPPORTED)continue;
            if(preventsImpact(owner,pokemon,new EffectOrigin(EffectOrigin.Kind.ABILITY,opponent,host.pokemonId()),EffectProtection.Impact.OTHER_EFFECTS))continue;
            var context=new ServerConditionContext(opponent,host.pokemonId());
            for(var binding:ability.effectProgram().forTrigger(EffectTrigger.PASSIVE))for(var effect:binding.effects())
                if(effect.type().equals("weakness_override_aura")
                    &&currentPokemonTypes(owner,pokemon).contains(EnergyType.valueOf(effect.arguments().get("pokemon_type")))
                    &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),context,candidate->candidate==effect))return effect;
        }
        return null;
    }
    private boolean starCipherAbilityAffects(UUID owner,UUID pokemon) {
        UUID opponent=other(owner).id;
        for(var host:publicFieldTargets(opponent)) {
            if(preventsImpact(owner,pokemon,new EffectOrigin(EffectOrigin.Kind.ABILITY,opponent,host.pokemonId()),EffectProtection.Impact.OTHER_EFFECTS))continue;
            if(activeAbilities(opponent,host.pokemonId()).stream().anyMatch(ability->ability.kind()==AbilityDefinition.Kind.PASSIVE
                &&ability.effectSupport()==EffectSupport.SUPPORTED
                &&ability.effect().opcode()==AbilityEffect.Opcode.PASSIVE_STAR_CIPHER))return true;
        }
        return false;
    }
    private EnergyType currentWeaknessType(UUID owner,UUID pokemon) {
        if(starCipherAbilityAffects(owner,pokemon))return EnergyType.PSYCHIC;
        var aura=weaknessOverrideAura(owner,pokemon);
        return aura==null?battlefield.effectiveWeaknessType(owner,pokemon):EnergyType.valueOf(aura.arguments().get("weakness_type"));
    }
    private int currentWeaknessBaseMultiplier(UUID owner,UUID pokemon) {
        var aura=weaknessOverrideAura(owner,pokemon);
        int amount=aura==null?battlefield.effectiveWeaknessMultiplier(owner,pokemon):Integer.parseInt(aura.arguments().get("multiplier"));
        // A changed Weakness gives a Pokémon with no printed Weakness the standard ×2 amount.
        return starCipherAbilityAffects(owner,pokemon)&&amount==0?2:amount;
    }
    /** Query only live Ability sources; neither rule leaves a mark when its source/partner leaves. */
    private boolean activePokemonPassiveRule(UUID owner,UUID pokemon,String type) {
        if(!battlefield.hasActive(owner)||!battlefield.printedActiveView(owner).pokemonId().equals(pokemon))return false;
        for(UUID controller:players.keySet())for(var host:publicFieldTargets(controller)) {
            var origin=new EffectOrigin(EffectOrigin.Kind.ABILITY,controller,host.pokemonId());
            if(preventsImpact(owner,pokemon,origin,EffectProtection.Impact.OTHER_EFFECTS))continue;
            EffectTarget scope=controller.equals(owner)?EffectTarget.OWN_ACTIVE:EffectTarget.OPPONENT_ACTIVE;
            for(var ability:activeAbilities(controller,host.pokemonId()))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(controller,host.pokemonId()),
                    e->e.type().equals(type)&&e.target()==scope))return true;
        }
        return false;
    }
    boolean canAttackWhileAsleepOrParalyzed(UUID owner,UUID pokemon) {
        return hasToolPassiveRule(owner,pokemon,"attack_while_asleep_or_paralyzed");
    }
    private boolean attackSpecialConditionsAllow(UUID owner,UUID pokemon) {
        var conditions=battlefield.pokemonView(owner,pokemon).conditions();
        return !conditions.contains(SpecialCondition.ASLEEP)&&!conditions.contains(SpecialCondition.PARALYZED)
            ||canAttackWhileAsleepOrParalyzed(owner,pokemon);
    }
    private boolean hasToolPassiveRule(UUID owner,UUID pokemon,String type) {
        if(battlefield==null||toolEffectsDisabled(owner,pokemon))return false;
        for(var tool:battlefield.printedPokemonView(owner,pokemon).attachedTools()) {
            var profile=combat.trainer(tool.definitionId()).orElse(null);
            if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                new ServerConditionContext(owner,pokemon),e->e.type().equals(type)&&e.target()==EffectTarget.SELF))return true;
        }
        return false;
    }
    private boolean pokemonHasPassiveRule(UUID owner,UUID pokemon,String type) {
        if(battlefield==null)return false;
        for(var ability:activeAbilities(owner,pokemon))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()&&ability.effectSupport()==EffectSupport.SUPPORTED
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),
                    new ServerConditionContext(owner,pokemon),effect->effect.type().equals(type)))return true;
        return false;
    }
    private boolean pokemonPlayLocked(UUID player,CardInstance card) {return pokemonPlayLocked(player,card.definitionId());}
    private boolean pokemonPlayLocked(UUID player,String definitionId) {
        var profile=combat.pokemon(definitionId).orElse(null);
        if(profile==null||profile.abilities().isEmpty()||profile.pokemonName()!=null&&profile.pokemonName().contains("Team Rocket's"))return false;
        if(offFieldAbilitiesSuppressed(definitionId))return false;
        String exempt=zoneSuppressionSourceId();
        if(exempt!=null&&profile.abilities().stream().noneMatch(a->a.id().equals(exempt)))return false;
        UUID opponent=other(player).id;
        if(!battlefield.hasActive(opponent))return false;
        UUID source=battlefield.printedActiveView(opponent).pokemonId();
        for(var ability:activeAbilities(opponent,source))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()&&ability.effectSupport()==EffectSupport.SUPPORTED
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(opponent,source),
                    effect->effect.type().equals("passive_pokemon_play_lock")))return true;
        return false;
    }
    private boolean damageCounterMovementBlocked(UUID owner,UUID pokemon) {
        for(UUID controller:players.keySet())for(var host:publicFieldTargets(controller)) {
            EffectTarget scope=controller.equals(owner)?EffectTarget.ALL_OWN_POKEMON:EffectTarget.ALL_OPPONENT_POKEMON;
            for(var ability:activeAbilities(controller,host.pokemonId()))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(controller,host.pokemonId()),
                    e->e.type().equals("prevent_damage_counter_move")&&e.target()==scope)
                &&!preventsImpact(owner,pokemon,new EffectOrigin(EffectOrigin.Kind.ABILITY,controller,host.pokemonId()),EffectProtection.Impact.OTHER_EFFECTS))return true;
        }
        return false;
    }
    private boolean healingBlocked(UUID owner,UUID pokemon) {
        if(stadium!=null&&stadiumController!=null) {
            var scope=stadiumController.equals(owner)?EffectTarget.ALL_OWN_POKEMON:EffectTarget.ALL_OPPONENT_POKEMON;
            var profile=combat.trainer(stadium.definitionId()).orElseThrow();
            if(dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),new ServerConditionContext(owner,pokemon),
                e->e.type().equals("prevent_healing")&&e.target()==scope)
                &&!preventsImpact(owner,pokemon,new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId()),EffectProtection.Impact.OTHER_EFFECTS))return true;
        }
        if(activePokemonPassiveRule(owner,pokemon,"prevent_healing"))return true;
        for(UUID controller:players.keySet()) {
            EffectTarget scope=controller.equals(owner)?EffectTarget.ALL_OWN_POKEMON:EffectTarget.ALL_OPPONENT_POKEMON;
            for(var host:publicFieldTargets(controller))for(var ability:activeAbilities(controller,host.pokemonId()))
                if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                    &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(controller,host.pokemonId()),
                        e->e.type().equals("prevent_healing")&&e.target()==scope
                            &&(!"true".equals(e.arguments().get("source_active_only"))||battlefield.hasActive(controller)
                                &&battlefield.printedActiveView(controller).pokemonId().equals(host.pokemonId()))))return true;
        }
        return false;
    }
    private int currentWeaknessMultiplier(UUID owner,UUID pokemon,int printed) {
        if(!battlefield.hasActive(owner)||!battlefield.printedActiveView(owner).pokemonId().equals(pokemon))return printed;
        for(UUID controller:players.keySet())for(var host:publicFieldTargets(controller)) {
            var origin=new EffectOrigin(EffectOrigin.Kind.ABILITY,controller,host.pokemonId());
            if(preventsImpact(owner,pokemon,origin,EffectProtection.Impact.OTHER_EFFECTS))continue;
            EffectTarget scope=controller.equals(owner)?EffectTarget.OWN_ACTIVE:EffectTarget.OPPONENT_ACTIVE;
            var context=new ServerConditionContext(controller,host.pokemonId());
            for(var ability:activeAbilities(controller,host.pokemonId()))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed())
                for(int amount:List.of(4,3))if(dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),context,
                    effect->effect.type().equals("weakness_multiplier")&&effect.target()==scope
                        &&Integer.toString(amount).equals(effect.arguments().get("amount"))))return amount;
        }
        if(attackCheckpoint!=null&&attackCheckpoint.damageSource!=null&&!owner.equals(attackCheckpoint.attacker.owner())
            &&attackCheckpoint.damageSource.weaknessMultiplier()>0)return attackCheckpoint.damageSource.weaknessMultiplier();
        return printed;
    }
    private boolean preventsCheckupRecovery(UUID owner,SpecialCondition status) {
        if(!battlefield.hasActive(owner))return false;
        if(status==SpecialCondition.BURNED&&stadiumHasPassiveRule("prevent_checkup_recovery"))return true;
        var target=battlefield.printedActiveView(owner).pokemonId();UUID opponent=other(owner).id;
        for(var host:publicFieldTargets(opponent)) {
            var origin=new EffectOrigin(EffectOrigin.Kind.ABILITY,opponent,host.pokemonId());
            if(preventsImpact(owner,target,origin,EffectProtection.Impact.OTHER_EFFECTS))continue;
            for(var ability:activeAbilities(opponent,host.pokemonId()))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(opponent,host.pokemonId()),
                    e->e.type().equals("prevent_checkup_recovery")&&e.arguments().get("status").equals(status.name())))return true;
        }
        return false;
    }
    private dev.hua.ptcglive.engine.effect.PassiveAttackGuard.Values passiveAttackGuard(UUID owner,UUID pokemon,EffectOrigin origin) {
        var result=dev.hua.ptcglive.engine.effect.PassiveAttackGuard.Values.NONE;
        if(origin.kind()!=EffectOrigin.Kind.ATTACK||origin.controller().equals(owner))return result;
        var sources=new ArrayList<>(battlefield.printedBenchView(owner));
        if(battlefield.hasActive(owner))sources.add(battlefield.printedActiveView(owner));
        for(var host:sources) {
            var abilityOrigin=new EffectOrigin(EffectOrigin.Kind.ABILITY,owner,host.pokemonId());
            if(preventsImpact(owner,pokemon,abilityOrigin,EffectProtection.Impact.OTHER_EFFECTS))continue;
            for(var ability:activeAbilities(owner,host.pokemonId()))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.effectSupport()==EffectSupport.SUPPORTED&&ability.composed())
                result=result.plus(dev.hua.ptcglive.engine.effect.PassiveAttackGuard.evaluate(ability.effectProgram(),new ServerConditionContext(owner,pokemon),filter->matchesAttackSource(filter,origin,true),scope->scope==EffectTarget.ALL_OWN_POKEMON
                    ||scope==EffectTarget.OWN_BENCH&&(!battlefield.hasActive(owner)||!battlefield.printedActiveView(owner).pokemonId().equals(pokemon))
                    ||scope==EffectTarget.SELF&&host.pokemonId().equals(pokemon),guardSourcePosition(owner,host.pokemonId())));
        }
        if(!toolEffectsDisabled(owner,pokemon))for(var tool:battlefield.printedPokemonView(owner,pokemon).attachedTools()) {
            var toolOrigin=new EffectOrigin(EffectOrigin.Kind.TRAINER,owner,tool.instanceId());
            if(preventsImpact(owner,pokemon,toolOrigin,EffectProtection.Impact.OTHER_EFFECTS))continue;
            result=result.plus(dev.hua.ptcglive.engine.effect.PassiveAttackGuard.evaluate(combat.trainer(tool.definitionId()).orElseThrow().ongoingProgram(),new ServerConditionContext(owner,pokemon),filter->matchesAttackSource(filter,origin,true),scope->scope==EffectTarget.SELF,guardSourcePosition(owner,pokemon)));
        }
        for(var energy:battlefield.attachedEnergy(owner,pokemon))
            result=result.plus(dev.hua.ptcglive.engine.effect.PassiveAttackGuard.evaluate(effectiveEnergyCard(owner,energy).passiveProgram(),new ServerConditionContext(owner,pokemon),filter->matchesAttackSource(filter,origin,true),scope->scope==EffectTarget.SELF,guardSourcePosition(owner,pokemon)));
        if(stadium!=null&&stadiumController!=null) {
            var stadiumOrigin=new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId());
            if(!preventsImpact(owner,pokemon,stadiumOrigin,EffectProtection.Impact.OTHER_EFFECTS)) {
                boolean own=stadiumController.equals(owner);
                result=result.plus(dev.hua.ptcglive.engine.effect.PassiveAttackGuard.evaluate(
                    combat.trainer(stadium.definitionId()).orElseThrow().ongoingProgram(),new ServerConditionContext(owner,pokemon),
                    filter->matchesAttackSource(filter,origin,true),scope->scope==EffectTarget.ALL_OWN_POKEMON&&own
                        ||scope==EffectTarget.ALL_OPPONENT_POKEMON&&!own,
                    dev.hua.ptcglive.engine.effect.PokemonSelectionScope.Position.ANY));
            }
        }
        return result;
    }
    private dev.hua.ptcglive.engine.effect.PokemonSelectionScope.Position guardSourcePosition(UUID owner,UUID source) {
        return battlefield.hasActive(owner)&&battlefield.printedActiveView(owner).pokemonId().equals(source)
            ?dev.hua.ptcglive.engine.effect.PokemonSelectionScope.Position.ACTIVE:dev.hua.ptcglive.engine.effect.PokemonSelectionScope.Position.BENCH;
    }
    private boolean preventCardEffect(UUID executor, UUID targetOwner, UUID pokemonId) {
        var origin=effectOrigin(executor);
        // Protection stops application, not the later consequences of an effect already on this exact Pokémon.
        if(resolvingDelayedApplication!=null && resolvingDelayedApplication.origin().equals(origin)
            && resolvingDelayedApplication.target().target().equals(new EffectTargetResolution.PokemonTarget(targetOwner,pokemonId))
            && delayedStillApplied(resolvingDelayedApplication))return false;
        if (!preventsImpact(targetOwner,pokemonId,origin,EffectProtection.Impact.OTHER_EFFECTS)) return false;
        recordReplay(executor,"卡牌效果被来源防护阻止："+origin.labelZh()+"；目标="+pokemonId);
        return true;
    }
