    private record QueuedAbility(UUID id, long batch, UUID owner, UUID pokemonId, dev.hua.ptcglive.engine.effect.AutomaticEffectDefinition ability,
                                 EffectLifecycleDispatcher.Source source, EffectEventBindings event,EffectOrigin origin,long cardEntry,
                                 CapturedDeckDiscardSource deckDiscardSource,CapturedHandDiscardSource handDiscardSource,CapturedBenchToActiveEvent benchToActive) {
        QueuedAbility(UUID id,long batch,UUID owner,UUID pokemonId,AbilityDefinition ability,EffectLifecycleDispatcher.Source source,EffectEventBindings event) {
            this(id,batch,owner,pokemonId,ability,source,event,new EffectOrigin(EffectOrigin.Kind.ABILITY,owner,pokemonId),0);
        }
        QueuedAbility(UUID id,long batch,UUID owner,UUID pokemonId,dev.hua.ptcglive.engine.effect.AutomaticEffectDefinition ability,
                      EffectLifecycleDispatcher.Source source,EffectEventBindings event,EffectOrigin origin,long cardEntry) {
            this(id,batch,owner,pokemonId,ability,source,event,origin,cardEntry,null);
        }
        QueuedAbility(UUID id,long batch,UUID owner,UUID pokemonId,dev.hua.ptcglive.engine.effect.AutomaticEffectDefinition ability,
                      EffectLifecycleDispatcher.Source source,EffectEventBindings event,EffectOrigin origin,long cardEntry,CapturedDeckDiscardSource deckDiscardSource) {
            this(id,batch,owner,pokemonId,ability,source,event,origin,cardEntry,deckDiscardSource,null,null);
        }
        QueuedAbility {
            if(benchToActive!=null) require(deckDiscardSource==null&&handDiscardSource==null&&cardEntry==0&&ability instanceof AbilityDefinition
                &&ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.BenchToActiveTriggerPolicy
                &&owner.equals(benchToActive.owner())&&Objects.equals(pokemonId,benchToActive.pokemonId())
                &&event.sourceEntrySequence()==benchToActive.entry()&&Objects.equals(event.sourcePokemon(),event.triggerPokemon())
                &&event.triggerEntrySequence()==benchToActive.entry(),"登上战斗位事件必须绑定同一真实登场身份");
            if(deckDiscardSource!=null) {
                require(handDiscardSource==null&&pokemonId==null&&event.equals(EffectEventBindings.NONE)&&cardEntry==0
                    &&origin.kind()==EffectOrigin.Kind.ABILITY&&origin.sourceId().equals(deckDiscardSource.card().instanceId())
                    &&owner.equals(deckDiscardSource.card().ownerId())&&ability instanceof AbilityDefinition
                    &&ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.DeckDiscardTriggerPolicy
                    &&source.sourceId().equals(deckDiscardSource.card().instanceId())&&source.program().equals(ability.effectProgram()),
                    "弃牌来源必须绑定真实物理卡和服务器捕获的限定程序");
            } else if(handDiscardSource!=null) {
                require(pokemonId==null&&event.equals(EffectEventBindings.NONE)&&cardEntry==0
                    &&origin.kind()==EffectOrigin.Kind.ABILITY&&origin.sourceId().equals(handDiscardSource.card().instanceId())
                    &&owner.equals(handDiscardSource.card().ownerId())&&ability instanceof AbilityDefinition
                    &&ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.HandDiscardTriggerPolicy
                    &&source.sourceId().equals(handDiscardSource.card().instanceId())&&source.program().equals(ability.effectProgram()),
                    "手牌弃置来源必须绑定真实物理卡和服务器捕获的限定程序");
            } else require(pokemonId==null ? origin.kind()!=EffectOrigin.Kind.ABILITY&&event.sourcePokemon()==null
                : event.sourcePokemon()!=null && event.sourcePokemon().owner().equals(owner)
                && event.sourcePokemon().pokemonId().equals(pokemonId),"待处理效果必须绑定原始来源宿主，场地没有宿主");
            require(origin.controller().equals(owner),"自动效果来源控制者不一致");
        }
        TriggerOrderPrompt.Entry view() { return new TriggerOrderPrompt.Entry(id, owner, pokemonId, ability.nameZh(),event.triggerPokemon(),event.attackingPokemon(),origin.kind(),deckDiscardSource==null&&handDiscardSource==null?origin.sourceId():null); }
        /** Only a pre-departure SELF leave-play capture may execute after its host leaves the field. */
        boolean departedSourceLastKnown() {
            return origin.kind() == EffectOrigin.Kind.ABILITY && pokemonId != null
                && ability.eventPolicy().trigger() == EffectTrigger.ON_LEAVE_PLAY
                && event.sourcePokemon() != null && event.triggerPokemon() != null
                && event.sourcePokemon().equals(event.triggerPokemon())
                && event.sourceEntrySequence() == event.triggerEntrySequence();
        }
        String auditLabel() {
            // The original attacker can now be in a hidden zone. Do not re-emit its instance UUID.
            if(deckDiscardSource!=null)return ability.id()+"；原控制者="+owner+"；牌库弃牌事件="+deckDiscardSource.movement()+"；捕获回合="+deckDiscardSource.turn();
            if(handDiscardSource!=null)return ability.id()+"；原控制者="+owner+"；手牌弃置事件="+handDiscardSource.movement()+"；捕获回合="+handDiscardSource.turn();
            if(ability instanceof ScheduledPokemonEffect delayed)return ability.id()+"；原控制者="+owner+"；目标登场="+delayed.target().entrySequence()+"；到期回合="+delayed.dueTurn();
            return ability.id() + "；来源=" + origin + "/" + pokemonId + "；来源登场="+event.sourceEntrySequence()+"；附着登场="+cardEntry+"；事件=" + batch + "；对象="+event.triggerPokemon()+"；攻击者="+event.attackingPokemon();
        }
    }
