    private final Map<UUID,ScheduledPlayerEffect> delayedPlayerEffects=new LinkedHashMap<>();
    private final Set<UUID> trainersExchangedWithPrizes=new LinkedHashSet<>();
    private final Set<UUID> trainersToShuffle=new LinkedHashSet<>();
    private final Set<UUID> trainersToHand=new LinkedHashSet<>();
    private final Set<UUID> trainersToBottom=new LinkedHashSet<>();
    private void disposePlayedTrainers(PendingResolution pending) {
        if(preparedBenchEnergy!=null&&preparedBenchEnergy.resolutionId().equals(pending.id()))preparedBenchEnergy=null;
        if(trainersExchangedWithPrizes.remove(pending.id()))return;
        if(trainersToBottom.remove(pending.id())) {
            for(var card:pending.playedCards())state(card.ownerId()).deck.add(0,card);
            return;
        }
        if(trainersToHand.remove(pending.id())) {
            for(var card:pending.playedCards())state(card.ownerId()).hand.add(card);
            return;
        }
        if(!trainersToShuffle.remove(pending.id())) {moveCardsToOwnerDiscard(pending.playedCards());return;}
        for(var card:pending.playedCards())state(card.ownerId()).deck.add(card);
        for(var owner:pending.playedCards().stream().map(CardInstance::ownerId).distinct().toList())shuffle(state(owner).deck,"trainer-source-return:"+owner);
    }
