    private record PendingFullHpSurvival(UUID token,UUID owner,PokemonCandidate target,int activeOpponentTurn) { }
    private final Map<UUID,PendingFullHpSurvival> pendingFullHpSurvivals=new LinkedHashMap<>();
    private boolean fullHpSurvivalStillApplied(PendingFullHpSurvival effect) {
        var target=effect.target();return sameFieldEntry(target.target().owner(),target.target().pokemonId(),target.entrySequence())
            &&battlefield.hasDelayedMarker(target.target().owner(),target.target().pokemonId(),effect.token());
    }
    private void removeFullHpSurvival(PendingFullHpSurvival effect) {
        if(effect==null)return;
        var target=effect.target();
        if(sameFieldEntry(target.target().owner(),target.target().pokemonId(),target.entrySequence()))
            battlefield.removeDelayedMarker(target.target().owner(),target.target().pokemonId(),effect.token());
        pendingFullHpSurvivals.remove(effect.token());
    }
    private void activateFullHpSurvivals() {
        for(var effect:List.copyOf(pendingFullHpSurvivals.values())) {
            if(!fullHpSurvivalStillApplied(effect)){removeFullHpSurvival(effect);continue;}
            if(effect.activeOpponentTurn()<0&&!effect.owner().equals(currentPlayer))
                pendingFullHpSurvivals.put(effect.token(),new PendingFullHpSurvival(effect.token(),effect.owner(),effect.target(),turnNumber));
        }
    }
    private void expireFullHpSurvivals() {
        for(var effect:List.copyOf(pendingFullHpSurvivals.values()))
            if(!fullHpSurvivalStillApplied(effect)||effect.activeOpponentTurn()==turnNumber)
                removeFullHpSurvival(effect);
    }
    /** Applies after actual attack damage, before lethal ON_DAMAGE observers and the KO checkpoint. */
    private boolean surviveFullHpAttackDamage(UUID owner,UUID pokemonId,UUID attacker,boolean hadFullHp,boolean lethal) {
        if(!lethal||!hadFullHp||owner.equals(attacker))return false;
        boolean protectedByAttack=pendingFullHpSurvivals.values().stream().anyMatch(effect ->
            effect.activeOpponentTurn()==turnNumber&&effect.owner().equals(owner)
                &&effect.target().target().pokemonId().equals(pokemonId)&&fullHpSurvivalStillApplied(effect));
        if(!protectedByAttack)return false;
        require(battlefield.surviveAttackDamage(owner,pokemonId),"满 HP 延迟生存替代缺少致命攻击伤害");
        recordReplay(owner,"延迟生存替代：致命攻击伤害后剩余 10 HP");
        return true;
    }
    private record PendingDefenderPrize(UUID token,UUID owner,PokemonCandidate target,int activeTurn) { }
    private final Map<UUID,PendingDefenderPrize> pendingDefenderPrizes=new LinkedHashMap<>();
    private boolean defenderPrizeStillApplied(PendingDefenderPrize effect) {
        var t=effect.target();return sameFieldEntry(t.target().owner(),t.target().pokemonId(),t.entrySequence())
            &&battlefield.hasDelayedMarker(t.target().owner(),t.target().pokemonId(),effect.token());
    }
    private void updateDefenderPrizes(boolean endingTurn) {
        for(var effect:List.copyOf(pendingDefenderPrizes.values())) {
            if(!defenderPrizeStillApplied(effect)||endingTurn&&effect.activeTurn()==turnNumber) {
                var t=effect.target();if(sameFieldEntry(t.target().owner(),t.target().pokemonId(),t.entrySequence()))battlefield.removeDelayedMarker(t.target().owner(),t.target().pokemonId(),effect.token());
                pendingDefenderPrizes.remove(effect.token());
            } else if(!endingTurn&&effect.activeTurn()<0&&effect.owner().equals(currentPlayer))
                pendingDefenderPrizes.put(effect.token(),new PendingDefenderPrize(effect.token(),effect.owner(),effect.target(),turnNumber));
        }
    }
    private int defenderPrizeBonus(Knockout knockout,boolean checkup) {
        if(checkup)return 0;
        return pendingDefenderPrizes.values().stream().anyMatch(e->e.activeTurn()==turnNumber&&e.owner().equals(currentPlayer)
            &&e.target().target().owner().equals(knockout.owner())&&e.target().target().pokemonId().equals(knockout.pokemonId())&&defenderPrizeStillApplied(e))?2:0;
    }
