    private void activateNoPrizeKos() {
        for(var effect:List.copyOf(pendingNoPrizeKos.values())) {
            if(!noPrizeKoStillApplied(effect)){removeNoPrizeKo(effect);continue;}
            if(effect.activeOpponentTurn()<0&&!effect.owner().equals(currentPlayer))
                pendingNoPrizeKos.put(effect.token(),new PendingNoPrizeKo(effect.token(),effect.owner(),effect.target(),turnNumber));
        }
    }
    private boolean noPrizeKoApplies(Knockout knockedOut) {
        return pendingNoPrizeKos.values().stream().anyMatch(effect -> effect.activeOpponentTurn()==turnNumber
            &&!effect.owner().equals(currentPlayer)&&effect.owner().equals(knockedOut.owner())
            &&effect.target().target().pokemonId().equals(knockedOut.pokemonId())&&noPrizeKoStillApplied(effect));
    }
    private void expireNoPrizeKos() {
        for(var effect:List.copyOf(pendingNoPrizeKos.values()))
            if(!noPrizeKoStillApplied(effect)||effect.activeOpponentTurn()==turnNumber)
                removeNoPrizeKo(effect);
    }
    private boolean attackKoProtectionStillApplied(PendingAttackKoProtection protection) {
        var target=protection.target();return sameFieldEntry(target.target().owner(),target.target().pokemonId(),target.entrySequence())
            &&battlefield.hasDelayedMarker(target.target().owner(),target.target().pokemonId(),protection.token());
    }
    private void removeAttackKoProtection(PendingAttackKoProtection protection) {
        if(protection==null)return;
        var target=protection.target();
        if(sameFieldEntry(target.target().owner(),target.target().pokemonId(),target.entrySequence()))
            battlefield.removeDelayedMarker(target.target().owner(),target.target().pokemonId(),protection.token());
        pendingAttackKoProtections.remove(protection.token());
    }
    private void qualifyAttackKoProtection(KnockoutCheckpoint checkpoint) {
        var protection=checkpoint.koProtection;checkpoint.koProtection=null;
        if(protection==null)return;
        boolean qualified=checkpoint.confirmed.stream().anyMatch(ko->dev.hua.ptcglive.engine.effect.AttackDamageKoProtection.qualifies(
            protection.owner(),ko.owner(),true,checkpoint.attackDamage.contains(ko)));
        if(qualified&&attackKoProtectionStillApplied(protection)) {
            pendingAttackKoProtections.put(protection.token(),protection);
            recordReplay(protection.owner(),"攻击伤害击倒已确认；防护等待下个对手回合");
        } else removeAttackKoProtection(protection);
    }
    /** Turn-end attacks and this attack's reactions must resolve before the next-turn protection becomes active. */
    private void activateAttackKoProtections() {
        for(var protection:List.copyOf(pendingAttackKoProtections.values())) {
            if(!attackKoProtectionStillApplied(protection)){removeAttackKoProtection(protection);continue;}
            if(protection.owner().equals(currentPlayer))continue;
            removeAttackKoProtection(protection);
            var target=protection.target().target();
            // The effect was applied at registration. Later immunity cannot retroactively cancel its marker.
            withOrigin(new EffectOrigin(EffectOrigin.Kind.ATTACK,protection.owner(),target.pokemonId()),
                ()->battlefield.addProtection(protection.owner(),target.owner(),target.pokemonId(),protection.protection()));
            recordReplay(protection.owner(),"击倒后防护生效；原目标登场="+protection.target().entrySequence());
        }
    }
