    public TriggerOrderPrompt triggerOrderPrompt() { return triggerOrderPrompt; }
    public boolean triggerSourceStillInPlay(UUID entryId) {
        var entry=optionalTriggeredAbility!=null && optionalTriggeredAbility.id().equals(entryId) ? optionalTriggeredAbility
            : triggeredAbilities.stream().filter(e->e.id().equals(entryId)).findFirst().orElse(null);
        if(entry==null||entry.deckDiscardSource()!=null||entry.handDiscardSource()!=null)return false;
        if(entry.origin().kind()==EffectOrigin.Kind.ABILITY)return !resolveEffectTarget(entry.owner(),entry.pokemonId(),EffectTarget.SELF,entry.event()).fixedTargets().isEmpty();
        if(entry.pokemonId()==null)return stadium!=null&&stadium.instanceId().equals(entry.origin().sourceId())&&stadiumEntrySequence==entry.cardEntry();
        for(UUID owner:players.keySet()) {
            var field=new ArrayList<>(battlefield.benchView(owner));if(battlefield.hasActive(owner))field.add(battlefield.activeView(owner));
            for(var host:field)if(java.util.stream.Stream.concat(host.attachedTools().stream(),battlefield.attachedEnergy(owner,host.pokemonId()).stream())
                .anyMatch(c->c.instanceId().equals(entry.origin().sourceId())))
                return battlefield.attachmentEntrySequence(owner,host.pokemonId(),entry.origin().sourceId())==entry.cardEntry();
        }
        return false;
    }
    public boolean triggerSubjectStillInPlay(UUID entryId) {
        var entry=optionalTriggeredAbility!=null && optionalTriggeredAbility.id().equals(entryId) ? optionalTriggeredAbility
            : triggeredAbilities.stream().filter(e->e.id().equals(entryId)).findFirst().orElse(null);
        return entry!=null && entry.event().triggerPokemon()!=null
            && !resolveEffectTarget(entry.owner(),entry.pokemonId(),EffectTarget.TRIGGER_POKEMON,entry.event()).fixedTargets().isEmpty();
    }
    private EffectTargetResolution.PokemonTarget canonicalInPlayTarget(EffectTargetResolution.PokemonTarget target) {
        return target==null?null:new EffectTargetResolution.PokemonTarget(target.owner(),battlefield.printedPokemonView(target.owner(),target.pokemonId()).pokemonId());
    }
    private EffectEventBindings bindEvent(EffectTargetResolution.PokemonTarget suppliedSubject,EffectTargetResolution.PokemonTarget suppliedAttacker) {
        var subject=canonicalInPlayTarget(suppliedSubject);var attacker=canonicalInPlayTarget(suppliedAttacker);
        return new EffectEventBindings(subject,subject==null?0:battlefield.pokemonEntrySequence(subject.owner(),subject.pokemonId()),
            attacker,attacker==null?0:battlefield.pokemonEntrySequence(attacker.owner(),attacker.pokemonId()));
    }
    private EffectEventBindings bindSourceEvent(UUID owner,UUID suppliedPokemonId,EffectEventBindings event) {
        UUID pokemonId=battlefield.printedPokemonView(owner,suppliedPokemonId).pokemonId();
        return event.withSource(new EffectTargetResolution.PokemonTarget(owner,pokemonId),battlefield.pokemonEntrySequence(owner,pokemonId));
    }
    private boolean sameFieldEntry(UUID owner,UUID pokemonId,long entry) {
        boolean present=battlefield.hasActive(owner)&&battlefield.printedActiveView(owner).pokemonId().equals(pokemonId)
            || battlefield.printedBenchView(owner).stream().anyMatch(p->p.pokemonId().equals(pokemonId));
        return present && battlefield.pokemonEntrySequence(owner,pokemonId)==entry;
    }
    private record PersistentListener(UUID owner,UUID host,CardInstance card,EffectOrigin.Kind kind,long entry,
                                      List<dev.hua.ptcglive.engine.effect.CardTriggerDefinition> effects) { }
    /** The same live-source gates used by numeric modifiers: disabled Tools and overridden Energy never listen. */
    private List<PersistentListener> persistentListeners() {
        var result=new ArrayList<PersistentListener>();
        for(UUID owner:players.keySet()) {
            var field=new ArrayList<>(battlefield.benchView(owner));if(battlefield.hasActive(owner))field.add(battlefield.activeView(owner));
            for(var host:field) {
                if(!toolEffectsDisabled(owner,host.pokemonId()))for(var card:host.attachedTools()) {
                    var effects=combat.trainer(card.definitionId()).orElseThrow().automaticEffects();
                    if(!effects.isEmpty())result.add(new PersistentListener(owner,host.pokemonId(),card,EffectOrigin.Kind.TRAINER,battlefield.attachmentEntrySequence(owner,host.pokemonId(),card.instanceId()),effects));
                }
                for(var card:battlefield.attachedEnergy(owner,host.pokemonId())) {
                    var effects=currentEnergyProfile(owner,host.pokemonId(),card).automaticEffects();
                    if(!effects.isEmpty())result.add(new PersistentListener(owner,host.pokemonId(),card,EffectOrigin.Kind.ENERGY,battlefield.attachmentEntrySequence(owner,host.pokemonId(),card.instanceId()),effects));
                }
            }
        }
        if(stadium!=null) {
            var effects=combat.trainer(stadium.definitionId()).orElseThrow().automaticEffects();
            if(!effects.isEmpty())result.add(new PersistentListener(stadiumController,null,stadium,EffectOrigin.Kind.TRAINER,stadiumEntrySequence,effects));
        }
        return List.copyOf(result);
    }
    private QueuedAbility persistentCandidate(PersistentListener listener,dev.hua.ptcglive.engine.effect.CardTriggerDefinition effect,EffectEventBindings event) {
        require(ruleset.triggerTiming()==dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,"此规则包的持续卡自动触发时序尚未核验");
        if(listener.host()!=null)event=bindSourceEvent(listener.owner(),listener.host(),event);
        var source=new EffectLifecycleDispatcher.Source(listener.card().instanceId(),"card:"+effect.id()+":entry:"+listener.entry(),effect.effectProgram());
        return new QueuedAbility(UUID.randomUUID(),0,listener.owner(),listener.host(),effect,source,event,
            new EffectOrigin(listener.kind(),listener.owner(),listener.card().instanceId()),listener.entry());
    }
    /**
     * Creates the same resumable public-target memory used by a queued
     * automatic resolution for its non-mutating preflight projection.
     */
    private ServerEffectExecutionContext automaticPreviewContext(UUID owner, UUID pokemonId,
                                                                  EffectEventBindings event,
                                                                  dev.hua.ptcglive.engine.effect.EffectProgram program) {
        var context=new ServerEffectExecutionContext(owner,pokemonId).bind(event);
        if(dev.hua.ptcglive.engine.effect.AttackCountBindings.usesCounts(program)) {
            dev.hua.ptcglive.engine.effect.AttackCountBindings.validateAutomatic(program,program.triggers().getFirst().trigger());
            context.automaticCounts=true;
        }
        if (dev.hua.ptcglive.engine.effect.AttackPokemonBindings.usesNamedBindings(program))
            context.pokemonBindings=new LinkedHashMap<>();
        return context;
    }
    private ServerEffectExecutionContext automaticContext(QueuedAbility entry) {
        var context=automaticPreviewContext(entry.owner(),entry.pokemonId(),entry.event(),entry.ability().effectProgram());context.origin=entry.origin();
        if(entry.ability() instanceof ScheduledPokemonEffect delayed)context.delayedApplication=delayed;
        context.scheduledPlayer=entry.ability() instanceof ScheduledPlayerEffect;
        context.capturedDeckDiscardSource=entry.deckDiscardSource();
        context.capturedHandDiscardSource=entry.handDiscardSource();
        context.capturedBenchToActive=entry.benchToActive();
        if(entry.benchToActive()!=null)context.sourceEntry=entry.benchToActive().entry();
        if(entry.ability() instanceof AbilityDefinition && entry.origin().kind()==EffectOrigin.Kind.ABILITY)
            context.deckDiscardCause=new DeckDiscardCause(entry.owner(),dev.hua.ptcglive.engine.effect.DeckDiscardTriggerPolicy.SourceKind.POKEMON_ABILITY,
                entry.origin().sourceId(),entry.ability().id(),entry.id());
        // Automatic effects can pause for a server-issued public Pokémon
        // choice.  Keep aliases only for this one queued resolution so a
        // later with_pokemon step cannot be forged, leaked, or reused by a
        // different trigger.
        context.sourceCardEntry=entry.cardEntry();context.departedSourceLastKnown=entry.departedSourceLastKnown();return context;
    }
    private boolean triggerUnused(QueuedAbility entry) {
        return !effectLifecycle.usageLimited(entry.source(),entry.ability().eventPolicy().trigger(),turnNumber,entry.ability().eventPolicy().usage())
            &&!sharedUsageExhausted(entry.owner(),entry.ability().usageLimit());
    }
    private List<QueuedAbility> persistentEnergyCandidates(UUID targetOwner,UUID pokemonId,CardInstance energy,EffectSourceZone origin,EnergyTriggerPolicy.Cause cause,
                                                         List<PersistentListener> listeners,UUID sourceOwner) {
        return persistentEnergyCandidates(targetOwner,pokemonId,energy,EnergyTriggerPolicy.Source.valueOf(origin.name()),cause,listeners,sourceOwner);
    }
    private List<QueuedAbility> persistentEnergyCandidates(UUID targetOwner,UUID pokemonId,CardInstance energy,EnergyTriggerPolicy.Source origin,EnergyTriggerPolicy.Cause cause,
                                                         List<PersistentListener> listeners,UUID sourceOwner) {
        var result=new ArrayList<QueuedAbility>();
        for(var listener:listeners)for(var effect:listener.effects()) {
            if(effect.sourceCardOnly()&&!listener.card().instanceId().equals(energy.instanceId()))continue;
            if(!(effect.eventPolicy() instanceof EnergyTriggerPolicy policy)||policy.ownHandOnly()&&!listener.owner().equals(sourceOwner)||policy.targetHandOnly()&&!targetOwner.equals(sourceOwner)||!policy.matches(listener.owner(),listener.host(),targetOwner,pokemonId,
                origin,cause,definition(energy).basicEnergy()))continue;
            var entry=persistentCandidate(listener,effect,bindEvent(new EffectTargetResolution.PokemonTarget(targetOwner,pokemonId),null));
            if(!triggerUnused(entry))continue;
            automaticContext(entry).preflight(effect.effectProgram(),EffectTrigger.ON_ENERGY_ATTACHED);result.add(entry);
        }
        return result;
    }
    private void preflightPersistentEnergy(UUID owner,UUID host,CardInstance incoming,EffectSourceZone zone,EnergyTriggerPolicy.Cause cause,UUID sourceOwner) {
        preflightPersistentEnergy(owner,host,incoming,EnergyTriggerPolicy.Source.valueOf(zone.name()),cause,sourceOwner);
    }
    private void preflightPersistentEnergy(UUID owner,UUID host,CardInstance incoming,EnergyTriggerPolicy.Source zone,EnergyTriggerPolicy.Cause cause,UUID sourceOwner) {
        var listeners=new ArrayList<>(persistentListeners());
        var effects=currentEnergyProfile(owner,host,incoming).automaticEffects();
        if(!effects.isEmpty())listeners.add(new PersistentListener(owner,host,incoming,EffectOrigin.Kind.ENERGY,0,effects));
        // Entry 0 is only a validation projection; actual capture occurs after attachment assigns a real entry.
        persistentEnergyCandidates(owner,host,incoming,zone,cause,listeners,sourceOwner);
    }
    private List<QueuedAbility> matchingEnergyAbilities(UUID targetOwner, UUID pokemonId, CardInstance energy,
                                                       EffectSourceZone origin, EnergyTriggerPolicy.Cause cause,UUID sourceOwner) {
        return matchingEnergyAbilities(targetOwner,pokemonId,energy,EnergyTriggerPolicy.Source.valueOf(origin.name()),cause,sourceOwner);
    }
    private List<QueuedAbility> matchingEnergyAbilities(UUID targetOwner,UUID pokemonId,CardInstance energy,
                                                       EnergyTriggerPolicy.Source origin,EnergyTriggerPolicy.Cause cause,UUID sourceOwner) {
        var result = new ArrayList<QueuedAbility>();
        var nonstackGroups = new LinkedHashSet<String>();
        for (UUID owner : players.keySet()) {
            var field = new ArrayList<>(battlefield.benchView(owner));
            if (battlefield.hasActive(owner)) field.add(battlefield.activeView(owner));
            for (var pokemon : field) for (var ability : activeAbilities(owner, pokemon.pokemonId())) {
                if (!ability.triggered() || !(ability.eventPolicy() instanceof EnergyTriggerPolicy policy) || policy.ownHandOnly()&&!owner.equals(sourceOwner) || policy.targetHandOnly()&&!targetOwner.equals(sourceOwner) || !policy.matches(owner, pokemon.pokemonId(), targetOwner, pokemonId,
                    origin, cause, definition(energy).basicEnergy())) continue;
                require(ruleset.triggerTiming() == dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,
                    "此规则包的自动触发时序尚未核验");
                TriggeredAbilityRules.validate(ability);
                var source = abilitySource(owner, pokemon.pokemonId(), ability);
                if (!effectLifecycle.usageLimited(source, EffectTrigger.ON_ENERGY_ATTACHED, turnNumber, ability.eventPolicy().usage())
                    && !sharedUsageExhausted(owner,ability.usageLimit())) {
                    var event=bindSourceEvent(owner,pokemon.pokemonId(),bindEvent(new EffectTargetResolution.PokemonTarget(targetOwner,pokemonId),null));
                    var context = automaticPreviewContext(owner,pokemon.pokemonId(),event,ability.effectProgram());
                    context.preflight(ability.effectProgram(), EffectTrigger.ON_ENERGY_ATTACHED);
                    if(policy.nonstackGroup()!=null) {
                        var binding=ability.effectProgram().triggers().getFirst();
                        if(!binding.conditions().stream().allMatch(condition->ConditionEvaluator.matches(condition,context))
                            ||!nonstackGroups.add(owner+":"+policy.nonstackGroup()))continue;
                    }
                    result.add(new QueuedAbility(UUID.randomUUID(), 0, owner, pokemon.pokemonId(), ability, source,event));
                }
            }
        }
        preflightPersistentEnergy(targetOwner,pokemonId,energy,origin,cause,sourceOwner);
        return result;
    }
    /**
     * Captures a public field-change event after its battlefield mutation but
     * before any later client intent.  The subject stays tied to this exact
     * stay in play; opening setup and Knock Out replacement deliberately do
     * not call this method. A non-KO leave-play event uses the sibling method
     * below because its subject is already absent from the field.
     */
    private long capturePokemonChangeEvent(EffectTrigger trigger, UUID subjectOwner, UUID subjectPokemonId) {
        return capturePokemonChangeEvent(trigger, subjectOwner, subjectPokemonId, dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy.Source.ANY);
    }
    private long capturePokemonChangeEvent(EffectTrigger trigger, UUID subjectOwner, UUID suppliedSubjectPokemonId,
                                           dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy.Source sourceZone) {
        require(java.util.Set.of(EffectTrigger.ON_ENTER_PLAY, EffectTrigger.ON_EVOLVE, EffectTrigger.ON_RETREAT, EffectTrigger.ON_SWITCH, EffectTrigger.ON_ACTIVE_TO_BENCH).contains(trigger),
            "不是已接入的场上变化事件：" + trigger);
        require(battlefield != null, "场上变化事件需要战场");
        refreshStadiumAbilityImmunity();
        UUID subjectPokemonId=battlefield.printedPokemonView(subjectOwner,suppliedSubjectPokemonId).pokemonId();
        long subjectEntry = battlefield.pokemonEntrySequence(subjectOwner, subjectPokemonId);
        var event = new EffectEventBindings(new EffectTargetResolution.PokemonTarget(subjectOwner, subjectPokemonId), subjectEntry, null, 0);
        var candidates = new ArrayList<QueuedAbility>();
        var nonstackGroups = new LinkedHashSet<String>();
        for (UUID owner : players.keySet()) {
            var field = new ArrayList<>(battlefield.benchView(owner));
            if (battlefield.hasActive(owner)) field.add(battlefield.activeView(owner));
            for (var pokemon : field) for (var ability : activeAbilities(owner, pokemon.pokemonId())) {
                if (!ability.triggered() || !(ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy policy)
                    || policy.trigger() != trigger || !policy.matches(owner, pokemon.pokemonId(), subjectOwner, subjectPokemonId, sourceZone)
                    || !changeSubjectMatches(policy,subjectOwner,subjectPokemonId)) continue;
                if (policy.fromPokemonName()!=null) {
                    var stack=battlefield.printedPokemonView(subjectOwner,subjectPokemonId).evolutionCardIds();
                    if (!owner.equals(currentPlayer)||stack.size()<2||!policy.fromPokemonName().equals(
                        combat.pokemon(stack.get(stack.size()-2)).map(p->p.pokemonName()).orElse(null))) continue;
                }
                if(trigger==EffectTrigger.ON_ACTIVE_TO_BENCH&&programHasRule(ability.effectProgram(),"replace_pokemon_from_deck")&&!owner.equals(currentPlayer))continue;
                if(policy.nonstackGroup()!=null&&!nonstackGroups.add(owner+":"+policy.nonstackGroup()))continue;
                require(ruleset.triggerTiming() == dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,
                    "此规则包的场上变化触发时序尚未核验");
                TriggeredAbilityRules.validate(ability);
                var entry = new QueuedAbility(UUID.randomUUID(), 0, owner, pokemon.pokemonId(), ability,
                    abilitySource(owner, pokemon.pokemonId(), ability), bindSourceEvent(owner, pokemon.pokemonId(), event));
                if (!triggerUnused(entry)) continue;
                automaticContext(entry).preflight(ability.effectProgram(), trigger);
                candidates.add(entry);
            }
        }
        for (var listener : persistentListeners()) for (var effect : listener.effects()) {
            if (!(effect.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy policy)
                || policy.trigger() != trigger || !policy.matches(listener.owner(), listener.host(), subjectOwner, subjectPokemonId, sourceZone)
                || !changeSubjectMatches(policy,subjectOwner,subjectPokemonId)) continue;
            if (policy.fromPokemonName()!=null) {
                var stack=battlefield.printedPokemonView(subjectOwner,subjectPokemonId).evolutionCardIds();
                if (!listener.owner().equals(currentPlayer)||stack.size()<2||!policy.fromPokemonName().equals(
                    combat.pokemon(stack.get(stack.size()-2)).map(p->p.pokemonName()).orElse(null))) continue;
            }
            if(policy.nonstackGroup()!=null&&!nonstackGroups.add(listener.owner()+":"+policy.nonstackGroup()))continue;
            var entry = persistentCandidate(listener, effect, event);
            if (!triggerUnused(entry)) continue;
            automaticContext(entry).preflight(effect.effectProgram(), trigger);
            candidates.add(entry);
        }
        long batch=++triggerEventBatch;
        captureTriggeredAbilities(candidates, batch);
        return batch;
    }
    /** Event qualifications use the subject owner and its immediately preceding evolution card. */
    private boolean changeSubjectMatches(dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy policy,UUID owner,UUID pokemon) {
        if(policy.basicBenchEntryOnly()&&(!fieldCardDefinition(battlefield.topCard(owner,pokemon).definitionId()).basicPokemon()
            ||battlefield.printedBenchView(owner).stream().noneMatch(v->v.pokemonId().equals(pokemon))))return false;
        if(policy.subjectOwnTurnOnly()&&!owner.equals(currentPlayer))return false;
        if(policy.fromPokemonFamily()==null)return true;
        var stack=battlefield.printedPokemonView(owner,pokemon).evolutionCardIds();
        return stack.size()>=2&&definitions.find(stack.get(stack.size()-2))
            .map(card->card.pokemonFamilies().contains(policy.fromPokemonFamily())).orElse(false);
    }
    /** Capture only a validated real Bench incarnation before the successful physical switch. */
    private CapturedBenchToActiveEvent benchToActiveBefore(UUID owner,UUID suppliedPokemon) {
        if(turnNumber<=0||resolvingCheckup||!owner.equals(currentPlayer))return null;
        UUID pokemon=battlefield.printedPokemonView(owner,suppliedPokemon).pokemonId();
        require(battlefield.printedBenchView(owner).stream().anyMatch(v->v.pokemonId().equals(pokemon)),"登上战斗位的来源必须原本在备战区");
        return new CapturedBenchToActiveEvent(owner,pokemon,battlefield.pokemonEntrySequence(owner,pokemon),currentPlayer,turnNumber);
    }
    private void captureBenchToActiveEvent(CapturedBenchToActiveEvent transition,long existingBatch) {
        if(transition==null)return;
        UUID owner=transition.owner(),pokemon=transition.pokemonId();
        require(owner.equals(currentPlayer)&&transition.turnPlayer().equals(currentPlayer)&&transition.turn()==turnNumber
            &&!resolvingCheckup&&battlefield.hasActive(owner)&&battlefield.printedActiveView(owner).pokemonId().equals(pokemon)
            &&sameFieldEntry(owner,pokemon,transition.entry()),"登上战斗位事件的真实转移已失效");
        var target=new EffectTargetResolution.PokemonTarget(owner,pokemon);
        var event=new EffectEventBindings(target,transition.entry(),null,0).withSource(target,transition.entry());
        var candidates=new ArrayList<QueuedAbility>();
        for(var ability:activeAbilities(owner,pokemon)) {
            if(!ability.triggered()||!(ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.BenchToActiveTriggerPolicy))continue;
            require(ruleset.triggerTiming()==dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,"此规则包的登上战斗位时序尚未核验");
            TriggeredAbilityRules.validate(ability);
            var entry=new QueuedAbility(UUID.randomUUID(),0,owner,pokemon,ability,abilitySource(owner,pokemon,ability),event,
                new EffectOrigin(EffectOrigin.Kind.ABILITY,owner,pokemon),0,null,null,transition);
            if(!triggerUnused(entry))continue;
            automaticContext(entry).preflight(ability.effectProgram(),EffectTrigger.ON_BENCH_TO_ACTIVE);
            candidates.add(entry);
        }
        if(!candidates.isEmpty())captureTriggeredAbilities(candidates,existingBatch>0?existingBatch:++triggerEventBatch);
    }
    private boolean hasBenchToActiveOpportunity() {
        return triggeredAbilities.stream().anyMatch(e->e.benchToActive()!=null)
            ||optionalTriggeredAbility!=null&&optionalTriggeredAbility.benchToActive()!=null
            ||pendingResolution!=null&&pendingResolution.triggered()!=null&&pendingResolution.triggered().benchToActive()!=null;
    }
    /** Late usability is deliberate: the causing card may have attached or removed Energy after the movement. */
    private boolean benchToActiveUsable(QueuedAbility entry) {
        var token=entry.benchToActive();
        if(token==null)return true;
        if(!token.owner().equals(currentPlayer)||!token.turnPlayer().equals(currentPlayer)||token.turn()!=turnNumber
            ||resolvingCheckup||!sameFieldEntry(token.owner(),token.pokemonId(),token.entry())||!triggerUnused(entry))return false;
        var host=battlefield.pokemonView(token.owner(),token.pokemonId());
        if(host.damage()>=host.hitPoints()||knockoutCheckpoint!=null&&knockoutCheckpoint.confirmed.contains(new Knockout(token.owner(),token.pokemonId())))return false;
        var context=automaticContext(entry);
        return context.canAffect(entry.ability().effectProgram().triggers().getFirst().effects().getFirst());
    }
    /**
     * Captures a SELF leave-play Ability before its host is removed. Its
     * program has already passed the deliberately narrow source-independent
     * LKI contract in TriggeredAbilityRules; capture-time conditions are
     * latched here while the exact entry is still public and in play.
     */
    private List<QueuedAbility> captureDepartingPokemonSelfLeavePlayEvent(UUID subjectOwner, UUID subjectPokemonId,
                                                                            long subjectEntry, long batch) {
        require(battlefield != null && subjectEntry > 0, "离场来源事件需要已捕获的场上对象");
        var subject = new EffectTargetResolution.PokemonTarget(subjectOwner, subjectPokemonId);
        var event = new EffectEventBindings(subject, subjectEntry, null, 0).withSource(subject, subjectEntry);
        var candidates = new ArrayList<QueuedAbility>();
        for (var ability : activeAbilities(subjectOwner, subjectPokemonId)) {
            if (!ability.triggered() || !(ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy policy)
                || policy.trigger() != EffectTrigger.ON_LEAVE_PLAY || policy.watch() != dev.hua.ptcglive.engine.effect.EventPokemonScope.SELF) continue;
            require(ruleset.triggerTiming() == dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,
                "此规则包的离场触发时序尚未核验");
            TriggeredAbilityRules.validate(ability);
            var entry = new QueuedAbility(UUID.randomUUID(), 0, subjectOwner, subjectPokemonId, ability,
                abilitySource(subjectOwner, subjectPokemonId, ability), event);
            if (!triggerUnused(entry)) continue;
            automaticContext(entry).preflight(ability.effectProgram(), EffectTrigger.ON_LEAVE_PLAY);
            candidates.add(entry);
        }
        return capturedAbilities(candidates, batch);
    }
    /**
     * Captures a reviewed non-Knock-Out return/shuffle/discard after the
     * public stack has left. Only surviving field sources can observe it:
     * this deliberately does not pretend to evaluate the departed source's
     * last-known Ability, Tool or Energy text.
     */
    private void capturePokemonLeavePlayEvent(UUID subjectOwner, UUID subjectPokemonId, long subjectEntry, long batch) {
        require(battlefield != null && subjectEntry > 0, "离场事件需要已捕获的场上对象");
        var event = new EffectEventBindings(new EffectTargetResolution.PokemonTarget(subjectOwner, subjectPokemonId), subjectEntry, null, 0);
        var candidates = new ArrayList<QueuedAbility>();
        for (UUID owner : players.keySet()) {
            var field = new ArrayList<>(battlefield.benchView(owner));
            if (battlefield.hasActive(owner)) field.add(battlefield.activeView(owner));
            for (var pokemon : field) for (var ability : activeAbilities(owner, pokemon.pokemonId())) {
                if (!ability.triggered() || !(ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy policy)
                    || policy.trigger() != EffectTrigger.ON_LEAVE_PLAY || !policy.matches(owner, pokemon.pokemonId(), subjectOwner, subjectPokemonId)) continue;
                require(ruleset.triggerTiming() == dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,
                    "此规则包的离场触发时序尚未核验");
                TriggeredAbilityRules.validate(ability);
                var entry = new QueuedAbility(UUID.randomUUID(), 0, owner, pokemon.pokemonId(), ability,
                    abilitySource(owner, pokemon.pokemonId(), ability), bindSourceEvent(owner, pokemon.pokemonId(), event));
                if (!triggerUnused(entry)) continue;
                automaticContext(entry).preflight(ability.effectProgram(), EffectTrigger.ON_LEAVE_PLAY);
                candidates.add(entry);
            }
        }
        for (var listener : persistentListeners()) for (var effect : listener.effects()) {
            if (!(effect.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy policy)
                || policy.trigger() != EffectTrigger.ON_LEAVE_PLAY || !policy.matches(listener.owner(), listener.host(), subjectOwner, subjectPokemonId)) continue;
            var entry = persistentCandidate(listener, effect, event);
            if (!triggerUnused(entry)) continue;
            automaticContext(entry).preflight(effect.effectProgram(), EffectTrigger.ON_LEAVE_PLAY);
            candidates.add(entry);
        }
        captureTriggeredAbilities(candidates, batch);
    }
    /**
     * Captures a completed public card play. The played card is represented
     * only by its server-known category and Trainer subcategory; automatic
     * effects never receive another player's hidden-zone identity. This runs
     * after the whole card has reached its resulting zone, so an unfinished
     * composed Trainer cannot fire an ON_CARD_PLAYED reaction early.
     */
    private void captureCardPlayedEvent(UUID playedBy, CardInstance card) {
        captureCardPlayedEvent(playedBy,List.of(card));
    }
    /** One logical completion can contain two simultaneous Item cards; history records both faces, listeners once. */
    private void captureCardPlayedEvent(UUID playedBy,List<CardInstance> cards) {
        require(battlefield != null && !cards.isEmpty(), "出牌事件需要已完成的公开对局操作");
        CardInstance card=cards.getFirst();
        var history=state(playedBy);
        if(history.handPlayTurn!=turnNumber){history.handPlays.clear();history.handPlayTurn=turnNumber;}
        for(var played:cards)history.handPlays.add(played.definitionId());
        var definition = definition(card);
        var trainerCategory = definition.category() == dev.hua.ptcglive.rules.CardCategory.TRAINER
            ? combat.trainer(card.definitionId()).map(dev.hua.ptcglive.rules.TrainerProfile::category)
                .orElse(dev.hua.ptcglive.rules.TrainerCategory.NONE)
            : dev.hua.ptcglive.rules.TrainerCategory.NONE;
        var event = EffectEventBindings.NONE;
        var candidates = new ArrayList<QueuedAbility>();
        for (UUID owner : players.keySet()) {
            var field = new ArrayList<>(battlefield.benchView(owner));
            if (battlefield.hasActive(owner)) field.add(battlefield.activeView(owner));
            for (var pokemon : field) for (var ability : activeAbilities(owner, pokemon.pokemonId())) {
                if (!ability.triggered() || !(ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.CardPlayedTriggerPolicy policy)
                    || !policy.matches(owner, playedBy, definition.category(), trainerCategory)) continue;
                require(ruleset.triggerTiming() == dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,
                    "此规则包的出牌触发时序尚未核验");
                TriggeredAbilityRules.validate(ability);
                var entry = new QueuedAbility(UUID.randomUUID(), 0, owner, pokemon.pokemonId(), ability,
                    abilitySource(owner, pokemon.pokemonId(), ability), bindSourceEvent(owner, pokemon.pokemonId(), event));
                if (!triggerUnused(entry)) continue;
                automaticContext(entry).preflight(ability.effectProgram(), EffectTrigger.ON_CARD_PLAYED);
                candidates.add(entry);
            }
        }
        for (var listener : persistentListeners()) for (var effect : listener.effects()) {
            if (!(effect.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.CardPlayedTriggerPolicy policy)
                || !policy.matches(listener.owner(), playedBy, definition.category(), trainerCategory)) continue;
            var entry = persistentCandidate(listener, effect, event);
            if (!triggerUnused(entry)) continue;
            automaticContext(entry).preflight(effect.effectProgram(), EffectTrigger.ON_CARD_PLAYED);
            candidates.add(entry);
        }
        captureTriggeredAbilities(candidates, ++triggerEventBatch);
    }
    private void captureTriggeredAbilities(List<QueuedAbility> candidates, long batch) {
        triggeredAbilities.addAll(capturedAbilities(candidates,batch));
    }
    private List<QueuedAbility> capturedAbilities(List<QueuedAbility> candidates, long batch) {
        var captured = new ArrayList<QueuedAbility>();
        for (var entry : candidates) {
            var context = automaticContext(entry);
            var binding = entry.ability().effectProgram().triggers().getFirst();
            // A captured lifecycle event is not by itself an instruction to
            // run a no-op program.  Reuse the same read-only potential check
            // used by manual cards so, for example, a "remove Poison" damage
            // trigger does not later fail when the source is not Poisoned.
            // This performs no random operation, hidden-zone access or state
            // mutation; the actual event predicates are still latched here.
            // Pokémon Checkup has a mandatory status step which is deliberately
            // orderable with captured effects.  A heal can be ineffective before
            // that step and effective afterwards, so filtering it by its current
            // potential would incorrectly remove a legal ordering choice.
            // Attachment healing (e.g. Herbal Energy) can follow simultaneous counters even at full HP.
            boolean attachmentHealing = binding.trigger()==EffectTrigger.ON_ENERGY_ATTACHED
                &&!entry.ability().eventPolicy().optional()&&!binding.effects().isEmpty()
                &&binding.effects().stream().allMatch(e->e.type().equals("heal")&&e.target()==EffectTarget.TRIGGER_POKEMON);
            boolean potentialCanChangeDuringCheckup = attachmentHealing || binding.trigger() == EffectTrigger.ON_POKEMON_CHECKUP || entry.ability() instanceof ScheduledPlayerEffect || entry.deckDiscardSource()!=null || entry.handDiscardSource()!=null || entry.benchToActive()!=null;
            if (binding.conditions().stream().allMatch(condition -> ConditionEvaluator.matches(condition, context))
                && (potentialCanChangeDuringCheckup
                    || dev.hua.ptcglive.engine.effect.EffectPotential.canAffect(binding, context, context::canAffect))) captured.add(new QueuedAbility(
                    entry.id(), batch, entry.owner(), entry.pokemonId(), entry.ability(), entry.source(),entry.event(),entry.origin(),entry.cardEntry(),entry.deckDiscardSource(),entry.handDiscardSource(),entry.benchToActive()));
        }
        return List.copyOf(captured);
    }
    public void chooseTriggeredEffect(UUID player, UUID promptId, UUID entryId) {
        requireNoToolOverflow();
        var prompt = triggerOrderPrompt;
        require(triggerPhase() && prompt != null && !prompt.optionalDecision(), "当前没有待排序的触发效果");
        require(prompt.choosingPlayer().equals(player) && prompt.id().equals(promptId), "触发排序请求无权或已过期");
        require(prompt.entries().stream().anyMatch(entry -> entry.id().equals(entryId)), "不能提前选择后续事件的触发效果");
        if (entryId.equals(checkupStatusStep)) {
            triggerOrderPrompt = null;
            resolveCheckupStatuses(); drainTriggeredAbilities(); return;
        }
        var entry = triggeredAbilities.stream().filter(e -> e.id().equals(entryId)).findFirst()
            .orElseThrow(() -> new IllegalArgumentException("触发效果不在当前候选中"));
        triggerOrderPrompt = null; triggeredAbilities.remove(entry);
        recordReplay(player, "选择触发顺序：" + entry.auditLabel());
        resolveOrOfferTriggeredAbility(entry); drainTriggeredAbilities();
    }
    public void decideTriggeredEffect(UUID player, UUID promptId, boolean use) {
        requireNoToolOverflow();
        var prompt = triggerOrderPrompt;
        require(triggerPhase() && prompt != null && prompt.optionalDecision() && optionalTriggeredAbility != null,
            "当前没有可选的触发效果");
        require(prompt.choosingPlayer().equals(player) && prompt.id().equals(promptId), "触发确认请求无权或已过期");
        var entry = optionalTriggeredAbility; optionalTriggeredAbility = null; triggerOrderPrompt = null;
        recordReplay(player, (use ? "使用" : "放弃") + (entry.origin().kind() == EffectOrigin.Kind.ABILITY ? "可选触发特性：" : "可选触发效果：") + entry.auditLabel());
        if (use) resolveTriggeredAbility(entry);
        drainTriggeredAbilities();
    }
    private void resolveOrOfferTriggeredAbility(QueuedAbility entry) {
        if(!benchToActiveUsable(entry))return;
        if(entry.ability() instanceof ScheduledPokemonEffect delayed && !delayedStillApplied(delayed)) {removeDelayedEffect(delayed);return;}
        if (entry.ability().eventPolicy().optional()) {
            optionalTriggeredAbility = entry;
            triggerOrderPrompt = new TriggerOrderPrompt(UUID.randomUUID(), entry.owner(), true, List.of(entry.view()),entry.ability().eventPolicy().trigger());
        } else resolveTriggeredAbility(entry);
    }
    private void resolveTriggeredAbility(QueuedAbility entry) {
        if(!benchToActiveUsable(entry))return;
        if(programHasRule(entry.ability().effectProgram(),"knockout_cards_to_hand")
            &&!knockoutCardsToHandAllowed(entry.owner(),entry.pokemonId(),entry.event().sourceEntrySequence(),entry.event(),
                dev.hua.ptcglive.engine.effect.KnockoutCardsToHand.opponentOnly(entry.ability().effectProgram().triggers().getFirst().effects().getFirst())))return;
        if(programHasRule(entry.ability().effectProgram(),"knockout_top_to_hand")
            &&!knockoutTopToHandAllowed(entry.owner(),entry.pokemonId(),entry.event().sourceEntrySequence(),entry.event()))return;
        if(entry.ability().eventPolicy() instanceof DamageTriggerPolicy policy && policy.fullHpOnly() && policy.lethalOnly()) {
            if(attackCheckpoint==null
                || attackCheckpoint.damage.stream().noneMatch(d->d.owner().equals(entry.owner())&&d.pokemonId().equals(entry.pokemonId())
                    &&sameFieldEntry(d.owner(),d.pokemonId(),d.entrySequence())&&damageReactionMatches(policy,d)))return;
        }
        var event = entry.ability().eventPolicy().trigger();
        if(sharedUsageExhausted(entry.owner(),entry.ability().usageLimit())
            || effectLifecycle.usageLimited(entry.source(),event,turnNumber,entry.ability().eventPolicy().usage()))return;
        var context = automaticContext(entry);
        context.preflight(entry.ability().effectProgram(), event);
        require(!resolvingEffectProgram && pendingResolution==null,"上一效果尚未完成");
        var cursor=effectLifecycle.beginCaptured(entry.source(),event,turnNumber,context,entry.ability().eventPolicy().usage());
        consumeSharedUsage(entry.owner(),entry.ability().usageLimit());
        pendingResolution=new PendingResolution(UUID.randomUUID(),entry.owner(),null,null,cursor,
            new MatchClientView.AbilityResolution(entry.pokemonId(),entry.ability().id(),entry.ability().nameZh(),entry.origin().kind()),null,entry);
        if(entry.ability() instanceof AbilityDefinition ability&&ability.endsTurn())endTurnAfterCardResolution=pendingResolution.id();
        resolvingEffectProgram=true;
        recordReplay(entry.owner(), (entry.origin().kind() == EffectOrigin.Kind.ABILITY ? "结算触发特性：" : "结算触发效果：") + entry.auditLabel());
        advancePendingResolution();
    }
    private void drainTriggeredAbilities() {
        if(pendingNativeCoinChoice!=null)return;
        if(toolOverflowPrompt()!=null)return;
        if (pendingEnergyHandCost!=null || pendingKnockoutDisposal!=null || drainingTriggers || advancingResolution || resolvingEffectProgram || pendingResolution != null
            || triggerOrderPrompt != null || !triggerPhase() || attackCheckpoint!=null && !attackCheckpoint.textComplete) return;
        drainingTriggers = true;
        try {
            if(attackCheckpoint!=null && !attackCheckpoint.reactionsCaptured) captureDamageReactions();
            while (triggerPhase() && triggerOrderPrompt == null && pendingResolution==null && pendingKnockoutDisposal==null && pendingNativeCoinChoice==null) {
                if(toolOverflowPrompt()!=null)return;
                triggeredAbilities.removeIf(entry -> entry.ability() instanceof ScheduledPokemonEffect delayed && !delayedStillApplied(delayed));
                triggeredAbilities.removeIf(entry -> effectLifecycle.usageLimited(entry.source(), entry.ability().eventPolicy().trigger(),
                    turnNumber, entry.ability().eventPolicy().usage()) || sharedUsageExhausted(entry.owner(),entry.ability().usageLimit()));
                prioritizeDeckDiscardReactions();
                if(deckDiscardCheckpointPending&&!hasDiscardReaction()) {
                    resumeDeckDiscardCheckpoint();if(!triggerPhase())return;continue;
                }
                if(attackCheckpoint!=null && (triggeredAbilities.isEmpty() || triggeredAbilities.getFirst().ability().eventPolicy().trigger()!=EffectTrigger.ON_DAMAGE
                    &&triggeredAbilities.getFirst().deckDiscardSource()==null&&triggeredAbilities.getFirst().handDiscardSource()==null)) {
                    finishAttackCheckpoint();
                    if(pendingNativeCoinChoice!=null)return;
                    if(phase!=MatchPhase.TURN) return;
                }
                if(knockoutCheckpoint!=null && (triggeredAbilities.isEmpty() || triggeredAbilities.getFirst().ability().eventPolicy().trigger()!=EffectTrigger.ON_KNOCKOUT
                    &&triggeredAbilities.getFirst().deckDiscardSource()==null&&triggeredAbilities.getFirst().handDiscardSource()==null)) {
                    commitKnockoutCheckpoint();
                    if(pendingNativeCoinChoice!=null)return;
                    if(!triggerPhase()) return;
                    if(knockoutCheckpoint!=null)continue;
                }
                if (triggeredAbilities.isEmpty()) {
                    if(phase==MatchPhase.TURN&&!prizeEffectFrames.isEmpty()) {
                        if(startingPrizeEffect)return;
                        resumePrizeEffect();
                        if(phase==MatchPhase.TURN)continue;
                        return;
                    }
                    if(phase==MatchPhase.TURN&&emergencyEntryTurnStartPending) {
                        emergencyEntryTurnStartPending=false;
                        runTurnStart();
                        if(phase!=MatchPhase.TURN)return;
                        continue;
                    }
                    if (phase == MatchPhase.TURN && turnStartInProgress) {
                        turnStartInProgress = false;
                        recordReplay(currentPlayer, "回合开始效果完成");
                        settleHitPointChanges();
                        // A start-of-turn expiry can itself create a KO.  We
                        // are already inside this dispatcher, so keep the
                        // same loop alive to commit its unified prize and
                        // replacement checkpoint instead of stranding it.
                        if (knockoutCheckpoint != null) continue;
                        return;
                    }
                    if(phase==MatchPhase.TURN_END) {
                        // A non-KO departure must be replaced before Checkup or the next turn's draw.
                        if(deferEmptyActiveSettlement) {
                            deferEmptyActiveSettlement=false;
                            settleEmptyActives();
                            if(phase!=MatchPhase.TURN_END)return;
                        }
                        turnEndInProgress=false;
                        recordReplay(currentPlayer,"回合末效果完成");
                        runCheckup();
                        if(triggerPhase())continue;
                        return;
                    }
                    if (phase == MatchPhase.POKEMON_CHECKUP) {
                        if (checkupStatusStep != null) resolveCheckupStatuses();
                        if(!triggeredAbilities.isEmpty())continue;
                        if(toolOverflowPrompt()!=null)return;
                        finishCheckup();
                        if(knockoutCheckpoint!=null) continue;
                        // Advancing from Checkup starts the next player's turn
                        // while this dispatcher is still on the stack.  Keep
                        // draining so the newly captured start-of-turn queue
                        // cannot be stranded behind this old Checkup frame.
                        if (phase == MatchPhase.TURN && turnStartInProgress) continue;
                    }
                    if (phase == MatchPhase.TURN && deferEmptyActiveSettlement) {
                        deferEmptyActiveSettlement = false;
                        settleHitPointChanges();
                        if (knockoutCheckpoint != null) continue;
                    }
                    if (phase == MatchPhase.TURN) settleEmptyActives();
                    return;
                }
                long batch = triggeredAbilities.getFirst().batch();
                var simultaneous = triggeredAbilities.stream().filter(entry -> entry.batch() == batch).toList();
                if (simultaneous.size() > 1 || checkupStatusStep != null) {
                    var entries = new ArrayList<>(simultaneous.stream().map(QueuedAbility::view).toList());
                    if (checkupStatusStep != null) entries.add(new TriggerOrderPrompt.Entry(checkupStatusStep,other(currentPlayer).id,null,"双方异常状态（中毒→灼伤→睡眠→麻痹）"));
                    var event=simultaneous.getFirst().ability().eventPolicy().trigger();
                    // One knocked-out Pokemon's own reactions (e.g. Wishful Baton and Exp. Share)
                    // are ordered by its controller. A multi-Pokemon KO retains the shared timing rule.
                    var subject=simultaneous.getFirst().event().triggerPokemon();
                    boolean ownSingleKnockout=event==EffectTrigger.ON_KNOCKOUT&&checkupStatusStep==null
                        &&knockoutCheckpoint!=null&&knockoutCheckpoint.confirmed.size()==1&&subject!=null
                        &&simultaneous.stream().allMatch(entry->entry.owner().equals(subject.owner())
                            &&subject.equals(entry.event().triggerPokemon()));
                    UUID orderingPlayer=ownSingleKnockout?subject.owner():phase==MatchPhase.POKEMON_CHECKUP ? other(currentPlayer).id
                        : event==EffectTrigger.ON_DAMAGE ? simultaneous.getFirst().owner() : currentPlayer;
                    triggerOrderPrompt = new TriggerOrderPrompt(UUID.randomUUID(),orderingPlayer,false,entries,event);
                    return;
                }
                resolveOrOfferTriggeredAbility(triggeredAbilities.removeFirst());
            }
        } finally { drainingTriggers = false; finishResumableAttackTurn(); }
    }
    private void finishResumableAttackTurn() {
        if(pendingNativeCoinChoice!=null)return;
        if(toolOverflowPrompt()!=null)return;
        if ((!endingResumableAttack && !endingResumableCardTurn && !endingPromotionTurn) || phase != MatchPhase.TURN || resolvingEffectProgram || advancingResolution
            || attackCheckpoint != null || knockoutCheckpoint != null || pendingResolution != null || triggerOrderPrompt != null || !triggeredAbilities.isEmpty() || deckDiscardCheckpointHeld()) return;
        if(endingResumableAttack&&!endingResumableCardTurn&&!endingPromotionTurn&&allowFestivalSecondAttack(currentPlayer)) {
            endingResumableAttack=false;
            recordReplay(currentPlayer,"Festival Lead：本回合可以进行第2次攻击");
            return;
        }
        endingResumableAttack = false;
        endingResumableCardTurn = false;
        endingPromotionTurn = false;
        runTurnEnd();
    }
    private boolean allowFestivalSecondAttack(UUID player) {
        var state=state(player);
        UUID pokemon=state.lastAttackPokemonId;
        return state.attacksMadeThisTurn==1&&pokemon!=null&&stadiumHasPassiveRule("festival_ground")
            &&battlefield.hasActive(player)&&battlefield.activeView(player).pokemonId().equals(pokemon)
            &&pokemonHasPassiveRule(player,pokemon,"festival_attack_twice");
    }
    private void endTurnAfterAttackAttempt(UUID player) {
        if(allowFestivalSecondAttack(player))recordReplay(player,"Festival Lead：本回合可以进行第2次攻击");
        else runTurnEnd();
    }
