    public ServerMatch(UUID matchId, UUID first, UUID second, List<CardInstance> firstDeck, List<CardInstance> secondDeck,
                       Ruleset ruleset, CardDatabase definitions, CombatCatalog combat, ServerRandom random) {
        if (first.equals(second)) throw new IllegalArgumentException("正式对局需要两名不同玩家");
        this.id = Objects.requireNonNull(matchId); this.ruleset = Objects.requireNonNull(ruleset); this.definitions = Objects.requireNonNull(definitions);
        require(ruleset.edition().matchEnabled(), "此规则档案尚未核验，不能开局：" + ruleset.edition().noticeZh());
        require(ruleset.setupProcedure() == dev.hua.ptcglive.rules.SetupProcedure.INTERNATIONAL_V1, "此开局流程版本尚未接入服务器");
        this.combat = Objects.requireNonNull(combat); this.random = Objects.requireNonNull(random);
        dev.hua.ptcglive.engine.effect.HitPointEnergyDependencies.unsupportedReason(combat,java.util.stream.Stream.concat(firstDeck.stream(),secondDeck.stream()).toList())
            .ifPresent(reason->{throw new IllegalArgumentException(reason);});
        if(java.util.stream.Stream.concat(firstDeck.stream(),secondDeck.stream())
            .anyMatch(card->combat.energyProfile(card.definitionId()).filter(profile->!profile.attachmentRule().pokemonTypes().isEmpty()).isPresent()))
            java.util.stream.Stream.concat(firstDeck.stream(),secondDeck.stream())
            .map(CardInstance::definitionId).distinct().forEach(card->combat.fieldPokemon(card).ifPresent(profile->
                require(profile.pokemonType()!=null||!definitions.find(card).orElseThrow().pokemonTypes().isEmpty(),"当前特殊能量附着规则需要完整宝可梦属性资料："+card)));
        java.util.stream.Stream.concat(firstDeck.stream(), secondDeck.stream()).map(CardInstance::definitionId).distinct()
            .forEach(card -> combat.fieldPokemon(card).ifPresent(profile -> profile.abilities().stream().filter(AbilityDefinition::triggered).forEach(ability -> {
                require(ruleset.triggerTiming() != dev.hua.ptcglive.rules.TriggerTiming.UNVERIFIED, "此规则包的自动触发时序尚未核验");
                TriggeredAbilityRules.validate(ability);
            })));
        this.battlefield = combat.isConfigured() ? new BattlefieldState(first, second, combat.fieldPokemonProfiles(), random, this::retreatReduction,
            ruleset.turnActionRules().energyAttachmentsFromHand(), ruleset.turnActionRules().retreats(), ruleset.matchSetupRules().benchLimit(),
            this::passiveHitPointsChange,
            (owner,pokemon)->passiveModifiers(owner,pokemon).freeRetreat(),
            (owner,pokemon)->hasToolPassiveRule(owner,pokemon,"retreat_while_asleep_or_paralyzed"),this::benchLimit) : null;
        if(battlefield!=null)battlefield.effectSourceKind(()-> {
            var origin=effectOrigin(currentPlayer==null?first:currentPlayer);
            return origin.kind()==EffectOrigin.Kind.RULE&&attackCheckpoint!=null?EffectOrigin.Kind.ATTACK:origin.kind();
        });
        players.put(first, prepare(first, firstDeck)); players.put(second, prepare(second, secondDeck));
        historyDecks.put(first,firstDeck.stream().map(CardInstance::definitionId).distinct().toList());
        historyDecks.put(second,secondDeck.stream().map(CardInstance::definitionId).distinct().toList());
        java.util.stream.Stream.concat(firstDeck.stream(),secondDeck.stream()).forEach(c->historyInstances.put(c.instanceId(),c.definitionId()));
        // Validate and lock the decks now, but do not shuffle or deal before turn order is decided.
        phase = MatchPhase.COIN_CALL; coinCaller = first;
    }
