    public UUID pendingChoicePlayer() {
        if(pendingNativeCoinChoice!=null)return pendingNativeCoinChoice.owner();
        if(pendingPrizeSearch!=null)return pendingPrizeSearch.owner();
        if(pendingPrizeEnergy!=null)return pendingPrizeEnergy.owner();
        if(pendingPrizeItem!=null)return pendingPrizeItem.owner();
        if(pendingQuiz!=null)return pendingQuiz.page()==-2?pendingQuiz.owner():other(pendingQuiz.owner()).id;
        if(pendingPrizeReactionOrder!=null)return prizeWindows.getFirst().owner;
        if(pendingEnergyHandCost!=null)return pendingEnergyHandCost.owner;
        if(pendingRockPaperScissors!=null)return pendingRockPaperScissors.first()==null
            ?pendingRockPaperScissors.actor():other(pendingRockPaperScissors.actor()).id;
        if(pendingKnockoutDisposal!=null)return pendingKnockoutDisposal.subject().owner();
        var overflow=toolOverflowPrompt();if(overflow!=null)return overflow.owner();
        if (triggerOrderPrompt != null) return triggerOrderPrompt.choosingPlayer();
        if (pendingReveal != null) return pendingReveal.view().confirmingPlayer();
        if (opponentChoosingCopiedAttack()) return other(pendingResolution.actor()).id;
        if (pendingPokemon != null) return pendingPokemon.chooser();
        if (pendingOpponentDiscard != null) return pendingOpponentDiscard.chooser();
        if (pendingPrizeTake != null) return pendingPrizeTake.owner();
        if (pendingLuckyBonus != null) return pendingLuckyBonus.player();
        if (pendingCustomCards != null && pendingResolution != null) return pendingResolution.actor();
        if (pendingZone != null && pendingResolution != null) return zoneSelectionChooser(pendingResolution.actor(),pendingZone.contract());
        if (pendingResolution != null) {
            var choice=pendingResolution.continuation().pendingChoice();
            if(choice!=null&&"OPPONENT".equals(choice.definition().arguments().get("chooser")))return other(pendingResolution.actor()).id;
            return pendingResolution.actor();
        }
        if (phase == MatchPhase.PRIZE_SELECTION) return prizeClaims.getFirst().player;
        if (phase == MatchPhase.CHOOSE_REPLACEMENT) return replacements.getFirst();
        if (phase == MatchPhase.COIN_CALL) return coinCaller;
        if (phase == MatchPhase.TURN_ORDER) return coinWinner;
        return currentPlayer;
    }
