    /** A deterministic, nonredundant payment suggestion for the existing quick-retreat UI, not a payment decision from the client. */
    public java.util.Optional<List<UUID>> suggestedRetreatPayment(UUID player) {
        requireCombatConfigured();
        if(battlefield==null||!battlefield.hasActive(player))return java.util.Optional.empty();
        if(battlefield.activeProfile(player).printedRules().preventsRetreat())return java.util.Optional.empty();
        int cost=activeRetreatCost(player);
        if(cost==0)return java.util.Optional.of(List.of());
        UUID active=battlefield.activeView(player).pokemonId();
        var selected=new ArrayList<CardInstance>();var units=new LinkedHashMap<UUID,Integer>();int total=0;
        for(var card:battlefield.attachedEnergy(player,active)) {
            int provided=currentEnergyProfile(player,active,card).unitCount();
            selected.add(card);units.put(card.instanceId(),provided);total+=provided;
            if(total>=cost)break;
        }
        if(total<cost)return java.util.Optional.empty();
        for(int i=selected.size()-1;i>=0;i--) {
            int provided=units.get(selected.get(i).instanceId());
            if(total-provided>=cost){total-=provided;selected.remove(i);}
        }
        return java.util.Optional.of(selected.stream().map(CardInstance::instanceId).toList());
    }
    /** Recomputed from current public sources, never cached across evolution, replacement or Knock Out. */
    private int retreatReduction(UUID player, UUID pokemonId) {
        return -passiveModifiers(player,pokemonId).retreatCostChange();
    }
    /**
     * Current implementation models only printed Colorless cost changes. A
     * reduction never erases a typed Energy symbol; an increase adds generic
     * Colorless symbols. Both UI affordability and declaration use this one
     * server calculation.
     */
    private Map<dev.hua.ptcglive.engine.field.EnergyType,Integer> currentAttackCost(UUID player, UUID pokemonId, AttackDefinition attack) {
        var context=new ServerConditionContext(player,pokemonId);
        var override=dev.hua.ptcglive.engine.effect.AttackCostOverride.current(attack.effectProgram(),context,attack.id());
        if(override.isPresent())return override.get();
        for(var ability:activeAbilities(player,pokemonId))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()) {
            try {
                override=dev.hua.ptcglive.engine.effect.AttackCostOverride.current(ability.effectProgram(),context,attack.id());
                if(override.isPresent())return override.get();
            } catch(IllegalArgumentException ignored) { /* Other passive programs do not declare an attack-cost override. */ }
        }
        var cost = new java.util.EnumMap<dev.hua.ptcglive.engine.field.EnergyType,Integer>(dev.hua.ptcglive.engine.field.EnergyType.class);
        cost.putAll(attack.energyCost());
        var modifiers=passiveModifiers(player,pokemonId);
        if(modifiers.ignoreAllAttackCost())return Map.of();
        int generic = cost.getOrDefault(dev.hua.ptcglive.engine.field.EnergyType.COLORLESS, 0);
        int changed = modifiers.ignoreColorlessAttackCost()?0:Math.max(0, Math.addExact(generic, Math.addExact(modifiers.attackCostChange(), battlefield.attackCostIncrease(player,pokemonId))));
        if (changed == 0) cost.remove(dev.hua.ptcglive.engine.field.EnergyType.COLORLESS);
        else cost.put(dev.hua.ptcglive.engine.field.EnergyType.COLORLESS, changed);
        modifiers.typedAttackCostChanges().forEach((type,amount)->{
            int remaining=Math.max(0,Math.addExact(cost.getOrDefault(type,0),amount));
            if(remaining==0)cost.remove(type);else cost.put(type,remaining);
        });
        return Map.copyOf(cost);
    }
    /** Every query discovers current attached/live sources; no activation, random draw or persistent cache. */
    private int passiveHitPointsChange(UUID owner,UUID pokemon) {
        var hp=passiveModifiers(owner,pokemon,true);
        return Math.addExact(hp.hitPointsChange(),hp.baseHitPoints()==0?0:hp.baseHitPoints()-battlefield.pokemonProfile(owner,pokemon).hitPoints());
    }
    private PassiveModifierProgram.Values passiveModifiers(UUID targetOwner,UUID targetId) {
        return passiveModifiers(targetOwner,targetId,false);
    }
    private PassiveModifierProgram.Values passiveModifiers(UUID targetOwner,UUID targetId,boolean hpOnly) {
        var result=PassiveModifierProgram.Values.NONE;
        var nonstackGroups=new java.util.HashSet<String>();
        for(UUID owner:players.keySet()) {
            var field=new ArrayList<>(battlefield.printedBenchView(owner));
            if(battlefield.hasActive(owner))field.add(battlefield.printedActiveView(owner));
            for(var host:field) {
                if(!host.attachedTools().isEmpty()&&!toolEffectsDisabled(owner,host.pokemonId()))for(var tool:host.attachedTools()) {
                    var profile=combat.trainer(tool.definitionId()).orElseThrow();
                    result=result.plus(passiveValues(profile.ongoingProgram(),new EffectOrigin(EffectOrigin.Kind.TRAINER,owner,tool.instanceId()),host.pokemonId(),targetOwner,targetId,hpOnly));
                }
                for(var card:battlefield.attachedEnergy(owner,host.pokemonId())) {
                    var profile=effectiveEnergyCard(owner,card);
                    if(!profile.passiveProgram().isEmpty())result=result.plus(passiveValues(profile.passiveProgram(),new EffectOrigin(EffectOrigin.Kind.ENERGY,owner,card.instanceId()),host.pokemonId(),targetOwner,targetId,hpOnly));
                }
                boolean modifierSource=battlefield.activeAbilities(owner,host.pokemonId()).stream().anyMatch(a->
                    a.kind()==AbilityDefinition.Kind.PASSIVE&&a.effectSupport()==EffectSupport.SUPPORTED&&a.composed()
                        &&PassiveModifierProgram.hasValues(a.effectProgram(),hpOnly));
                if(modifierSource)for(var ability:activeAbilities(owner,host.pokemonId())) {
                    if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.effectSupport()==EffectSupport.SUPPORTED&&ability.composed()) {
                        var values=passiveValues(ability.effectProgram(),new EffectOrigin(EffectOrigin.Kind.ABILITY,owner,host.pokemonId()),host.pokemonId(),targetOwner,targetId,hpOnly);
                        String group=dev.hua.ptcglive.engine.effect.PassiveModifierProgram.nonstackGroup(ability.effectProgram());
                        if(!values.equals(PassiveModifierProgram.Values.NONE)&&(group==null||nonstackGroups.add(owner+":"+group)))result=result.plus(values);
                    }
                }
            }
        }
        if(stadium!=null) {
            var profile=combat.trainer(stadium.definitionId()).orElseThrow();
            result=result.plus(passiveValues(profile.ongoingProgram(),new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId()),null,targetOwner,targetId,hpOnly));
        }
        return result;
    }
    /**
     * The one ability read path for this match. Printed card text remains on
     * the card, but temporary locks and persistent data-driven suppressions
     * are both enforced before any activation, passive query, or trigger scan.
     */
    private List<AbilityDefinition> activeAbilities(UUID affectedOwner, UUID pokemonId) {
        if (battlefield == null) return List.of();
        if(timedAbilitiesSuppressed(affectedOwner,pokemonId))return List.of();
        var printed=battlefield.activeAbilities(affectedOwner,pokemonId);
        if(printed.isEmpty())return List.of(); // No ability can be suppressed or granted by these queries.
        String directExemption=activeAbilitySuppressionExemption(affectedOwner,pokemonId);
        if(directExemption!=null)return printed.stream()
            .filter(ability->ability.id().equals(directExemption)).toList();
        if(abilitySuppressed(affectedOwner, pokemonId)) return List.of();
        String exempt=zoneSuppressionSourceId(affectedOwner,pokemonId);
        boolean damp=printed.stream().anyMatch(this::abilityRequiresSelfKnockout)&&dampActive();
        return printed.stream()
            .filter(a->exempt==null||a.id().equals(exempt))
            .filter(a->!damp||!abilityRequiresSelfKnockout(a)).toList();
    }
    /** Exact live suppression used by current Rule-Box and opposing-Active effects; a non-null ID is the printed exception. */
    private String activeAbilitySuppressionExemption(UUID affectedOwner,UUID pokemonId) {
        if(battlefield==null)return null;
        var target=fieldCardDefinition(battlefield.printedPokemonView(affectedOwner,pokemonId).topCardId());
        boolean targetActive=battlefield.hasActive(affectedOwner)&&battlefield.printedActiveView(affectedOwner).pokemonId().equals(pokemonId);
        for(UUID controller:players.keySet()) {
            if(!battlefield.hasActive(controller))continue;
            if(!controller.equals(affectedOwner)&&abilityGuardTool(affectedOwner,pokemonId))continue;
            var source=battlefield.printedActiveView(controller);
            if(timedAbilitiesSuppressed(controller,source.pokemonId())||zoneSuppressionSourceId(controller,source.pokemonId())!=null)continue;
            if(basicZoneStadium()&&persistentAbilitySuppressed(controller,source.pokemonId()))continue;
            for(var ability:battlefield.activeAbilities(controller,source.pokemonId()))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed())
                for(var binding:ability.effectProgram().triggers())for(var effect:binding.effects())if(effect.type().equals("suppress_abilities")) {
                    var args=effect.arguments();
                    if("ALL_IN_PLAY".equals(args.get("scope"))&&args.containsKey("rule_box_only")
                        &&target.pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.RULE_BOX)
                        &&!target.pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.FUTURE))return "";
                    if("OPPONENT_ACTIVE".equals(args.get("scope"))&&!controller.equals(affectedOwner)&&targetActive)
                        return args.getOrDefault("except_ability_id","");
                }
        }
        return null;
    }
    private boolean resolvingDamp;
    private boolean dampActive() {
        if(resolvingDamp)return false;
        resolvingDamp=true;
        try {
            for(UUID owner:players.keySet())for(var host:publicFieldTargets(owner)) {
                if(abilitySuppressed(owner,host.pokemonId()))continue;
                for(var ability:battlefield.activeAbilities(owner,host.pokemonId()))
                    if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()&&ability.effectSupport()==EffectSupport.SUPPORTED
                        &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(owner,host.pokemonId()),
                            effect->effect.type().equals("suppress_self_knockout_abilities")))return true;
            }
            return false;
        } finally {resolvingDamp=false;}
    }
    private boolean abilityRequiresSelfKnockout(AbilityDefinition ability) {
        return ability.effectProgram().triggers().stream().flatMap(binding->binding.effects().stream()).anyMatch(this::containsSelfKnockout);
    }
    private boolean containsSelfKnockout(EffectDefinition effect) {
        return effect.type().equals("knock_out")&&effect.target()==EffectTarget.SELF
            ||effect.effects().stream().anyMatch(this::containsSelfKnockout);
    }
    private EnergyType memoryType(UUID owner,UUID pokemon) {
        if(!"Silvally-GX".equals(battlefield.pokemonProfile(owner,pokemon).pokemonName())||toolEffectsDisabled(owner,pokemon))return null;
        EnergyType result=null;
        for(var tool:battlefield.printedPokemonView(owner,pokemon).attachedTools()) {
            var profile=combat.trainer(tool.definitionId()).orElse(null);if(profile==null)continue;
            for(var binding:profile.ongoingProgram().triggers())for(var effect:binding.effects())
                if(effect.type().equals("pokemon_type_override"))result=EnergyType.valueOf(effect.arguments().get("pokemon_type"));
        }
        return result;
    }
    private EnergyType currentPrimaryPokemonType(UUID owner,UUID pokemon) {
        var memory=memoryType(owner,pokemon);return memory!=null?memory:battlefield.pokemonProfile(owner,pokemon).pokemonType();
    }
    private Set<dev.hua.ptcglive.rules.PokemonFamily> currentPokemonFamilies(UUID owner,UUID pokemon) {
        var result=java.util.EnumSet.noneOf(dev.hua.ptcglive.rules.PokemonFamily.class);
        result.addAll(fieldCardDefinition(battlefield.printedPokemonView(owner,pokemon).topCardId()).pokemonFamilies());
        if(!toolEffectsDisabled(owner,pokemon))for(var tool:battlefield.printedPokemonView(owner,pokemon).attachedTools())
            if(combat.trainer(tool.definitionId()).map(profile->programHasRule(profile.ongoingProgram(),"add_pokemon_families")).orElse(false))
                result.add(dev.hua.ptcglive.rules.PokemonFamily.TEAM_PLASMA);
        return Set.copyOf(result);
    }
    /** Preserve printed identity and legality while querying live field types and affiliation. */
    private CardDefinition currentFieldDefinition(UUID owner,UUID pokemon) {
        var printed=fieldCardDefinition(battlefield.printedPokemonView(owner,pokemon).topCardId());
        var types=currentPokemonTypes(owner,pokemon);var families=currentPokemonFamilies(owner,pokemon);
        if(types.equals(printed.pokemonTypes())&&families.equals(printed.pokemonFamilies()))return printed;
        return new CardDefinition(printed.id(),printed.nameZh(),printed.category(),printed.trainerCategory(),printed.regulationMark(),
            printed.regions(),printed.basicPokemon(),printed.basicEnergy(),printed.copyLimit(),printed.specialDeckLimits(),
            printed.effectSupport(),printed.unsupportedReasonZh(),families,types,printed.battleStyles());
    }
    private boolean resolvingCurrentPokemonTypes;
    /** Current in-play types, including reviewed passive type additions; recursion falls back to printed facts. */
    private Set<EnergyType> currentPokemonTypes(UUID owner,UUID pokemonId) {
        var result=java.util.EnumSet.noneOf(EnergyType.class);
        var view=battlefield.printedPokemonView(owner,pokemonId);
        var printed=fieldCardDefinition(view.topCardId()).pokemonTypes();
        if(printed.isEmpty()) {
            var fallback=battlefield.pokemonProfile(owner,pokemonId).pokemonType();
            if(fallback!=null)result.add(fallback);
        } else result.addAll(printed);
        var memory=memoryType(owner,pokemonId);if(memory!=null){result.clear();result.add(memory);}
        if(resolvingCurrentPokemonTypes)return Set.copyOf(result);
        resolvingCurrentPokemonTypes=true;
        try {
            if(!abilitySuppressed(owner,pokemonId))for(var ability:battlefield.activeAbilities(owner,pokemonId)) {
                if(ability.kind()!=AbilityDefinition.Kind.PASSIVE||!ability.composed()||ability.effectSupport()!=EffectSupport.SUPPORTED)continue;
                var context=new ServerConditionContext(owner,pokemonId);
                for(var type:EnergyType.values())if(dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(
                    ability.effectProgram(),context,effect->effect.type().equals("add_pokemon_types")
                        &&dev.hua.ptcglive.engine.effect.PokemonTypeFilter.fromWire(effect.arguments().get("pokemon_types")).types().contains(type)))result.add(type);
            }
        } finally {resolvingCurrentPokemonTypes=false;}
        return Set.copyOf(result);
    }
    private Set<EnergyType> attackDamageTypes(UUID owner,UUID pokemonId,AttackDefinition attack) {
        if(memoryType(owner,pokemonId)!=null)return currentPokemonTypes(owner,pokemonId);
        var printed=battlefield.pokemonProfile(owner,pokemonId).pokemonType();
        // A body materialized with an explicit different type (copied/synthetic attack) uses that type alone.
        // Otherwise live added Pokémon types also apply to its attacks.
        if(attack.damageType()!=null&&attack.damageType()!=printed)return Set.of(attack.damageType());
        return currentPokemonTypes(owner,pokemonId);
    }
    private AbilityDefinition beginAbility(UUID player, UUID pokemonId, String abilityId) {
        require(activeAbilities(player,pokemonId).stream().anyMatch(a->a.id().equals(abilityId)),"该特性当前失效");
        return battlefield.beginAbility(player, pokemonId, abilityId);
    }
    /**
     * Persistent sources are queried live, so removing or replacing a Stadium
     * restores printed Abilities immediately and never leaves a stale lock on
     * a Pokémon. The query is server-only and uses the actual in-play card.
     */
    private boolean abilitySuppressed(UUID affectedOwner, UUID pokemonId) {
        if(battlefield==null)return false;
        if(timedAbilitiesSuppressed(affectedOwner,pokemonId))return true;
        if(persistentAbilitySuppressed(affectedOwner,pokemonId))return true;
        var target=fieldCardDefinition(battlefield.printedPokemonView(affectedOwner,pokemonId).topCardId());
        if(!target.basicPokemon()||target.pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.RULE_BOX))return false;
        UUID opponent=other(affectedOwner).id;if(!battlefield.hasActive(opponent))return false;
        var host=battlefield.printedActiveView(opponent);
        if(!fieldCardDefinition(host.topCardId()).pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.RULE_BOX)
            ||persistentAbilitySuppressed(opponent,host.pokemonId())||timedAbilitiesSuppressed(opponent,host.pokemonId()))return false;
        for(var ability:battlefield.activeAbilities(opponent,host.pokemonId()))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&zoneSuppressionSourceId(opponent,host.pokemonId())==null
                &&AbilitySuppressionProgram.hasRuleBoxSource(ability.effectProgram())
                &&suppressesAbilities(ability.effectProgram(),new EffectOrigin(EffectOrigin.Kind.ABILITY,opponent,host.pokemonId()),affectedOwner,pokemonId))return true;
        return false;
    }
    /** Acyclic discovery: sources are evolved, self-exempt and depend only on a physical Tool plus non-Ability locks. */
    private String zoneSuppressionSourceId() { return zoneSuppressionSourceId(null,null); }
    private String zoneSuppressionSourceId(UUID affectedOwner,UUID pokemonId) {
        if(battlefield==null)return null;
        for(UUID owner:players.keySet())for(var host:publicFieldTargets(owner)) {
            if(affectedOwner!=null&&!owner.equals(affectedOwner)&&abilityGuardTool(affectedOwner,pokemonId))continue;
            var view=battlefield.printedPokemonView(owner,host.pokemonId());
            if(timedAbilitiesSuppressed(owner,host.pokemonId()))continue;
            if(view.attachedTools().isEmpty()||fieldCardDefinition(view.topCardId()).basicPokemon())continue;
            for(var ability:battlefield.activeAbilities(owner,host.pokemonId())) {
                String exempt=AbilitySuppressionProgram.zoneSourceId(ability.effectProgram());
                if(exempt!=null&&ability.effectSupport()==EffectSupport.SUPPORTED&&!persistentAbilitySuppressed(owner,host.pokemonId()))return exempt;
            }
        }
        return null;
    }
    private boolean timedAbilitiesSuppressed(UUID owner,UUID pokemon) {
        if(players.values().stream().anyMatch(p->p.globalAbilitySuppression!=null
            &&p.globalAbilitySuppression.unaffected().entrySet().stream().noneMatch(entry->
                entry.getKey().target().equals(new EffectTargetResolution.PokemonTarget(owner,pokemon))
                &&sameFieldEntry(owner,pokemon,entry.getKey().entrySequence())
                &&battlefield.topCard(owner,pokemon).instanceId().equals(entry.getValue()))))return true;
        var suppression=other(owner).activeAbilitySuppression;
        if(suppression==null||suppression.turn()!=turnNumber||!battlefield.hasActive(owner)
            ||!battlefield.printedActiveView(owner).pokemonId().equals(pokemon))return false;
        var target=suppression.unaffected();
        return target==null||!target.target().equals(new EffectTargetResolution.PokemonTarget(owner,pokemon))
            ||!sameFieldEntry(owner,pokemon,target.entrySequence())
            ||!battlefield.topCard(owner,pokemon).instanceId().equals(suppression.top());
    }
    /** Hand/discard only. Deck and Prize triggers retain their printed pre-movement abilities. */
    private boolean offFieldAbilitiesSuppressed(CardInstance card) {
        return offFieldAbilitiesSuppressed(card.definitionId());
    }
    private boolean offFieldAbilitiesSuppressed(String definitionId) {
        var definition=fieldCardDefinition(definitionId);
        return definition.category()==CardCategory.POKEMON
            &&(players.values().stream().anyMatch(p->p.globalAbilitySuppression!=null)
                ||definition.basicPokemon()&&basicZoneStadium());
    }
    private boolean basicZoneStadium() {
        return stadium!=null&&AbilitySuppressionProgram.basicZoneStadium(combat.trainer(stadium.definitionId()).orElseThrow().ongoingProgram());
    }
    private boolean rememberedStadiumImmunity(UUID owner,UUID pokemon) {
        return abilityImmunityStadiumEntry==stadiumEntrySequence&&stadiumAbilityImmunity.entrySet().stream().anyMatch(entry->
            entry.getKey().target().equals(new EffectTargetResolution.PokemonTarget(owner,pokemon))
                &&sameFieldEntry(owner,pokemon,entry.getKey().entrySequence())
                &&battlefield.topCard(owner,pokemon).instanceId().equals(entry.getValue()));
    }
    private Map<PokemonCandidate,UUID> currentStadiumAbilityImmunity() {
        var result=new LinkedHashMap<PokemonCandidate,UUID>();
        var origin=new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId());
        for(UUID owner:players.keySet())for(var target:publicFieldTargets(owner))
            if(fieldCardDefinition(battlefield.printedPokemonView(owner,target.pokemonId()).topCardId()).basicPokemon()
                &&preventsImpact(owner,target.pokemonId(),origin,EffectProtection.Impact.OTHER_EFFECTS))
                result.put(new PokemonCandidate(target,battlefield.pokemonEntrySequence(owner,target.pokemonId())),battlefield.topCard(owner,target.pokemonId()).instanceId());
        return Map.copyOf(result);
    }
    /** Remember already-working protection to resolve the Lab/New Moon priority cycle; reads never mutate it. */
    private void refreshStadiumAbilityImmunity() {
        if(refreshingStadiumAbilityImmunity||initializingStadiumAbilitySuppression)return;
        if(!basicZoneStadium()||battlefield==null) {stadiumAbilityImmunity=Map.of();abilityImmunityStadiumEntry=-1;return;}
        refreshingStadiumAbilityImmunity=true;
        try {
            while(true) {
                var next=currentStadiumAbilityImmunity();
                if(next.equals(stadiumAbilityImmunity))break;
                stadiumAbilityImmunity=next;
            }
            abilityImmunityStadiumEntry=stadiumEntrySequence;
        } finally {refreshingStadiumAbilityImmunity=false;}
    }
    private void beginStadiumAbilitySuppression() {
        stadiumAbilityImmunity=Map.of();abilityImmunityStadiumEntry=stadiumEntrySequence;
        if(!basicZoneStadium())return;
        initializingStadiumAbilitySuppression=true;
        try {stadiumAbilityImmunity=currentStadiumAbilityImmunity();}
        finally {initializingStadiumAbilitySuppression=false;}
        refreshStadiumAbilityImmunity();
    }
    private int discardCount(UUID owner,Map<String,String> arguments) {
        if(arguments.containsKey("name_contains")) {
            String wanted=arguments.get("name_contains");
            return (int)state(owner).discard.stream().filter(c->{
                String name=combat.pokemon(c.definitionId()).map(p->p.pokemonName()).orElse(null);
                return name!=null?name.contains(wanted):definitions.find(c.definitionId()).map(d->d.nameZh().contains(wanted)).orElse(false);
            }).count();
        }
        if (arguments.containsKey("definition_ids")) {
            var ids=dev.hua.ptcglive.engine.effect.TurnHistoryCondition.values(arguments.get("definition_ids"));
            return (int)state(owner).discard.stream().filter(c->ids.contains(c.definitionId())).count();
        }
        if("SUPPORTER".equals(arguments.get("trainer_category"))||"STADIUM".equals(arguments.get("trainer_category"))) {
            var category=dev.hua.ptcglive.rules.TrainerCategory.valueOf(arguments.get("trainer_category"));
            return (int)state(owner).discard.stream()
                .filter(c->definition(c).category()==CardCategory.TRAINER)
                .filter(c->definition(c).trainerCategory()==category).count();
        }
        if(arguments.containsKey("card_category")) {
            if("POKEMON".equals(arguments.get("card_category")))
                return (int)state(owner).discard.stream().filter(c->definition(c).category()==CardCategory.POKEMON).count();
            if(!"ENERGY".equals(arguments.get("card_category"))||!"true".equals(arguments.get("basic_energy_only")))
                throw new IllegalArgumentException("弃牌筛选目前只核验基本能量");
            EnergyType type=EnergyType.valueOf(arguments.get("energy_type"));
            return (int)state(owner).discard.stream().filter(c->definition(c).basicEnergy())
                .filter(c->combat.energyType(c.definitionId()).filter(t->t==type).isPresent()).count();
        }
        String id=arguments.get("ability_id");if(id==null)return state(owner).discard.size();
        String exempt=zoneSuppressionSourceId();if(exempt!=null&&!id.equals(exempt))return 0;
        return (int)state(owner).discard.stream().filter(c->definition(c).category()==CardCategory.POKEMON)
            .filter(c->!offFieldAbilitiesSuppressed(c))
            .filter(c->combat.pokemon(c.definitionId()).map(p->p.abilities().stream().anyMatch(a->a.id().equals(id))).orElse(false)).count();
    }
    /** An activation/effect lock does not erase printed possession; actual removal does. */
    private boolean hasPossessedAbilities(UUID owner,UUID pokemon) {
        return !possessedAbilities(owner,pokemon).isEmpty();
    }
    private List<AbilityDefinition> possessedAbilities(UUID owner,UUID pokemon) {
        if(abilitySuppressed(owner,pokemon))return List.of();
        String activeExempt=activeAbilitySuppressionExemption(owner,pokemon);
        String exempt=zoneSuppressionSourceId(owner,pokemon);
        return battlefield.abilities(owner,pokemon).stream()
            .filter(a->activeExempt==null||a.id().equals(activeExempt))
            .filter(a->exempt==null||a.id().equals(exempt)).toList();
    }
    private boolean persistentAbilitySuppressed(UUID affectedOwner, UUID pokemonId) {
        if (battlefield == null) return false;
        for (UUID owner : players.keySet()) {
            var field = new ArrayList<>(battlefield.printedBenchView(owner));
            if (battlefield.hasActive(owner)) field.add(battlefield.printedActiveView(owner));
            for (var host : field) {
                if (!host.attachedTools().isEmpty()&&!toolEffectsDisabled(owner, host.pokemonId())) for (var tool : host.attachedTools()) {
                    var profile = combat.trainer(tool.definitionId()).orElseThrow();
                    if (suppressesAbilities(profile.ongoingProgram(),
                        new EffectOrigin(EffectOrigin.Kind.TRAINER, owner, tool.instanceId()), affectedOwner, pokemonId)) return true;
                }
                for (var energy : battlefield.attachedEnergy(owner, host.pokemonId())) {
                    var profile = effectiveEnergyCard(owner, energy);
                    if (suppressesAbilities(profile.passiveProgram(),
                        new EffectOrigin(EffectOrigin.Kind.ENERGY, owner, energy.instanceId()), affectedOwner, pokemonId)) return true;
                }
            }
        }
        if (stadium != null) {
            var profile = combat.trainer(stadium.definitionId()).orElseThrow();
            if (suppressesAbilities(profile.ongoingProgram(),
                new EffectOrigin(EffectOrigin.Kind.TRAINER, stadiumController, stadium.instanceId()), affectedOwner, pokemonId)) return true;
        }
        return false;
    }
    private boolean suppressesAbilities(EffectProgram program, EffectOrigin origin, UUID affectedOwner, UUID pokemonId) {
        if(program.triggers().stream().filter(binding->binding.trigger()==EffectTrigger.PASSIVE)
            .flatMap(binding->binding.effects().stream()).noneMatch(AbilitySuppressionProgram::contains))return false;
        boolean lab=AbilitySuppressionProgram.basicZoneStadium(program);
        if(lab&&(initializingStadiumAbilitySuppression||!fieldCardDefinition(battlefield.printedPokemonView(affectedOwner,pokemonId).topCardId()).basicPokemon()))return false;
        var query=new AbilitySuppressionQuery(program,origin,affectedOwner,pokemonId);
        if(!resolvingAbilitySuppressionProtection.add(query))return !lab||!rememberedStadiumImmunity(affectedOwner,pokemonId);
        try {
            if (preventsImpact(affectedOwner, pokemonId, origin, EffectProtection.Impact.OTHER_EFFECTS)) return false;
        } finally {
            resolvingAbilitySuppressionProtection.remove(query);
        }
        if(origin.sourceId()!=null&&dev.hua.ptcglive.engine.effect.AbilitySuppressionProgram.requiresSourceActive(program)
            &&(!battlefield.hasActive(origin.controller())||!battlefield.printedActiveView(origin.controller()).pokemonId().equals(origin.sourceId())))return false;
        if(origin.sourceId()!=null&&dev.hua.ptcglive.engine.effect.AbilitySuppressionProgram.requiresSourceBench(program)
            &&battlefield.benchView(origin.controller()).stream().noneMatch(p->p.pokemonId().equals(origin.sourceId())))return false;
        return AbilitySuppressionProgram.suppresses(program,
            hostConditionContext(origin.controller(), affectedOwner, pokemonId, true), origin.controller(), affectedOwner,
            currentPrimaryPokemonType(affectedOwner,pokemonId));
    }
    private PassiveModifierProgram.Values passiveValues(EffectProgram program,EffectOrigin origin,UUID host,UUID targetOwner,UUID targetId) {
        return passiveValues(program,origin,host,targetOwner,targetId,false);
    }
    private PassiveModifierProgram.Values passiveValues(EffectProgram program,EffectOrigin origin,UUID host,UUID targetOwner,UUID targetId,boolean hpOnly) {
        UUID controller=stadium!=null&&host==null&&origin.kind()==EffectOrigin.Kind.TRAINER&&stadium.instanceId().equals(origin.sourceId())
            ?stadiumScopeController():origin.controller();
        var context=hostConditionContext(controller,targetOwner,targetId);
        boolean own=controller.equals(targetOwner);
        boolean active=battlefield.hasActive(targetOwner)&&battlefield.printedActiveView(targetOwner).pokemonId().equals(targetId);
        var values=PassiveModifierProgram.evaluate(program,context,scope->switch(scope) {
            case SELF -> own&&Objects.equals(host,targetId);
            case OWN_ACTIVE -> own&&active;
            case OPPONENT_ACTIVE -> !own&&active;
            case OWN_BENCH -> own&&!active;
            case OPPONENT_BENCH -> !own&&!active;
            case ALL_OWN_POKEMON -> own;
            case ALL_OPPONENT_POKEMON -> !own;
            default -> throw new IllegalStateException("未校验持续目标："+scope);
        },hpOnly,host != null && battlefield.hasActive(controller)
            && battlefield.printedActiveView(controller).pokemonId().equals(host));
        // Guard-only programs and modifiers outside this target/layer have no numerical impact.
        // Asking their protection first would recurse through an HP-dependent guard while reading HP.
        return values.equals(PassiveModifierProgram.Values.NONE)
            ||!preventsImpact(targetOwner,targetId,origin,EffectProtection.Impact.OTHER_EFFECTS)
            ?values:PassiveModifierProgram.Values.NONE;
    }
    /** Card replacement -> HP -> conditional provision -> other numerical modifiers. */
    private dev.hua.ptcglive.engine.field.EnergyProfile currentEnergyProfile(UUID owner,UUID host,CardInstance card) {
        var profile=effectiveEnergyCard(owner,card).resolve(hostConditionContext(owner,owner,host));
        if(definition(card).basicEnergy()&&combat.energyType(card.definitionId()).orElse(null)==EnergyType.GRASS) {
            boolean doubled=publicFieldTargets(owner).stream().anyMatch(source->activeAbilities(owner,source.pokemonId()).stream()
                .anyMatch(ability->ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.effectSupport()==EffectSupport.SUPPORTED
                    &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),
                        new ServerConditionContext(owner,source.pokemonId()),effect->effect.type().equals("basic_energy_multiplier_aura"))));
            if(doubled) {
                var unit=new dev.hua.ptcglive.engine.field.EnergyProfile.Unit(Set.of(EnergyType.GRASS));
                return new dev.hua.ptcglive.engine.field.EnergyProfile(List.of(unit,unit),profile.passiveProgram(),List.of(),profile.automaticEffects(),profile.attachmentRule());
            }
        }
        return profile;
    }
    private boolean energyAttachmentAllowed(CardInstance energy,UUID owner,UUID host,UUID sourceOwner,EffectSourceZone zone) {
        return energyAttachmentAllowed(energy,owner,host,sourceOwner,zone,false);
    }
    private boolean energyAttachmentAllowed(CardInstance energy,UUID owner,UUID host,UUID sourceOwner,EffectSourceZone zone,boolean discardInvalid) {
        if(zone==EffectSourceZone.HAND&&currentPlayer.equals(sourceOwner)) {
            if(state(sourceOwner).specialEnergyHandLocked&&!definition(energy).basicEnergy())return false;
            if(owner.equals(sourceOwner)&&!battlefield.energyFromHandAllowed(owner,host))return false;
        }
        if(zone==EffectSourceZone.HAND&&!canPayEnergyHandCost(sourceOwner,List.of(energy))
            &&!handEnergyLockDiscardsEffectAttempt(owner,host,sourceOwner,zone))return false;
        return discardInvalid||energyHostAllowed(energy,owner,host);
    }
    /** Pokemon-local hand locks discard an effect's attempted attachment; player play prohibitions do not. */
    private boolean energyAttachmentByEffectAllowed(CardInstance energy,UUID owner,UUID host,UUID sourceOwner,EffectSourceZone zone,boolean discardInvalid) {
        if(zone==EffectSourceZone.HAND&&currentPlayer.equals(sourceOwner)
            &&state(sourceOwner).specialEnergyHandLocked&&!definition(energy).basicEnergy())return false;
        if(zone==EffectSourceZone.HAND&&!canPayEnergyHandCost(sourceOwner,List.of(energy))
            &&!handEnergyLockDiscardsEffectAttempt(owner,host,sourceOwner,zone))return false;
        return discardInvalid||energyHostAllowed(energy,owner,host);
    }
    private boolean handEnergyLockDiscardsEffectAttempt(UUID owner,UUID host,UUID sourceOwner,EffectSourceZone zone) {
        return zone==EffectSourceZone.HAND&&currentPlayer.equals(sourceOwner)&&owner.equals(sourceOwner)
            &&!battlefield.energyFromHandAllowed(owner,host);
    }
    private boolean energyEffectHostMatches(EffectDefinition effect,UUID owner,UUID host) {
        if(effect.arguments().containsKey("target_pokemon_name")
            &&!effect.arguments().get("target_pokemon_name").equals(battlefield.pokemonProfile(owner,host).pokemonName()))return false;
        if(Boolean.parseBoolean(effect.arguments().getOrDefault("target_basic_only","false"))
            &&!fieldCardDefinition(battlefield.topCard(owner,host).definitionId()).basicPokemon())return false;
        if(effect.arguments().containsKey("target_pokemon_names")
            &&!dev.hua.ptcglive.engine.effect.TurnHistoryCondition.values(effect.arguments().get("target_pokemon_names"))
                .contains(battlefield.pokemonProfile(owner,host).pokemonName()))return false;
        if(effect.arguments().containsKey("target_tool_definition_ids")
            &&battlefield.printedPokemonView(owner,host).attachedTools().stream().noneMatch(t->
                dev.hua.ptcglive.engine.effect.TurnHistoryCondition.values(effect.arguments().get("target_tool_definition_ids")).contains(t.definitionId())))return false;
        if(effect.arguments().containsKey("target_name_contains")) {
            String name=battlefield.pokemonProfile(owner,host).pokemonName();
            if(name==null||!name.contains(effect.arguments().get("target_name_contains")))return false;
        }
        if(effect.arguments().containsKey("target_pokemon_type")
            &&!currentPokemonTypes(owner,host)
                .contains(EnergyType.valueOf(effect.arguments().get("target_pokemon_type"))))return false;
        if(effect.arguments().containsKey("target_pokemon_families")&&!dev.hua.ptcglive.engine.effect.PokemonFamilyFilter
            .fromWire(effect.arguments().get("target_pokemon_families"),"ANY")
            .matches(currentFieldDefinition(owner,host)))return false;
        return true;
    }
    private boolean energyEffectAllowed(UUID actor,EffectDefinition effect,CardInstance energy,UUID owner,UUID host) {
        return energyEffectHostMatches(effect,owner,host)&&energyAttachmentByEffectAllowed(energy,owner,host,energyEffectSourceOwner(actor,effect),EffectSourceZone.valueOf(dev.hua.ptcglive.engine.effect.AttachEnergyEffect.from(effect).source().name()),"DISCARD".equals(effect.arguments().get("invalid_host_policy")));
    }
    private boolean energyHostAllowed(CardInstance energy,UUID owner,UUID host) {
        var view=battlefield.pokemonView(owner,host);
        // Incoming cards are not yet in play. A Stadium affecting attached Energy does not erase this restriction.
        return combat.energyProfile(energy.definitionId()).orElseThrow(()->new IllegalStateException("能量缺少供给数据"))
            .attachmentRule().allows(currentFieldDefinition(owner,host),combat.fieldPokemon(view.topCardId()).orElseThrow());
    }
    private void settleInvalidEnergyAttachments() {
        if(battlefield==null)return;
        settleAbilityGuardEffects();
        for(UUID owner:players.keySet()) {
            var field=new ArrayList<>(battlefield.benchView(owner));if(battlefield.hasActive(owner))field.add(battlefield.activeView(owner));
            for(var host:field) {
                for(var tool:host.attachedTools()) {
                    var profile=combat.trainer(tool.definitionId()).orElseThrow();
                    if(profile.opponentLegacyExTool()&&!toolHostAllowed(tool,profile,owner,host.pokemonId())) {
                        var removed=battlefield.detachTool(owner,host.pokemonId(),tool.instanceId());
                        moveCardToOwnerDiscard(removed);
                        recordReplay(owner,"闪焰队装备因宿主不再是对手旧版EX而回到持有者弃牌区");
                    }
                }
                var invalid=new ArrayList<UUID>();
                for(var card:battlefield.attachedEnergy(owner,host.pokemonId())) {
                    var rule=effectiveEnergyCard(owner,card).attachmentRule();
                    if(rule.discardIfInvalid()&&!rule.allows(currentFieldDefinition(owner,host.pokemonId()),combat.fieldPokemon(host.topCardId()).orElseThrow()))invalid.add(card.instanceId());
                }
                if(!invalid.isEmpty()) {
                    discardAttachedEnergyCards(owner,host.pokemonId(),invalid);
                    recordReplay(owner,"特殊能量因宿主不符而弃置："+invalid.size()+" 张");
                }
            }
        }
        settleEnergyConditionImmunity();
    }
    private dev.hua.ptcglive.engine.field.EnergyProfile effectiveEnergyCard(UUID owner,CardInstance card) {
        var printed=combat.energyProfile(card.definitionId()).orElseThrow(()->new IllegalStateException("附着能量缺少供给数据"));
        if(!definition(card).basicEnergy()&&stadium!=null) {
            var override=PassiveModifierProgram.specialEnergyOverride(combat.trainer(stadium.definitionId()).orElseThrow().ongoingProgram(),owner.equals(stadiumController));
            // This affects the Energy card, not its host. Pokémon-only protection does not block it.
            if(override.isPresent())return override.get();
        }
        return printed;
    }
    private int currentEnergyUnits(UUID owner,UUID host) {
        return currentEnergyCount(owner,host,dev.hua.ptcglive.engine.effect.EnergyCountQuery.ALL_UNITS);
    }
    private int currentEnergyCount(UUID owner,UUID host,dev.hua.ptcglive.engine.effect.EnergyCountQuery query) {
        return query.count(battlefield.attachedEnergy(owner,host).stream().map(c->
            new dev.hua.ptcglive.engine.effect.EnergyCountQuery.Contribution(currentEnergyProfile(owner,host,c),definition(c).basicEnergy(),c.definitionId())).toList());
    }
    private int countEnergyOnFixedTargets(UUID actor,UUID source,EffectTarget target,dev.hua.ptcglive.engine.effect.EnergyCountQuery query) {
        dev.hua.ptcglive.engine.effect.EnergyCountQuery.validateDamageTarget(target);
        var resolved=resolveEffectTarget(actor,source,target);
        var contributions=new ArrayList<dev.hua.ptcglive.engine.effect.EnergyCountQuery.Contribution>();
        for(var ref:resolved.fixedTargets()) {
            if(!(ref instanceof EffectTargetResolution.PokemonTarget pokemon))throw new IllegalStateException("能量计数只能读取公开宝可梦");
            for(var card:battlefield.attachedEnergy(pokemon.owner(),pokemon.pokemonId()))
                contributions.add(new dev.hua.ptcglive.engine.effect.EnergyCountQuery.Contribution(currentEnergyProfile(pokemon.owner(),pokemon.pokemonId(),card),definition(card).basicEnergy(),card.definitionId()));
        }
        // Aggregate before counting: distinct types shared by several hosts count once.
        return query.count(contributions);
    }
    /** Total damage counters on a public group (Bench / whole side); an empty group counts zero. */
    private int countDamageCountersOnFixedTargets(UUID actor,UUID source,EffectTarget target) {
        return countDamageCountersOnFixedTargets(actor,source,target,null);
    }
    private int countDamageCountersOnFixedTargets(UUID actor,UUID source,EffectTarget target,String pokemonTypes) {
        return countDamageCountersOnFixedTargets(actor,source,target,pokemonTypes,null);
    }
    private int countDamageCountersOnFixedTargets(UUID actor,UUID source,EffectTarget target,String pokemonTypes,String pokemonNames) {
        var filter=pokemonTypes==null?null:dev.hua.ptcglive.engine.effect.PokemonTypeFilter.fromWire(pokemonTypes);
        var names=pokemonNames==null?Set.<String>of():dev.hua.ptcglive.engine.effect.TurnHistoryCondition.values(pokemonNames);
        int total=0;
        for(var ref:resolveEffectTarget(actor,source,target).fixedTargets()) {
            if(!(ref instanceof EffectTargetResolution.PokemonTarget pokemon))throw new IllegalStateException("伤害指示物计数只能读取公开宝可梦");
            if(filter!=null&&currentPokemonTypes(pokemon.owner(),pokemon.pokemonId()).stream().noneMatch(filter.types()::contains))continue;
            String name=battlefield.pokemonProfile(pokemon.owner(),pokemon.pokemonId()).pokemonName();
            if(!names.isEmpty()&&(name==null||!names.contains(name)))continue;
            total=Math.addExact(total,battlefield.pokemonView(pokemon.owner(),pokemon.pokemonId()).damage()/10);
        }
        return total;
    }
    private EffectConditionContext hostConditionContext(UUID controller,UUID targetOwner,UUID targetId) {
        return hostConditionContext(controller, targetOwner, targetId, false);
    }
    /**
     * Persistent effects normally see dynamic HP, such as a conditional
     * Special Energy.  Ability-suppression discovery alone reads stable
     * printed HP, so it cannot recursively re-enter passive Ability queries.
     */
    private EffectConditionContext hostConditionContext(UUID controller,UUID targetOwner,UUID targetId,boolean printedHitPoints) {
        var facts=new ServerConditionContext(controller,null);
        facts.printedDependencyFacts=true;
        facts.printedHitPointsOnly=printedHitPoints;
        facts.chosenPokemon=new PokemonCandidate(new EffectTargetResolution.PokemonTarget(targetOwner,targetId),battlefield.pokemonEntrySequence(targetOwner,targetId));
        return new EffectConditionContext() {
            public int number(ConditionType type,EffectTarget target,Map<String,String> args) {
                if(type==ConditionType.POKEMON_COUNT)
                    return target==EffectTarget.SELF?countFilteredFieldPokemon(targetOwner,targetId,EffectTarget.SELF,args):facts.number(type,target,args);
                return type==ConditionType.HAND_SIZE&&target==EffectTarget.OPPONENT_ACTIVE
                    ?facts.number(type,target,args):facts.number(type,EffectTarget.CHOSEN_POKEMON,args);
            }
            public int opponentNumber(ConditionType type,Map<String,String> args) {
                return type==ConditionType.PRIZE_COUNT?other(targetOwner).prizes.size():facts.opponentNumber(type,args);
            }
            public int ownPrizeCardsTaken() {
                var owner=state(targetOwner);return Math.max(0,owner.initialPrizeCards-owner.prizes.size());
            }
            public boolean selfKnockedOutByOpponentAttackDamage() {
                var ko=new Knockout(targetOwner,targetId);
                return knockoutCheckpoint!=null&&knockoutCheckpoint.confirmed.contains(ko)
                    &&knockoutCheckpoint.attackDamage.contains(ko)&&knockoutCheckpoint.attacker!=null
                    &&!knockoutCheckpoint.attacker.owner().equals(targetOwner);
            }
            public int energyUnitsForHitPoints(dev.hua.ptcglive.engine.effect.EnergyCountQuery query) {
                for(var card:battlefield.attachedEnergy(targetOwner,targetId))
                    require(!dev.hua.ptcglive.engine.effect.HitPointEnergyDependencies.readsHp(effectiveEnergyCard(targetOwner,card)),"HP供能查询存在未经审核的循环依赖");
                return currentEnergyCount(targetOwner,targetId,query);
            }
            public boolean opponentActiveMatches(dev.hua.ptcglive.engine.effect.AttackDefenderFilter filter) {return matchesOpposingActive(targetOwner,filter);}
            public int opponentPrizeCardsTaken() {
                var opponent=other(controller);
                return Math.max(0,opponent.initialPrizeCards-opponent.prizes.size());
            }
            public int opponentPokemonCount(dev.hua.ptcglive.engine.effect.PokemonFamilyFilter family) {
                UUID opponent=other(controller).id;
                var field=new ArrayList<>(battlefield.printedBenchView(opponent));
                if(battlefield.hasActive(opponent))field.add(battlefield.printedActiveView(opponent));
                return (int)field.stream().filter(p->family.matches(fieldCardDefinition(p.topCardId()))).count();
            }
            public int opponentBenchCount() {return battlefield.printedBenchView(other(controller).id).size();}
            public int discardDefinitionCount(java.util.Set<String> ids) {return (int)state(controller).discard.stream().filter(c->ids.contains(c.definitionId())).count();}
            public boolean hasStatus(EffectTarget target,String status) {return facts.hasStatus(EffectTarget.CHOSEN_POKEMON,status);}
            public boolean flag(ConditionType type,EffectTarget target,Map<String,String> args) {return facts.flag(type,EffectTarget.CHOSEN_POKEMON,args);}
            public int printedAttachedEnergyCards(dev.hua.ptcglive.engine.effect.EnergyCountQuery query) {
                if(query.energyType()!=null||query.mode()!=dev.hua.ptcglive.engine.effect.EnergyCountQuery.Mode.CARDS)
                    throw new IllegalArgumentException("持续HP只能读取实际附着能量卡张数");
                return (int) battlefield.attachedEnergy(targetOwner,targetId).stream().filter(card ->
                    query.cardKind()==dev.hua.ptcglive.engine.effect.EnergyCountQuery.CardKind.ANY
                    ||query.cardKind()==dev.hua.ptcglive.engine.effect.EnergyCountQuery.CardKind.BASIC==definition(card).basicEnergy()).count();
            }
            public boolean coinResult(String expected) {throw new IllegalStateException("持续修正不允许硬币条件");}
            public boolean customCondition(ConditionDefinition condition) {throw new IllegalStateException("持续修正不允许未审核条件");}
        };
    }
    public boolean canEvolve(UUID player, UUID target, String definition) {
        if(battlefield==null||pokemonPlayLocked(player,definition)||!battlefield.evolutionFromHandAllowed(player,target))return false;
        var permission=evolutionPermission(player,target,definition);
        if(battlefield.canEvolve(player,target,definition,permission))return true;
        var evolved=fieldCardDefinition(definition);
        for(var ability:activeAbilities(player,target))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed())
            for(var binding:ability.effectProgram().triggers())for(var effect:binding.effects())
                if(effect.type().equals("evolution_name_alias")
                    &&dev.hua.ptcglive.engine.effect.PokemonFamilyFilter.fromWire(effect.arguments().get("pokemon_families"),null).matches(evolved)
                    &&battlefield.canEvolveFromNameAlias(player,target,definition,permission,effect.arguments().get("pokemon_name")))return true;
        return false;
    }
    public boolean canPlayBasicPokemonToBench(UUID player,String definition) {
        return battlefield!=null&&state(player).bench.size()<benchLimit(player)&&fieldCardDefinition(definition).basicPokemon()&&!pokemonPlayLocked(player,definition);
    }
    public boolean canUseEmergencyRotation(UUID player,UUID cardInstanceId) {
        try {validateEmergencyRotation(player,cardInstanceId);return true;}
        catch(IllegalArgumentException|IllegalStateException rejected){return false;}
    }
    private CardInstance validateEmergencyRotation(UUID player,UUID cardInstanceId) {
        requireTurn(player);requireCombatConfigured();var own=state(player);
        require(!resolvingEffectProgram&&pendingResolution==null&&phase==MatchPhase.TURN&&player.equals(currentPlayer),"只能在自己的普通回合发动紧急转动");
        require(own.bench.size()<benchLimit(player),"备战区已满");var card=cardInHand(own,cardInstanceId);
        require(combat.pokemon(card.definitionId()).filter(p->p.placementRule()==dev.hua.ptcglive.engine.field.PokemonPlacementRule.EMERGENCY_ROTATION).isPresent(),"此卡没有紧急转动的手牌上场规则");
        require(!offFieldAbilitiesSuppressed(card)&&zoneSuppressionSourceId()==null,"手牌中的上场特性当前已失效");
        require(!own.handAbilityUses.contains(card.instanceId()),"本回合已使用这张卡的手牌特性");
        UUID opponent=other(player).id;var field=new ArrayList<>(battlefield.printedBenchView(opponent));if(battlefield.hasActive(opponent))field.add(battlefield.printedActiveView(opponent));
        require(field.stream().anyMatch(p->evolutionStageDepth(p.topCardId())==2),"对手场上没有2阶进化宝可梦");return card;
    }
    public void useEmergencyRotation(UUID player,UUID cardInstanceId) {
        var card=validateEmergencyRotation(player,cardInstanceId);var own=state(player);own.handAbilityUses.add(card.instanceId());
        battlefield.placeOnBench(player,card);own.hand.remove(card);own.bench.add(card);
        capturePokemonChangeEvent(EffectTrigger.ON_ENTER_PLAY,player,card.instanceId(),dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy.Source.HAND);
        applyBenchEntryStadium(player,card,PokemonChangeTriggerPolicy.Source.HAND);recordReplay(player,"紧急转动：从手牌将 "+card.definitionId()+" 放到备战区");drainTriggeredAbilities();
    }
    public String handPlacementAbilityName(UUID player,UUID cardInstanceId) {
        return combat.pokemon(cardInHand(state(player),cardInstanceId).definitionId()).orElseThrow().placementRule()==dev.hua.ptcglive.engine.field.PokemonPlacementRule.EXCITED_DIVE?"兴奋俯冲":"肿胀闪光";
    }
    public boolean canUseSwellingFlash(UUID player,UUID cardInstanceId) {
        try {validateSwellingFlash(player,cardInstanceId);return true;}
        catch(IllegalArgumentException|IllegalStateException rejected){return false;}
    }
    private CardInstance validateSwellingFlash(UUID player,UUID cardInstanceId) {
        requireTurn(player);requireCombatConfigured();var own=state(player);
        require(!resolvingEffectProgram&&pendingResolution==null&&phase==MatchPhase.TURN&&player.equals(currentPlayer),"只能在自己的普通回合发动肿胀闪光");
        require(own.bench.size()<benchLimit(player),"备战区已满");var card=cardInHand(own,cardInstanceId);
        require(combat.pokemon(card.definitionId()).filter(p->p.placementRule()==dev.hua.ptcglive.engine.field.PokemonPlacementRule.SWELLING_FLASH||p.placementRule()==dev.hua.ptcglive.engine.field.PokemonPlacementRule.EXCITED_DIVE).isPresent(),"此卡没有肿胀闪光的手牌上场规则");
        require(!offFieldAbilitiesSuppressed(card)&&zoneSuppressionSourceId()==null,"手牌中的上场特性当前已失效");
        if(combat.pokemon(card.definitionId()).orElseThrow().placementRule()==dev.hua.ptcglive.engine.field.PokemonPlacementRule.EXCITED_DIVE) {
            var hosts=new ArrayList<CardInstance>(own.bench);if(own.active!=null)hosts.add(own.active);
            require(hosts.stream().anyMatch(host->fieldCardDefinition(host.definitionId()).pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.MEGA_EVOLUTION_EX)
                &&currentPokemonTypes(player,host.instanceId()).contains(EnergyType.COLORLESS)),"场上需要无色超级进化宝可梦ex");
        } else require(own.prizes.size()>state(other(player).id).prizes.size(),"自己的剩余奖赏卡没有多于对手");
        require(!own.handAbilityUses.contains(card.instanceId()),"本回合已使用这张卡的手牌特性");return card;
    }
    public void useSwellingFlash(UUID player,UUID cardInstanceId) {
        var card=validateSwellingFlash(player,cardInstanceId);var own=state(player);own.handAbilityUses.add(card.instanceId());
        battlefield.placeOnBench(player,card);own.hand.remove(card);own.bench.add(card);
        capturePokemonChangeEvent(EffectTrigger.ON_ENTER_PLAY,player,card.instanceId(),dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy.Source.HAND);
        applyBenchEntryStadium(player,card,PokemonChangeTriggerPolicy.Source.HAND);recordReplay(player,"手牌上场特性：将 "+card.definitionId()+" 放到备战区");drainTriggeredAbilities();
    }
    private dev.hua.ptcglive.engine.field.EvolutionPermission evolutionPermission(UUID player,UUID pokemonId,String evolutionDefinition) {
        for(var ability:activeAbilities(player,pokemonId))
            if(ability.effectSupport()==EffectSupport.SUPPORTED&&ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),
                    new ServerConditionContext(player,pokemonId),e->e.type().equals("evolution_timing_override")))
                return dev.hua.ptcglive.engine.field.EvolutionPermission.CARD_EFFECT_ALL_TIMING;
        if(stadium!=null
            &&currentPokemonTypes(player,pokemonId).contains(EnergyType.GRASS)) {
            for(var rule:combat.trainer(stadium.definitionId()).orElseThrow().ongoingProgram().triggers().stream().flatMap(binding->binding.effects().stream()).toList())
                if(dev.hua.ptcglive.engine.effect.PassiveRuleProgram.grassEvolutionTiming(rule)) {
                    if("GRASS_ALL_TIMING".equals(rule.arguments().get("mode")))return dev.hua.ptcglive.engine.field.EvolutionPermission.CARD_EFFECT_ALL_TIMING;
                    if(fieldCardDefinition(evolutionDefinition).pokemonTypes().contains(EnergyType.GRASS))return new dev.hua.ptcglive.engine.field.EvolutionPermission(false,true,true);
                }
        }
        return dev.hua.ptcglive.engine.field.EvolutionPermission.STRICT;
    }
    /** Reserved for audited server card-effect resolvers; MatchSession has no client intent for this override. */
    public boolean canEvolveByEffect(UUID player, UUID target, String definition, dev.hua.ptcglive.engine.field.EvolutionPermission permission) {
        return battlefield != null && battlefield.evolutionFromHandAllowed(player,target) && battlefield.canEvolve(player, target, definition, permission);
    }
    /** A narrower predicate for effects explicitly limited to skipping just one stage from a Basic Pokémon. */
    public boolean canEvolveByEffectSkippingOneStage(UUID player, UUID target, String evolutionDefinitionId,
                                                      dev.hua.ptcglive.engine.field.EvolutionPermission permission) {
        return battlefield != null && battlefield.evolutionFromHandAllowed(player,target) && fieldCardDefinition(battlefield.topCard(player, target).definitionId()).basicPokemon()
            && battlefield.canEvolveSkippingOneStage(player, target, evolutionDefinitionId, permission);
    }
    public int mulliganDrawLimit(UUID player) { return Math.min(Math.max(0, other(player).mulligans - state(player).mulligans), state(player).deck.size()); }
    public List<AttackDefinition> activeAttacks(UUID player) {
        return battlefield == null || !battlefield.hasActive(player)
            ||!attackSpecialConditionsAllow(player,battlefield.printedActiveView(player).pokemonId())
            ||passiveModifiers(player,battlefield.printedActiveView(player).pokemonId()).attackProhibited()
            ||turnEnergyAttackLocked(player,battlefield.printedActiveView(player).pokemonId()) ? List.of() : battlefield.activeProfile(player).attacks().stream()
            .filter(attack -> attackTimingAllowed(player,battlefield.printedActiveView(player).pokemonId(),attack) && !battlefield.activeAttackLocked(player, attack) && !attackSharedUsageExhausted(player,battlefield.printedActiveView(player).pokemonId(),attack.usageLimit()) && attackUseAllowed(player,battlefield.printedActiveView(player).pokemonId(),attack)).toList();
    }
    private boolean attackTimingAllowed(UUID player,UUID pokemonId,AttackDefinition attack) {
        if(attack.onlySecondPlayerFirstTurn()&&turnNumber!=2)return false;
        if(turnNumber==1&&!ruleset.firstTurnRules().firstPlayerMayAttack()&&!attack.mayAttackFirstTurn()
            &&!pokemonHasPassiveRule(player,pokemonId,"first_turn_attack_permission"))return false;
        return turnNumber!=2||!attack.cannotAttackSecondPlayerFirstTurn();
    }
    private boolean attackUseAllowed(UUID player,UUID pokemon,AttackDefinition attack) {
        var p=state(player);
        if(dev.hua.ptcglive.engine.effect.DamageCounterEffect.restrictedPreviousAttacks(attack.effectProgram()).stream()
            .anyMatch(p.previousTurnAttackIds::contains))return false;
        var requirement=attack.useRequirement();
        if(requirement==null)return true;
        return switch(requirement.type()) {
            case NO_SUPPORTER_IN_DISCARD -> discardCount(player,Map.of("trainer_category","SUPPORTER"))==0;
            case LOST_ZONE_TEN_CARDS -> p.lostZone.size()>=10;
            case PREVIOUS_OWN_TURN_NAMED_ATTACK -> p.previousTurnNamedAttacks.contains(
                new NamedAttack(requirement.pokemonName(),requirement.attackId()));
            case PREVIOUS_OWN_TURN_ATTACK_NOT_USED -> !p.previousTurnAttackIds.contains(requirement.attackId());
            case PREVIOUS_OWN_TURN_SOURCE_ATTACK -> p.previousTurnSourceAttacks.contains(
                new SourceAttack(pokemon,battlefield.pokemonEntrySequence(player,pokemon),requirement.attackId()));
        };
    }
    /**
     * Non-mutating affordability check used when the server issues tabletop
     * actions. Special-Energy replacements and Stadium overrides are resolved
     * here, so a client can never invent an available attack from its own view.
     */
    public boolean canPayActiveAttackCost(UUID player, AttackDefinition attack) {
        if (battlefield == null || attack == null || !battlefield.hasActive(player)) return false;
        return canPayAttackCost(player,battlefield.activeView(player).pokemonId(),attack);
    }
    public boolean canPayAttackCost(UUID player,UUID pokemonId,AttackDefinition attack) {
        if(battlefield==null||attack==null)return false;
        var supplied=battlefield.attachedEnergy(player,pokemonId).stream().map(card->currentEnergyProfile(player,pokemonId,card)).toList();
        return dev.hua.ptcglive.engine.field.EnergyProfile.canPay(supplied,currentAttackCost(player,pokemonId,attack));
    }
    /** Authenticated seat adapter uses only its own public field and actual resolved cost/provision facts. */
    public Map<UUID,dev.hua.ptcglive.ai.AiView.Energy> decisionEnergy(UUID player) {
        var result=new LinkedHashMap<UUID,dev.hua.ptcglive.ai.AiView.Energy>();
        if(battlefield==null)return Map.of();
        var own=new ArrayList<>(battlefield.benchView(player));if(battlefield.hasActive(player))own.add(battlefield.activeView(player));
        var borrowed=borrowedAttackOptions(player);
        for(var mon:own) {
            var units=battlefield.attachedEnergy(player,mon.pokemonId()).stream().flatMap(c->currentEnergyProfile(player,mon.pokemonId(),c).units().stream()).toList();
            var costs=new LinkedHashMap<String,Map<EnergyType,Integer>>();var payable=new LinkedHashMap<String,Boolean>();
            for(var a:battlefield.pokemonProfile(player,mon.pokemonId()).attacks()) {costs.put(a.id(),currentAttackCost(player,mon.pokemonId(),a));payable.put(a.id(),canPayAttackCost(player,mon.pokemonId(),a));}
            for(var b:borrowed)if(b.holderId().equals(mon.pokemonId())&&b.attack()!=null) {
                String key="borrow|"+b.providerCardId()+"|"+b.attackId();
                costs.put(key,currentAttackCost(player,mon.pokemonId(),b.attack()));
                payable.put(key,canPayAttackCost(player,mon.pokemonId(),b.attack()));
            }
            result.put(mon.pokemonId(),new dev.hua.ptcglive.ai.AiView.Energy(units,costs,payable));
        }return Map.copyOf(result);
    }
    private boolean extraAttackEnergy(UUID player,UUID pokemon,AttackDefinition costAttack,
                                      dev.hua.ptcglive.engine.effect.ExtraAttackEnergyRequirement requirement) {
        require(costAttack!=null,"额外能量查询缺少本次声明招式");
        var supplied=battlefield.attachedEnergy(player,pokemon).stream()
            .map(card->currentEnergyProfile(player,pokemon,card)).toList();
        return requirement.matches(supplied,currentAttackCost(player,pokemon,costAttack));
    }
    /** Own-field-only Ability list for an authorized player; never exposes an opponent's private choices. */
    public List<AbilityOption> abilityOptions(UUID player) {
        if (battlefield == null || !battlefield.hasActive(player)) return List.of();
        var result = new ArrayList<AbilityOption>();
        var active = battlefield.activeView(player);
        addAbilities(player, result, active);
        for (var bench : battlefield.benchView(player)) addAbilities(player, result, bench);
        return List.copyOf(result);
    }
    public record AbilityOption(UUID pokemonId, String pokemonDefinitionId, AbilityDefinition ability, boolean usedThisTurn) { }
    private void addAbilities(UUID player, List<AbilityOption> target, BattlefieldState.PokemonView pokemon) {
        for (AbilityDefinition ability : activeAbilities(player, pokemon.pokemonId())) if (ability.activated() && !RevivingFlameAbility.containsReviveStep(ability)&&!RestoredPokemonRules.containsBottom(ability))
            target.add(new AbilityOption(pokemon.pokemonId(), pokemon.topCardId(), ability,
                sharedUsageExhausted(player,ability.usageLimit()) || (ability.composed() ? effectLifecycle.usageLimited(abilitySource(player, pokemon.pokemonId(), ability),
                    ability.activationTrigger(), turnNumber) : ability.oncePerTurn() && battlefield.abilityUsed(player, pokemon.pokemonId(), ability.id()))));
    }
    public record DiscardAbilityOption(UUID cardInstanceId, String cardDefinitionId, AbilityDefinition ability) { }
    /** Printed discard-zone Abilities are offered only on their actual owner's physical cards. */
    public List<DiscardAbilityOption> discardAbilityOptions(UUID player) {
        if (battlefield == null || !battlefield.hasActive(player)) return List.of();
        var options = new ArrayList<DiscardAbilityOption>();
        for (var card : state(player).discard) if (card.ownerId().equals(player))
            combat.pokemon(card.definitionId()).ifPresent(profile -> {
                for (var ability : profile.abilities()) if (RevivingFlameAbility.matches(ability)||RestoredPokemonRules.prehistoricCall(ability))
                    options.add(new DiscardAbilityOption(card.instanceId(),card.definitionId(),ability));
            });
        return List.copyOf(options);
    }
    private record DiscardAbilityActivation(CardInstance card,AbilityDefinition ability,
                                            ServerEffectExecutionContext context,EffectLifecycleDispatcher.Source source) { }
    private DiscardAbilityActivation prepareDiscardAbility(UUID player,UUID cardInstanceId,String abilityId) {
        requireTurn(player);requireCombatConfigured();
        require(battlefield.hasActive(player),"当前没有可继续对战的战斗宝可梦");
        var card=state(player).discard.stream().filter(c->c.instanceId().equals(cardInstanceId)).findFirst()
            .orElseThrow(()->new IllegalArgumentException("特性来源已不在己方弃牌区"));
        require(card.ownerId().equals(player)&&definition(card).category()==CardCategory.POKEMON
            &&(definition(card).basicPokemon()||restoredPokemon(card)),"弃牌区特性来源必须是己方对应宝可梦实体卡");
        var ability=combat.pokemon(card.definitionId()).orElseThrow().ability(abilityId).orElseThrow(
            ()->new IllegalArgumentException("该弃牌区宝可梦没有指定特性"));
        boolean prehistoric=RestoredPokemonRules.prehistoricCall(ability)&&restoredPokemon(card);
        require(ability.effectSupport()==EffectSupport.SUPPORTED&&(prehistoric||RevivingFlameAbility.matches(ability)),
            "弃牌区仅支持已审核的完整原始呼唤或复活火焰特性");
        dev.hua.ptcglive.engine.effect.ActivatedAbilityRules.validate(ability);
        String exempt=zoneSuppressionSourceId();
        require(!offFieldAbilitiesSuppressed(card)&&(exempt==null||exempt.equals(ability.id())),"弃牌区特性当前被封锁");
        if(!prehistoric)require(state(player).bench.size()<benchLimit(player),"备战区已满，无法发动复活火焰");
        var origin=new EffectOrigin(EffectOrigin.Kind.ABILITY,player,card.instanceId());
        // Returning to a hidden zone ends this discard incarnation, as with Propagation.
        var source=new EffectLifecycleDispatcher.Source(card.instanceId(),"discard-ability:"+ability.id()
            +(prehistoric?":"+prehistoricCallDepartures.getOrDefault(card.instanceId(),0L):""),ability.effectProgram());
        require(!effectLifecycle.usageLimited(source,ability.activationTrigger(),turnNumber),"此弃牌区特性本回合已使用");
        var context=new ServerEffectExecutionContext(player,card.instanceId());context.resumable=true;
        context.preflight(ability.effectProgram(),ability.activationTrigger());
        require(dev.hua.ptcglive.engine.effect.EffectPotential.canActivateAbility(ability.effectProgram().triggers().getFirst(),
            context,context::canAffect),"复活火焰目前不能产生效果");
        return new DiscardAbilityActivation(card,ability,context,source);
    }
    public boolean canUseDiscardAbility(UUID player,UUID cardInstanceId,String abilityId) {
        try {prepareDiscardAbility(player,cardInstanceId,abilityId);return true;}
        catch(IllegalArgumentException|IllegalStateException rejected){return false;}
    }
    public void useDiscardAbility(UUID player,UUID cardInstanceId,String abilityId) {
        var activation=prepareDiscardAbility(player,cardInstanceId,abilityId);
        var cursor=effectLifecycle.beginActivation(activation.source(),turnNumber,activation.context());
        pendingResolution=new PendingResolution(UUID.randomUUID(),player,null,null,cursor,
            new MatchClientView.AbilityResolution(null,activation.ability().id(),activation.ability().nameZh()));
        resolvingEffectProgram=true;
        endTurnAfterCardResolution=activation.ability().endsTurn()?pendingResolution.id():null;
        recordReplay(player,"发动弃牌区特性："+activation.ability().id()+"；实体卡="+cardInstanceId);
        advancePendingResolution();
    }
    public boolean canUseAbility(UUID player, UUID pokemonId, String abilityId) {
        return canUseAbility(player, pokemonId, abilityId, null);
    }
    /** Target-bearing Ability intents are validated against the acting player's public own field. */
    public boolean canUseAbility(UUID player, UUID pokemonId, String abilityId, UUID targetPokemonId) {
        return canUseAbility(player, pokemonId, abilityId, targetPokemonId, null);
    }
    /**
     * Validates an activated Ability before a client action is offered.  A client
     * may name only public in-play instances; it cannot move an arbitrary card
     * from a hidden zone or bypass the source attachment check.
     */
    public boolean canUseAbility(UUID player, UUID pokemonId, String abilityId, UUID targetPokemonId, UUID attachedEnergyId) {
        try {
            AbilityDefinition ability = validateAbility(player, pokemonId, abilityId);
            if (ability.effect().needsDeckSelection()) return false;
            if (ability.composed()) {
                require(attachedEnergyId == null, "组合特性须通过服务器分步选择附着能量");
                prepareComposedAbility(player, pokemonId, ability, targetPokemonId);
                return true;
            }
            validateAbilityTarget(player, pokemonId, ability.effect(), targetPokemonId, attachedEnergyId);
            return true;
        }
        catch (IllegalArgumentException | IllegalStateException rejected) { return false; }
    }
    /** Checks a complete owner-private Ability deck selection without exposing it to another seat. */
    public boolean canUseAbilityDeckSearch(UUID player, UUID pokemonId, String abilityId, List<UUID> selectedDeckCardIds) {
        try {
            AbilityDefinition ability = validateAbility(player, pokemonId, abilityId);
            require(ability.effect().needsDeckSelection(), "此特性不使用牌库检索选择");
            validateAbilityDeckSearchSelections(state(player), ability.effect(), selectedDeckCardIds);
            return true;
        }
        catch (IllegalArgumentException | IllegalStateException rejected) { return false; }
    }
    private AbilityDefinition validateAbility(UUID player, UUID pokemonId, String abilityId) {
        requireTurn(player); requireCombatConfigured();
        require(!battlefield.abilityEffectsDisabled(player, pokemonId), "该宝可梦的特性当前失效");
        require(activeAbilities(player,pokemonId).stream().anyMatch(a->a.id().equals(abilityId)),"该特性当前失效");
        AbilityDefinition ability = battlefield.ability(player, pokemonId, abilityId);
        require(ability.activated(), "被动特性不是可点击操作；它只能由已支持的服务器规则自动结算");
        require(!RevivingFlameAbility.containsReviveStep(ability)&&!RestoredPokemonRules.containsBottom(ability),"复活火焰只能从这张实体卡的弃牌区入口发动");
        require(ability.effectSupport() == EffectSupport.SUPPORTED, "此特性尚未支持：" + ability.unsupportedReasonZh());
        requireSharedUsage(player,ability.usageLimit());
        if (ability.composed()) {
            return ability;
        }
        require(!ability.oncePerTurn() || !battlefield.abilityUsed(player, pokemonId, abilityId), "此宝可梦本回合已经使用过该特性");
        if (ability.effect().opcode() == AbilityEffect.Opcode.DRAW || ability.effect().opcode() == AbilityEffect.Opcode.SHUFFLE_SELF_DRAW_IF_DREW)
            require(!state(player).deck.isEmpty(), "牌库为空，该特性不会产生效果");
        if (ability.effect().opcode() == AbilityEffect.Opcode.DRAW_UNTIL_HAND_SIZE)
            require(state(player).hand.size() < ability.effect().amount() && !state(player).deck.isEmpty(),
                "手牌已达到特性指定数量，或牌库为空，无法使用该特性");
        if (ability.effect().needsDeckSelection() && ability.effect().minimumDeckSelections() > 0)
            require(state(player).deck.stream().anyMatch(card -> ability.effect().allowsDeckSearchCandidate(definition(card))),
                "牌库中没有符合此特性检索条件的卡牌");
        return ability;
    }
    private EffectLifecycleDispatcher.Source abilitySource(UUID player, UUID pokemonId, AbilityDefinition ability) {
        return new EffectLifecycleDispatcher.Source(pokemonId,
            "ability:" + ability.id() + ":entry:" + battlefield.pokemonEntrySequence(player, pokemonId), ability.effectProgram());
    }
    /** One activated ability is one gate + one sequence. Nested effects do not become separate activations. */
    private ServerEffectExecutionContext prepareComposedAbility(UUID player, UUID pokemonId, AbilityDefinition ability, UUID targetId) {
        var bindings = ability.effectProgram().triggers();
        require(ability.activated() && bindings.size() == 1 && bindings.getFirst().trigger() == ability.activationTrigger(),
            "此组合特性的触发时机尚未接入主动特性入口");
        require(!effectLifecycle.usageLimited(abilitySource(player, pokemonId, ability), ability.activationTrigger(), turnNumber),
            "此特性使用资格已消耗或仍在结算");
        dev.hua.ptcglive.engine.effect.ActivatedAbilityRules.validate(ability);
        var selection = dev.hua.ptcglive.engine.effect.ResumableProgramRules.selectionTarget(ability.effectProgram());
        require((selection != null) == (targetId != null), "组合特性的目标选择与卡文不符");
        ServerEffectExecutionContext context;
        if (selection == null) context = new ServerEffectExecutionContext(player, pokemonId);
        else {
            UUID owner = selection == EffectTarget.SELECT_OWN_POKEMON ? player : other(player).id;
            battlefield.pokemonView(owner, targetId);
            context = new ServerEffectExecutionContext(player, pokemonId, selection,
                List.of(new EffectTargetResolution.PokemonTarget(owner, targetId)));
        }
        context.resumable = true;
        context.pokemonBindings = new LinkedHashMap<>();
        context.deckDiscardCause=new DeckDiscardCause(player,dev.hua.ptcglive.engine.effect.DeckDiscardTriggerPolicy.SourceKind.POKEMON_ABILITY,
            context.source,ability.id(),UUID.randomUUID());
        context.preflight(ability.effectProgram(), ability.activationTrigger());
        var cost=dev.hua.ptcglive.engine.effect.ActivationCostRules.costEffect(ability.effectProgram(),ability.activationTrigger());
        dev.hua.ptcglive.engine.effect.ActivationCostRules.requireAffordable(ability.effectProgram(),ability.activationTrigger(),context::activationCostCandidates);
        context.potentialHandDiscard=cost==null?0:dev.hua.ptcglive.engine.effect.ActivationCostRules.handCost(cost);
        context.potentialHandToDeck=cost!=null&&"DECK_BOTTOM".equals(cost.arguments().get("destination"))?context.potentialHandDiscard:0;
        try {
            boolean needsReward=cost!=null&&"true".equals(cost.arguments().get("requires_effect"));
            require(needsReward?dev.hua.ptcglive.engine.effect.EffectPotential.canAffect(bindings.getFirst(),context,context::canAffect)
                :dev.hua.ptcglive.engine.effect.EffectPotential.canActivateAbility(bindings.getFirst(),context,context::canAffect),
                "当前不满足该特性的使用条件，或不会产生任何效果");
        } finally {context.potentialHandDiscard=0;context.potentialHandToDeck=0;}
        return context;
    }
    /**
     * Resolves a vetted Ability on the server. The caller provides only the
     * in-play instance and effect id; draw identities, discard contents and any
     * replacement requirement are calculated from authoritative state.
     */
    public void useAbility(UUID player, UUID pokemonId, String abilityId) {
        useAbility(player, pokemonId, abilityId, null, null);
    }
    public void useAbility(UUID player, UUID pokemonId, String abilityId, UUID targetPokemonId) {
        useAbility(player, pokemonId, abilityId, targetPokemonId, null);
    }
    /**
     * Resolves a target-bearing Ability entirely on the server.  The selected
     * Energy is rechecked as attached to the source before the once-per-turn
     * mark is committed, so stale UI and forged intents are harmless.
     */
    public void useAbility(UUID player, UUID suppliedPokemonId, String abilityId, UUID targetPokemonId, UUID attachedEnergyId) {
        requireCombatConfigured();UUID pokemonId=battlefield.printedPokemonView(player,suppliedPokemonId).pokemonId();
        withOrigin(new EffectOrigin(EffectOrigin.Kind.ABILITY,player,pokemonId), () -> {
            var ability=validateAbility(player,pokemonId,abilityId);
            if(ability.composed()||resolvingEffectProgram)useAbilityInternal(player,pokemonId,abilityId,targetPokemonId,attachedEnergyId);
            else resolveEffectProgram(()->useAbilityInternal(player,pokemonId,abilityId,targetPokemonId,attachedEnergyId));
        });
    }
    private void useAbilityInternal(UUID player, UUID pokemonId, String abilityId, UUID targetPokemonId, UUID attachedEnergyId) {
        AbilityDefinition ability = validateAbility(player, pokemonId, abilityId);
        AbilityEffect effect = ability.effect();
        require(!effect.needsDeckSelection(), "此特性需要先选择牌库中的卡牌");
        if (ability.composed()) {
            require(attachedEnergyId == null, "组合特性须通过服务器分步选择附着能量");
            var context = prepareComposedAbility(player, pokemonId, ability, targetPokemonId);
            var source = abilitySource(player, pokemonId, ability);
            require(!resolvingEffectProgram && pendingResolution == null, "上一效果尚未完成");
            var cursor = effectLifecycle.beginActivation(source, turnNumber, context);
            consumeSharedUsage(player,ability.usageLimit());
            pendingResolution = new PendingResolution(UUID.randomUUID(), player, null, null, cursor,
                new MatchClientView.AbilityResolution(pokemonId, ability.id(), ability.nameZh()));
            resolvingEffectProgram = true;
            recordReplay(player, "发动组合特性：" + ability.id() + "；来源=" + pokemonId);
            endTurnAfterCardResolution = ability.endsTurn() ? pendingResolution.id() : null;
            advancePendingResolution();
            return;
        }
        validateAbilityTarget(player, pokemonId, effect, targetPokemonId, attachedEnergyId);
        beginAbility(player, pokemonId, abilityId);
        consumeSharedUsage(player,ability.usageLimit());
        recordReplay(player,"公开特性·"+player+"·"+pokemonId+"·"+ability.nameZh());
        PlayerState p = state(player);
        switch (effect.opcode()) {
            case COMPOSED -> throw new IllegalStateException("组合特性必须通过通用 Effect 解释器执行");
            case DRAW -> drawEffect(p, effect.amount());
            case DRAW_UNTIL_HAND_SIZE -> drawEffect(p, effect.amount() - p.hand.size());
            case SEARCH_BASIC_POKEMON_TO_HAND, SEARCH_POKEMON_TO_HAND, SEARCH_CARD_TO_HAND ->
                throw new IllegalStateException("牌库检索特性必须带服务器验证的选择");
            case DISCARD_SELF_DRAW -> {
                var discardReturns=fieldDiscardReturnCards();
                BattlefieldState.LeavePlayResult left = battlefield.removePokemonByEffect(player, pokemonId);
                moveCardsToOwnerDiscard(left.discardedCards(),discardReturns);
                syncField(player);
                drawEffect(p, effect.amount());
                if (left.wasActive()) resolveActiveLeaveByEffect(player);
            }
            case SHUFFLE_SELF_DRAW_IF_DREW -> {
                int drawn = drawEffect(p, effect.amount());
                // The card text makes the leave-play/shuffle conditional on drawing at least one card.
                if (drawn > 0) {
                    BattlefieldState.LeavePlayResult left = battlefield.removePokemonByEffect(player, pokemonId);
                    for(var card:left.discardedCards())if(!redirectFlareGearDeparture(card))state(card.ownerId()).deck.add(card);
                    shuffle(p.deck, "ability-shuffle-self:" + abilityId);
                    syncField(player);
                    if (left.wasActive()) resolveActiveLeaveByEffect(player);
                }
            }
            case HEAL_OWN_POKEMON -> healDamageByEffect(player,player,targetPokemonId,effect.amount());
            case MOVE_ONE_ATTACHED_ENERGY_TO_OWN_POKEMON -> {
                if (!preventCardEffect(player,player,pokemonId) && !preventCardEffect(player,player,targetPokemonId))
                    battlefield.moveAttachedEnergyByEffect(player,pokemonId,player,targetPokemonId,List.of(attachedEnergyId));
            }
        }
        recordReplay(player, "使用已审核特性");
    }
    /** Compatibility entry point for the old one-card private Ability search intent. */
    public void useAbilityWithDeckSearch(UUID player, UUID pokemonId, String abilityId, UUID selectedDeckCardId) {
        useAbilityWithDeckSearches(player, pokemonId, abilityId, selectedDeckCardId == null ? List.of() : List.of(selectedDeckCardId));
    }
    /**
     * Resolves a full Ability deck selection on the server. Every UUID is
     * rechecked against the owner's current private deck before the once-per-
     * turn mark or any zone movement is committed.
     */
    public void useAbilityWithDeckSearches(UUID player, UUID pokemonId, String abilityId, List<UUID> selectedDeckCardIds) {
        AbilityDefinition ability = validateAbility(player, pokemonId, abilityId);
        AbilityEffect effect = ability.effect();
        require(effect.needsDeckSelection(), "此特性不使用牌库检索选择");
        PlayerState p = state(player);
        List<CardInstance> selected = validateAbilityDeckSearchSelections(p, effect, selectedDeckCardIds);
        beginAbility(player, pokemonId, abilityId);
        consumeSharedUsage(player,ability.usageLimit());
        recordReplay(player,"公开特性·"+player+"·"+pokemonId+"·"+ability.nameZh());
        p.deck.removeAll(selected);
        p.hand.addAll(selected);
        shuffle(p.deck, "ability-search:" + abilityId);
        recordReplay(player, "使用已审核特性并检索牌库卡");
    }
    /** Validates all Ability deck choices before marking the instance as used or changing any zone. */
    private List<CardInstance> validateAbilityDeckSearchSelections(PlayerState player, AbilityEffect effect, List<UUID> selectedDeckCardIds) {
        List<UUID> selectedIds = selectedDeckCardIds == null ? List.of() : new ArrayList<>(selectedDeckCardIds);
        require(selectedIds.size() >= effect.minimumDeckSelections() && selectedIds.size() <= effect.amount(),
            "必须选择 " + effect.minimumDeckSelections() + " 至 " + effect.amount() + " 张符合条件的牌库卡");
        require(new java.util.LinkedHashSet<>(selectedIds).size() == selectedIds.size(), "同一张牌库卡不能重复选择");
        List<CardInstance> selected = new ArrayList<>();
        for (UUID selectedId : selectedIds) {
            CardInstance card = player.deck.stream().filter(candidate -> candidate.instanceId().equals(selectedId)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("指定卡牌不在你的牌库中"));
            require(effect.allowsDeckSearchCandidate(definition(card)), "指定卡牌不符合此特性牌库检索条件");
            selected.add(card);
        }
        return selected;
    }
    private void validateAbilityTarget(UUID player, UUID sourcePokemonId, AbilityEffect effect, UUID targetPokemonId,
                                       UUID attachedEnergyId) {
        require(effect.needsPokemonTarget() == (targetPokemonId != null), "该特性的目标参数无效");
        require(effect.needsAttachedEnergyTarget() == (attachedEnergyId != null), "该特性的附着能量参数无效");
        if (!effect.needsPokemonTarget()) return;
        BattlefieldState.PokemonView target = battlefield.pokemonView(player, targetPokemonId);
        switch (effect.opcode()) {
            case HEAL_OWN_POKEMON -> require(target.damage() > 0&&!healingBlocked(player,targetPokemonId), "目标没有可回复的伤害");
            case MOVE_ONE_ATTACHED_ENERGY_TO_OWN_POKEMON -> {
                require(!sourcePokemonId.equals(targetPokemonId), "附着能量必须移动到另一只己方宝可梦");
                BattlefieldState.PokemonView source = battlefield.pokemonView(player, sourcePokemonId);
                require(source.attachedEnergyIds().contains(attachedEnergyId), "指定卡牌不是该特性来源宝可梦附着的能量");
            }
            default -> throw new IllegalStateException("该特性不应要求宝可梦目标");
        }
    }
    /** A non-KO effect that leaves an Active empty never grants Prizes. */
    private void resolveActiveLeaveByEffect(UUID player) {
        settleHitPointChanges();
    }
    private List<MatchClientView.Player> clientPlayers(UUID viewingSeat) {
        boolean revealed = turnNumber > 0;
        var views = new ArrayList<MatchClientView.Player>();
        for (var p : players.values()) {
            boolean show = revealed || p.id.equals(viewingSeat);
            // While the just-drawn card awaits its owner's Emergency Entry choice,
            // publish the ordinary draw's hand count to avoid exposing its identity.
            int visibleHandSize=p.hand.size()+(pendingEmergencyEntry!=null&&pendingEmergencyEntry.owner().equals(p.id)||pendingDrawnTrainer!=null&&pendingDrawnTrainer.owner().equals(p.id)?1:0);
            views.add(new MatchClientView.Player(p.id, visibleHandSize, p.deck.size(), p.prizes.size(),
                show && battlefield != null && battlefield.hasActive(p.id) ? activePokemonView(p.id) : null,
                show && battlefield != null ? benchPokemonView(p.id) : List.of(), List.copyOf(p.discard), List.copyOf(p.lostZone),
                sharedUsage.markerUsed(p.id,dev.hua.ptcglive.engine.effect.SharedUsageLimit.GX,turnNumber),
                sharedUsage.markerUsed(p.id,dev.hua.ptcglive.engine.effect.SharedUsageLimit.VSTAR,turnNumber),
                java.util.stream.IntStream.range(0,p.prizes.size()).filter(slot->p.faceUpPrizeIds.contains(p.prizes.get(slot).instanceId()))
                    .mapToObj(slot->new MatchClientView.Player.FaceUpPrize(slot,p.prizes.get(slot).definitionId())).toList()));
        }
        return List.copyOf(views);
    }
    private List<CardInstance> publicResolvingTrainers() {
        var cards=new LinkedHashMap<UUID,CardInstance>();
        var resolutions=new ArrayList<PendingResolution>();if(pendingResolution!=null)resolutions.add(pendingResolution);
        if(effectPrizeResume!=null)resolutions.add(effectPrizeResume.resolution());
        for(var frame:prizeEffectFrames)if(frame.effect!=null)resolutions.add(frame.effect.resolution());
        if(pendingPrizeSearch!=null)cards.put(pendingPrizeSearch.card().instanceId(),pendingPrizeSearch.card());
        for(var resolution:resolutions) {
            if(resolution.card()!=null)cards.put(resolution.card().instanceId(),resolution.card());
            resolution.playedCards().forEach(card->cards.put(card.instanceId(),card));
        }
        return List.copyOf(cards.values());
    }
    private CardInstance publicResolvingTrainer() {var cards=publicResolvingTrainers();return cards.isEmpty()?null:cards.getFirst();}
    public MatchClientView clientView(UUID viewingSeat) {
        if(viewingSeat!=null)state(viewingSeat);
        boolean openingHandVisible=currentPlayer!=null;
        var views=clientPlayers(viewingSeat);
        return new MatchClientView(id, viewingSeat, phase, turnNumber, currentPlayer, pendingChoicePlayer(), result,
            List.copyOf(views), viewingSeat == null || !openingHandVisible ? List.of() : List.copyOf(state(viewingSeat).hand),
            viewingSeat == null ? List.of() : java.util.stream.IntStream.range(0, state(viewingSeat).prizes.size()).boxed().toList(),
            players.values().stream().map(p -> new MatchClientView.SetupPlayer(p.id, p.mulligans, needsMulligan(p), p.openingReady, p.mulliganAcknowledged)).toList(),
            List.copyOf(currentMulliganReveals), stadium, publicResolvingTrainer(),
            hasPendingCardSelection() && pendingChoicePlayer().equals(viewingSeat) ? effectCardPrompt(viewingSeat) : null,
            effectCardReveal(), pendingResolution != null && pendingChoicePlayer().equals(viewingSeat) ? currentAttachmentPrompt() : null, publicTriggerOrder(),
            pendingAllocation != null && pendingResolution != null && pendingResolution.actor().equals(viewingSeat) ? damageAllocationPrompt(viewingSeat) : null,
            publicResolvingAbility(), publicResolvingAttack(),toolOverflowPrompt(),
            publicResolvingTrainers(),stadiumCompanion);
    }
    private boolean publicSourceOnField(UUID owner,UUID pokemonId) {
        return battlefield!=null&&pokemonId!=null&&((battlefield.hasActive(owner)&&battlefield.printedActiveView(owner).pokemonId().equals(pokemonId))
            ||battlefield.printedBenchView(owner).stream().anyMatch(p->p.pokemonId().equals(pokemonId)));
    }
    private TriggerOrderPrompt publicTriggerOrder() {
        if(triggerOrderPrompt==null)return null;
        var entries=triggerOrderPrompt.entries().stream().map(entry -> new TriggerOrderPrompt.Entry(entry.id(),entry.owner(),
            publicCardInstance(entry.pokemonId())?entry.pokemonId():null,entry.nameZh(),
            entry.triggerPokemon()!=null&&publicCardInstance(entry.triggerPokemon().pokemonId())?entry.triggerPokemon():null,
            entry.attackingPokemon()!=null&&publicCardInstance(entry.attackingPokemon().pokemonId())?entry.attackingPokemon():null,
            entry.sourceKind(),publicCardInstance(entry.sourceCardId())?entry.sourceCardId():null)).toList();
        return new TriggerOrderPrompt(triggerOrderPrompt.id(),triggerOrderPrompt.choosingPlayer(),triggerOrderPrompt.optionalDecision(),entries,triggerOrderPrompt.trigger());
    }
    private boolean publicCardInstance(UUID cardId) {
        if(cardId==null)return false;
        if(stadium!=null&&stadium.instanceId().equals(cardId)||pendingResolution!=null&&pendingResolution.card()!=null&&pendingResolution.card().instanceId().equals(cardId))return true;
        for(var player:players.values()) {
            if(java.util.stream.Stream.concat(player.discard.stream(),player.lostZone.stream()).anyMatch(card->card.instanceId().equals(cardId)))return true;
            if(battlefield==null)continue;
            var field=new ArrayList<>(battlefield.benchView(player.id));if(battlefield.hasActive(player.id))field.add(battlefield.activeView(player.id));
            for(var pokemon:field)if(pokemon.pokemonId().equals(cardId)||pokemon.attachedEnergyIds().contains(cardId)
                ||pokemon.attachedTools().stream().anyMatch(card->card.instanceId().equals(cardId)))return true;
        }
        return false;
    }
    private MatchClientView.AbilityResolution publicResolvingAbility() {
        if(pendingResolution==null||pendingResolution.ability()==null)return null;
        var source=pendingResolution.ability();
        return publicSourceOnField(pendingResolution.actor(),source.pokemonId())?source:
            new MatchClientView.AbilityResolution(null,source.abilityId(),source.nameZh(),source.sourceKind());
    }
    private MatchClientView.AttackResolution publicResolvingAttack() {
        if(pendingResolution==null||pendingResolution.attack()==null)return null;
        var source=pendingResolution.attack();
        return publicSourceOnField(pendingResolution.actor(),source.pokemonId())?source:
            new MatchClientView.AttackResolution(null,source.attackId(),source.nameZh(),source.phase());
    }
    /** Only the acting player receives the identities of their own Benched Pokémon. */
