    public void choosePrizeRandomSwapSlot(UUID player,UUID resolutionId,long step,int slot) {
        requireResolutionPhase();require(!advancingResolution,"随机手牌奖赏交换不能重入");var prompt=prizeRandomSwapPrompt(player);
        require(prompt.resolutionId().equals(resolutionId)&&prompt.step()==step&&!prompt.decisionReady(),"随机手牌奖赏位置步骤已更新");
        require(prompt.faceDownSlots().contains(slot),"只能选择对手仍为暗面的奖赏卡");
        var pending=pendingPrizeRandomSwap;var owner=state(pending.owner());var prize=owner.prizes.get(slot);
        owner.faceUpPrizeIds.add(prize.instanceId());
        CardInstance randomCard=owner.hand.isEmpty()?null:owner.hand.get(random.nextInt("prize-random-hand-swap:"+player,owner.hand.size()));
        pendingPrizeRandomSwap=new PendingPrizeRandomSwap(pending.owner(),step,pending.prizes(),pending.hand(),slot,randomCard,false);
        var faces=randomCard==null?List.of(prize.definitionId()):List.of(prize.definitionId(),randomCard.definitionId());
        pendingReveal=new PendingReveal(new EffectCardReveal(UUID.randomUUID(),pending.owner(),player,step,faces,"公开对手奖赏与随机手牌"),List.of(),EffectExecutionContext.InteractionKind.PRIZE_RANDOM_HAND_SWAP);
        recordReplay(player,"翻开对手奖赏位置 "+(slot+1)+" 并由服务器随机选择对手1张手牌");
    }
    public void decidePrizeRandomHandSwap(UUID player,UUID resolutionId,long step,boolean swap) {
        requireResolutionPhase();var prompt=prizeRandomSwapPrompt(player);
        require(prompt.resolutionId().equals(resolutionId)&&prompt.step()==step&&prompt.decisionReady(),"随机手牌奖赏交换决定已更新");
        var pending=pendingPrizeRandomSwap;var owner=state(pending.owner());var handCard=pending.randomHandCard();
        require(handCard!=null&&owner.hand.contains(handCard),"被随机选中的手牌已改变");
        if(swap) {
            var prize=owner.prizes.get(pending.slot());
            require(prize.equals(pending.prizes().get(pending.slot())),"奖赏位置已改变");
            owner.hand.remove(handCard);owner.hand.add(prize);owner.prizes.set(pending.slot(),handCard);
            owner.faceUpPrizeIds.remove(prize.instanceId());owner.faceUpPrizeIds.add(handCard.instanceId());
            recordReplay(player,"交换公开奖赏与服务器随机选中的对手手牌");
        } else recordReplay(player,"保留公开奖赏与随机手牌原位");
        pendingResolution.continuation().completeInteraction(step,EffectExecutionContext.InteractionKind.PRIZE_RANDOM_HAND_SWAP);
        pendingPrizeRandomSwap=null;advancePendingResolution();
    }
