    public void takeEffectPrizeAt(UUID player,UUID resolutionId,long step,int selection,int position) {
        requireResolutionPhase();require(!advancingResolution,"拿取奖赏不能重入");
        var prompt=prizeTakePrompt(player);
        require(prompt.resolutionId().equals(resolutionId)&&prompt.step()==step&&prompt.selection()==selection,"暗面奖赏选择步骤已更新");
        var taking=pendingPrizeTake;var owner=state(player);
        require(owner.prizes.equals(taking.prizes()),"奖赏区域已改变");
        require(position>=0&&position<owner.prizes.size(),"奖赏卡位置无效");
        var prize=owner.prizes.remove(position);boolean faceDown=!owner.faceUpPrizeIds.remove(prize.instanceId());
        if(taking.taken()==0)prizeWindows.addFirst(new PrizeWindow(player));
        prizeWindows.getFirst().cards.add(new TakenPrize(prize,faceDown));owner.currentTurnPrizesTaken++;
        int taken=taking.taken()+1;
        recordReplay(player,"由卡牌效果拿取暗面奖赏卡；第 "+taken+" 张");
        // Section E checks a win as soon as all Prizes have been taken. Do not execute more card text after game end.
        // No Pokémon is removed here and no Knock Out award/replacement queue is involved.
        if(owner.prizes.isEmpty()) {finish(player,MatchResult.Reason.PRIZES);return;}
        if(taking.remaining()>1) {
            pendingPrizeTake=new PendingPrizeTake(taking.owner(),step,taking.effect(),List.copyOf(owner.prizes),taking.remaining()-1,taken);return;
        }
        effectPrizeResume=new EffectPrizeResume(pendingResolution,
            new PendingPrizeTake(taking.owner(),step,taking.effect(),List.of(),0,taken),phase,resolvingEffectProgram);
        pendingResolution=null;pendingPrizeTake=null;resolvingEffectProgram=false;phase=MatchPhase.PRIZE_SELECTION;
        preparePrizeClaims();
    }
