                        recordReplay(pending.actor(),"复制招式掷硬币："+(heads?"正面":"反面"));
                        var options=heads?copyAttackOptionsForSource(pending.actor(),attackCheckpoint.attacker.pokemonId(),declared):List.<CopyAttackOption>of();
