    private static String attachedEnergyLabel(EffectDefinition effect, String target) {
        var operation = dev.hua.ptcglive.engine.effect.AttachedEnergyEffect.from(effect);
        if(dev.hua.ptcglive.engine.effect.AttachedEnergyEffect.otherOwnMetalToSelf(effect))
            return "选择己方其他宝可梦身上任意张提供"+effect.arguments().get("energy_type")+"属性的能量卡，移到此特性来源宝可梦（至少1张）";
        if(operation.typedPayment())return "选择支付火、水、雷各1个能量所需的附着能量卡（每张卡必须参与支付）";

        String kind = switch (operation.cardKind()) {
            case BASIC -> "基本";
            case SPECIAL -> "特殊";
            default -> "";
        };
        String type = operation.energyType() == null ? "" : switch (operation.energyType()) {
            case GRASS -> "草"; case FIRE -> "火"; case WATER -> "水"; case LIGHTNING -> "雷"; case PSYCHIC -> "超";
            case FIGHTING -> "斗"; case DARKNESS -> "恶"; case METAL -> "钢"; case DRAGON -> "龙"; case COLORLESS -> "无色"; case FAIRY -> "妖精";
        };
        String energy = (type.isEmpty() ? "" : type + "属性") + kind + "能量";
        String action = switch (operation.mode()) {
            case DISCARD -> "弃置";
            case RETURN_TO_HAND -> "放回拥有者手牌";
            case SHUFFLE_INTO_DECK -> "洗回拥有者牌库";
            case DECK_TOP -> "放到拥有者牌库顶";
            case DECK_BOTTOM -> "放到拥有者牌库底";
            case LOST_ZONE -> "放入拥有者放逐区";
            case MOVE -> "移动到其他宝可梦身上";
        };
        return operation.all() ? "将" + target + "宝可梦身上全部" + energy + action
            : "选择" + target + "宝可梦身上的" + energy + "（最多 " + operation.maximum() + " 个）并" + action;
    }
    private static String nestedEffectLabel(EffectDefinition effect) {
        return effect.effects().stream().limit(3).map(ServerMatch::effectLabel).collect(java.util.stream.Collectors.joining("；"))
            + (effect.effects().size() > 3 ? "等后续效果" : "");
    }
    /** Preflight all limits and targets before moving any cards. The acting trainer is never part of the hand effect. */
    /** Called once after legal declaration validation, before any source, cost, replacement or trigger mutation. */
    private boolean trainerAttemptRejected(UUID player,CardInstance trainer,Runnable resume) {
        return trainerAttemptRejected(player,List.of(trainer),resume);
    }
    private boolean trainerAttemptRejected(UUID player,List<CardInstance> trainers,Runnable resume) {
        CardInstance trainer=trainers.getFirst();
        if(!state(player).trainerAttemptCoinGated)return false;
        require(state(player).hand.containsAll(trainers),"尝试使用的训练家已不在该玩家手牌");
        if(pauseForCoinChoice(player,resume))return true;
        boolean heads=flipEffectCoin(player,"trainer-attempt-coin:"+player+":"+trainer.definitionId());
        recordReplay(player,heads?"训练家使用前掷币：正面，照常使用":"训练家使用前掷币：反面，弃置且不视为使用");
        if(heads)return false;
        state(player).hand.removeAll(trainers);moveCardsToOwnerDiscard(trainers);
        // No usage quota, hand-play history, ON_CARD_PLAYED, attachment/evolution event, cost or effect.
        return true;
    }
    private EffectDefinition discardSupporterRecoveryRule(String definitionId) {
        var profile=combat.trainer(definitionId).orElse(null);if(profile==null)return null;
        for(var binding:profile.effectProgram().triggers())for(var effect:binding.effects()) {
            var found=findEffectType(effect,"discard_recover_named_supporter");if(found!=null)return found;
        }
        return null;
    }
    public boolean canRecoverDiscardSupporter(UUID player,UUID cardId) {
        try {
            requireTurn(player);requireCombatConfigured();
            require(!resolvingEffectProgram&&pendingResolution==null,"上一效果尚未完成");
            var p=state(player);var card=p.discard.stream().filter(c->c.instanceId().equals(cardId)).findFirst().orElseThrow();
            var rule=discardSupporterRecoveryRule(card.definitionId());require(rule!=null,"此卡没有弃牌区回收规则");
            dev.hua.ptcglive.engine.effect.EffectSchemaValidator.validate(rule);
            require(dev.hua.ptcglive.engine.effect.TurnHistoryCondition.values(rule.arguments().get("definition_ids")).contains(card.definitionId()),"印刷编号不属于此回收规则");
            var excluded=dev.hua.ptcglive.engine.effect.TurnHistoryCondition.values(rule.arguments().get("definition_ids"));
            require(p.hand.stream().filter(c->!excluded.contains(c.definitionId())).count()>=2,"除同名支援者外的手牌不足2张");
            require(!unrecoverableFromDiscard(player,card),"该卡当前不能从弃牌区回收");
            return true;
        } catch(IllegalArgumentException|IllegalStateException rejected) {return false;}
    }
    public boolean canRecoverDiscardSupporter(UUID player,UUID cardId,List<UUID> handCardIds) {
        if(!canRecoverDiscardSupporter(player,cardId)||handCardIds==null||handCardIds.size()!=2||new LinkedHashSet<>(handCardIds).size()!=2)return false;
        var p=state(player);var source=p.discard.stream().filter(c->c.instanceId().equals(cardId)).findFirst().orElseThrow();
        var excluded=dev.hua.ptcglive.engine.effect.TurnHistoryCondition.values(discardSupporterRecoveryRule(source.definitionId()).arguments().get("definition_ids"));
        return handCardIds.stream().allMatch(id->p.hand.stream().anyMatch(c->c.instanceId().equals(id)&&!excluded.contains(c.definitionId())));
    }
    public void recoverDiscardSupporter(UUID player,UUID cardId,List<UUID> handCardIds) {
        require(canRecoverDiscardSupporter(player,cardId,handCardIds),"须选择两张不同的手牌，且不能弃置同名支援者");
        var p=state(player);var costs=handCardIds.stream().map(id->cardInHand(p,id)).toList();
        var source=p.discard.stream().filter(c->c.instanceId().equals(cardId)).findFirst().orElseThrow();
        p.hand.removeAll(costs);moveCardsToOwnerDiscard(costs);p.discard.remove(source);p.hand.add(source);
        recordReplay(player,"弃置2张手牌，从弃牌区回收支援者："+source.definitionId());
    }
    private record PreparedTrainerPair(List<CardInstance> cards,dev.hua.ptcglive.rules.TrainerProfile profile,
                                       ServerEffectExecutionContext context,EffectProgram program) { }
    private PreparedTrainerPair prepareTrainerPair(UUID player,List<UUID> cardIds) {
        requireTurn(player);requireCombatConfigured();
        require(!resolvingEffectProgram&&pendingResolution==null,"上一效果尚未完成");
        require(cardIds!=null&&(cardIds.size()==2||cardIds.size()==4)&&cardIds.stream().allMatch(Objects::nonNull)
            &&Set.copyOf(cardIds).size()==cardIds.size(),"须选择规则要求数量的不同手牌");
        var cards=cardIds.stream().map(id->cardInHand(state(player),id)).toList();
        var profile=validateTrainerCard(player,cardIds.getFirst());
        var pair=profile.pairedPlay();require(pair!=null&&pair.count()==cardIds.size(),"所选数量不符合此卡的同时使用规则");
        for(var card:cards) {
            var next=validateTrainerCard(player,card.instanceId());
            require(pair.equals(next.pairedPlay())&&pair.definitionIds().contains(card.definitionId())
                &&profile.effectProgram().equals(next.effectProgram()),"所选卡不属于同一已审核的同时使用规则");
        }
        var program=pair.allowsSingle()?pair.program():profile.effectProgram();
        var context=prepareComposedTrainer(player,cards.getFirst(),profile,null,Set.copyOf(cardIds),program);
        return new PreparedTrainerPair(List.copyOf(cards),profile,context,program);
    }
    public boolean canPlayTrainerPair(UUID player,List<UUID> cardIds) {
        try {prepareTrainerPair(player,cardIds);return true;}
        catch(IllegalArgumentException|IllegalStateException rejected){return false;}
    }
    public void playTrainerPair(UUID player,List<UUID> cardIds) {
        var prepared=prepareTrainerPair(player,cardIds);var cards=prepared.cards();
        withOrigin(new EffectOrigin(EffectOrigin.Kind.TRAINER,player,cards.getFirst().instanceId()),()->{
            if(trainerAttemptRejected(player,cards,()->playTrainerPair(player,cards.stream().map(CardInstance::instanceId).toList())))return;
            var cursor=new dev.hua.ptcglive.engine.effect.EffectContinuation(prepared.program().triggers().getFirst(),prepared.context());
            pendingResolution=new PendingResolution(UUID.randomUUID(),player,cards.getFirst(),prepared.profile().category(),
                cursor,null,null,null,0,cards);
            state(player).hand.removeAll(cards);resolvingEffectProgram=true;
            recordReplay(player,"同时使用"+(cards.size()==2?"两":"四")+"张训练家，结算一次："+cards.stream().map(CardInstance::definitionId).toList());
            advancePendingResolution();
        });
    }
    private static final EffectProgram QUAD_STONE_FOUR_PROGRAM=new EffectProgram(List.of(
        new dev.hua.ptcglive.engine.effect.TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(
            new EffectDefinition("heal",EffectTarget.ALL_OWN_POKEMON,Map.of("mode","ALL"),List.of(),List.of())))));
    private record PreparedQuadStone(List<CardInstance> cards,dev.hua.ptcglive.rules.TrainerProfile profile,
                                     ServerEffectExecutionContext context) { }
    private PreparedQuadStone prepareQuadStoneFour(UUID player,List<UUID> cardIds) {
        requireTurn(player);requireCombatConfigured();
        require(!resolvingEffectProgram&&pendingResolution==null,"上一效果尚未完成");
        require(cardIds!=null&&cardIds.size()==4&&cardIds.stream().allMatch(Objects::nonNull)
            &&Set.copyOf(cardIds).size()==4,"四尖石须选择手牌中四张不同的实体卡");
        var cards=cardIds.stream().map(id->cardInHand(state(player),id)).toList();
        for(var card:cards)require("swsh12_en_163".equals(card.definitionId()),"四张均须为四尖石");
        var profile=validateTrainerCard(player,cardIds.getFirst());
        require(profile.category()==dev.hua.ptcglive.rules.TrainerCategory.ITEM&&profile.composed()
            &&profile.pairedPlay()==null,"四尖石四张模式缺少已审核的单张规则");
        for(var card:cards)validateTrainerCard(player,card.instanceId());
        var context=prepareComposedTrainer(player,cards.getFirst(),profile,null,Set.copyOf(cardIds),QUAD_STONE_FOUR_PROGRAM);
        return new PreparedQuadStone(List.copyOf(cards),profile,context);
    }
    public boolean canPlayQuadStoneFour(UUID player,List<UUID> cardIds) {
        try {prepareQuadStoneFour(player,cardIds);return true;}
        catch(IllegalArgumentException|IllegalStateException rejected){return false;}
    }
    public void playQuadStoneFour(UUID player,List<UUID> cardIds) {
        var prepared=prepareQuadStoneFour(player,cardIds);var cards=prepared.cards();
        withOrigin(new EffectOrigin(EffectOrigin.Kind.TRAINER,player,cards.getFirst().instanceId()),()->{
            if(trainerAttemptRejected(player,cards,()->playQuadStoneFour(player,cards.stream().map(CardInstance::instanceId).toList())))return;
            var cursor=new dev.hua.ptcglive.engine.effect.EffectContinuation(QUAD_STONE_FOUR_PROGRAM.triggers().getFirst(),prepared.context());
            pendingResolution=new PendingResolution(UUID.randomUUID(),player,cards.getFirst(),prepared.profile().category(),
                cursor,null,null,null,0,cards);
            state(player).hand.removeAll(cards);resolvingEffectProgram=true;
            recordReplay(player,"同时使用四张四尖石，为己方所有宝可梦回复全部伤害");
            advancePendingResolution();
        });
    }
    public void playTrainer(UUID player, UUID cardId, UUID targetId) {playTrainer(player,cardId,targetId,null);}
    public void playTrainer(UUID player, UUID cardId, UUID targetId, UUID firstSidePlayer) {
        var selectedProfile=validateTrainer(player,cardId,targetId);
        require(selectedProfile.directionalStadium()?firstSidePlayer!=null&&players.containsKey(firstSidePlayer):firstSidePlayer==null,
            "须在放置前选择场地朝向，且只能朝向本局玩家");
        var played=cardInHand(state(player),cardId);
        var previous=resolvingHandTrainer;resolvingHandTrainer=played;
        try {
            withOrigin(new EffectOrigin(EffectOrigin.Kind.TRAINER,player,cardId), () -> {
                if(resolvingEffectProgram)playTrainerInternal(player,cardId,targetId,firstSidePlayer);
                else {
                    // Legacy actions may invoke several primitives; HP is checked after the whole card.
                    var profile=validateTrainer(player,cardId,targetId);
                    if(profile.composed())playTrainerInternal(player,cardId,targetId,firstSidePlayer);
                    else resolveEffectProgram(()->playTrainerInternal(player,cardId,targetId,firstSidePlayer));
                }
            });
        } finally {resolvingHandTrainer=previous;}
    }
    private void playTrainerInternal(UUID player, UUID cardId, UUID targetId, UUID firstSidePlayer) {
        var profile = validateTrainer(player, cardId, targetId);
        if (profile.composed()) {
            PlayerState p = state(player); CardInstance card = cardInHand(p, cardId);
            var context = prepareComposedTrainer(player, card, profile, targetId);
            // Even text without an explicit choice can encounter a mandatory rule correction.
            require(!resolvingEffectProgram && pendingResolution == null, "上一效果尚未完成");
            if(trainerAttemptRejected(player,card,()->playTrainer(player,cardId,targetId,firstSidePlayer)))return;
            pendingResolution = new PendingResolution(UUID.randomUUID(), player, card, profile.category(),
                new dev.hua.ptcglive.engine.effect.EffectContinuation(profile.effectProgram().triggers().getFirst(), context), null);
            endTurnAfterCardResolution = profile.endsTurn() ? pendingResolution.id() : null;
            p.hand.remove(card); resolvingEffectProgram = true;
            recordReplay(player,"训练家已公开打出");
            advancePendingResolution();
            return;
        }
        require(!profile.effect().needsDeckSelection(), "此训练家卡需要先选择牌库中的卡牌");
        require(!profile.effect().needsEvolutionCardSelection(), "此训练家卡需要选择手牌中的进化宝可梦");
        var effect = profile.effect();
        require(effect.discardHandCost() == 0, "此训练家卡需要选择弃置手牌成本");
        PlayerState p = state(player); CardInstance card = cardInHand(p, cardId);
        if(trainerAttemptRejected(player,card,()->playTrainer(player,cardId,targetId,firstSidePlayer)))return;
        p.hand.remove(card);
        // Legacy tools have no pending resolution card for the public journal to reveal.
        // Emit the identity only after play validation and removal from the hidden hand.
        recordReplay(player,profile.category()==dev.hua.ptcglive.rules.TrainerCategory.TOOL
            ?"训练家已公开打出·"+card.definitionId():"训练家已公开打出");
        switch (effect.opcode()) {
            case PLAY_AS_POKEMON -> {
                battlefield.placeOnBench(player,card);
                p.bench.add(card);
                capturePokemonChangeEvent(EffectTrigger.ON_ENTER_PLAY,player,card.instanceId(),
                    dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy.Source.HAND);
            }
            case DRAW -> drawEffect(p, effect.drawCount(p.prizes.size()));
            // The played Trainer is already out of hand here, so the target is
            // evaluated after its own removal, as required by the card text.
            case DRAW_UNTIL_HAND_SIZE -> drawEffect(p, effect.amount() - p.hand.size());
            case SEARCH_BASIC_POKEMON_TO_HAND, SEARCH_POKEMON_TO_HAND, SEARCH_CARD_TO_HAND -> throw new IllegalStateException("牌库检索必须带服务器验证的选择");
            case DISCARD_HAND_DRAW -> {
                moveCardsToOwnerDiscard(p.hand); p.hand.clear(); drawEffect(p, effect.drawCount(p.prizes.size()));
            }
            case SHUFFLE_HAND_DRAW -> {
                // Do not shuffle when no cards were returned (2026 ordering clarification).
                if (!p.hand.isEmpty()) { p.deck.addAll(p.hand); p.hand.clear(); shuffle(p.deck, "trainer-shuffle:" + card.definitionId()); }
                drawEffect(p, effect.drawCount(p.prizes.size()));
            }
            case DISCARD_OPPONENT_RANDOM_HAND -> {
                var kind=profile.category()==dev.hua.ptcglive.rules.TrainerCategory.ITEM
                    ?dev.hua.ptcglive.engine.effect.DeckDiscardTriggerPolicy.SourceKind.ITEM
                    :profile.category()==dev.hua.ptcglive.rules.TrainerCategory.SUPPORTER
                        ?dev.hua.ptcglive.engine.effect.DeckDiscardTriggerPolicy.SourceKind.SUPPORTER:null;
                discardRandomHandCardsByEffect(player, other(player).id,new RandomHandDiscardPolicy(effect.amount(),effect.amount()),
                    kind==null?null:new DeckDiscardCause(player,kind,card.instanceId(),card.definitionId(),UUID.randomUUID()));
            }
            case DISCARD_STADIUM -> discardStadiumByEffect(player);
            case CURE_OWN_ACTIVE_SPECIAL_CONDITIONS -> clearSpecialConditionsByEffect(player, player,
                battlefield.activeView(player).pokemonId(), java.util.Set.of(SpecialCondition.POISONED, SpecialCondition.BURNED,
                    SpecialCondition.ASLEEP, SpecialCondition.PARALYZED, SpecialCondition.CONFUSED));
            case HEAL -> healDamageByEffect(player,player,targetId,effect.amount());
            case SWITCH_ACTIVE -> switchActiveByEffect(player,player,targetId,SwitchEffectTarget.ACTIVE);
            case SWITCH_OPPONENT_ACTIVE -> switchActiveByEffect(player, other(player).id, targetId,SwitchEffectTarget.SELECTED_BENCH);
            case TOOL_RETREAT_REDUCTION, TOOL_RETREAT_REDUCTION_ALLOW_TWO, PASSIVE_TOOL -> {
                UUID hostOwner=profile.opponentLegacyExTool()?other(player).id:player;
                battlefield.attachToolByEffect(hostOwner, targetId, card, toolAttachmentCapacity(hostOwner, targetId, profile,card.instanceId()));
                if(profile.opponentLegacyExTool())attachedFlareGear.add(card.instanceId());
                applyToolAttachCure(hostOwner,targetId,profile);
            }
            case STADIUM_BASIC_RETREAT_REDUCTION, PASSIVE_STADIUM -> {
                // Check the old Stadium before removing it; the new card must never become an active source.
                boolean discardReplacement=stadiumHasPassiveRule("discard_replacing_stadium");
                if (stadium != null) {
                    beginLeavingStadiumBenchCorrection();
                    moveCardToOwnerDiscard(stadium);
                }
                var companion=legendaryPartner(player,card);
                if(companion!=null) {p.hand.remove(companion);stadiumCompanion=companion;stadiumPrimaryId=card.instanceId();}
                p.stadiumsPlayed++;
                if(discardReplacement) {
                    stadium=null;stadiumController=null;
                    moveCardToOwnerDiscard(card);
                    recordReplay(player,"混沌之潮弃置了新打出的场地，其效果未生效");
                    break;
                }
                stadium = card; stadiumController = player; stadiumFirstSide=firstSidePlayer; stadiumEntrySequence++;
                beginStadiumAbilitySuppression();
                var benchRule=stadiumPassiveRule("bench_limit");
                if(benchRule!=null&&benchRule.target()==EffectTarget.OWN_BENCH) {
                    // Parallel City's restricted side acts first, including replacement of Sky Field.
                    benchOverflowFirst=stadiumScopeController();benchOverflowForcedLimit=null;
                } else if(benchRule!=null&&benchOverflowFirst==null) {
                    benchOverflowFirst=player;benchOverflowForcedLimit=Integer.parseInt(benchRule.arguments().get("amount"));
                }
                settleEnergyConditionImmunity();
            }
        }
        if (!effect.persistent() && profile.inPlayPokemon()==null) moveCardToOwnerDiscard(card);
        if (profile.category() == dev.hua.ptcglive.rules.TrainerCategory.SUPPORTER) p.supportersPlayed++;
        captureCardPlayedEvent(player, card);
        recordReplay(player, "使用已审核训练家卡");
    }
    /**
     * Atomically resolves a reviewed Trainer that evolves one of its owner's
     * Pokémon from hand. Only this server path may use the explicit card-effect
     * timing permission; ordinary player evolution always remains strict.
     */
    public void playTrainerWithEvolution(UUID player, UUID trainerCardId, UUID targetPokemonId, UUID evolutionCardId) {
        var profile = validateTrainer(player, trainerCardId, targetPokemonId);
        var effect = profile.effect();
        require(effect.needsEvolutionCardSelection(), "此训练家卡不使用手牌进化选择");
        require(effect.discardHandCost() == 0, "此训练家卡需要选择弃置手牌成本");
        PlayerState p = state(player);
        CardInstance trainer = cardInHand(p, trainerCardId);
        CardInstance evolution = cardInHand(p, evolutionCardId);
        require(!trainer.instanceId().equals(evolution.instanceId()), "训练家卡不能作为进化宝可梦");
        require(definition(evolution).category() == dev.hua.ptcglive.rules.CardCategory.POKEMON, "选择的手牌不是宝可梦进化牌");
        var permission = effect.evolutionPermission();
        boolean mayEvolve = effect.requiresSkippedEvolutionStage()
            ? canEvolveByEffectSkippingOneStage(player, targetPokemonId, evolution.definitionId(), permission)
            : canEvolveByEffect(player, targetPokemonId, evolution.definitionId(), permission);
        require(mayEvolve, "该宝可梦不符合已审核进化效果的进化条件");
        // Every requirement is now checked before either hand card is moved.
        if(trainerAttemptRejected(player,trainer,()->playTrainerWithEvolution(player,trainerCardId,targetPokemonId,evolutionCardId)))return;
        p.hand.remove(trainer);
        boolean wasResolving=resolvingEffectProgram;
        resolvingEffectProgram=true;
        try {
            evolveByEffect(player, targetPokemonId, evolutionCardId, permission);
            moveCardToOwnerDiscard(trainer);
            if (profile.category() == dev.hua.ptcglive.rules.TrainerCategory.SUPPORTER) p.supportersPlayed++;
            captureCardPlayedEvent(player, trainer);
            recordReplay(player, "使用已审核训练家卡并从手牌进化");
        } finally {resolvingEffectProgram=wasResolving;}
        if(!wasResolving)drainTriggeredAbilities();
    }
    /** Compatibility entry point for the old mandatory one-card search intent. */
    public void playTrainerWithDeckSearch(UUID player, UUID cardId, UUID selectedDeckCardId) {
        playTrainerWithDeckSearches(player, cardId, selectedDeckCardId == null ? List.of() : List.of(selectedDeckCardId));
    }
    private static EffectProgram legacySearchProgram(String opcode,int amount,int minimum,EffectTrigger trigger) {
        var args=new LinkedHashMap<String,String>();args.put("amount",Integer.toString(amount));args.put("minimum",Integer.toString(minimum));
        if(!opcode.equals("SEARCH_CARD_TO_HAND"))args.put("card_category","POKEMON");
        if(opcode.equals("SEARCH_BASIC_POKEMON_TO_HAND"))args.put("basic_pokemon_only","true");
        return new EffectProgram(List.of(new dev.hua.ptcglive.engine.effect.TriggeredEffects(trigger,List.of(),
            List.of(new EffectDefinition("search_deck",EffectTarget.DECK,args,List.of(),List.of())))));
    }
    private static EffectProgram legacyTrainerSearchProgram(dev.hua.ptcglive.rules.TrainerEffect effect) {
        var search=legacySearchProgram(effect.opcode().name(),effect.amount(),effect.opcode()==dev.hua.ptcglive.rules.TrainerEffect.Opcode.SEARCH_CARD_TO_HAND?effect.minimumDeckSelections():0,EffectTrigger.ON_CARD_PLAYED);
        var steps=new ArrayList<EffectDefinition>();
        if(effect.discardHandCost()>0)steps.add(new EffectDefinition("discard",EffectTarget.HAND,
            Map.of("amount",Integer.toString(effect.discardHandCost()),"minimum",Integer.toString(effect.discardHandCost()),"as_cost","true"),List.of(),List.of()));
        for(var selection:search.triggers().getFirst().effects()){
            var args=new LinkedHashMap<>(selection.arguments());
            if(effect.opcode()!=dev.hua.ptcglive.rules.TrainerEffect.Opcode.SEARCH_CARD_TO_HAND)args.put("reveal","true");
            steps.add(new EffectDefinition(selection.type(),selection.target(),args,selection.conditions(),selection.effects()));
        }
        return new EffectProgram(List.of(new dev.hua.ptcglive.engine.effect.TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),steps)));
    }
    public boolean canBeginTrainerSearch(UUID player,UUID cardId) {
        try {var profile=validateTrainer(player,cardId,null);var e=profile.effect();
            require(e.needsDeckSelection(),"该卡不使用此检索入口");
            prepareComposedTrainer(player,cardInHand(state(player),cardId),profile,null,Set.of(cardId),legacyTrainerSearchProgram(e));
            return true;
        }catch(IllegalStateException|IllegalArgumentException e){return false;}
    }
    /** Commit the public card before opening the existing private, non-cancellable selector. */
    public void beginTrainerSearch(UUID player,UUID cardId) {
        require(canBeginTrainerSearch(player,cardId),"当前不能使用此检索训练家");
        var profile=validateTrainer(player,cardId,null);var e=profile.effect();var p=state(player);var card=cardInHand(p,cardId);
        var program=legacyTrainerSearchProgram(e);
        var context=prepareComposedTrainer(player,card,profile,null,Set.of(cardId),program);
        if(trainerAttemptRejected(player,card,()->beginTrainerSearch(player,cardId)))return;
        pendingResolution=new PendingResolution(UUID.randomUUID(),player,card,profile.category(),new dev.hua.ptcglive.engine.effect.EffectContinuation(program.triggers().getFirst(),context),null);
        p.hand.remove(card);resolvingEffectProgram=true;recordReplay(player,"训练家已公开打出");advancePendingResolution();
    }
    public boolean canBeginAbilitySearch(UUID player,UUID pokemon,String abilityId) {
        try {var ability=validateAbility(player,pokemon,abilityId);var e=ability.effect();require(e.needsDeckSelection(),"不是检索特性");
            return state(player).deck.stream().filter(c->e.allowsDeckSearchCandidate(definition(c))).count()>=e.minimumDeckSelections();
        }catch(IllegalStateException|IllegalArgumentException e){return false;}
    }
    public void beginAbilitySearch(UUID player,UUID pokemon,String abilityId) {
        require(canBeginAbilitySearch(player,pokemon,abilityId),"当前不能发动此检索特性");
        var ability=validateAbility(player,pokemon,abilityId);var e=ability.effect();
        var program=legacySearchProgram(e.opcode().name(),e.amount(),e.minimumDeckSelections(),ability.activationTrigger());
        var context=new ServerEffectExecutionContext(player,pokemon);context.resumable=true;context.pokemonBindings=new LinkedHashMap<>();
        context.origin=new EffectOrigin(EffectOrigin.Kind.ABILITY,player,pokemon);context.preflight(program,ability.activationTrigger());
        beginAbility(player,pokemon,abilityId);consumeSharedUsage(player,ability.usageLimit());
        pendingResolution=new PendingResolution(UUID.randomUUID(),player,null,null,new dev.hua.ptcglive.engine.effect.EffectContinuation(program.triggers().getFirst(),context),
            new MatchClientView.AbilityResolution(pokemon,abilityId,ability.nameZh()));
        resolvingEffectProgram=true;recordReplay(player,"使用已审核特性");advancePendingResolution();
    }
    /**
     * Plays a reviewed Trainer with one or more owner-private deck choices.
     * The full selection is checked before the Trainer leaves hand, so stale,
     * duplicate or forged choices cannot consume it. A zero-card selection is
     * allowed only if the data explicitly declares a zero minimum.
     */
    public void playTrainerWithDeckSearches(UUID player, UUID cardId, List<UUID> selectedDeckCardIds) {
        var profile = validateTrainer(player, cardId, null);
        var effect = profile.effect();
        require(effect.needsDeckSelection(),
            "此训练家卡不使用牌库检索选择");
        require(effect.discardHandCost() == 0, "此训练家卡需要选择弃置手牌成本");
        PlayerState p = state(player);
        List<CardInstance> selected = validateDeckSearchSelections(p, effect, selectedDeckCardIds);
        CardInstance trainer = cardInHand(p, cardId);
        if(trainerAttemptRejected(player,trainer,()->playTrainerWithDeckSearches(player,cardId,selected.stream().map(CardInstance::instanceId).toList())))return;
        p.hand.remove(trainer);
        p.deck.removeAll(selected);
        p.hand.addAll(selected);
        shuffle(p.deck, "trainer-search:" + trainer.definitionId());
        moveCardToOwnerDiscard(trainer);
        if (profile.category() == dev.hua.ptcglive.rules.TrainerCategory.SUPPORTER) p.supportersPlayed++;
        captureCardPlayedEvent(player, trainer);
        recordReplay(player, "使用已审核训练家卡并检索牌库卡");
    }
    /** Atomic cost-and-search resolver for an audited Trainer effect. No client can spend fewer cards than printed. */
    public void playTrainerWithDiscardAndDeckSearch(UUID player, UUID cardId, List<UUID> discardedHandCardIds, UUID selectedDeckCardId) {
        playTrainerWithDiscardAndDeckSearches(player, cardId, discardedHandCardIds,
            selectedDeckCardId == null ? List.of() : List.of(selectedDeckCardId));
    }
    /** Atomic cost-and-search resolver with an entire server-validated private deck selection. */
    public void playTrainerWithDiscardAndDeckSearches(UUID player, UUID cardId, List<UUID> discardedHandCardIds, List<UUID> selectedDeckCardIds) {
        var profile = validateTrainer(player, cardId, null);
        var effect = profile.effect();
        require(effect.needsDeckSelection() && effect.discardHandCost() > 0, "此训练家卡不使用弃置成本检索");
        List<UUID> costs = List.copyOf(discardedHandCardIds == null ? List.of() : discardedHandCardIds);
        require(costs.size() == effect.discardHandCost(), "必须弃置恰好 " + effect.discardHandCost() + " 张手牌作为成本");
        require(new java.util.LinkedHashSet<>(costs).size() == costs.size(), "同一张手牌不能重复作为弃置成本");
        PlayerState p = state(player);
        CardInstance trainer = cardInHand(p, cardId);
        List<CardInstance> costCards = new ArrayList<>();
        for (UUID costId : costs) {
            require(!costId.equals(cardId), "打出的训练家卡不能同时作为弃置成本");
            costCards.add(cardInHand(p, costId));
        }
        List<CardInstance> selected = validateDeckSearchSelections(p, effect, selectedDeckCardIds);
        if(trainerAttemptRejected(player,trainer,()->playTrainerWithDiscardAndDeckSearches(player,cardId,costs,selected.stream().map(CardInstance::instanceId).toList())))return;
        p.hand.remove(trainer); p.hand.removeAll(costCards); moveCardsToOwnerDiscard(costCards);
        p.deck.removeAll(selected); p.hand.addAll(selected); shuffle(p.deck, "trainer-cost-search:" + trainer.definitionId());
        moveCardToOwnerDiscard(trainer);
        if (profile.category() == dev.hua.ptcglive.rules.TrainerCategory.SUPPORTER) p.supportersPlayed++;
        captureCardPlayedEvent(player, trainer);
        recordReplay(player, "使用已审核训练家卡，弃置成本并检索牌库卡");
    }
    /** Validates every private deck selection before any card changes zone. */
    private List<CardInstance> validateDeckSearchSelections(PlayerState player, dev.hua.ptcglive.rules.TrainerEffect effect,
                                                             List<UUID> selectedDeckCardIds) {
        // Do not let a malformed null element escape as an unchecked list-copy
        // failure. It is treated like any forged deck id and rejected below.
        List<UUID> selectedIds = selectedDeckCardIds == null ? List.of() : new ArrayList<>(selectedDeckCardIds);
        require(selectedIds.size() >= effect.minimumDeckSelections() && selectedIds.size() <= effect.amount(),
            "必须选择 " + effect.minimumDeckSelections() + " 至 " + effect.amount() + " 张符合条件的牌库卡");
        require(new java.util.LinkedHashSet<>(selectedIds).size() == selectedIds.size(), "同一张牌库卡不能重复选择");
        List<CardInstance> selected = new ArrayList<>();
        for (UUID selectedId : selectedIds) {
            CardInstance card = player.deck.stream().filter(candidate -> candidate.instanceId().equals(selectedId)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("指定卡牌不在你的牌库中"));
            require(effect.allowsDeckSearchCandidate(definition(card)), "指定卡牌不符合此训练家卡的牌库检索条件");
            selected.add(card);
        }
        return selected;
    }
    private int drawEffect(PlayerState p, int requested) {
        int count = Math.min(requested, p.deck.size());
        for (int i = 0; i < count; i++) draw(p, "trainer-draw");
        return count;
    }
    /** Current retention capacity; a prohibition on attaching NEW Tools is deliberately separate. */
    public int currentToolCapacity(UUID player, UUID pokemonId) {
        int capacity=Math.max(1,passiveModifiers(player,pokemonId).toolCapacity());
        for(var ability:activeAbilities(player,pokemonId))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.effectSupport()==EffectSupport.SUPPORTED
                &&ability.effect().opcode()==AbilityEffect.Opcode.PASSIVE_OWN_TOOL_CAPACITY)
                capacity=Math.max(capacity,ability.effect().amount());
        return capacity;
    }
    private boolean toolTurnAdvancePending, toolEffectCheckpointPending;
    private final Set<Knockout> toolDeferredKnockouts=new LinkedHashSet<>(),toolDeferredDirectKnockouts=new LinkedHashSet<>();
    /** A pure projection, not a UI-triggered mutation or random request. */
    public ToolOverflowPrompt toolOverflowPrompt() {
        if(battlefield==null||turnNumber==0||phase==MatchPhase.FINISHED)return null;
        if(trainerBenchDiscardOwner!=null) {
            var prompt=benchOverflowPrompt(trainerBenchDiscardOwner,trainerBenchKeep);
            if(prompt!=null)return prompt;
            trainerBenchDiscardOwner=null;
        }
        if(benchOverflowFirst!=null) {
            var first=benchOverflowPrompt(benchOverflowFirst,benchOverflowForcedLimit==null?benchLimit(benchOverflowFirst):benchOverflowForcedLimit);
            if(first!=null)return first;
            var second=benchOverflowPrompt(other(benchOverflowFirst).id,benchOverflowForcedLimit==null?benchLimit(other(benchOverflowFirst).id):benchOverflowForcedLimit);
            if(second!=null)return second;
            benchOverflowFirst=null;benchOverflowForcedLimit=null;
        }
        for(UUID owner:players.keySet()) {
            var prompt=benchOverflowPrompt(owner,benchLimit(owner));if(prompt!=null)return prompt;
        }
        for(UUID owner:players.keySet()) {
            var field=new ArrayList<>(battlefield.benchView(owner));if(battlefield.hasActive(owner))field.addFirst(battlefield.activeView(owner));
            for(var host:field) {
                if(host.attachedTools().size()<=1)continue;
                int capacity=currentToolCapacity(owner,host.pokemonId());
                if(host.attachedTools().size()<=capacity)continue;
                String signature=id+":"+owner+":"+host.pokemonId()+":"+battlefield.pokemonEntrySequence(owner,host.pokemonId())+":"+capacity;
                for(var card:host.attachedTools())signature+=":"+card.instanceId()+":"+battlefield.attachmentEntrySequence(owner,host.pokemonId(),card.instanceId());
                UUID promptId=UUID.nameUUIDFromBytes(signature.getBytes(java.nio.charset.StandardCharsets.UTF_8));
                return new ToolOverflowPrompt(promptId,owner,host.pokemonId(),capacity,host.attachedTools());
            }
        }
        return null;
    }
    private ToolOverflowPrompt benchOverflowPrompt(UUID owner,int limit) {
        var bench=battlefield.printedBenchView(owner);if(bench.size()<=limit)return null;
        var cards=bench.stream().map(view->battlefield.topCard(owner,view.pokemonId())).toList();
        String signature=id+":bench:"+owner+":"+limit+":"+cards.stream().map(card->card.instanceId().toString()).collect(java.util.stream.Collectors.joining(":"));
        return new ToolOverflowPrompt(UUID.nameUUIDFromBytes(signature.getBytes(java.nio.charset.StandardCharsets.UTF_8)),owner,
            bench.getFirst().pokemonId(),limit,cards,true);
    }
    private void requireNoToolOverflow() {require(toolOverflowPrompt()==null,"请先由工具所属玩家处理超量工具");}
    /** One deliberate discard at a time; recompute capacity after each removed source. */
    public void discardOverflowTool(UUID player,UUID promptId,UUID toolId) {
        var prompt=toolOverflowPrompt();
        require(prompt!=null&&prompt.owner().equals(player)&&prompt.id().equals(promptId),"超量工具选择无权或已更新");
        require(!advancingResolution,"工具选择不能重入");
        require(prompt.tools().stream().anyMatch(c->c.instanceId().equals(toolId)),"卡牌不属于本次超量工具候选");
        if(prompt.bench()) {
            var host=battlefield.printedBenchView(player).stream().filter(view->battlefield.topCard(player,view.pokemonId()).instanceId().equals(toolId))
                .findFirst().orElseThrow(()->new IllegalArgumentException("所选宝可梦已不在备战区"));
            resolvingBenchOverflow=true;advancingResolution=true;
            try {movePokemonOutOfPlay(currentPlayer,player,host.pokemonId(),LeavePlayDestination.DISCARD,false);}
            finally {resolvingBenchOverflow=false;advancingResolution=false;}
            recordReplay(player,"按卡牌效果或备战区上限弃置宝可梦："+toolId);
            if(toolOverflowPrompt()!=null)return;
            resumeAfterOverflow();
            return;
        }
        var card=discardAttachedToolCard(player,prompt.pokemonId(),toolId);
        syncField(player);
        recordReplay(player,"按规则弃置超量工具："+card.definitionId()+"；实体="+toolId+"；宿主="+prompt.pokemonId());
        if(toolOverflowPrompt()!=null)return;
        resumeAfterOverflow();
    }
    /** Bench and Tool correction both suspend the same HP/KO and turn continuations. */
    private void resumeAfterOverflow() {
        settleHitPointChanges();
        if(toolEffectCheckpointPending) {
            toolEffectCheckpointPending=false;
            pendingEffectKnockouts.addAll(toolDeferredKnockouts);pendingDirectKnockouts.addAll(toolDeferredDirectKnockouts);
            toolDeferredKnockouts.clear();toolDeferredDirectKnockouts.clear();
            try{finishEffectCheckpoint();}finally{clearEffectCheckpoint();}
        }
        if(toolTurnAdvancePending)advanceTurn();
        else if(pendingResolution!=null)advancePendingResolution();
        else {drainTriggeredAbilities();finishResumableAttackTurn();}
    }
    /** Existing attached tools and the candidate tool contribute to one server-calculated slot cap. */
    private int toolAttachmentCapacity(UUID player, UUID pokemonId, dev.hua.ptcglive.rules.TrainerProfile candidate,UUID candidateId) {
        // An audited passive can prohibit new Tools outright. Existing cards are
        // not silently discarded: it only constrains the attachment action.
        if (activeAbilities(player, pokemonId).stream().anyMatch(ability ->
            ability.kind() == AbilityDefinition.Kind.PASSIVE && ability.effectSupport() == EffectSupport.SUPPORTED
                && ability.effect().opcode() == AbilityEffect.Opcode.PASSIVE_PREVENT_POKEMON_TOOLS)) return 0;
        boolean toolsDisabled = toolEffectsDisabled(player, pokemonId);
        int capacity=currentToolCapacity(player,pokemonId);
        if(!toolsDisabled)capacity=Math.max(capacity,passiveValues(candidate.ongoingProgram(),new EffectOrigin(EffectOrigin.Kind.TRAINER,player,candidateId),pokemonId,player,pokemonId).toolCapacity());
        // This is evaluated from the current public top card each time a Tool is
        // attached. It is never a client action and therefore cannot leave a
        // stale capacity behind when a Pokémon evolves or leaves play.
        for (AbilityDefinition ability : activeAbilities(player, pokemonId)) {
            if (ability.kind() == AbilityDefinition.Kind.PASSIVE && ability.effectSupport() == EffectSupport.SUPPORTED
                && ability.effect().opcode() == AbilityEffect.Opcode.PASSIVE_OWN_TOOL_CAPACITY)
                capacity = Math.max(capacity, ability.effect().amount());
        }
        return Math.max(1, capacity);
    }
    private boolean printedAbilityGuardTool(UUID owner,UUID pokemon) {
        if(battlefield==null)return false;
        return battlefield.printedPokemonView(owner,pokemon).attachedTools().stream().anyMatch(tool->
            combat.trainer(tool.definitionId()).map(profile->profile.ongoingProgram().triggers().stream()
                .filter(binding->binding.trigger()==EffectTrigger.PASSIVE).flatMap(binding->binding.effects().stream())
                .anyMatch(dev.hua.ptcglive.engine.effect.PassiveRuleProgram::selfAbilityEffectsGuard)).orElse(false));
    }
    private boolean abilityGuardTool(UUID owner,UUID pokemon) {
        return printedAbilityGuardTool(owner,pokemon)&&!toolEffectsDisabled(owner,pokemon);
    }
    /** Removing an existing effect is permanent; suppression only suspends the Tool's protection against new effects. */
    private void settleAbilityGuardEffects() {
        if(battlefield==null)return;
        for(UUID owner:players.keySet())for(var target:publicFieldTargets(owner)) {
            UUID pokemon=target.pokemonId();if(!abilityGuardTool(owner,pokemon))continue;
            battlefield.removeOpponentAbilityEffects(owner,pokemon);
            for(var effect:List.copyOf(delayedPokemonEffects.values()))if(effect.origin().kind()==EffectOrigin.Kind.ABILITY
                &&!effect.origin().controller().equals(owner)&&effect.target().target().equals(target)) {
                if(sameFieldEntry(owner,pokemon,effect.target().entrySequence()))battlefield.removeDelayedMarker(owner,pokemon,effect.token());
                delayedPokemonEffects.remove(effect.token());
            }
            handEnergyCounterTraps.removeIf(e->e.targetOwner().equals(owner)&&e.pokemonId().equals(pokemon)
                &&e.origin().kind()==EffectOrigin.Kind.ABILITY&&!e.origin().controller().equals(owner));
            handEnergyEndTurnTraps.removeIf(e->e.targetOwner().equals(owner)&&e.pokemonId().equals(pokemon)
                &&e.origin().kind()==EffectOrigin.Kind.ABILITY&&!e.origin().controller().equals(owner));
        }
    }
    /** Live Tool suppression: temporary effects and the current Stadium use one authoritative query. */
    private boolean toolEffectsDisabled(UUID owner,UUID pokemonId) {
        if(nonToolSourcesDisableTools(owner,pokemonId))return true;
        if(!battlefield.hasActive(owner)||!battlefield.printedActiveView(owner).pokemonId().equals(pokemonId))return false;
        UUID opponent=other(owner).id;if(!battlefield.hasActive(opponent))return false;
        var source=battlefield.printedActiveView(opponent);
        // Other Jammers never disable this rule. Non-Tool suppression still disables the source.
        if(nonToolSourcesDisableTools(opponent,source.pokemonId()))return false;
        return source.attachedTools().stream().anyMatch(tool->programHasRule(combat.trainer(tool.definitionId()).orElseThrow().ongoingProgram(),"disable_opponent_active_tools"));
    }
    private boolean nonToolSourcesDisableTools(UUID owner,UUID pokemonId) {
        if(battlefield.toolEffectsDisabled(owner,pokemonId,printedAbilityGuardTool(owner,pokemonId)))return true;
        if(stadium==null)return false;
        var program=combat.trainer(stadium.definitionId()).orElseThrow().ongoingProgram();
        return dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(program,
            new ServerConditionContext(stadiumController,null),effect->effect.type().equals("disable_all_tools"));
    }
    public void attachBasicEnergy(UUID player, UUID energyInstanceId) {
        if (battlefield != null) {
            attachEnergy(player, energyInstanceId, battlefield.activeView(player).pokemonId());
            return;
        }
        requireTurn(player); PlayerState p = state(player);
        require(p.energyAttachments < ruleset.turnActionRules().energyAttachmentsFromHand(), "本规则包的每回合能量附着次数已用完");
        CardInstance energy = cardInHand(p, energyInstanceId); require(definition(energy).category() == dev.hua.ptcglive.rules.CardCategory.ENERGY, "只能附着能量卡");
        if (battlefield != null) {
            if (combat.energyProfile(energy.definitionId()).isEmpty())
                throw new IllegalStateException("该能量卡没有已支持的能量供给数据，不能进入正式结算");
            battlefield.attachEnergy(player, p.active.instanceId(), energy);
        }
        p.hand.remove(energy); p.activeEnergy.add(energy); p.energyAttachments++;
        recordReplay(player, "从手牌附着能量");
    }
    /**
     * Reserved for an audited server card-effect resolver. Clients have no
     * intent that calls this method. Lost Zone is public and irreversible in
     * the generic core; retrieving a card requires a dedicated audited effect.
     */
    public void sendToLostZoneByEffect(UUID player, EffectSourceZone source, UUID cardInstanceId) {
        requireTurn(player);
        Objects.requireNonNull(source, "放逐来源区域");
        PlayerState p = state(player);
        List<CardInstance> zone = switch (source) {
            case HAND -> p.hand;
            case DECK -> p.deck;
            case DISCARD -> p.discard;
        };
        CardInstance card = zone.stream().filter(candidate -> candidate.instanceId().equals(cardInstanceId)).findFirst()
            .orElseThrow(() -> new IllegalArgumentException("指定卡牌不在可放逐的服务器区域"));
        zone.remove(card);
        p.lostZone.add(card);
        recordReplay(player, "已审核效果将卡牌移入放逐区");
    }
    /**
     * Server-only hook for an audited card effect that places damage counters.
     * Counters bypass damage modifiers, not immunity to their actual card
     * source. The ordinary Knock Out, Prize and replacement procedure remains.
     */
    public void placeDamageCountersByEffect(UUID player, UUID affectedPlayer, UUID suppliedPokemonId, int counters) {
        if (counters < 1 || counters > 60) throw new IllegalArgumentException("伤害指示物数量无效");
        placeComputedDamageCountersByEffect(player,affectedPlayer,suppliedPokemonId,counters);
    }
    /** One computed placement checks protection once, even when its total exceeds the public action's 60-counter limit. */
    private void placeComputedDamageCountersByEffect(UUID player,UUID affectedPlayer,UUID suppliedPokemonId,int counters) {
        requireTurn(player);requireCombatConfigured();state(affectedPlayer);
        UUID pokemonId=battlefield.printedPokemonView(affectedPlayer,suppliedPokemonId).pokemonId();
        if(counters<1||counters>Integer.MAX_VALUE/10)throw new IllegalArgumentException("计算所得伤害指示物数量无效");
        if(preventsDamageCounterPlacement(affectedPlayer,pokemonId,effectOrigin(player))||preventCardEffect(player,affectedPlayer,pokemonId))return;
        BattlefieldState.DamageResult placed=null;
        for(int remaining=counters;remaining>0;) {
            int batch=Math.min(60,remaining);placed=battlefield.placeDamageCounters(affectedPlayer,pokemonId,batch);remaining-=batch;
        }
        recordReplay(player,"已审核效果放置伤害指示物");
        if(placed.knockedOut())resolveEffectKnockouts(List.of(new Knockout(affectedPlayer,pokemonId)));
    }
    /**
     * Validates both public hosts and the complete source amount before removing counters.
     * An immune source keeps its counters; an immune destination does not receive the removed counters.
     * This is not healing or attack damage and never applies Weakness,
     * Resistance or attack-only damage modifiers.
     */
    public void moveDamageCountersByEffect(UUID player, UUID sourceOwner, UUID sourcePokemonId,
                                            UUID destinationOwner, UUID destinationPokemonId, int counters) {
        if(counters<1||counters>60)throw new IllegalArgumentException("移动伤害指示物数量无效");
        moveComputedDamageCountersByEffect(player,sourceOwner,sourcePokemonId,destinationOwner,destinationPokemonId,counters);
    }
    private void moveComputedDamageCountersByEffect(UUID player,UUID sourceOwner,UUID suppliedSource,UUID destinationOwner,UUID suppliedDestination,int counters) {
        requireTurn(player);requireCombatConfigured();state(sourceOwner);state(destinationOwner);
        if(counters<1||counters>Integer.MAX_VALUE/10)throw new IllegalArgumentException("计算所得移动数量无效");
        var sourceView=battlefield.pokemonView(sourceOwner,suppliedSource);
        UUID sourcePokemonId=sourceView.pokemonId(),destinationPokemonId=battlefield.pokemonView(destinationOwner,suppliedDestination).pokemonId();
        if(sourceOwner.equals(destinationOwner)&&sourcePokemonId.equals(destinationPokemonId))throw new IllegalArgumentException("移动来源和目的地不能相同");
        int damage=Math.multiplyExact(counters,10);
        if(sourceView.damage()<damage)throw new IllegalArgumentException("来源宝可梦没有足够的伤害指示物");
        // Prohibition leaves counters on the original Pokemon; destination immunity does not.
        if(damageCounterMovementBlocked(sourceOwner,sourcePokemonId)||preventCardEffect(player,sourceOwner,sourcePokemonId))return;
        int removed=battlefield.removeDamageForMove(sourceOwner,sourcePokemonId,damage);
        if(removed!=damage)throw new IllegalStateException("伤害指示物移动在提交时失去来源伤害");
        if(preventsDamageCounterPlacement(destinationOwner,destinationPokemonId,effectOrigin(player))
            ||preventCardEffect(player,destinationOwner,destinationPokemonId)) {
            recordReplay(player,"已移除来源伤害指示物；目的地受效果保护，未放置指示物");return;
        }
        BattlefieldState.DamageResult placed=null;
        for(int remaining=counters;remaining>0;){int batch=Math.min(60,remaining);placed=battlefield.placeDamageCounters(destinationOwner,destinationPokemonId,batch);remaining-=batch;}
        recordReplay(player,"已审核效果移动伤害指示物");
        if(placed.knockedOut())resolveEffectKnockouts(List.of(new Knockout(destinationOwner,destinationPokemonId)));
    }

    private int benchToolBonus(UUID owner,UUID pokemon) {
        if(toolEffectsDisabled(owner,pokemon))return 0;
        int total=0;
        for(var tool:battlefield.printedPokemonView(owner,pokemon).attachedTools()) {
            var profile=combat.trainer(tool.definitionId()).orElse(null);
            if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                new ServerConditionContext(owner,pokemon),e->e.type().equals("bench_attack_damage_bonus")&&e.target()==EffectTarget.SELF))total+=30;
        }
        return total;
    }
    private boolean toolAppliesBenchWeakness(UUID defenderOwner,UUID defenderId) {
        return attackCheckpoint!=null&&attackCheckpoint.damageSource!=null&&attackCheckpoint.damageSource.benchWeaknessResistance()
            &&!attackCheckpoint.attacker.owner().equals(defenderOwner)
            &&battlefield.printedBenchView(defenderOwner).stream().anyMatch(p->p.pokemonId().equals(defenderId));
    }
    private int opponentBenchAttackBonus(UUID attackerOwner,UUID defenderOwner,UUID defenderId) {
        if(attackerOwner.equals(defenderOwner)||attackCheckpoint==null||attackCheckpoint.damageSource==null
            ||battlefield.printedBenchView(defenderOwner).stream().noneMatch(p->p.pokemonId().equals(defenderId)))return 0;
        var families=currentFieldDefinition(defenderOwner,defenderId).pokemonFamilies();
        int tool=families.contains(dev.hua.ptcglive.rules.PokemonFamily.V)||families.contains(dev.hua.ptcglive.rules.PokemonFamily.GX)
            ?attackCheckpoint.damageSource.benchToolBonus():0;
        return tool+throwingCoachBonus(attackerOwner,defenderOwner,defenderId);
    }
    private int toolBenchWeaknessDamage(UUID owner,UUID pokemon,int damage) {
        var attack=attackCheckpoint.bodyAttack;
        if(damage<=0||!toolAppliesBenchWeakness(owner,pokemon)||attack.ignoresWeaknessAndResistance())return damage;
        var types=attackCheckpoint.damageSource.types();var profile=battlefield.pokemonProfile(owner,pokemon);
        var weakness=currentWeaknessType(owner,pokemon);
        if(!attack.ignoresWeakness()&&!removesWeakness(owner,pokemon)&&weakness!=null&&types.contains(weakness))
            damage=dev.hua.ptcglive.engine.field.DamageArithmetic.weakness(damage,currentWeaknessBaseMultiplier(owner,pokemon));
        if(!attack.ignoresResistance()&&!stadiumHasPassiveRule("no_resistance")&&profile.resistanceType()!=null&&types.contains(profile.resistanceType()))
            damage=dev.hua.ptcglive.engine.field.DamageArithmetic.resistance(damage,profile.resistanceAmount());
        return damage;
    }
    /** The printed source and each current recipient are checked separately; duplicate Abilities contribute only once. */
    private int throwingCoachBonus(UUID attackerOwner, UUID defenderOwner, UUID defenderId) {
        if(attackerOwner.equals(defenderOwner)||attackCheckpoint==null||attackCheckpoint.damageSource==null
            ||!attackCheckpoint.damageSource.facts().card().battleStyles().contains(dev.hua.ptcglive.rules.BattleStyle.RAPID_STRIKE)
            ||battlefield.printedBenchView(defenderOwner).stream().noneMatch(view->view.pokemonId().equals(defenderId)))
            return 0;
        var defender=fieldCardDefinition(battlefield.printedPokemonView(defenderOwner,defenderId).topCardId());
        if(!defender.pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.V)
            &&!defender.pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.GX))return 0;
        for(var host:publicFieldTargets(attackerOwner)) {
            var origin=new EffectOrigin(EffectOrigin.Kind.ABILITY,attackerOwner,host.pokemonId());
            if(sameFieldEntry(attackerOwner,attackCheckpoint.attacker.pokemonId(),attackCheckpoint.attackerEntrySequence)
                &&preventsImpact(attackerOwner,attackCheckpoint.attacker.pokemonId(),origin,EffectProtection.Impact.OTHER_EFFECTS))
                continue;
            for(var ability:activeAbilities(attackerOwner,host.pokemonId()))
                if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                    &&ability.effectSupport()==EffectSupport.SUPPORTED
                    &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),
                        new ServerConditionContext(attackerOwner,host.pokemonId()),
                        effect->effect.type().equals("bench_attack_damage_bonus")))
                    return 30; // One Throwing Coach at most, even with multiple Passimian in play.
        }
        return 0;
    }
    /**
     * A selected Bench target takes attack damage, rather than damage counters.
     * Weakness and Resistance apply only when the attacking Tool permits them; public damage
     * prevention/reduction, attack-damage triggers, Knock Outs and Prizes stay
     * in the same authoritative attack checkpoint as the printed attack.
     */
    private int calculateBenchDamageBeforeCoin(UUID player, UUID affectedPlayer, UUID pokemonId, int amount) {
        requireTurn(player); requireCombatConfigured(); state(affectedPlayer);
        require(attackCheckpoint != null && attackCheckpoint.attacker.owner().equals(player),
            "备战伤害必须属于当前服务器攻击");
        require(battlefield.benchView(affectedPlayer).stream().anyMatch(view -> view.pokemonId().equals(pokemonId)),
            "BenchDamageEffect 只能指定当前备战宝可梦");
        if(amount==0)return 0;
        if (amount < 10 || amount > 1_000 || amount % 10 != 0)
            throw new IllegalArgumentException("备战攻击伤害必须是 10 至 1000 的 10 倍数");
        var target = battlefield.pokemonView(affectedPlayer, pokemonId);
        // Validate any ON_DAMAGE programs before this step can mutate the field.
        preflightDamageReactions(affectedPlayer, List.of(target));
        var attacker = attackCheckpoint.attacker;
        var origin = new EffectOrigin(EffectOrigin.Kind.ATTACK, attacker.owner(), attacker.pokemonId());
        require(attackCheckpoint.damageSource!=null,"备战伤害缺少当前攻击的伤害计算状态");
        int sourceChange = attackCheckpoint.damageSource.modifiers().damageDealtChange(!attacker.owner().equals(affectedPlayer))
            - attackCheckpoint.damageSource.penalty()
            + opponentBenchAttackBonus(attacker.owner(),affectedPlayer,pokemonId);
        int adjusted = toolBenchWeaknessDamage(affectedPlayer,pokemonId,Math.max(0, amount + sourceChange));
        boolean protectedTarget = preventsImpact(affectedPlayer, pokemonId, origin, EffectProtection.Impact.DAMAGE)
            || passivelyPreventsAttackDamage(affectedPlayer, pokemonId, origin) || benchedPreventsAttackDamage(affectedPlayer, pokemonId);
        int reduction = battlefield.attackDamageReduction(affectedPlayer, pokemonId, attacker.owner())
            + playerTurnDamageReduction(affectedPlayer,pokemonId,attacker.owner());
        int passiveReduction = passiveAttackDamageReduction(affectedPlayer, pokemonId, origin);
        int receivedChange = adjusted == 0 ? 0 : passiveModifiers(affectedPlayer, pokemonId).damageReceivedChange(!attacker.owner().equals(affectedPlayer));
        int temporaryChange = adjusted==0?0:battlefield.attackDamageReceivedChange(affectedPlayer,pokemonId,attacker.owner(),attackCheckpoint.damageSource.facts());
        int finalDamage = protectedTarget ? 0 : Math.max(0, adjusted - reduction - passiveReduction + receivedChange + temporaryChange);
        if(passiveAttackGuard(affectedPlayer,pokemonId,origin).prevents(finalDamage))finalDamage=0;
        return finalDamage;
    }
    private void applyBenchDamageByEffect(UUID player,UUID affectedPlayer,UUID pokemonId,int amount) {
        int finalDamage=calculateBenchDamageBeforeCoin(player,affectedPlayer,pokemonId,amount);
        var target=battlefield.pokemonView(affectedPlayer,pokemonId);
        if (coinPreventsAttackDamage(affectedPlayer, pokemonId, finalDamage)) finalDamage = 0;
        BattlefieldState.DamageResult result = battlefield.damagePokemon(affectedPlayer, pokemonId, finalDamage);
        if (finalDamage > 0) {
            boolean lethal=result.knockedOut()&&!surviveFullHpAttackDamage(affectedPlayer,pokemonId,player,target.damage()==0,result.knockedOut());
            recordAttackDamage(new AttackDamageEvent(affectedPlayer, pokemonId, finalDamage, false, lethal,
                battlefield.pokemonEntrySequence(affectedPlayer, pokemonId),target.damage()==0));
        }
        recordReplay(player, "攻击效果对备战宝可梦造成伤害：" + finalDamage);
    }
    /** Dragon Launcher deals attack damage to either position, but never applies Weakness or Resistance. */
    private void applyDragonLauncherDamage(UUID player,UUID pokemonId) {
        requireTurn(player);requireCombatConfigured();
        UUID opponent=other(player).id;
        require(attackCheckpoint!=null&&attackCheckpoint.attacker.owner().equals(player)
            &&attackCheckpoint.damageSource!=null&&attackCheckpoint.bodyAttack!=null,
            "龙之发射器缺少当前攻击伤害状态");
        require(publicFieldTargets(opponent).stream().anyMatch(target->target.pokemonId().equals(pokemonId)),
            "龙之发射器只能伤害当前对手在场宝可梦");
        var attacker=attackCheckpoint.attacker;
        var origin=new EffectOrigin(EffectOrigin.Kind.ATTACK,player,attacker.pokemonId());
        boolean active=battlefield.hasActive(opponent)&&battlefield.activeView(opponent).pokemonId().equals(pokemonId);
        var victim=battlefield.pokemonView(opponent,pokemonId);
        int damage=100+attackCheckpoint.damageSource.modifiers().damageDealtChange(true)
            -attackCheckpoint.damageSource.penalty();
        if(active)damage+=attackCheckpoint.damageSource.modifiers().activeDamageDealtChange()
            +playerTurnAttackBonus(player,battlefield.pokemonView(player,attacker.pokemonId()))
            +battlefield.attackDamageBonus(player,attacker.pokemonId(),attackCheckpoint.costAttack.id());
        else damage+=opponentBenchAttackBonus(player,opponent,pokemonId);
        boolean nativeBypass=attackCheckpoint.bodyAttack.ignoresActiveDefenderDamageEffects()
            ||pokemonHasPassiveRule(player,attacker.pokemonId(),"ignore_defender_damage_effects");
        boolean bypass=nativeBypass||active&&playerTurnAttackBypass(player,attacker.pokemonId());
        if(damage>0 && !bypass) {
            if(preventsImpact(opponent,pokemonId,origin,EffectProtection.Impact.DAMAGE)
                ||passivelyPreventsAttackDamage(opponent,pokemonId,origin)
                ||stadiumPreventsAttackDamage(opponent,pokemonId,origin)
                ||!active&&benchedPreventsAttackDamage(opponent,pokemonId))damage=0;
        }
        if(damage>0) {
            damage=Math.max(0,damage
                -(bypass?0:battlefield.attackDamageReduction(opponent,pokemonId,player)
                    +playerTurnDamageReduction(opponent,pokemonId,player)
                    +passiveAttackDamageReduction(opponent,pokemonId,origin))
                +(bypass?0:passiveModifiers(opponent,pokemonId).damageReceivedChange(true)
                    +battlefield.damageTakenIncrease(opponent,pokemonId)
                    +battlefield.attackDamageReceivedChange(opponent,pokemonId,player,attackCheckpoint.damageSource.facts())));
        } else damage=0;
        if(!bypass&&passiveAttackGuard(opponent,pokemonId,origin).prevents(damage))damage=0;
        if(!bypass&&coinPreventsAttackDamage(opponent,pokemonId,damage))damage=0;
        int maximumGuard=bypass?0:battlefield.attackDamageMaximumGuard(opponent,pokemonId,player);
        if(damage>0&&maximumGuard>0&&damage<=maximumGuard)damage=0;
        var result=battlefield.damagePokemon(opponent,pokemonId,damage);
        boolean lethal=result.knockedOut();
        if(lethal&&(!nativeBypass||!active))lethal=!surviveFullHpAttackDamage(opponent,pokemonId,player,victim.damage()==0,true);
        if(damage>0) {
            EnergyType opponentActiveType=battlefield.hasActive(player)
                ?currentPrimaryPokemonType(player,battlefield.activeView(player).pokemonId()):null;
            recordAttackDamage(new AttackDamageEvent(opponent,pokemonId,damage,active,lethal,
                battlefield.pokemonEntrySequence(opponent,pokemonId),victim.damage()==0,opponentActiveType));
        }
        recordReplay(player,"龙之发射器对对手宝可梦造成攻击伤害："+damage);
    }
    /**
     * Server-only hook for a reviewed effect that directly Knocks Out one
     * public in-play Pokémon. It deliberately does not calculate attack damage,
     * Weakness, Resistance or damage counters; the shared Knock Out resolver
     * remains responsible for all card movement, Prizes and replacements.
     */
    public void knockOutPokemonByEffect(UUID player, UUID affectedPlayer, UUID pokemonId) {
        knockOutPokemonByEffect(player, InPlayTargetScope.ANY_FIELD, affectedPlayer, pokemonId);
    }
    /** Direct Knock Out with an audited public target scope. */
    public void knockOutPokemonByEffect(UUID player, InPlayTargetScope targetScope, UUID affectedPlayer, UUID suppliedPokemonId) {
        tryKnockOutPokemonByEffect(player,targetScope,affectedPlayer,suppliedPokemonId);
    }
    private boolean tryKnockOutPokemonByEffect(UUID player, InPlayTargetScope targetScope, UUID affectedPlayer, UUID suppliedPokemonId) {
        requireTurn(player); requireCombatConfigured(); state(affectedPlayer);
        UUID pokemonId=battlefield.printedPokemonView(affectedPlayer,suppliedPokemonId).pokemonId();
        Objects.requireNonNull(targetScope, "直接击倒目标范围");
        // Validate the current public target before marking it Knocked Out.
        battlefield.pokemonView(affectedPlayer, pokemonId);
        if (!inPlayTargetAllowed(player, targetScope, affectedPlayer, pokemonId))
            throw new IllegalArgumentException("所选宝可梦不在本效果允许的目标范围内");
        if (preventCardEffect(player,affectedPlayer,pokemonId)) return false;
        battlefield.knockOutPokemonByEffect(affectedPlayer, pokemonId);
        recordReplay(player, "已审核效果直接击倒宝可梦");
        var knockout = new Knockout(affectedPlayer, pokemonId);
        if(attackCheckpoint!=null) attackCheckpoint.attackDamageKnockouts.remove(knockout);
        if (resolvingEffectProgram) pendingDirectKnockouts.add(knockout);
        resolveEffectKnockouts(List.of(knockout));
        return true;
    }
    /**
     * Server-only multi-target allocation. All public targets are validated
     * before damage is placed, then Knock Outs are resolved together so a
     * distributed effect never awards Prizes in an arbitrary target order.
     */
    public void placeDamageCountersAcrossTargetsByEffect(UUID player, List<DamageCounterPlacement> placements) {
        requireTurn(player); requireCombatConfigured();
        List<DamageCounterPlacement> safe = validateDamageCounterPlacements(placements);
        List<Knockout> knocked = placeValidatedDamageCounters(safe);
        recordReplay(player, "已审核效果分配伤害指示物");
        if (!knocked.isEmpty()) resolveEffectKnockouts(knocked);
    }
    /**
     * Server-only allocation for effects that say to distribute exactly a fixed
     * number of damage counters. The total is checked before any target takes
     * damage, so a forged or stale client selection cannot partly resolve an
     * effect by underpaying, overpaying or repeating a target.
     */
    public void placeExactDamageCountersAcrossTargetsByEffect(UUID player, int counterBudget,
                                                               List<DamageCounterPlacement> placements) {
        placeExactDamageCountersAcrossTargetsByEffect(player,
            new DamageCounterAllocation(counterBudget, InPlayTargetScope.ANY_FIELD, 1, 60), placements);
    }
    /**
     * Fixed-budget allocation with an audited public target policy. The
     * selected targets, their number and their total counters are all checked
     * before any damage is placed, preventing clients from expanding a card's
     * target range or partly resolving an invalid allocation.
     */
    public void placeExactDamageCountersAcrossTargetsByEffect(UUID player, DamageCounterAllocation allocation,
                                                               List<DamageCounterPlacement> placements) {
        requireTurn(player); requireCombatConfigured();
        Objects.requireNonNull(allocation, "伤害指示物分配规则");
        List<DamageCounterPlacement> safe = validateDamageCounterPlacements(placements);
        if (safe.size() < allocation.minTargets() || safe.size() > allocation.maxTargets())
            throw new IllegalArgumentException("本效果必须选择 " + allocation.minTargets() + " 至 " + allocation.maxTargets() + " 个目标");
        for (DamageCounterPlacement placement : safe) {
            if (!inPlayTargetAllowed(player, allocation.targetScope(), placement.affectedPlayer(), placement.pokemonId()))
                throw new IllegalArgumentException("所选宝可梦不在本效果允许的目标范围内");
        }
        int allocated = safe.stream().mapToInt(DamageCounterPlacement::counters).sum();
        if (allocated != allocation.counterBudget())
            throw new IllegalArgumentException("本效果必须恰好分配 " + allocation.counterBudget() + " 个伤害指示物，当前为 " + allocated + " 个");
        List<Knockout> knocked = placeValidatedDamageCounters(safe);
        recordReplay(player, "已审核效果按额度分配伤害指示物（" + allocation.counterBudget() + "个）");
        if (!knocked.isEmpty()) resolveEffectKnockouts(knocked);
    }
    /** Validates every public target before the caller mutates the battlefield. */
    private List<DamageCounterPlacement> validateDamageCounterPlacements(List<DamageCounterPlacement> placements) {
        if (placements == null || placements.isEmpty()) throw new IllegalArgumentException("至少选择一个伤害指示物目标");
        List<DamageCounterPlacement> safe = List.copyOf(placements);
        java.util.Set<String> identities = new java.util.HashSet<>();
        for (DamageCounterPlacement placement : safe) {
            state(placement.affectedPlayer());
            if (!identities.add(placement.affectedPlayer() + ":" + placement.pokemonId()))
                throw new IllegalArgumentException("同一宝可梦不能在同一次分配中重复选择");
            battlefield.pokemonView(placement.affectedPlayer(), placement.pokemonId());
        }
        return safe;
    }
    /** Resolves an audited target scope exclusively from current public battlefield identities. */
    private boolean inPlayTargetAllowed(UUID player, InPlayTargetScope scope, UUID affectedPlayer, UUID pokemonId) {
        boolean own = player.equals(affectedPlayer);
        boolean active = battlefield.hasActive(affectedPlayer)
            && battlefield.activeView(affectedPlayer).pokemonId().equals(pokemonId);
        return switch (scope) {
            case OWN_ACTIVE -> own && active;
            case OWN_BENCH -> own && !active;
            case OWN_FIELD -> own;
            case OPPONENT_ACTIVE -> !own && active;
            case OPPONENT_BENCH -> !own && !active;
            case OPPONENT_FIELD -> !own;
            case ANY_FIELD -> true;
        };
    }
    /** All targets were prevalidated; defer Knock Outs so the allocation resolves simultaneously. */
    private List<Knockout> placeValidatedDamageCounters(List<DamageCounterPlacement> placements) {
        List<Knockout> knocked = new ArrayList<>();
        for (DamageCounterPlacement placement : placements) {
            if (preventsDamageCounterPlacement(placement.affectedPlayer(),placement.pokemonId(),effectOrigin(currentPlayer))
                ||preventCardEffect(currentPlayer,placement.affectedPlayer(),placement.pokemonId())) continue;
            BattlefieldState.DamageResult result = battlefield.placeDamageCounters(placement.affectedPlayer(), placement.pokemonId(), placement.counters());
            if (result.knockedOut()) knocked.add(new Knockout(placement.affectedPlayer(), placement.pokemonId()));
        }
        return knocked;
    }
