    /**
     * Server-only energy attachment from a card-effect source. It bypasses the
     * once-per-turn manual attachment cap, but still verifies the source card,
     * its energy data and the public in-play target.
     */
    public void attachEnergyByEffect(UUID player, UUID sourceOwner, EffectSourceZone source, UUID energyInstanceId,
                                     UUID targetOwner, UUID targetPokemonId) {
        attachEnergyByEffect(player, new EnergyAttachmentPolicy(1, 1, InPlayTargetScope.ANY_FIELD, false, java.util.Set.of()),
            sourceOwner, source, List.of(energyInstanceId), targetOwner, targetPokemonId, "已审核效果附着能量");
    }
    private void applyHandEnergyCounterTrap(UUID targetOwner,UUID pokemonId,UUID sourceOwner,EffectSourceZone source,int cards) {
        if(source!=EffectSourceZone.HAND||!targetOwner.equals(sourceOwner)||cards<=0)return;
        var active=battlefield.hasActive(targetOwner)?battlefield.printedActiveView(targetOwner):null;
        for(var trap:List.copyOf(handEnergyCounterTraps)) {
            boolean live=turnNumber==trap.dueTurn()&&currentPlayer.equals(targetOwner)&&trap.targetOwner().equals(targetOwner)
                &&trap.pokemonId().equals(pokemonId)&&active!=null&&active.pokemonId().equals(pokemonId)
                &&sameFieldEntry(targetOwner,pokemonId,trap.entry())
                &&battlefield.topCard(targetOwner,pokemonId).instanceId().equals(trap.topCard());
            if(!live)continue;
            withOrigin(trap.origin(),()->placeDamageCountersByEffect(currentPlayer,targetOwner,pokemonId,Math.multiplyExact(trap.counters(),cards)));
        }
        boolean end=false;
        for(var trap:List.copyOf(handEnergyEndTurnTraps)) {
            boolean live=turnNumber==trap.dueTurn()&&currentPlayer.equals(targetOwner)&&trap.targetOwner().equals(targetOwner)
                &&trap.pokemonId().equals(pokemonId)&&active!=null&&active.pokemonId().equals(pokemonId)
                &&sameFieldEntry(targetOwner,pokemonId,trap.entry())
                &&battlefield.topCard(targetOwner,pokemonId).instanceId().equals(trap.topCard());
            if(live){end=true;recordReplay(trap.effectOwner(),"梦境效果：对手从手牌向防守宝可梦附能，回合结束");}
        }
        handEnergyCounterTraps.removeIf(t->t.dueTurn()<turnNumber||t.dueTurn()==turnNumber&&!currentPlayer.equals(t.targetOwner()));
        handEnergyEndTurnTraps.removeIf(t->t.dueTurn()<turnNumber||t.dueTurn()==turnNumber&&!currentPlayer.equals(t.targetOwner()));
        if(end&&phase==MatchPhase.TURN)endTurn(targetOwner);
    }
    /** Server-only bulk Energy attachment with explicit source-card and public-target constraints. */
    public void attachEnergyByEffect(UUID player, EnergyAttachmentPolicy policy, UUID sourceOwner, EffectSourceZone source,
                                     List<UUID> energyInstanceIds, UUID targetOwner, UUID targetPokemonId) {
        attachEnergyByEffect(player, policy, sourceOwner, source, energyInstanceIds, targetOwner, targetPokemonId,
            "已审核效果按条件附着能量");
    }
    private void attachEnergyByEffect(UUID player, EnergyAttachmentPolicy policy, UUID sourceOwner, EffectSourceZone source,
                                      List<UUID> energyInstanceIds, UUID targetOwner, UUID targetPokemonId, String replayOperation) {
        attachEnergyByEffect(player,policy,sourceOwner,source,energyInstanceIds,targetOwner,targetPokemonId,replayOperation,false);
    }
    private void attachEnergyByEffect(UUID player, EnergyAttachmentPolicy policy, UUID sourceOwner, EffectSourceZone source,
                                      List<UUID> energyInstanceIds, UUID targetOwner, UUID suppliedTargetPokemonId, String replayOperation,boolean discardInvalid) {
        attachEnergyByEffect(player,policy,sourceOwner,source,energyInstanceIds,targetOwner,suppliedTargetPokemonId,replayOperation,discardInvalid,true);
    }
    private void attachEnergyByEffect(UUID player, EnergyAttachmentPolicy policy, UUID sourceOwner, EffectSourceZone source,
                                      List<UUID> energyInstanceIds, UUID targetOwner, UUID suppliedTargetPokemonId, String replayOperation,boolean discardInvalid,boolean shuffleDeck) {
        requireTurn(player); requireCombatConfigured(); Objects.requireNonNull(policy, "能量附着规则");
        UUID targetPokemonId=battlefield.printedPokemonView(targetOwner,suppliedTargetPokemonId).pokemonId();
        Objects.requireNonNull(source, "能量来源区域");
        PlayerState from = state(sourceOwner); state(targetOwner);
        List<UUID> selected = List.copyOf(energyInstanceIds == null ? List.of() : energyInstanceIds);
        if (selected.size() < policy.minCards() || selected.size() > policy.maxCards())
            throw new IllegalArgumentException("本效果必须选择 " + policy.minCards() + " 至 " + policy.maxCards() + " 张能量");
        if (new java.util.LinkedHashSet<>(selected).size() != selected.size())
            throw new IllegalArgumentException("同一张能量不能重复附着");
        require(inPlayTargetAllowed(player, policy.targetScope(), targetOwner, targetPokemonId), "能量附着目标不符合本效果范围");
        // Validate target and every source card before moving any hidden zone card.
        battlefield.pokemonView(targetOwner, targetPokemonId);
        List<CardInstance> sourceZone = switch (source) {
            case HAND -> from.hand;
            case DISCARD -> from.discard;
            case DECK -> from.deck;
        };
        List<CardInstance> energies = new ArrayList<>();
        for (UUID energyId : selected) {
            CardInstance energy = sourceZone.stream().filter(card -> card.instanceId().equals(energyId)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("指定能量不在效果来源区域"));
            require(policy.allows(definition(energy)) && combat.energyProfile(energy.definitionId()).isPresent(),
                "指定能量不符合本效果的附着条件或缺少可用的能量数据");
            require(energyAttachmentByEffectAllowed(energy,targetOwner,targetPokemonId,sourceOwner,source,discardInvalid),"未支持：效果覆盖特殊能量宿主限制及其触发／弃置顺序尚未核验");
            energies.add(energy);
        }
        if (preventCardEffect(player,targetOwner,targetPokemonId)) {
            // Protection stops attachment to the Pokemon, not the independent deck-search shuffle.
            if (source == EffectSourceZone.DECK && shuffleDeck) shuffle(from.deck, "effect-attach-deck-energy:" + sourceOwner);
            return;
        }
        if(handEnergyLockDiscardsEffectAttempt(targetOwner,targetPokemonId,sourceOwner,source)) {
            // Discard the physical cards directly: no transient provision, immunity or attachment event.
            sourceZone.removeAll(energies);
            moveCardsToOwnerDiscard(energies);
            recordReplay(player,"附能效果受到手牌附能限制，所选能量放入原拥有者弃牌区");
            return;
        }
        Runnable attach = () -> {
            var events = energies.stream().map(energy -> matchingEnergyAbilities(targetOwner, targetPokemonId, energy,
                source, EnergyTriggerPolicy.Cause.EFFECT,sourceOwner)).toList();
            sourceZone.removeAll(energies);
            long batch = ++triggerEventBatch;
            for (int i = 0; i < energies.size(); i++) {
                battlefield.attachEnergyByEffect(targetOwner, targetPokemonId, energies.get(i));
                captureTriggeredAbilities(events.get(i), batch);
                captureTriggeredAbilities(persistentEnergyCandidates(targetOwner,targetPokemonId,energies.get(i),source,EnergyTriggerPolicy.Cause.EFFECT,persistentListeners(),sourceOwner),batch);
            }
            applyHandEnergyCounterTrap(targetOwner,targetPokemonId,sourceOwner,source,energies.size());
            settleEnergyConditionImmunity();
            if (source == EffectSourceZone.DECK && shuffleDeck) shuffle(from.deck, "effect-attach-deck-energy:" + sourceOwner);
            recordReplay(player, replayOperation);
        };
        Runnable commit=()->{if(resolvingEffectProgram)attach.run();else resolveEffectProgram(attach);};
        if(!requestEnergyHandCost(sourceOwner,source,energies,energies,List.of(energyCostHost(targetOwner,targetPokemonId)),commit))commit.run();
    }
    /**
     * Atomically attaches selected source Energy cards to individually chosen
     * public hosts. Unlike the legacy bulk helper, the deck is shuffled once
     * and no host/card pair is accepted until every pair has been rechecked.
     */
    private void attachEnergyDistributedByEffect(UUID player, EnergyAttachmentPolicy policy, UUID sourceOwner, EffectSourceZone source,
                                                  Map<PokemonCandidate, List<CardInstance>> groups,boolean shuffleDeck) {
        requireTurn(player); requireCombatConfigured(); Objects.requireNonNull(policy, "能量附着规则");
        Objects.requireNonNull(source, "能量来源区域"); Objects.requireNonNull(groups, "能量分配方案");
        var sourceZone = switch (source) {
            case HAND -> state(sourceOwner).hand;
            case DISCARD -> state(sourceOwner).discard;
            case DECK -> state(sourceOwner).deck;
        };
        var all = new ArrayList<CardInstance>();
        for (var entry : groups.entrySet()) {
            PokemonCandidate host = entry.getKey();
            require(inPlayTargetAllowed(player, policy.targetScope(), host.target().owner(), host.target().pokemonId()), "能量附着目标不符合本效果范围");
            require(sameFieldEntry(host.target().owner(), host.target().pokemonId(), host.entrySequence()), "能量附着目标已离场或重新登场");
            for (CardInstance energy : entry.getValue()) {
                require(sourceZone.stream().anyMatch(card -> card.instanceId().equals(energy.instanceId())), "指定能量不在效果来源区域");
                require(policy.allows(definition(energy)) && combat.energyProfile(energy.definitionId()).isPresent(),
                    "指定能量不符合本效果的附着条件或缺少可用的能量数据");
                require(energyAttachmentByEffectAllowed(energy, host.target().owner(), host.target().pokemonId(),sourceOwner,source,false), "该能量当前不能附着到此目标");
                all.add(energy);
            }
        }
        if (all.size() < policy.minCards() || all.size() > policy.maxCards())
            throw new IllegalArgumentException("本效果必须选择 " + policy.minCards() + " 至 " + policy.maxCards() + " 张能量");
        if (all.stream().map(CardInstance::instanceId).collect(java.util.stream.Collectors.toSet()).size() != all.size())
            throw new IllegalArgumentException("同一张能量不能重复附着");
        var applied = new LinkedHashMap<PokemonCandidate, List<CardInstance>>();
        for (var entry : groups.entrySet()) if (!preventCardEffect(player, entry.getKey().target().owner(), entry.getKey().target().pokemonId()))
            applied.put(entry.getKey(), List.copyOf(entry.getValue()));
        if (applied.isEmpty()) {
            settleEnergyConditionImmunity();
            if (shuffleDeck&&source == EffectSourceZone.DECK) shuffle(sourceZone, "effect-attach-deck-energy:" + sourceOwner);
            return;
        }
        Runnable attach = () -> {
            var attached = applied.values().stream().flatMap(List::stream).toList();
            sourceZone.removeAll(attached);
            boolean hasAttachment=applied.keySet().stream().anyMatch(host->!handEnergyLockDiscardsEffectAttempt(host.target().owner(),host.target().pokemonId(),sourceOwner,source));
            long batch = hasAttachment ? ++triggerEventBatch : triggerEventBatch;
            for (var entry : applied.entrySet()) {
                PokemonCandidate host = entry.getKey();
                if(handEnergyLockDiscardsEffectAttempt(host.target().owner(),host.target().pokemonId(),sourceOwner,source)) {
                    moveCardsToOwnerDiscard(entry.getValue());
                    recordReplay(player,"分配附能受到手牌附能限制，所选能量放入原拥有者弃牌区");
                    continue;
                }
                for (CardInstance energy : entry.getValue()) {
                    var events = matchingEnergyAbilities(host.target().owner(), host.target().pokemonId(), energy, source, EnergyTriggerPolicy.Cause.EFFECT,sourceOwner);
                    battlefield.attachEnergyByEffect(host.target().owner(), host.target().pokemonId(), energy);
                    captureTriggeredAbilities(events, batch);
                    captureTriggeredAbilities(persistentEnergyCandidates(host.target().owner(), host.target().pokemonId(), energy,
                        source, EnergyTriggerPolicy.Cause.EFFECT, persistentListeners(),sourceOwner), batch);
                }
                applyHandEnergyCounterTrap(host.target().owner(),host.target().pokemonId(),sourceOwner,source,entry.getValue().size());
            }
            if (shuffleDeck&&source == EffectSourceZone.DECK) shuffle(sourceZone, "effect-attach-deck-energy:" + sourceOwner);
            recordReplay(player, "已审核效果分配附着能量");
        };
        var payable=applied.entrySet().stream().filter(entry->!handEnergyLockDiscardsEffectAttempt(entry.getKey().target().owner(),entry.getKey().target().pokemonId(),sourceOwner,source))
            .flatMap(entry->entry.getValue().stream()).toList();
        Runnable commit=()->{if(resolvingEffectProgram)attach.run();else resolveEffectProgram(attach);};
        if(!requestEnergyHandCost(sourceOwner,source,all,payable,List.copyOf(applied.keySet()),commit))commit.run();
    }
    /** Server-only hook for an audited effect that discards one or more attached Energy cards. */
    public void discardAttachedEnergyByEffect(UUID player, UUID affectedPlayer, UUID pokemonId, List<UUID> energyInstanceIds) {
        discardAttachedEnergyByEffect(player,affectedPlayer,pokemonId,energyInstanceIds,fieldDiscardReturnCards());
    }
    private void discardAttachedEnergyByEffect(UUID player,UUID affectedPlayer,UUID pokemonId,List<UUID> energyInstanceIds,Set<UUID> discardReturns) {
        requireTurn(player); requireCombatConfigured();
        List<CardInstance> returned = nitroEnergyReturnedAfterAttackDiscard(affectedPlayer,pokemonId,
            battlefield.attachedEnergy(affectedPlayer,pokemonId).stream().filter(c->energyInstanceIds.contains(c.instanceId())).toList());
        List<CardInstance> discarded = battlefield.detachEnergy(affectedPlayer, pokemonId, energyInstanceIds);
        if(attackCheckpoint!=null&&pendingResolution!=null&&pendingResolution.attack()!=null
            &&attackCheckpoint.attacker.owner().equals(affectedPlayer)&&attackCheckpoint.attacker.pokemonId().equals(pokemonId)
            &&sameFieldEntry(affectedPlayer,pokemonId,attackCheckpoint.attackerEntrySequence))
            attackCheckpoint.boomerangEnergy.addAll(discarded.stream().filter(card->"sv6_en_166".equals(card.definitionId())).toList());
        if(attackCheckpoint!=null)attackCheckpoint.nitroEnergy.addAll(returned);
        moveCardsToOwnerDiscard(discarded,discardReturns);
        recordReplay(player, "已审核效果弃置场上的能量");
        settleHitPointChanges();
    }

    /** Nitro {R} Energy returns only when an attack effect discarded it from its Fire attacker. */
    private List<CardInstance> nitroEnergyReturnedAfterAttackDiscard(UUID affectedPlayer, UUID pokemonId, List<CardInstance> discarded) {
        if (attackCheckpoint == null || pendingResolution == null || pendingResolution.attack() == null
            || !attackCheckpoint.attacker.owner().equals(affectedPlayer)
            || !attackCheckpoint.attacker.pokemonId().equals(pokemonId)
            || !isFirePokemon(affectedPlayer, pokemonId)) return List.of();
        return discarded.stream().filter(card -> Set.of("me4_en_086","me6_en_134").contains(card.definitionId())
            &&effectiveEnergyCard(affectedPlayer,card).equals(combat.energyProfile(card.definitionId()).orElseThrow())).toList();
    }

    private boolean isFirePokemon(UUID owner, UUID pokemonId) {
        return currentPokemonTypes(owner,pokemonId).contains(EnergyType.FIRE);
    }
    /** Server-only hook for an audited effect that moves existing attached Energy between public targets. */
