    /** Server-only hook for an audited effect that returns attached Energy to its owner's hand. */
    public void returnAttachedEnergyToHandByEffect(UUID player, UUID affectedPlayer, UUID pokemonId, List<UUID> energyInstanceIds) {
        requireTurn(player); requireCombatConfigured();
        if(opponentPreventsReturnToHand(affectedPlayer)) {recordReplay(player,"平稳境地阻止附着能量回到手牌");return;}
        List<CardInstance> returned = battlefield.detachEnergy(affectedPlayer, pokemonId, energyInstanceIds);
        moveCardsToOwnerHand(returned);
        recordReplay(player, "已审核效果将附着能量回到手牌");
        settleHitPointChanges();
    }
    /**
     * Server-only hook for an audited effect that returns a public attached
     * Tool to its actual owner's hidden hand.  The owner is read from the
     * card instance instead of inferred from the affected field, so this
     * remains correct for old saves as well as future control-changing cards.
     */
    public void returnAttachedToolToHandByEffect(UUID player, UUID affectedPlayer, UUID pokemonId, UUID toolInstanceId) {
        requireTurn(player); requireCombatConfigured();
        if(opponentPreventsReturnToHand(affectedPlayer)) {recordReplay(player,"平稳境地阻止宝可梦工具回到手牌");return;}
        CardInstance tool = battlefield.detachTool(affectedPlayer, pokemonId, toolInstanceId);
        moveCardsToOwnerHand(List.of(tool));
        // Replacement effects can send a detached Tool to discard instead. Announce only its actual destination.
        recordReplay(player, state(tool.ownerId()).hand.contains(tool)
            ? "公开工具回手·"+affectedPlayer+"·"+pokemonId+"·"+tool.instanceId()+"·"+tool.ownerId()
            : "已审核效果将附着宝可梦工具回到手牌");
        settleHitPointChanges();
    }
    private boolean opponentPreventsReturnToHand(UUID affectedPlayer) {
        UUID blocker=other(affectedPlayer).id;
        for(var host:publicFieldTargets(blocker))for(var ability:activeAbilities(blocker,host.pokemonId()))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()&&ability.effectSupport()==EffectSupport.SUPPORTED
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(blocker,host.pokemonId()),
                    effect->effect.type().equals("prevent_return_to_hand")&&effect.target()==EffectTarget.ALL_OPPONENT_POKEMON))return true;
        return false;
    }
    /** Server-only attachment of an actual Tool card from a reviewed effect source. */
    public void attachToolByEffect(UUID player, UUID sourceOwner, EffectSourceZone source, UUID toolInstanceId,
                                   UUID targetOwner, UUID targetPokemonId) {
        requireTurn(player); requireCombatConfigured();
        PlayerState from = state(sourceOwner); state(targetOwner);
        List<CardInstance> sourceZone = switch (source) {
            case HAND -> from.hand;
            case DISCARD -> from.discard;
            case DECK -> from.deck;
        };
        CardInstance tool = sourceZone.stream().filter(card -> card.instanceId().equals(toolInstanceId)).findFirst()
            .orElseThrow(() -> new IllegalArgumentException("指定工具不在效果来源区域"));
        CardDefinition definition = definition(tool);
        require(definition.category() == dev.hua.ptcglive.rules.CardCategory.TRAINER
            && definition.trainerCategory() == dev.hua.ptcglive.rules.TrainerCategory.TOOL, "该卡不是宝可梦工具");
        var profile = combat.trainer(tool.definitionId()).orElseThrow(() -> new IllegalStateException("该工具没有已审核效果数据"));
        require(toolHostAllowed(tool,profile,targetOwner,targetPokemonId),"此道具不能附着于所选宝可梦");
        // Validate capacity and target before changing the hidden source zone.
        battlefield.attachToolByEffect(targetOwner, targetPokemonId, tool, toolAttachmentCapacity(targetOwner, targetPokemonId, profile,tool.instanceId()));
        sourceZone.remove(tool);
        if(profile.opponentLegacyExTool())attachedFlareGear.add(tool.instanceId());
        applyToolAttachCure(targetOwner,targetPokemonId,profile);
        if (source == EffectSourceZone.DECK) shuffle(from.deck, "effect-attach-deck-tool:" + sourceOwner);
        recordReplay(player, "已审核效果附着宝可梦工具");
        settleEnergyConditionImmunity();
        settleHitPointChanges();
    }
    private void applyToolAttachCure(UUID owner,UUID pokemon,dev.hua.ptcglive.rules.TrainerProfile profile) {
        settleAbilityGuardEffects();
        var context=new ServerConditionContext(owner,pokemon);
        for(var binding:profile.ongoingProgram().triggers())if(binding.trigger()==EffectTrigger.PASSIVE
            &&binding.conditions().stream().allMatch(condition->dev.hua.ptcglive.engine.effect.ConditionEvaluator.matches(condition,context)))
            for(var effect:binding.effects())if(dev.hua.ptcglive.engine.effect.ClearSpecialConditionsEffect.onAttach(effect)
                &&effect.target()==EffectTarget.SELF
                &&effect.conditions().stream().allMatch(condition->dev.hua.ptcglive.engine.effect.ConditionEvaluator.matches(condition,context))) {
                var conditions=dev.hua.ptcglive.engine.effect.ClearSpecialConditionsEffect.from(effect).conditions();
                var present=battlefield.pokemonView(owner,pokemon).conditions().stream().filter(conditions::contains).collect(java.util.stream.Collectors.toSet());
                if(!present.isEmpty())battlefield.clearSpecialConditions(owner,pokemon,present);
            }
    }
