    public void putBasicPokemonFromDiscardToBenchByEffect(UUID player, UUID affectedPlayer, CardSelectionPolicy policy,
                                                           List<UUID> cardInstanceIds) {
        putBasicPokemonFromDiscardToBenchByEffect(player, affectedPlayer, policy, cardInstanceIds,
            "已审核效果按条件从弃牌区放置基础宝可梦到备战区");
    }
    private void putBasicPokemonFromDiscardToBenchByEffect(UUID player, UUID affectedPlayer, CardSelectionPolicy policy,
                                                            List<UUID> cardInstanceIds, String replayOperation) {
        putPokemonFromDiscardToBenchByEffect(player,affectedPlayer,policy,cardInstanceIds,false,replayOperation);
    }
    private void putPokemonFromDiscardToBenchByEffect(UUID player,UUID affectedPlayer,CardSelectionPolicy policy,List<UUID> cardInstanceIds,boolean allowEvolution,String replayOperation) {
        requireTurn(player); requireCombatConfigured(); state(affectedPlayer); Objects.requireNonNull(policy, "弃牌上场选择规则");
        require(policy.basicPokemonOnly()||allowEvolution&&player.equals(affectedPlayer)
            &&policy.category()==dev.hua.ptcglive.rules.CardCategory.POKEMON,
            "弃牌上场须为基础宝可梦或已审核的己方跨阶段效果");
        List<UUID> selected = List.copyOf(cardInstanceIds == null ? List.of() : cardInstanceIds);
        if (selected.size() < policy.minCards() || selected.size() > policy.maxCards())
            throw new IllegalArgumentException("本效果必须选择 " + policy.minCards() + " 至 " + policy.maxCards() + " 张弃牌区基础宝可梦");
        if (new java.util.LinkedHashSet<>(selected).size() != selected.size())
            throw new IllegalArgumentException("同一张弃牌区基础宝可梦不能重复选择");
        PlayerState affected = state(affectedPlayer);
        if (selected.size() > benchLimit(affectedPlayer) - affected.bench.size())
            throw new IllegalArgumentException("所选基础宝可梦超过当前可用备战位");
        List<CardInstance> selectedCards = new ArrayList<>();
        for (UUID cardId : selected) {
            CardInstance card = affected.discard.stream().filter(candidate -> candidate.instanceId().equals(cardId)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("指定宝可梦不在该方弃牌区"));
            if ((!allowEvolution&&!definition(card).basicPokemon())||definition(card).category()!=dev.hua.ptcglive.rules.CardCategory.POKEMON || !policy.allows(definition(card), ruleset.trainerClassification()))
                throw new IllegalArgumentException("指定卡牌不符合本效果的基础宝可梦复活条件");
            selectedCards.add(card);
        }
        for (CardInstance card : selectedCards) {
            battlefield.placeOnBench(affectedPlayer, card);
            capturePokemonChangeEvent(EffectTrigger.ON_ENTER_PLAY, affectedPlayer, card.instanceId(), dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy.Source.DISCARD);
        }
        affected.discard.removeAll(selectedCards);
        affected.bench.addAll(selectedCards);
        for(CardInstance card:selectedCards)
            applyBenchEntryStadium(affectedPlayer,card,PokemonChangeTriggerPolicy.Source.DISCARD);
        recordReplay(player, replayOperation);
        if (!resolvingEffectProgram) drainTriggeredAbilities();
    }
