    private void putItemPokemonFromDeckToBench(UUID player,List<UUID> ids,dev.hua.ptcglive.engine.effect.ZoneSelectionEffect operation) {
        requireTurn(player);requireCombatConfigured();
        dev.hua.ptcglive.engine.effect.ItemPokemonDeckSearch.validate(operation.definition());
        var own=state(player);
        require(ids!=null && ids.size()<=operation.selection().maximum() && new java.util.HashSet<>(ids).size()==ids.size(),"化石检索张数无效或重复选择");
        require(own.bench.size()+ids.size()<=benchLimit(player),"备战区没有足够空位");
        var selected=new ArrayList<CardInstance>();
        for(UUID id:ids) {
            var card=own.deck.stream().filter(c->c.instanceId().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("所选物品已不在自己的牌库中"));
            require(dev.hua.ptcglive.engine.effect.ItemPokemonDeckSearch.matches(operation.definition(),definition(card),combat.trainer(card.definitionId()).orElse(null)),"所选卡牌不是符合印刷名称且可上场的化石物品");
            selected.add(card);
        }
        own.deck.removeAll(selected);
        for(var card:selected) {
            battlefield.placeOnBench(player,card);own.bench.add(card);
            capturePokemonChangeEvent(EffectTrigger.ON_ENTER_PLAY,player,card.instanceId(),dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy.Source.DECK);
        }
        shuffle(own.deck,"effect-deck-item-pokemon-to-bench:"+player);
        recordReplay(player,"从牌库将"+selected.size()+"张化石物品放入备战区并重洗牌库");
        if(!resolvingEffectProgram)drainTriggeredAbilities();
    }
    private boolean canPlaceDeckPokemonOnBench(CardInstance card) {
        return definition(card).category()==dev.hua.ptcglive.rules.CardCategory.POKEMON
            &&definition(card).effectSupport()==EffectSupport.SUPPORTED
            &&combat.pokemon(card.definitionId()).filter(p->p.placementRule().permitsBenchPlacement()).isPresent();
    }
    private void putPokemonFromOwnDeckToBenchByEffect(UUID player, CardSelectionPolicy policy,
                                                       List<UUID> cardInstanceIds,Set<String> pokemonNames,boolean anyStage,String replayOperation) {
        putPokemonFromOwnDeckToBenchByEffect(player,policy,cardInstanceIds,pokemonNames,anyStage,replayOperation,true);
    }
    private void putPokemonFromOwnDeckToBenchByEffect(UUID player, CardSelectionPolicy policy,
                                                       List<UUID> cardInstanceIds,Set<String> pokemonNames,boolean anyStage,String replayOperation,boolean shuffleDeck) {
        requireTurn(player); requireCombatConfigured(); Objects.requireNonNull(policy, "牌库上场选择规则");
        require(policy.basicPokemonOnly()||!pokemonNames.isEmpty()||anyStage, "从牌库放入备战区的效果须明确基础、指定名称或任意阶段宝可梦");
        List<UUID> selected = List.copyOf(cardInstanceIds == null ? List.of() : cardInstanceIds);
        if (selected.size() < policy.minCards() || selected.size() > policy.maxCards())
            throw new IllegalArgumentException("本效果必须选择 " + policy.minCards() + " 至 " + policy.maxCards() + " 张牌库基础宝可梦");
        if (new java.util.LinkedHashSet<>(selected).size() != selected.size())
            throw new IllegalArgumentException("同一张牌库基础宝可梦不能重复选择");
        PlayerState own = state(player);
        if (selected.size() > benchLimit(player) - own.bench.size())
            throw new IllegalArgumentException("所选基础宝可梦超过当前可用备战位");
        List<CardInstance> selectedCards = new ArrayList<>();
        for (UUID cardId : selected) {
            CardInstance card = own.deck.stream().filter(candidate -> candidate.instanceId().equals(cardId)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("指定宝可梦不在你的牌库中"));
            if (!policy.allows(definition(card), ruleset.trainerClassification())
                ||!canPlaceDeckPokemonOnBench(card)
                ||!pokemonNames.isEmpty()&&combat.pokemon(card.definitionId()).filter(p->p.pokemonName()!=null&&pokemonNames.contains(p.pokemonName())).isEmpty())
                throw new IllegalArgumentException("指定卡牌不符合本效果的基础宝可梦上场条件");
            selectedCards.add(card);
        }
        own.deck.removeAll(selectedCards);
        for (CardInstance card : selectedCards) {
            battlefield.placeOnBench(player, card);
            own.bench.add(card);
            capturePokemonChangeEvent(EffectTrigger.ON_ENTER_PLAY, player, card.instanceId(), dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy.Source.DECK);
            applyBenchEntryStadium(player,card,PokemonChangeTriggerPolicy.Source.DECK);
        }
        if(shuffleDeck)shuffle(own.deck, "effect-deck-basic-to-bench:" + player);
        recordReplay(player, replayOperation);
        if (!resolvingEffectProgram) drainTriggeredAbilities();
    }
    /** Server-only hook for audited effects that cure one or more Special Conditions. */
    public void clearSpecialConditionsByEffect(UUID player, UUID affectedPlayer, UUID pokemonId,
                                               java.util.Set<SpecialCondition> conditions) {
        requireTurn(player); requireCombatConfigured();
        require(conditions != null && !conditions.isEmpty(), "至少指定一种要移除的异常状态");
        require(battlefield.pokemonView(affectedPlayer,pokemonId).conditions().stream().anyMatch(conditions::contains),"指定宝可梦没有可移除的异常状态");
        if (preventCardEffect(player,affectedPlayer,pokemonId)) return;
        battlefield.clearSpecialConditions(affectedPlayer, pokemonId, conditions);
        recordReplay(player, "已审核效果移除异常状态");
    }
    /**
     * Server-only hook for an audited effect that applies one official Special
     * Condition to an Active Pokémon. Positional conditions replace one
     * another; a redundant application is rejected instead of being reported
     * to an effect resolver as a successful state change.
     */
    public void applySpecialConditionByEffect(UUID player, UUID affectedPlayer, SpecialCondition condition) {
        applySpecialConditionByEffect(player, affectedPlayer, condition, BattlefieldState.defaultCheckupCounters(condition));
    }
    /** {@code checkupCounters}: damage counters a Poisoned / Burned puts during Pokémon Checkup (“instead of 1”). */
    public void applySpecialConditionByEffect(UUID player, UUID affectedPlayer, SpecialCondition condition, int checkupCounters) {
        requireTurn(player); requireCombatConfigured(); state(affectedPlayer);
        Objects.requireNonNull(condition,"异常状态");
        require(battlefield.hasActive(affectedPlayer),"当前没有可附加异常状态的战斗宝可梦");
        if (preventCardEffect(player,affectedPlayer,battlefield.activeView(affectedPlayer).pokemonId())) return;
        if (passivelyPreventsSpecialConditions(affectedPlayer,condition)) {
            recordReplay(player, "已审核效果附加异常状态被持续免疫阻止");
            return;
        }
        require(battlefield.applySpecialCondition(affectedPlayer, condition, checkupCounters), "目标已处于该异常状态");
        if(condition==SpecialCondition.ASLEEP)twoCoinSleepEntries.remove(affectedPlayer);
        recordReplay(player, "已审核效果附加异常状态" + (checkupCounters != BattlefieldState.defaultCheckupCounters(condition)
            ? "（宝可梦检查时放 " + checkupCounters + " 个伤害指示物）" : ""));
    }
    /** Special Conditions can exist only on an Active Pokémon, so a self-only passive is resolved from that public instance. */
    private boolean passivelyPreventsSpecialConditions(UUID affectedPlayer,SpecialCondition condition) {
        if (battlefield == null || !battlefield.hasActive(affectedPlayer)) return false;
        UUID active = battlefield.activeView(affectedPlayer).pokemonId();
        if(stadiumHasPassiveRule("energy_special_condition_immunity")&&!battlefield.attachedEnergy(affectedPlayer,active).isEmpty())return true;
        if(stadium!=null) {
            var profile=combat.trainer(stadium.definitionId()).orElse(null);
            EffectTarget scope=stadiumScopeController().equals(affectedPlayer)?EffectTarget.ALL_OWN_POKEMON:EffectTarget.ALL_OPPONENT_POKEMON;
            if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                hostConditionContext(stadiumScopeController(),affectedPlayer,active),effect->effect.type().equals("special_condition_immunity")
                    &&effect.target()==scope&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.immuneConditions(effect).contains(condition))
                &&!preventsImpact(affectedPlayer,active,new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId()),EffectProtection.Impact.OTHER_EFFECTS))return true;
        }
        if(energyPreventsCondition(affectedPlayer,active,condition))return true;
        if(!toolEffectsDisabled(affectedPlayer,active))for(var tool:battlefield.printedPokemonView(affectedPlayer,active).attachedTools()) {
            var profile=combat.trainer(tool.definitionId()).orElse(null);
            if(profile!=null&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(profile.ongoingProgram(),
                new ServerConditionContext(affectedPlayer,active),effect->effect.type().equals("special_condition_immunity")
                    &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.immuneConditions(effect).contains(condition)))return true;
        }
        return activeAbilities(affectedPlayer, active).stream().anyMatch(ability -> {
            if(ability.kind()!=AbilityDefinition.Kind.PASSIVE||ability.effectSupport()!=EffectSupport.SUPPORTED)return false;
            if(ability.effect().opcode()==AbilityEffect.Opcode.PASSIVE_PREVENT_ALL_SPECIAL_CONDITIONS)return true;
            return ability.composed()&&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(
                ability.effectProgram(),new ServerConditionContext(affectedPlayer,active),
                effect->effect.type().equals("special_condition_immunity")
                    &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.immuneConditions(effect).contains(condition));
        });
    }
    /** Attack-only immunity is checked on every actual target, including a selected Benched Pokémon. */
    private boolean passivelyPreventsAttackDamage(UUID affectedPlayer, UUID pokemonId, EffectOrigin origin) {
        return fieldAttackProtectionPreventsDamage(affectedPlayer,pokemonId,origin)
            || passiveAttackGuard(affectedPlayer,pokemonId,origin).prevent() || !origin.controller().equals(affectedPlayer)
            && activeAbilities(affectedPlayer, pokemonId).stream().anyMatch(ability ->
            ability.kind() == AbilityDefinition.Kind.PASSIVE && ability.effectSupport() == EffectSupport.SUPPORTED
                && ability.effect().opcode() == AbilityEffect.Opcode.PASSIVE_PREVENT_OPPONENT_ATTACK_DAMAGE);
    }
    private boolean fieldAttackProtectionPreventsDamage(UUID affectedPlayer,UUID pokemonId,EffectOrigin origin) {
        if(origin.kind()!=EffectOrigin.Kind.ATTACK||origin.controller().equals(affectedPlayer)||attackCheckpoint==null
            ||attackCheckpoint.damageSource==null||!currentPlayer.equals(other(affectedPlayer).id))return false;
        var target=fieldCardDefinition(battlefield.topCard(affectedPlayer,pokemonId).definitionId());
        return state(affectedPlayer).fieldAttackProtections.stream().anyMatch(timed->
            (!timed.rule().sourceActiveBound()||sameFieldEntry(affectedPlayer,timed.source(),timed.entry())
                &&battlefield.hasActive(affectedPlayer)&&battlefield.activeView(affectedPlayer).pokemonId().equals(timed.source()))
                &&timed.rule().recipients().matches(target)&&timed.rule().attackers().matches(attackCheckpoint.damageSource.facts()));
    }
    /**
     * Tera rule, printed on every Tera Pokémon: “As long as this Pokémon is on your Bench, prevent all damage done to
     * this Pokémon by attacks (both yours and your opponent's).” It is a rule of the benched card itself, not an effect
     * on the opponent's Active Pokémon, so attack text that ignores such effects does not bypass it.
     * The Ability “As long as this Pokémon is on your Bench, prevent all damage done to this Pokémon by attacks.” has the
     * same scope; it stops working while the Ability is suppressed.
     */
    private boolean benchedPreventsAttackDamage(UUID owner, UUID pokemonId) {
        if (battlefield.hasActive(owner) && battlefield.activeView(owner).pokemonId().equals(pokemonId)) return false;
        return fieldCardDefinition(battlefield.pokemonView(owner, pokemonId).topCardId()).pokemonFamilies()
            .contains(dev.hua.ptcglive.rules.PokemonFamily.TERA)
            || activeAbilities(owner, pokemonId).stream().anyMatch(ability ->
                ability.kind() == AbilityDefinition.Kind.PASSIVE && ability.effectSupport() == EffectSupport.SUPPORTED
                    && ability.effect().opcode() == AbilityEffect.Opcode.PASSIVE_PREVENT_ATTACK_DAMAGE_WHILE_BENCHED);
    }
    /**
     * Ability “If any damage is done to this Pokémon by attacks, flip a coin. If heads, prevent that damage.”: the server
     * flips only when an attack would actually do damage (both players' attacks); a suppressed Ability does not flip.
     */
    private boolean hasDamagePreventionCoin(UUID owner,UUID pokemonId,int damage) {
        return damage>0&&activeAbilities(owner, pokemonId).stream().anyMatch(ability ->
            ability.kind() == AbilityDefinition.Kind.PASSIVE && ability.effectSupport() == EffectSupport.SUPPORTED
                && (ability.effect().opcode() == AbilityEffect.Opcode.PASSIVE_COIN_PREVENT_ATTACK_DAMAGE
                    || ability.composed() && dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(
                        ability.effectProgram(), new ServerConditionContext(owner,pokemonId),
                        effect -> effect.type().equals("coin_prevent_attack_damage"))));
    }
    private boolean coinPreventsAttackDamage(UUID owner, UUID pokemonId, int damage) {
        if(!hasDamagePreventionCoin(owner,pokemonId,damage))return false;
        boolean heads = flipEffectCoin(owner,"ability-coin-prevent-damage:" + owner + ":" + pokemonId);
        recordReplay(owner, heads ? "特性掷硬币：正面，防止这次招式伤害" : "特性掷硬币：反面，照常受到伤害");
        return heads;
    }
    /** Static reduction stacks with the existing temporary public reduction, after Weakness/Resistance in normal damage order. */
    private int passiveAttackDamageReduction(UUID affectedPlayer, UUID pokemonId, EffectOrigin origin) {
        return passiveAttackGuard(affectedPlayer,pokemonId,origin).reduction() + (origin.controller().equals(affectedPlayer) ? 0
            : activeAbilities(affectedPlayer, pokemonId).stream().filter(ability ->
            ability.kind() == AbilityDefinition.Kind.PASSIVE && ability.effectSupport() == EffectSupport.SUPPORTED
                && ability.effect().opcode() == AbilityEffect.Opcode.PASSIVE_REDUCE_OPPONENT_ATTACK_DAMAGE)
            .mapToInt(ability -> ability.effect().amount()).sum());
    }
    /** Server-only hook for an audited effect that heals an in-play Pokémon on either field. */
    public void healDamageByEffect(UUID player, UUID affectedPlayer, UUID pokemonId, int amount) {
        requireTurn(player); requireCombatConfigured(); state(affectedPlayer);
        if (amount < 1 || amount % 10 != 0) throw new IllegalArgumentException("回复量必须为正且为10的倍数");
        if (healingBlocked(affectedPlayer,pokemonId)||preventCardEffect(player,affectedPlayer,pokemonId)) return;
        require(battlefield.healByEffect(affectedPlayer, pokemonId, legendaryHealing()?Math.multiplyExact(amount,2):amount) > 0, "目标没有可回复的伤害");
        if(attackCheckpoint!=null) {
            var healed=battlefield.pokemonView(affectedPlayer,pokemonId);
            if(healed.damage()<healed.hitPoints()) attackCheckpoint.attackDamageKnockouts.remove(new Knockout(affectedPlayer,pokemonId));
        }
        recordReplay(player, "已审核效果回复伤害");
        settleHitPointChanges();
    }
    /** Server-only hook for an audited effect that discards the current shared Stadium. */
    public void discardStadiumByEffect(UUID player) {
        requireTurn(player);
        if (stadium == null || stadiumController == null) throw new IllegalStateException("场上没有可弃置的场地");
        if(stadiumProtectedFrom(effectOrigin(player)))return;
        beginLeavingStadiumBenchCorrection();
        moveCardToOwnerDiscard(stadium);
        stadium = null;
        stadiumController = null;
        recordReplay(player, "已审核效果弃置场地");
        settleHitPointChanges();
    }
    private void beginLeavingStadiumBenchCorrection() {
        var rule=stadiumPassiveRule("tera_bench_expansion");
        if(rule==null)rule=stadiumPassiveRule("bench_limit");
        if(rule==null||!rule.arguments().containsKey("leave_limit")||stadiumController==null)return;
        int limit=Integer.parseInt(rule.arguments().get("leave_limit"));
        if(players.keySet().stream().noneMatch(owner->battlefield.printedBenchView(owner).size()>limit))return;
        benchOverflowFirst=stadium.ownerId();benchOverflowForcedLimit=limit;
    }
    /** The printed instruction determines which Pokémon receives a switching effect (C-03/C-04 versus C-05). */
    private enum SwitchEffectTarget { ACTIVE, SELECTED_BENCH }
    /**
     * Server-only C-03/C-04 hook: move the Active to the Bench, checking protection on that Active only.
     * Reviewed gust programs and legacy opponent-targeted Trainers instead explicitly affect the selected Bench.
     * @return whether the Pokémon actually switched (false when the affected Pokémon prevented the effect).
     */
    public boolean switchActiveByEffect(UUID player, UUID affectedPlayer, UUID suppliedReplacementPokemonId) {
        return switchActiveByEffect(player, affectedPlayer, suppliedReplacementPokemonId, SwitchEffectTarget.ACTIVE);
    }
    private boolean switchActiveByEffect(UUID player, UUID affectedPlayer, UUID suppliedReplacementPokemonId,
                                         SwitchEffectTarget effectTarget) {
        requireTurn(player); requireCombatConfigured();
        UUID replacementPokemonId=battlefield.printedPokemonView(affectedPlayer,suppliedReplacementPokemonId).pokemonId();
        require(battlefield.hasActive(affectedPlayer),"没有可换出的战斗宝可梦");
        require(battlefield.benchView(affectedPlayer).stream().anyMatch(p->p.pokemonId().equals(replacementPokemonId)),"替换目标不在备战区");
        UUID affectedPokemonId = effectTarget == SwitchEffectTarget.ACTIVE
            ? battlefield.activeView(affectedPlayer).pokemonId() : replacementPokemonId;
        if (preventCardEffect(player, affectedPlayer, affectedPokemonId)) return false;
        UUID outgoingPokemonId=battlefield.activeView(affectedPlayer).pokemonId();
        var switchOrigin=effectOrigin(player);
        int inheritedPoison=stadiumHasPassiveRule("inherit_poison_on_own_trainer_switch")
            &&switchOrigin.kind()==EffectOrigin.Kind.TRAINER&&switchOrigin.controller().equals(affectedPlayer)
            &&battlefield.activeView(affectedPlayer).conditions().contains(SpecialCondition.POISONED)
            ?battlefield.checkupCounters(affectedPlayer,SpecialCondition.POISONED):0;
        var incoming=benchToActiveBefore(affectedPlayer,replacementPokemonId);
        battlefield.switchActiveByEffect(affectedPlayer, replacementPokemonId);
        syncField(affectedPlayer);
        if(inheritedPoison>0)withOrigin(new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId()),
            ()->applySpecialConditionByEffect(player,affectedPlayer,SpecialCondition.POISONED,inheritedPoison));
        capturePokemonChangeEvent(EffectTrigger.ON_ACTIVE_TO_BENCH, affectedPlayer, outgoingPokemonId);
        long batch=capturePokemonChangeEvent(EffectTrigger.ON_SWITCH, affectedPlayer, replacementPokemonId);
        captureBenchToActiveEvent(incoming,batch);
        recordReplay(affectedPlayer,"公开换位·"+affectedPlayer+"·"+outgoingPokemonId+"·"+replacementPokemonId+"·效果");
        recordReplay(player, "已审核效果交换战斗宝可梦");
        settleHitPointChanges();
        if (!resolvingEffectProgram) drainTriggeredAbilities();
        return true;
    }
