    /**
     * Server-only hook for a reviewed effect that returns/discards a Pokémon
     * and its complete in-play stack. This is deliberately not an attack or a
     * Knock Out: it grants no Prize, but an emptied Active still requires a
     * replacement or loses by having no Pokémon.
     */
    public void movePokemonByEffect(UUID player, UUID affectedPlayer, UUID suppliedPokemonId, LeavePlayDestination destination) {
        movePokemonOutOfPlay(player,affectedPlayer,suppliedPokemonId,destination,true);
    }
    private void flusteredLeapByEffect(UUID player,UUID suppliedPokemonId) {
        requireTurn(player);requireCombatConfigured();var owner=state(player);
        require(!owner.deck.isEmpty(),"牌库底没有可弃置的卡牌");
        UUID pokemonId=battlefield.printedPokemonView(player,suppliedPokemonId).pokemonId();
        require(battlefield.printedBenchView(player).stream().anyMatch(view->view.pokemonId().equals(pokemonId)),"慌张跳跃来源已不在备战区");
        var bottom=owner.deck.removeFirst();moveCardsToOwnerDiscard(List.of(bottom));
        long leavingEntry=battlefield.pokemonEntrySequence(player,pokemonId);long batch=++triggerEventBatch;
        var departing=captureDepartingPokemonSelfLeavePlayEvent(player,pokemonId,leavingEntry,batch);
        UUID topId=battlefield.topCard(player,pokemonId).instanceId();
        var discardReturns=fieldDiscardReturnCards();
        var left=battlefield.removePokemonByEffect(player,pokemonId);
        var top=left.discardedCards().stream().filter(card->card.instanceId().equals(topId)).findFirst()
            .orElseThrow(()->new IllegalStateException("慌张跳跃缺少来源宝可梦卡"));
        moveCardsToOwnerDiscard(left.discardedCards().stream().filter(card->!card.instanceId().equals(topId)).toList(),discardReturns);
        owner.deck.add(top);syncField(player);triggeredAbilities.addAll(departing);
        capturePokemonLeavePlayEvent(player,pokemonId,leavingEntry,batch);
        recordReplay(player,"慌张跳跃：弃置牌库底，来源宝可梦回到牌库顶");settleHitPointChanges();
        if(!resolvingEffectProgram)drainTriggeredAbilities();
    }
