    public void discardRandomHandCardsByEffect(UUID player, UUID affectedPlayer, int count) {
        discardRandomHandCardsByEffect(player, affectedPlayer, new RandomHandDiscardPolicy(count, count));
    }
    /** Server-only random discard with audited minimum/maximum card counts. */
    public void discardRandomHandCardsByEffect(UUID player, UUID affectedPlayer, RandomHandDiscardPolicy policy) {
        discardRandomHandCardsByEffect(player,affectedPlayer,policy,null);
    }
    private void discardRandomHandCardsByEffect(UUID player, UUID affectedPlayer, RandomHandDiscardPolicy policy,DeckDiscardCause cause) {
        requireTurn(player); Objects.requireNonNull(policy, "随机弃置手牌规则");
        PlayerState affected = state(affectedPlayer);
        int count = Math.min(policy.maxCards(), affected.hand.size());
        require(count >= policy.minCards(), "目标手牌不足，无法满足随机弃置数量");
        List<CardInstance> pool = new ArrayList<>(affected.hand);
        List<CardInstance> discarded = new ArrayList<>();
        for (int i = 0; i < count; i++) discarded.add(pool.remove(random.nextInt("effect-random-hand-discard:" + affectedPlayer, pool.size())));
        affected.hand.removeAll(discarded);
        moveCardsToOwnerDiscard(discarded);
        recordReplay(player, "已审核效果随机弃置手牌");
        captureHandDiscardedCards(affectedPlayer,List.copyOf(discarded),cause);
    }
    /** A hand reaction is latched only after an attributed effect actually moves the physical card to discard. */
    private void captureHandDiscardedCards(UUID handOwner,List<CardInstance> moved,DeckDiscardCause cause) {
        if(moved.isEmpty()||cause==null||combat==null||phase!=MatchPhase.TURN&&phase!=MatchPhase.TURN_END)return;
        long movement=++handDiscardMovement;
        String suppressedExcept=zoneSuppressionSourceId();var entries=new ArrayList<QueuedAbility>();
        for(var card:moved) {
            if(!card.ownerId().equals(handOwner)||definition(card).category()!=CardCategory.POKEMON)continue;
            if(offFieldAbilitiesSuppressed(card))continue;
            var profile=combat.pokemon(card.definitionId()).orElse(null);if(profile==null)continue;
            for(var ability:profile.abilities()) {
                if(ability.effectSupport()!=EffectSupport.SUPPORTED
                    ||!(ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.HandDiscardTriggerPolicy policy)
                    ||suppressedExcept!=null&&!ability.id().equals(suppressedExcept)
                    ||!policy.matches(handOwner,currentPlayer,true,cause.controller(),cause.kind(),true,true))continue;
                require(ruleset.triggerTiming()==dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,"此规则包的手牌弃置触发时序尚未核验");
                dev.hua.ptcglive.engine.effect.TriggeredAbilityRules.validate(ability);
                var source=new EffectLifecycleDispatcher.Source(card.instanceId(),"ability:"+ability.id()+":hand-discard:"+movement,ability.effectProgram());
                var captured=new CapturedHandDiscardSource(card,movement,cause,turnNumber);
                var entry=new QueuedAbility(UUID.randomUUID(),0,handOwner,null,ability,source,EffectEventBindings.NONE,
                    new EffectOrigin(EffectOrigin.Kind.ABILITY,handOwner,card.instanceId()),0,null,captured,null);
                automaticContext(entry).preflight(ability.effectProgram(),EffectTrigger.ON_DISCARDED_FROM_HAND);entries.add(entry);
            }
        }
        if(!entries.isEmpty())captureTriggeredAbilities(entries,++triggerEventBatch);
    }
