    /** Plays a Basic Pokémon from the acting player's hand to an available Benched slot. */
    public void playBasicPokemonToBench(UUID player, UUID cardInstanceId) {
        requireTurn(player);
        requireCombatConfigured();
        PlayerState p = state(player);
        require(p.bench.size() < benchLimit(player), "备战区已达到本规则包上限");
        CardInstance card = cardInHand(p, cardInstanceId);
        require(definition(card).basicPokemon(), "只有基础宝可梦可以从手牌放入备战区");
        require(!pokemonPlayLocked(player,card),"对手战斗宝可梦的特性：不能从手牌使用带有特性的非火箭队宝可梦");
        battlefield.placeOnBench(player, card);
        p.hand.remove(card);
        p.bench.add(card);
        capturePokemonChangeEvent(EffectTrigger.ON_ENTER_PLAY, player, card.instanceId(), dev.hua.ptcglive.engine.effect.PokemonChangeTriggerPolicy.Source.HAND);
        applyBenchEntryStadium(player,card,PokemonChangeTriggerPolicy.Source.HAND);
        captureCardPlayedEvent(player, card);
        recordReplay(player, "从手牌放置基础宝可梦到备战区");
        settleHitPointChanges();
        drainTriggeredAbilities();
    }
    /**
     * Pays the authoritative battlefield's retreat cost. The replacement is a Pokémon identity,
     * not a client-selected card definition; the server checks it is actually on this player's Bench.
     */
    /** The coin instruction applies to the opposing player, not as an effect placed on their Pokemon. */
    private boolean retreatAttemptCoinGated(UUID player) {
        UUID opponent=other(player).id;
        for(var host:publicFieldTargets(opponent))
            for(var ability:activeAbilities(opponent,host.pokemonId()))
                if(ability.effectSupport()==EffectSupport.SUPPORTED&&ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                    &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),
                        new ServerConditionContext(opponent,host.pokemonId()),e->e.type().equals("retreat_attempt_coin_gate")))
                    return true;
        return false;
    }
    private boolean retreatPreventedByPassive(UUID player) {
        UUID opponent=other(player).id;
        if(!battlefield.hasActive(opponent))return false;
        UUID source=battlefield.printedActiveView(opponent).pokemonId();
        for(var ability:activeAbilities(opponent,source))
            if(ability.effectSupport()==EffectSupport.SUPPORTED&&ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(opponent,source),
                    e->e.type().equals("prevent_retreat")&&e.target()==EffectTarget.OPPONENT_ACTIVE
                        &&"true".equals(e.arguments().get("source_active_only"))))return true;
        return false;
    }
    private int validateRetreat(UUID player, UUID replacementPokemonId, List<UUID> paidEnergyIds) {
        requireTurn(player);
        requireCombatConfigured();
        require(!retreatPreventedByPassive(player),"对手战斗宝可梦的特性使当前战斗宝可梦无法撤退");
        Objects.requireNonNull(paidEnergyIds, "撤退支付能量");
        UUID activePokemonId = battlefield.activeView(player).pokemonId();
        if (new java.util.LinkedHashSet<>(paidEnergyIds).size() != paidEnergyIds.size())
            throw new IllegalArgumentException("同一张附着能量不能重复支付撤退费用");
        Map<UUID, CardInstance> attached = new LinkedHashMap<>();
        for (CardInstance energy : battlefield.attachedEnergy(player, activePokemonId)) attached.put(energy.instanceId(), energy);
        List<dev.hua.ptcglive.engine.field.EnergyProfile> profiles = new ArrayList<>();
        for (UUID energyId : paidEnergyIds) {
            CardInstance energy = attached.get(energyId);
            if (energy == null) throw new IllegalArgumentException("撤退费用包含未附着在战斗宝可梦上的能量");
            if (definition(energy).category() != dev.hua.ptcglive.rules.CardCategory.ENERGY)
                throw new IllegalStateException("撤退费用只能使用能量卡");
            profiles.add(currentEnergyProfile(player,activePokemonId,energy));
        }
        int retreatCost = activeRetreatCost(player);
        if (!dev.hua.ptcglive.engine.field.EnergyProfile.isValidGenericPayment(profiles, retreatCost))
            throw new IllegalStateException("选择的能量不足、存在零供能卡，或卡牌数超过撤退所需能量个数");
        int paidUnits=dev.hua.ptcglive.engine.field.EnergyProfile.totalUnits(profiles);
        battlefield.validateRetreat(player,replacementPokemonId,paidEnergyIds,paidUnits);
        return paidUnits;
    }
    public void retreat(UUID player, UUID replacementPokemonId, List<UUID> paidEnergyIds) {
        int paidUnits=validateRetreat(player,replacementPokemonId,paidEnergyIds);
        PlayerState p=state(player);
        if(retreatAttemptCoinGated(player)) {
            var payment=List.copyOf(paidEnergyIds);
            if(pauseForCoinChoice(player,()->retreat(player,replacementPokemonId,payment)))return;
            boolean heads=flipEffectCoin(player,"retreat-attempt-coin");
            recordReplay(player,heads?"撤退掷币：正面":"撤退掷币：反面，本回合撤退次数已使用");
            if(!heads) {
                battlefield.consumeFailedRetreatAttempt(player,replacementPokemonId,paidEnergyIds,paidUnits);
                return;
            }
        }
        // Resolve replacement permissions on the outgoing Active before it moves or loses Energy.
        UUID outgoing=battlefield.activeView(player).pokemonId();
        boolean returnAll=false,returnBasic=false;
        if(!opponentPreventsReturnToHand(player)) {
            if(!toolEffectsDisabled(player,outgoing))for(var tool:battlefield.pokemonView(player,outgoing).attachedTools()) {
                if(programHasRule(combat.trainer(tool.definitionId()).orElseThrow().ongoingProgram(),"retreat_energy_to_hand")
                    &&!preventsImpact(player,outgoing,new EffectOrigin(EffectOrigin.Kind.TRAINER,tool.ownerId(),tool.instanceId()),EffectProtection.Impact.OTHER_EFFECTS))returnAll=true;
            }
            returnBasic=stadiumHasPassiveRule("retreat_energy_to_hand")
                &&!preventsImpact(player,outgoing,new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId()),EffectProtection.Impact.OTHER_EFFECTS);
        }
        var returnedEnergy=new java.util.HashSet<UUID>();
        for(var energy:battlefield.attachedEnergy(player,outgoing))
            if(paidEnergyIds.contains(energy.instanceId())&&(returnAll||returnBasic&&definition(energy).basicEnergy()))returnedEnergy.add(energy.instanceId());
        var incoming=benchToActiveBefore(player,replacementPokemonId);
        var discardReturns=fieldDiscardReturnCards();
        BattlefieldState.RetreatResult retreat = battlefield.retreat(player, replacementPokemonId, paidEnergyIds,
            paidUnits);
        moveCardsToOwnerHand(retreat.discardedEnergy().stream().filter(card->returnedEnergy.contains(card.instanceId())).toList());
        moveCardsToOwnerDiscard(retreat.discardedEnergy().stream().filter(card->!returnedEnergy.contains(card.instanceId())).toList(),discardReturns);
        syncField(player);
        capturePokemonChangeEvent(EffectTrigger.ON_ACTIVE_TO_BENCH, player, retreat.movedToBench());
        long batch=capturePokemonChangeEvent(EffectTrigger.ON_RETREAT, player, retreat.movedToBench());
        captureBenchToActiveEvent(incoming,batch);
        recordReplay(player,"公开换位·"+player+"·"+retreat.movedToBench()+"·"+retreat.movedToActive()+"·撤退");
        recordReplay(player, "撤退并支付费用");
        settleHitPointChanges();
        drainTriggeredAbilities();
    }
    public void endTurn(UUID player) {
        requireTurn(player); recordReplay(player, "结束回合"); runTurnEnd();
    }

    /** Resolves an Active-targeting attack. Targeted attacks must use the overload below. */
    public void attack(UUID player, String attackId) { attackTargets(player, attackId, List.of()); }
    /** Clients may name only a public in-play target; all target checks and results are server-owned. */
    public void attack(UUID player, String attackId, UUID targetPokemonId) {
        attackTargets(player, attackId, targetPokemonId == null ? List.of() : List.of(targetPokemonId));
    }
    /** Multi-target entry point used only with server-generated, public in-play identities. */
    public void attackTargets(UUID player, String attackId, List<UUID> targetPokemonIds) {
        attackWithEnergyDiscards(player, attackId, targetPokemonIds, List.of());
    }
    /** Server-only resolved option. Commands accept only captured identities, never its executable definition. */
    public record BorrowedAttackOption(UUID holderId,long holderEntry,UUID holderTop,String abilityId,
        UUID providerId,long providerEntry,UUID providerTop,String providerCardId,String attackId,String nameZh,
        AttackDefinition attack,String unsupportedReasonZh) { }
    public List<BorrowedAttackOption> borrowedAttackOptions(UUID player) {
        state(player);if(battlefield==null)return List.of();
        var holders=new ArrayList<>(battlefield.benchView(player));if(battlefield.hasActive(player))holders.addFirst(battlefield.activeView(player));
        var result=new ArrayList<BorrowedAttackOption>();
        for(var holder:holders) {
            if(!mayAttackFrom(player,holder.pokemonId()))continue;
            var holderProfile=battlefield.pokemonProfile(player,holder.pokemonId());
            boolean holderActive=battlefield.hasActive(player)&&battlefield.activeView(player).pokemonId().equals(holder.pokemonId());
            if(holderActive&&!toolEffectsDisabled(player,holder.pokemonId())) {
                for(var tool:holder.attachedTools()) {
                    var toolProfile=combat.trainer(tool.definitionId()).orElse(null);
                    if(toolProfile==null)continue;
                    var grant=dev.hua.ptcglive.engine.effect.ToolGrantedAttack.fromProgram(toolProfile.ongoingProgram());
                    if(grant==null)continue;
                    if(grant.arguments().containsKey("holder_attack_id")&&holderProfile.attacks().stream()
                        .noneMatch(a->a.id().equals(grant.arguments().get("holder_attack_id"))))continue;
                    if(grant.arguments().containsKey("pokemon_name")
                        &&!grant.arguments().get("pokemon_name").equals(holderProfile.pokemonName()))continue;
                    if(grant.arguments().containsKey("holder_name_contains")
                        &&!holderProfile.pokemonName().contains(grant.arguments().get("holder_name_contains")))continue;
                    if(grant.arguments().containsKey("holder_battle_style")&&!fieldCardDefinition(holder.topCardId()).battleStyles().contains(
                        dev.hua.ptcglive.rules.BattleStyle.valueOf(grant.arguments().get("holder_battle_style"))))continue;
                    if(grant.arguments().containsKey("holder_families")
                        &&!dev.hua.ptcglive.engine.effect.PokemonFamilyFilter.fromWire(
                            grant.arguments().get("holder_families"),null).matches(fieldCardDefinition(holder.topCardId())))continue;
                    AttackDefinition resolved=null;String reason=null;
                    try {
                        resolved=dev.hua.ptcglive.engine.effect.ToolGrantedAttack.materialize(grant,holderProfile.pokemonType());
                        if(grant.arguments().containsKey("opponent_prizes"))require(state(other(player).id).prizes.size()==Integer.parseInt(grant.arguments().get("opponent_prizes")),"对手奖赏卡数量不符合此招式条件");
                        require(!battlefield.pokemonAttackLocked(player,holder.pokemonId(),resolved),"实际使用者当前不能使用这个名称的招式");
                        requireAttackSharedUsage(player,holder.pokemonId(),resolved.usageLimit());require(attackUseAllowed(player,holder.pokemonId(),resolved),"招式使用条件不满足");
                    } catch(IllegalArgumentException|IllegalStateException invalid) {resolved=null;reason=invalid.getMessage();}
                    result.add(new BorrowedAttackOption(holder.pokemonId(),battlefield.pokemonEntrySequence(player,holder.pokemonId()),
                        battlefield.topCard(player,holder.pokemonId()).instanceId(),"tool:"+tool.instanceId()+":"+battlefield.attachmentEntrySequence(player,holder.pokemonId(),tool.instanceId()),holder.pokemonId(),
                        battlefield.pokemonEntrySequence(player,holder.pokemonId()),tool.instanceId(),tool.definitionId(),
                        grant.arguments().get("attack_id"),grant.arguments().get("name_zh"),resolved,reason));
                }
            }
            for(var ability:activeAbilities(player,holder.pokemonId())) {
                if(ability.effectSupport()!=EffectSupport.SUPPORTED||ability.kind()!=AbilityDefinition.Kind.PASSIVE
                    ||!dev.hua.ptcglive.engine.effect.BorrowedAttackProgram.contains(ability.effectProgram()))continue;
                dev.hua.ptcglive.engine.effect.BorrowedAttackProgram.validate(ability.effectProgram());
                if(dev.hua.ptcglive.engine.effect.BorrowedAttackProgram.previousEvolutions(ability.effectProgram()))continue;
                if(dev.hua.ptcglive.engine.effect.BorrowedAttackProgram.discardBasics(ability.effectProgram())) {
                    for(var provider:state(player).discard) {
                        var providerDefinition=definition(provider);
                        if(providerDefinition.category()!=CardCategory.POKEMON||!providerDefinition.basicPokemon()
                            ||providerDefinition.pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.RULE_BOX))continue;
                        var providerProfile=combat.pokemon(provider.definitionId()).orElse(null);if(providerProfile==null)continue;
                        for(var printed:providerProfile.attacks()) {
                            AttackDefinition resolved=null;String reason=null;
                            try {
                                resolved=dev.hua.ptcglive.engine.effect.BorrowedAttackProgram.materialize(printed,holderProfile.pokemonType());
                                require(!battlefield.pokemonAttackLocked(player,holder.pokemonId(),resolved),"实际使用者当前不能使用这个名称的招式");
                                requireAttackSharedUsage(player,holder.pokemonId(),resolved.usageLimit());require(attackUseAllowed(player,holder.pokemonId(),resolved),"招式使用条件不满足");
                            } catch(IllegalArgumentException|IllegalStateException invalid) {resolved=null;reason=invalid.getMessage();}
                            result.add(new BorrowedAttackOption(holder.pokemonId(),battlefield.pokemonEntrySequence(player,holder.pokemonId()),
                                battlefield.topCard(player,holder.pokemonId()).instanceId(),ability.id(),provider.instanceId(),-1,
                                provider.instanceId(),provider.definitionId(),printed.id(),printed.nameZh(),resolved,reason));
                        }
                    }
                    continue;
                }
                for(var provider:battlefield.benchView(player))for(var printed:battlefield.pokemonProfile(player,provider.pokemonId()).attacks()) {
                    if(!holderActive&&!printed.mayUseFromBench())continue;
                    AttackDefinition resolved=null;String reason=null;
                    try {
                        resolved=dev.hua.ptcglive.engine.effect.BorrowedAttackProgram.materialize(printed,holderProfile.pokemonType());
                        require(!battlefield.pokemonAttackLocked(player,holder.pokemonId(),resolved),"实际使用者当前不能使用这个名称的招式");
                                requireAttackSharedUsage(player,holder.pokemonId(),resolved.usageLimit());require(attackUseAllowed(player,holder.pokemonId(),resolved),"招式使用条件不满足");
                    } catch(IllegalArgumentException|IllegalStateException invalid) {resolved=null;reason=invalid.getMessage();}
                    result.add(new BorrowedAttackOption(holder.pokemonId(),battlefield.pokemonEntrySequence(player,holder.pokemonId()),
                        battlefield.topCard(player,holder.pokemonId()).instanceId(),ability.id(),provider.pokemonId(),
                        battlefield.pokemonEntrySequence(player,provider.pokemonId()),battlefield.topCard(player,provider.pokemonId()).instanceId(),
                        provider.topCardId(),printed.id(),printed.nameZh(),resolved,reason));
                }
            }
            var memorySource=previousEvolutionAttackPermission(player,holder.pokemonId());
            if(memorySource!=null) {
                for(var previousCard:battlefield.previousEvolutionCards(player,holder.pokemonId())) {
                    String previousCardId=previousCard.definitionId();
                    var previous=combat.pokemon(previousCardId).orElse(null);if(previous==null)continue;
                    for(var printed:previous.attacks()) {
                        if(!holderActive&&!printed.mayUseFromBench())continue;
                        AttackDefinition resolved=null;String reason=null;
                        try {
                            resolved=dev.hua.ptcglive.engine.effect.BorrowedAttackProgram.materialize(printed,holderProfile.pokemonType());
                            require(!battlefield.pokemonAttackLocked(player,holder.pokemonId(),resolved),"实际使用者当前不能使用这个名称的招式");
                            requireAttackSharedUsage(player,holder.pokemonId(),resolved.usageLimit());require(attackUseAllowed(player,holder.pokemonId(),resolved),"招式使用条件不满足");
                        } catch(IllegalArgumentException|IllegalStateException invalid) {resolved=null;reason=invalid.getMessage();}
                        result.add(new BorrowedAttackOption(holder.pokemonId(),battlefield.pokemonEntrySequence(player,holder.pokemonId()),
                            battlefield.topCard(player,holder.pokemonId()).instanceId(),memorySource,holder.pokemonId(),
                            battlefield.pokemonEntrySequence(player,holder.pokemonId()),previousCard.instanceId(),
                            previousCardId,printed.id(),printed.nameZh(),resolved,reason));
                    }
                }
            }
        }
        return List.copyOf(result);
    }
    private String previousEvolutionAttackPermission(UUID player,UUID holder) {
        for(var source:publicFieldTargets(player))for(var ability:activeAbilities(player,source.pokemonId()))
            if(ability.effectSupport()==EffectSupport.SUPPORTED&&ability.kind()==AbilityDefinition.Kind.PASSIVE
                &&previousEvolutionProgram(ability.effectProgram()))return "memory-dive:"+source.pokemonId();
        if(!toolEffectsDisabled(player,holder))for(var tool:battlefield.pokemonView(player,holder).attachedTools()) {
            var profile=combat.trainer(tool.definitionId()).orElse(null);
            if(profile!=null&&previousEvolutionProgram(profile.ongoingProgram()))return "memory-tool:"+tool.instanceId()+":"+battlefield.attachmentEntrySequence(player,holder,tool.instanceId());
        }
        for(var energy:battlefield.attachedEnergy(player,holder))
            if(previousEvolutionProgram(effectiveEnergyCard(player,energy).passiveProgram()))return "memory-energy:"+energy.instanceId()+":"+battlefield.attachmentEntrySequence(player,holder,energy.instanceId());
        if(stadium!=null&&previousEvolutionProgram(combat.trainer(stadium.definitionId()).orElseThrow().ongoingProgram())
            &&!preventsImpact(player,holder,new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId()),EffectProtection.Impact.OTHER_EFFECTS))
            return "memory-stadium:"+stadium.instanceId()+":"+stadiumEntrySequence;
        return null;
    }
    private static boolean previousEvolutionProgram(EffectProgram program) {
        return dev.hua.ptcglive.engine.effect.BorrowedAttackProgram.contains(program)
            &&dev.hua.ptcglive.engine.effect.BorrowedAttackProgram.previousEvolutions(program);
    }
    private BorrowedAttackOption requireBorrowedAttack(UUID player,UUID holder,long holderEntry,UUID holderTop,String abilityId,
        UUID provider,long providerEntry,UUID providerTop,String attackId) {
        requireTurn(player);requireCombatConfigured();
        var offered=borrowedAttackOptions(player).stream().filter(o->o.holderId().equals(holder)&&o.holderEntry()==holderEntry
            &&o.holderTop().equals(holderTop)&&o.abilityId().equals(abilityId)&&o.providerId().equals(provider)
            &&o.providerEntry()==providerEntry&&o.providerTop().equals(providerTop)&&o.attackId().equals(attackId)).findFirst()
            .orElseThrow(()->new IllegalArgumentException("借招特性、实际使用者或备战位印刷来源已改变"));
        require(offered.attack()!=null,offered.unsupportedReasonZh());return offered;
    }
    public List<CopyAttackOption> borrowedCopyAttackOptions(UUID player,UUID holder,long holderEntry,UUID holderTop,String abilityId,
        UUID provider,long providerEntry,UUID providerTop,String attackId) {
        var offered=requireBorrowedAttack(player,holder,holderEntry,holderTop,abilityId,provider,providerEntry,providerTop,attackId);
        return copyAttackOptionsForSource(player,holder,offered.attack());
    }
    public void attackBorrowed(UUID player,UUID holder,long holderEntry,UUID holderTop,String abilityId,
        UUID provider,long providerEntry,UUID providerTop,String attackId,UUID effectTarget,List<UUID> targets,List<UUID> discarded,
        UUID copySource,long copyEntry,String copiedId,String lockedId) {
        var offered=requireBorrowedAttack(player,holder,holderEntry,holderTop,abilityId,provider,providerEntry,providerTop,attackId);
        declareAttackFromPokemon(player,holder,offered.attack(),attackId,effectTarget,targets,discarded,copySource,copyEntry,copiedId,lockedId);
    }
    /** Revalidated native Bench declaration. Clients use issued option indices, never an executable attack. */
    public void attackFromBench(UUID player,UUID pokemonId,long entry,UUID topCardId,String attackId) {
        attackFromBenchWithChoices(player,pokemonId,entry,topCardId,attackId,null,List.of(),List.of(),null,-1,null,null);
    }
    public record BenchAttackOption(UUID pokemonId,long entry,UUID topCardId,AttackDefinition attack) { }
    public List<BenchAttackOption> benchAttackOptions(UUID player) {
        state(player);if(battlefield==null)return List.of();var result=new ArrayList<BenchAttackOption>();
        for(var pokemon:battlefield.benchView(player))if(mayAttackFrom(player,pokemon.pokemonId()))
            for(var attack:battlefield.pokemonProfile(player,pokemon.pokemonId()).attacks())
                if(attack.mayUseFromBench()&&attack.effectSupport()==EffectSupport.SUPPORTED&&dev.hua.ptcglive.engine.effect.AttackProgramRules.unsupportedReason(attack).isEmpty()
                    &&!battlefield.pokemonAttackLocked(player,pokemon.pokemonId(),attack)&&!attackSharedUsageExhausted(player,pokemon.pokemonId(),attack.usageLimit())&&attackUseAllowed(player,pokemon.pokemonId(),attack))
                    result.add(new BenchAttackOption(pokemon.pokemonId(),battlefield.pokemonEntrySequence(player,pokemon.pokemonId()),battlefield.topCard(player,pokemon.pokemonId()).instanceId(),attack));
        return List.copyOf(result);
    }
    public List<CopyAttackOption> benchCopyAttackOptions(UUID player,UUID pokemonId,String attackId) {
        requireCombatConfigured();require(battlefield.benchView(player).stream().anyMatch(p->p.pokemonId().equals(pokemonId)),"复制招式来源不在自己的备战位");
        var attack=battlefield.pokemonProfile(player,pokemonId).attack(attackId).orElseThrow();require(attack.mayUseFromBench(),"复制招式没有备战位宣告许可");
        return copyAttackOptionsForSource(player,pokemonId,attack);
    }
    public void attackFromBenchWithChoices(UUID player,UUID pokemonId,long entry,UUID topCardId,String attackId,
        UUID effectTarget,List<UUID> targets,List<UUID> discarded,UUID copySource,long copyEntry,String copiedId,String lockedId) {
        requireTurn(player);requireCombatConfigured();
        require(battlefield.benchView(player).stream().anyMatch(p->p.pokemonId().equals(pokemonId)),"攻击者不在自己的备战位");
        require(sameFieldEntry(player,pokemonId,entry)&&battlefield.topCard(player,pokemonId).instanceId().equals(topCardId),"备战招式来源已改变");
        declareAttackFromPokemon(player,pokemonId,null,attackId,effectTarget,targets,discarded,copySource,copyEntry,copiedId,lockedId);
    }
    /** Server-only candidate. Network clients receive labels/issued option indices, never this executable definition. */
    public record CopyAttackOption(UUID owner,UUID pokemonId,long entrySequence,String topCardId,
                                   String attackId,String nameZh,AttackDefinition effectiveAttack,String unsupportedReasonZh) { }
    public boolean hasPendingTopDeckAttackCopy() {return pendingTopDeckAttackCopy!=null&&pendingTopDeckAttackCopy.decisionReady()&&pendingReveal==null;}
    public boolean opponentChoosingCopiedAttack() {
        return pendingResolution!=null&&hasPendingTopDeckAttackCopy()
            &&CopyAttackProgram.opponentChooses(pendingTopDeckAttackCopy.declared())&&!pendingTopDeckAttackCopy.opponentSelected();
    }
    public boolean resolvingOpponentChosenAttack() {
        return hasPendingTopDeckAttackCopy()&&CopyAttackProgram.opponentChooses(pendingTopDeckAttackCopy.declared())
            &&pendingTopDeckAttackCopy.opponentSelected();
    }
    public TopDeckAttackCopyPrompt topDeckAttackCopyPrompt(UUID recipient) {
        require(pendingResolution!=null&&pendingChoicePlayer().equals(recipient)&&hasPendingTopDeckAttackCopy(),"你无权选择复制招式");
        var pending=pendingTopDeckAttackCopy;
        if(CopyAttackProgram.deckTop(pending.declared()))require(state(pending.opponent()).deck.equals(pending.deck()),"公开的对手牌库顶已改变");
        return new TopDeckAttackCopyPrompt(pendingResolution.id(),pending.step(),pending.declared(),pending.options());
    }
    /** The opponent chooses only a public attack. Its targets and costs belong to the actual attacker. */
    public void chooseOpponentCopiedAttack(UUID player,UUID resolutionId,long step,UUID source,long entry,String attackId) {
        require(opponentChoosingCopiedAttack(),"当前不等待对手选择招式");
        var prompt=topDeckAttackCopyPrompt(player);
        require(prompt.resolutionId().equals(resolutionId)&&prompt.step()==step,"复制招式选择已更新");
        var selected=prompt.options().stream().filter(o->o.pokemonId().equals(source)&&o.entrySequence()==entry&&o.attackId().equals(attackId))
            .findFirst().orElseThrow(()->new IllegalArgumentException("招式不在对手场上候选中"));
        require(sameFieldEntry(player,source,entry)&&battlefield.topCard(player,source).definitionId().equals(selected.topCardId()),"复制来源已经改变");
        require(selected.effectiveAttack()!=null,selected.unsupportedReasonZh());
        var pending=pendingTopDeckAttackCopy;
        pendingTopDeckAttackCopy=new PendingTopDeckAttackCopy(player,step,List.of(),List.of(),pending.declared(),List.of(selected),true,true);
        recordReplay(player,"对手指定复制招式："+selected.topCardId()+"/"+selected.attackId());
        // A printed usage restriction can prevent using the selected attack. It never lets the attacker pick another.
        var body=selected.effectiveAttack();UUID actor=pendingResolution.actor();
        boolean blocked=!attackUseAllowed(actor,attackCheckpoint.attacker.pokemonId(),body)||battlefield.pokemonAttackLocked(actor,attackCheckpoint.attacker.pokemonId(),body);
        try {requireAttackSharedUsage(actor,attackCheckpoint.attacker.pokemonId(),body.usageLimit());} catch(IllegalArgumentException|IllegalStateException unavailable) {blocked=true;}
        if(blocked) {
            recordReplay(actor,"被指定的招式使用条件不满足，攻击无效果");
            finishTopDeckAttackCopy(null,null,List.of(),List.of(),null);advancePendingResolution();
        }
    }
    public void chooseTopDeckCopiedAttack(UUID player,UUID resolutionId,long step,UUID sourceCardId,String copiedAttackId,
                                           UUID selectedEffectTarget,List<UUID> targets,List<UUID> discardedEnergy,String lockedOpponentAttackId) {
        var prompt=topDeckAttackCopyPrompt(player);
        require(!opponentChoosingCopiedAttack()&&pendingResolution.actor().equals(player),"应先由对手指定招式，再由攻击者结算");
        require(prompt.resolutionId().equals(resolutionId)&&prompt.step()==step,"牌库顶招式选择已更新");
        var option=prompt.options().stream().filter(o->o.pokemonId().equals(sourceCardId)&&o.attackId().equals(copiedAttackId)).findFirst()
            .orElseThrow(()->new IllegalArgumentException("选择的招式不在公开牌库顶窗口内"));
        require(option.effectiveAttack()!=null,option.unsupportedReasonZh());
        finishTopDeckAttackCopy(option,selectedEffectTarget,targets,discardedEnergy,lockedOpponentAttackId);
        advancePendingResolution();
    }
    public void declineTopDeckCopiedAttack(UUID player,UUID resolutionId,long step) {
        var prompt=topDeckAttackCopyPrompt(player);
        require(!CopyAttackProgram.opponentChooses(prompt.declared()),"对手指定的招式不能取消");
        require(!CopyAttackProgram.coinGated(prompt.declared()),"正面后必须选择一个可用的对方招式");
        require(prompt.resolutionId().equals(resolutionId)&&prompt.step()==step,"牌库顶招式选择已更新");
        finishTopDeckAttackCopy(null,null,List.of(),List.of(),null);advancePendingResolution();
    }
    private void finishTopDeckAttackCopy(CopyAttackOption option,UUID selectedEffectTarget,List<UUID> targets,
                                          List<UUID> discardedEnergy,String lockedOpponentAttackId) {
        var pending=pendingTopDeckAttackCopy;require(pending!=null&&pendingResolution!=null&&attackCheckpoint!=null,"牌库顶复制已结束");
        UUID player=pendingResolution.actor(),defender=other(player).id;var owner=state(pending.opponent());
        if(CopyAttackProgram.deckTop(pending.declared()))require(owner.deck.equals(pending.deck()),"公开牌库顶后的牌库已改变");
        else if(option!=null)require(sameFieldEntry(option.owner(),option.pokemonId(),option.entrySequence())
            &&battlefield.topCard(option.owner(),option.pokemonId()).definitionId().equals(option.topCardId()),"复制来源已经改变");
        if(CopyAttackProgram.ownDiscardedDeckTop(pending.declared()))require(pending.window().stream().allMatch(card->owner.discard.contains(card)
            ||hasPrismStarRule(card)&&owner.lostZone.contains(card)),"本次弃置的己方牌库顶卡已离开结算区域");
        AttackDefinition attack=option==null?pending.declared().withEffectProgram(EffectProgram.EMPTY):option.effectiveAttack();
        OpponentAttackLockChoice lockChoice=null;
        if(ServerMatch.locksOpponentAttack(attack)) {
            var choices=opponentAttackLockOptions(player);require(lockedOpponentAttackId!=null,"请先选择要锁定的对方招式");
            var chosen=choices.stream().filter(a->a.id().equals(lockedOpponentAttackId)).findFirst()
                .orElseThrow(()->new IllegalArgumentException("对方战斗宝可梦没有这个招式"));
            UUID target=battlefield.activeView(defender).pokemonId();
            lockChoice=new OpponentAttackLockChoice(defender,target,battlefield.pokemonEntrySequence(defender,target),chosen.nameZh());
        } else require(lockedOpponentAttackId==null,"这个被复制招式不能指定锁定目标");
        var preselection=resolveBeforeAttackPreselection(player,attack,selectedEffectTarget);
        validatePostAttackEnergyDiscard(player,attackCheckpoint.attacker.pokemonId(),attack,discardedEnergy);
        var defenders=resolveDamageTargets(defender,attack,targets,attackCheckpoint.attacker.pokemonId());
        preflightAttackProgram(player,attackCheckpoint.attacker.pokemonId(),attack,pending.declared(),defenders,preselection);
        for(UUID ownerId:players.keySet())preflightDamageReactions(ownerId,defenders.stream().filter(p->fieldOwner(p.pokemonId()).equals(ownerId)).toList(),attackCheckpoint.attacker.pokemonId());
        require(attackUseAllowed(player,attackCheckpoint.attacker.pokemonId(),attack),"招式使用条件不满足");
        require(!battlefield.pokemonAttackLocked(player,attackCheckpoint.attacker.pokemonId(),attack),"实际攻击者当前不能使用被复制招式");
        if(option!=null) {requireAttackSharedUsage(player,attackCheckpoint.attacker.pokemonId(),attack.usageLimit());consumeAttackSharedUsage(player,attackCheckpoint.attacker.pokemonId(),attack.usageLimit());}
        attackCheckpoint.bodyAttack=attack;attackCheckpoint.lockedOpponentAttack=lockChoice;attackCheckpoint.pendingPreselection=preselection;
        attackCheckpoint.pendingDamage=new DeclaredAttack(player,attack,targets,discardedEnergy);
        if(dev.hua.ptcglive.engine.effect.RepeatTargetDamage.handles(attack)) {
            var counts=new LinkedHashMap<UUID,Integer>();targets.forEach(id->counts.merge(id,1,Integer::sum));attackCheckpoint.repeatedTargetCounts=Map.copyOf(counts);
        }
        if(CopyAttackProgram.opponentDeckTop(pending.declared()))shuffle(owner.deck,"opponent-top-copy:"+player);
        recordReplay(player,CopyAttackProgram.opponentChooses(pending.declared())
            ?option==null?"复制攻击无效果":"结算对手指定招式："+option.topCardId()+"/"+option.attackId()
            :option==null?"未选择公开招式":"选择公开招式："+option.topCardId()+"/"+option.attackId());
        if(option!=null){state(player).currentTurnAttackIds.add(attack.id());state(player).currentTurnSourceAttacks.add(new SourceAttack(attackCheckpoint.attacker.pokemonId(),attackCheckpoint.attackerEntrySequence,attack.id()));}
        pendingResolution.continuation().completeInteraction(pending.step(),EffectExecutionContext.InteractionKind.TOP_DECK_ATTACK_COPY);
        pendingTopDeckAttackCopy=null;
    }
    private void continueTopDeckCopiedAttack() {
        require(attackCheckpoint!=null&&attackCheckpoint.pendingDamage!=null,"牌库顶复制未生成攻击");
        var declared=attackCheckpoint.pendingDamage;var before=dev.hua.ptcglive.engine.effect.AttackProgramRules.beforeDamage(declared.attack());
        if(before.triggers().isEmpty()) {attackCheckpoint.beforeDamageComplete=true;continueDeclaredAttackDamage();return;}
        resolvingEffectProgram=true;
        pendingResolution=new PendingResolution(UUID.randomUUID(),declared.actor(),null,null,
            new dev.hua.ptcglive.engine.effect.EffectContinuation(before.triggers().getFirst(),
                attackContinuationContext(declared.actor(),attackCheckpoint.attacker.pokemonId(),attackCheckpoint.pendingPreselection)),null,
            new MatchClientView.AttackResolution(attackCheckpoint.attacker.pokemonId(),declared.attack().id(),declared.attack().nameZh(),EffectTrigger.BEFORE_ATTACK));
        advancePendingResolution();
    }
    public List<CopyAttackOption> copyAttackOptions(UUID player,String declaredAttackId) {
        state(player);requireCombatConfigured();
        var profile=battlefield.activeProfile(player);
        var declared=profile.attack(declaredAttackId).orElseThrow(()->new IllegalArgumentException("当前战斗宝可梦没有此复制攻击"));
        return copyAttackOptionsForSource(player,battlefield.activeView(player).pokemonId(),declared);
    }
    /** No previous printed attack means this payable attack resolves with no effect. Missing card profiles fail closed. */
    public boolean previousEvolutionCopyHasNoChoice(UUID player,UUID attackerPokemonId,AttackDefinition declared) {
        if(!CopyAttackProgram.previousEvolutions(declared))return false;
        var cards=battlefield.previousEvolutionCards(player,attackerPokemonId);
        return cards.stream().allMatch(card->combat.pokemon(card.definitionId()).isPresent())
            &&copyAttackOptionsForSource(player,attackerPokemonId,declared).isEmpty();
    }
    /** A read-only server query used by every declaration adapter and its issued client actions. */
    public boolean needsCopyAttackSelection(UUID player,AttackDefinition declared) {
        var actor=state(player);
        return CopyAttackProgram.containsCopy(declared)&&!CopyAttackProgram.deckTop(declared)&&!CopyAttackProgram.opponentChooses(declared)&&!CopyAttackProgram.coinGated(declared)
            &&CopyAttackProgram.conditionSatisfied(declared,actor.hand.size());
    }
    private List<CopyAttackOption> copyAttackOptionsForSource(UUID player,UUID attackerPokemonId,AttackDefinition declared) {
        var profile=battlefield.pokemonProfile(player,attackerPokemonId);
        var scope=CopyAttackProgram.sourceScope(declared);
        var sourceFilters=CopyAttackProgram.sourceFilters(declared);
        if(!needsCopyAttackSelection(player,declared)&&!CopyAttackProgram.opponentChooses(declared)&&!CopyAttackProgram.coinGated(declared))return List.of();
        if(CopyAttackProgram.previousEvolutions(declared)) {
            var result=new ArrayList<CopyAttackOption>();
            long entry=battlefield.pokemonEntrySequence(player,attackerPokemonId);
            for(var card:battlefield.previousEvolutionCards(player,attackerPokemonId)) {
                var sourceProfile=combat.pokemon(card.definitionId()).orElse(null);
                if(sourceProfile==null)continue;
                for(var selected:sourceProfile.attacks())
                    result.add(copyAttackOption(player,attackerPokemonId,declared,profile.pokemonType(),
                        player,card.instanceId(),entry,card.definitionId(),selected));
            }
            return List.copyOf(result);
        }
        if(scope==EffectTarget.DISCARD) {
            boolean apex=CopyAttackProgram.apexDragon(declared);
            var result=new ArrayList<CopyAttackOption>();
            for(var card:state(player).discard) {
                var source=definition(card);
                if(source.category()!=CardCategory.POKEMON||!source.pokemonTypes().contains(EnergyType.DRAGON))continue;
                var sourceProfile=combat.pokemon(card.definitionId()).orElse(null);
                if(sourceProfile==null)continue;
                for(var selected:sourceProfile.attacks()) {
                    if(apex&&"apex-dragon".equals(selected.id())&&CopyAttackProgram.containsCopy(selected))continue;
                    result.add(copyAttackOption(player,attackerPokemonId,declared,profile.pokemonType(),
                        player,card.instanceId(),0,card.definitionId(),selected));
                }
            }
            return List.copyOf(result);
        }
        UUID owner=switch(scope) {
            case OWN_BENCH,ALL_OWN_POKEMON -> player;
            default -> other(player).id;
        };
        var sources=new ArrayList<BattlefieldState.PokemonView>();
        if(scope==EffectTarget.OPPONENT_ACTIVE||scope==EffectTarget.ALL_OWN_POKEMON||scope==EffectTarget.ALL_OPPONENT_POKEMON)
            if(battlefield.hasActive(owner))sources.add(battlefield.activeView(owner));
        if(scope!=EffectTarget.OPPONENT_ACTIVE)sources.addAll(battlefield.benchView(owner));
        sources.removeIf(source->{
            var sourceProfile=battlefield.pokemonProfile(owner,source.pokemonId());
            var sourceCard=fieldCardDefinition(source.topCardId());
            return sourceFilters.containsKey("source_name_contains")
                    &&(sourceProfile.pokemonName()==null||!sourceProfile.pokemonName().contains(sourceFilters.get("source_name_contains")))
                ||sourceFilters.containsKey("source_family")
                    &&!sourceCard.pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.valueOf(sourceFilters.get("source_family")));
        });
        var result=new ArrayList<CopyAttackOption>();
        for(var source:sources)for(var selected:battlefield.pokemonProfile(owner,source.pokemonId()).attacks())
            result.add(copyAttackOption(player,attackerPokemonId,declared,profile.pokemonType(),owner,source.pokemonId(),
                battlefield.pokemonEntrySequence(owner,source.pokemonId()),source.topCardId(),selected));
        return List.copyOf(result);
    }
    private CopyAttackOption copyAttackOption(UUID player,UUID attackerPokemonId,AttackDefinition declared,EnergyType attackerType,
        UUID sourceOwner,UUID sourceId,long sourceEntry,String sourceCardId,AttackDefinition selected) {
        AttackDefinition effective=null;String reason=null;
        try {
            effective=CopyAttackProgram.materialize(declared,selected,attackerType);
            if(CopyAttackProgram.opponentChooses(declared))return new CopyAttackOption(sourceOwner,sourceId,sourceEntry,sourceCardId,selected.id(),selected.nameZh(),effective,null);
            requireAttackSharedUsage(player,attackerPokemonId,declared.usageLimit());requireAttackSharedUsage(player,attackerPokemonId,selected.usageLimit());
            require(!battlefield.pokemonAttackLocked(player,attackerPokemonId,selected),"实际攻击者当前不能使用被复制招式");
            require(attackUseAllowed(player,attackerPokemonId,effective),"招式使用条件不满足");
        } catch(IllegalArgumentException|IllegalStateException invalid) {effective=null;reason=invalid.getMessage();}
        return new CopyAttackOption(sourceOwner,sourceId,sourceEntry,sourceCardId,selected.id(),selected.nameZh(),effective,reason);
    }
    public void copyAttackWithEnergyDiscards(UUID player,String declaredAttackId,UUID sourcePokemonId,long sourceEntrySequence,
                                            String copiedAttackId,List<UUID> targets,List<UUID> discardedEnergy) {
        copyAttackWithSelectedEffectTargetAndEnergyDiscards(player, declaredAttackId, sourcePokemonId, sourceEntrySequence,
            copiedAttackId, null, targets, discardedEnergy);
    }
    /** Copy-attack counterpart of the public pre-damage selection API. */
    public void copyAttackWithSelectedEffectTargetAndEnergyDiscards(UUID player,String declaredAttackId,UUID sourcePokemonId,long sourceEntrySequence,
                                                                     String copiedAttackId,UUID selectedEffectTarget,List<UUID> targets,List<UUID> discardedEnergy) {
        copyAttackWithSelectedEffectTargetAndEnergyDiscards(player,declaredAttackId,sourcePokemonId,sourceEntrySequence,
            copiedAttackId,selectedEffectTarget,targets,discardedEnergy,null);
    }
    /** Carries the copied attack's declaration-time lock choice through the same server validation as a normal attack. */
    public void copyAttackWithSelectedEffectTargetAndEnergyDiscards(UUID player,String declaredAttackId,UUID sourcePokemonId,long sourceEntrySequence,
                                                                     String copiedAttackId,UUID selectedEffectTarget,List<UUID> targets,List<UUID> discardedEnergy,
                                                                     String lockedOpponentAttackId) {
        declareAttack(player,declaredAttackId,selectedEffectTarget,targets,discardedEnergy,sourcePokemonId,sourceEntrySequence,
            copiedAttackId,lockedOpponentAttackId);
    }
    public void attackWithEnergyDiscards(UUID player, String attackId, List<UUID> targetPokemonIds, List<UUID> energyInstanceIds) {
        attackWithSelectedEffectTargetAndEnergyDiscards(player, attackId, null, targetPokemonIds, energyInstanceIds);
    }
    /**
     * Server-authoritative attack declaration with a distinct pre-damage
     * SELECT_* target.  The client may name only a visible in-play identity;
     * the server still validates its side, current incarnation and printed
     * program before any randomness or energy discard is committed.
     */
    public void attackWithSelectedEffectTargetAndEnergyDiscards(UUID player, String attackId, UUID selectedEffectTarget,
                                                                 List<UUID> targetPokemonIds, List<UUID> energyInstanceIds) {
        declareAttack(player,attackId,selectedEffectTarget,targetPokemonIds,energyInstanceIds,null,-1,null,null);
    }
    /** “Choose 1 of your opponent's Active Pokémon's attacks. …”: the opponent's Active Pokémon's printed attacks to choose from. */
    public List<AttackDefinition> opponentAttackLockOptions(UUID player) {
        UUID opponent = other(player).id;
        return battlefield == null || !battlefield.hasActive(opponent) ? List.of() : battlefield.activeProfile(opponent).attacks();
    }
    /** Attack declaration that names the opponent's attack for lock_opponent_attack (validated against the server's options). */
    public void attackLockingOpponentAttack(UUID player, String attackId, String lockedOpponentAttackId, UUID selectedEffectTarget,
                                            List<UUID> targetPokemonIds, List<UUID> energyInstanceIds) {
        declareAttack(player,attackId,selectedEffectTarget,targetPokemonIds,energyInstanceIds,null,-1,null,lockedOpponentAttackId);
    }
    /** Whether this attack text contains lock_opponent_attack and therefore needs the opponent's attack chosen at declaration. */
    public static boolean locksOpponentAttack(AttackDefinition attack) {
        return attack.effectProgram().triggers().stream().flatMap(t -> t.effects().stream()).anyMatch(ServerMatch::locksOpponentAttack);
    }
    private static boolean locksOpponentAttack(EffectDefinition effect) {
        return effect.type().equals("lock_opponent_attack") || effect.effects().stream().anyMatch(ServerMatch::locksOpponentAttack);
    }
    private void declareAttack(UUID player,String attackId,UUID selectedEffectTarget,List<UUID> targetPokemonIds,List<UUID> energyInstanceIds,
                               UUID copySource,long copyEntry,String copiedAttackId,String lockedOpponentAttackId) {
        requireTurn(player);requireCombatConfigured();
        declareAttackFromPokemon(player,battlefield.activeView(player).pokemonId(),null,attackId,selectedEffectTarget,targetPokemonIds,
            energyInstanceIds,copySource,copyEntry,copiedAttackId,lockedOpponentAttackId);
    }
    /** Only server-validated source adapters may supply a declaration resolved outside the holder's printed profile. */
    private void declareAttackFromPokemon(UUID player,UUID attackerPokemonId,AttackDefinition resolvedDeclaration,String attackId,
        UUID selectedEffectTarget,List<UUID> targetPokemonIds,List<UUID> energyInstanceIds,
        UUID copySource,long copyEntry,String copiedAttackId,String lockedOpponentAttackId) {
        requireTurn(player);
        require(mayAttackFrom(player,attackerPokemonId), "当前招式使用者不能攻击");
        requireCombatConfigured();
        UUID defenderId = other(player).id;
        PokemonProfile profile = battlefield.pokemonProfile(player,attackerPokemonId);
        AttackDefinition declared = resolvedDeclaration!=null?resolvedDeclaration:profile.attack(attackId).orElseThrow(() -> new IllegalArgumentException("当前招式使用者没有此攻击：" + attackId));
        require(attackTimingAllowed(player,attackerPokemonId,declared),"这个招式不能在当前首回合使用");
        require(battlefield.hasActive(player)&&battlefield.activeView(player).pokemonId().equals(attackerPokemonId)||declared.mayUseFromBench(),"这个招式不能从备战位宣告");
        requireAttackSharedUsage(player,attackerPokemonId,declared.usageLimit());
        require(!battlefield.pokemonAttackLocked(player,attackerPokemonId,declared), "该宝可梦在自己的下个回合不能使用此攻击");
        if (declared.effectSupport() == EffectSupport.UNSUPPORTED)
            throw new IllegalStateException("此攻击尚未支持：" + declared.unsupportedReasonZh());
        AttackDefinition attack=declared;
        CopyAttackOption copied=null;
        boolean topDeckCopy=CopyAttackProgram.containsCopy(declared)&&(CopyAttackProgram.deckTop(declared)||CopyAttackProgram.opponentChooses(declared)||CopyAttackProgram.coinGated(declared));
        if(topDeckCopy) {
            if(CopyAttackProgram.opponentChooses(declared))for(var option:copyAttackOptionsForSource(player,attackerPokemonId,declared))
                require(option.effectiveAttack()!=null,"对手可能指定尚未支持的招式："+option.nameZh()+"；"+option.unsupportedReasonZh());
            require(copySource==null&&copiedAttackId==null&&copyEntry==-1,"牌库顶复制须在攻击开始后由服务器展示并选择");
            attack=declared.withEffectProgram(EffectProgram.EMPTY);
        } else if(CopyAttackProgram.containsCopy(declared)&&!needsCopyAttackSelection(player,declared)) {
            // Failure of the printed gate still permits a payable, no-effect attack. Never execute a stale selected copy.
            require(copySource==null&&copiedAttackId==null&&copyEntry==-1,"复制条件未满足，不能指定复制来源");
            attack=declared.withEffectProgram(EffectProgram.EMPTY);
        } else if(CopyAttackProgram.previousEvolutions(declared)
            &&previousEvolutionCopyHasNoChoice(player,attackerPokemonId,declared)) {
            require(copySource==null&&copiedAttackId==null&&copyEntry==-1,"没有进化前招式时不能指定复制来源");
            attack=declared.withEffectProgram(EffectProgram.EMPTY);
        } else if(CopyAttackProgram.containsCopy(declared)) {
            require(copySource!=null&&copiedAttackId!=null,"请先选择服务器提供的复制招式");
            copied=copyAttackOptionsForSource(player,attackerPokemonId,declared).stream().filter(c->c.pokemonId().equals(copySource)
                &&c.entrySequence()==copyEntry&&c.attackId().equals(copiedAttackId)).findFirst()
                .orElseThrow(()->new IllegalArgumentException("复制来源或招式已改变，不能使用旧选择"));
            require(copied.effectiveAttack()!=null,copied.unsupportedReasonZh());
            attack=copied.effectiveAttack();
        } else require(copySource==null&&copiedAttackId==null,"普通攻击不能指定复制来源");
        require(attackUseAllowed(player,attackerPokemonId,attack),"招式使用条件不满足");
        OpponentAttackLockChoice lockChoice=null;
        if(locksOpponentAttack(attack)) {
            var options=opponentAttackLockOptions(player);
            if(options.isEmpty()) require(lockedOpponentAttackId==null,"对方战斗宝可梦没有招式可以选择");
            else {
                require(lockedOpponentAttackId!=null,"请先选择要锁定的对方招式");
                var chosen=options.stream().filter(o->o.id().equals(lockedOpponentAttackId)).findFirst()
                    .orElseThrow(()->new IllegalArgumentException("对方战斗宝可梦没有这个招式，不能使用旧选择"));
                UUID lockedPokemon=battlefield.activeView(defenderId).pokemonId();
                lockChoice=new OpponentAttackLockChoice(defenderId,lockedPokemon,battlefield.pokemonEntrySequence(defenderId,lockedPokemon),chosen.nameZh());
            }
        } else require(lockedOpponentAttackId==null,"这个招式不能指定要锁定的对方招式");
        var qualifications=new LinkedHashSet<dev.hua.ptcglive.engine.effect.SharedUsageLimit>();
        if(declared.usageLimit()!=null)qualifications.add(declared.usageLimit());
        if(attack.usageLimit()!=null)qualifications.add(attack.usageLimit());
        qualifications.forEach(q->requireAttackSharedUsage(player,attackerPokemonId,q));
        if (!attackSpecialConditionsAllow(player,attackerPokemonId))
            throw new IllegalStateException("睡眠或麻痹的宝可梦不能攻击");
        requireAttackEnergy(player, battlefield.pokemonView(player,attackerPokemonId).pokemonId(), declared);
        validatePostAttackEnergyDiscard(player,attackerPokemonId,attack,energyInstanceIds);
        // A forged target must not spend confusion RNG or change the board before validation.
        var defenderViews = resolveDamageTargets(defenderId, attack, targetPokemonIds,attackerPokemonId);
        var preselection = resolveBeforeAttackPreselection(player, attack, selectedEffectTarget);
        preflightAttackProgram(player, battlefield.pokemonView(player,attackerPokemonId).pokemonId(), attack, declared, defenderViews, preselection);
        for(UUID owner:players.keySet())preflightDamageReactions(owner,defenderViews.stream().filter(p->fieldOwner(p.pokemonId()).equals(owner)).toList(),attackerPokemonId);
        int gateFlips=battlefield.attackGateFlips(player,battlefield.pokemonView(player,attackerPokemonId).pokemonId());
        if(gateFlips>0) {
            var targets=List.copyOf(targetPokemonIds);var energy=List.copyOf(energyInstanceIds);
            if(pauseForCoinChoice(player,()->declareAttackFromPokemon(player,attackerPokemonId,resolvedDeclaration,attackId,
                selectedEffectTarget,targets,energy,copySource,copyEntry,copiedAttackId,lockedOpponentAttackId)))return;
        }
        var attackingState=state(player);
        attackingState.attacksMadeThisTurn++;
        attackingState.lastAttackPokemonId=attackerPokemonId;

        // Rulebook attack step 2-a: resolve attack-failure effects BEFORE Confusion (step 2-b).
        // A failed gate ends the turn without a Confusion coin or its three damage counters.
        if(gateFlips>0) {
            boolean allHeads=true;
            for(int i=0;i<gateFlips;i++) {
                boolean heads=flipEffectCoin(player,"attack-coin-gate:"+player+(gateFlips==1?"":":"+i));
                allHeads &= heads; // Both printed flips happen even when the first is tails.
                recordReplay(player,"攻击前第"+(i+1)+"次掷硬币："+(heads?"正面":"反面"));
            }
            if(!allHeads) {
                lastAttack=new AttackResolution(player,defenderId,declared.id(),declared.baseDamage(),0,0,false,false,false);
                endTurnAfterAttackAttempt(player);return;
            }
        }

        if (battlefield.pokemonView(player,attackerPokemonId).conditions().contains(SpecialCondition.CONFUSED)
            && !flipCoin(player,"attack-confusion:" + player)) {
            int counters=battlefield.confusionCounters(player);
            BattlefieldState.DamageResult selfDamage = battlefield.placeDamageCounters(player,attackerPokemonId,counters);
            lastAttack = new AttackResolution(player, defenderId, declared.id(), declared.baseDamage(), 0, counters*10, false, false, selfDamage.knockedOut());
            recordReplay(player, "混乱判定失败，攻击终止");
            if (selfDamage.knockedOut()) resolveKnockouts(List.of(new Knockout(player, battlefield.pokemonView(player,attackerPokemonId).pokemonId())), false);
            else endTurnAfterAttackAttempt(player);
            return;
        }
        var attackerView = battlefield.pokemonView(player,attackerPokemonId);
        String attackingName=battlefield.pokemonProfile(player,attackerView.pokemonId()).pokemonName();
        if(attackingName!=null)state(player).currentTurnAttackers.add(attackingName);
        if(attackingName!=null)state(player).currentTurnNamedAttacks.add(new NamedAttack(attackingName,declared.id()));
        for(var family:fieldCardDefinition(attackerView.topCardId()).pokemonFamilies())
            state(player).currentTurnAttackers.add("family:"+family.name()+":"+attackerView.pokemonId());
        state(player).currentTurnAttackIds.add(declared.id());
        state(player).currentTurnAttackIds.add(attack.id());
        long sourceEntry=battlefield.pokemonEntrySequence(player,attackerPokemonId);
        state(player).currentTurnSourceAttacks.add(new SourceAttack(attackerPokemonId,sourceEntry,declared.id()));
        state(player).currentTurnSourceAttacks.add(new SourceAttack(attackerPokemonId,sourceEntry,attack.id()));
        attackCheckpoint = new AttackCheckpoint(new EffectTargetResolution.PokemonTarget(player,battlefield.pokemonView(player,attackerPokemonId).pokemonId()),
            battlefield.pokemonEntrySequence(player,battlefield.pokemonView(player,attackerPokemonId).pokemonId()));
        attackCheckpoint.lockedOpponentAttack=lockChoice;
        attackCheckpoint.costAttack=declared;attackCheckpoint.bodyAttack=attack;
        if(dev.hua.ptcglive.engine.effect.RepeatTargetDamage.handles(attack)) {
            var counts=new LinkedHashMap<UUID,Integer>();
            targetPokemonIds.forEach(id->counts.merge(id,1,Integer::sum));
            attackCheckpoint.repeatedTargetCounts=Map.copyOf(counts);
        }
        // Confusion failure means this attack never happens; successful zero damage still uses the Power.
        qualifications.forEach(q->consumeAttackSharedUsage(player,attackerPokemonId,q));
        recordReplay(player,"宣告攻击："+declared.id());
        // Printed public name for the client presentation; never derive it from a private action label.
        recordReplay(player,"公开招式名称："+declared.nameZh());
        if(copied!=null)recordReplay(player,"复制公开招式："+copied.topCardId()+"/"+copied.attackId()+"；来源方="+copied.owner()+"；入场序号="+copied.entrySequence());
        if(topDeckCopy) {
            var effect=CopyAttackProgram.definition(declared);
            var binding=new dev.hua.ptcglive.engine.effect.TriggeredEffects(EffectTrigger.BEFORE_ATTACK,List.of(),List.of(effect));
            var context=attackContinuationContext(player,attackerView.pokemonId(),preselection);
            beginAttackComputation(player,declared,EffectTrigger.BEFORE_ATTACK,
                new dev.hua.ptcglive.engine.effect.EffectContinuation(binding,context),this::continueTopDeckCopiedAttack);
            return;
        }
        attackCheckpoint.pendingDamage=new DeclaredAttack(player,attack,targetPokemonIds,energyInstanceIds);
        var beforeDamage=dev.hua.ptcglive.engine.effect.AttackProgramRules.beforeDamage(attack);
        if(!beforeDamage.triggers().isEmpty()) {
            resolvingEffectProgram=true;
            pendingResolution=new PendingResolution(UUID.randomUUID(),player,null,null,
                new dev.hua.ptcglive.engine.effect.EffectContinuation(beforeDamage.triggers().getFirst(),attackContinuationContext(player,attackerView.pokemonId(),preselection)),null,
                new MatchClientView.AttackResolution(attackerView.pokemonId(),attack.id(),attack.nameZh(),EffectTrigger.BEFORE_ATTACK));
            advancePendingResolution();
        } else {
            attackCheckpoint.beforeDamageComplete=true;
            continueDeclaredAttackDamage();
        }
    }
    private void continueDeclaredAttackDamage() {
        if(phase!=MatchPhase.TURN||attackCheckpoint==null||!attackCheckpoint.beforeDamageComplete||attackCheckpoint.pendingDamage==null
            ||pendingResolution!=null||advancingResolution||toolOverflowPrompt()!=null)return;
        var declared=attackCheckpoint.pendingDamage;
        attackCheckpoint.pendingDamage=null;
        resolveDeclaredAttackDamage(declared);
    }
    /**
     * Binds a legacy public SELECT_* target before the attack checkpoint is
     * created.  This is deliberately separate from damage targets: a Bench
     * attack can have its own selected victims, while pre-damage text may
     * independently read or affect another public Pokémon.
     */
    private AttackPreselection resolveBeforeAttackPreselection(UUID player, AttackDefinition attack, UUID selectedPokemonId) {
        var selection = dev.hua.ptcglive.engine.effect.AttackProgramRules.beforeDamageSelectionTarget(attack);
        if (selection == null) {
            require(selectedPokemonId == null, "此攻击没有伤害前宝可梦选择");
            return AttackPreselection.NONE;
        }
        require(selectedPokemonId != null, "此攻击须先选择伤害前效果目标");
        UUID owner = switch (selection) {
            case SELECT_OWN_POKEMON -> player;
            case SELECT_OPPONENT_POKEMON -> other(player).id;
            default -> throw new IllegalStateException("伤害前预选目标类型尚未支持：" + selection);
        };
        battlefield.pokemonView(owner, selectedPokemonId);
        return new AttackPreselection(selection, new EffectTargetResolution.PokemonTarget(owner, selectedPokemonId));
    }
    private void resolveDeclaredAttackDamage(DeclaredAttack declared) {
        UUID player=declared.actor(),defenderId=other(player).id;
        var attack=declared.attack();var energyInstanceIds=declared.energyDiscards();var attacker=state(player);
        var attackerView=battlefield.pokemonView(player,attackCheckpoint.attacker.pokemonId());
        require(sameFieldEntry(player,attackerView.pokemonId(),attackCheckpoint.attackerEntrySequence)
            &&attackerView.pokemonId().equals(attackCheckpoint.attacker.pokemonId()),"伤害前攻击者已变化，不能重新宣告攻击");
        var sourceProfile=battlefield.pokemonProfile(player,attackerView.pokemonId());
        var sourceFacts=new dev.hua.ptcglive.engine.effect.AttackSourceFilter.Facts(currentFieldDefinition(player,attackerView.pokemonId()),sourceProfile.pokemonName(),
            battlefield.attachedEnergy(player,attackerView.pokemonId()).stream().anyMatch(c->!definition(c).basicEnergy()),sourceProfile,
            currentEnergyUnits(player,attackerView.pokemonId()),Set.copyOf(attackerView.conditions()),hasPossessedAbilities(player,attackerView.pokemonId()),attackerView.hitPoints()-attackerView.damage());
        attackCheckpoint.damageSource=new AttackDamageSource(sourceFacts,passiveModifiers(player,attackerView.pokemonId()),battlefield.attackDamagePenalty(player,attackerView.pokemonId()),
            attackDamageTypes(player,attackerView.pokemonId(),attack),hasToolPassiveRule(player,attackerView.pokemonId(),"bench_weakness_resistance"),
            hasToolPassiveRule(player,attackerView.pokemonId(),"attack_weakness_multiplier")?3:0,benchToolBonus(player,attackerView.pokemonId()));
        var defenderViews=resolveDamageTargets(defenderId,attack,declared.targets(),attackerView.pokemonId());
        if(dev.hua.ptcglive.engine.effect.PerTargetCoinDamage.contains(attack)&&attackCheckpoint.perTargetCoinDamage==null) {
            var originalTargets=defenderViews.stream().map(BattlefieldState.PokemonView::pokemonId).toList();
            if(coinChoiceAvailable(player)&&originalTargets.size()>1&&attackCheckpoint.firstCoinTarget==null) {
                require(pendingNativeCoinChoice==null,"逐目标投币排序不能重入");
                pendingNativeCoinChoice=new NativeCoinChoice(UUID.randomUUID(),player,null,originalTargets,selected->{
                    attackCheckpoint.firstCoinTarget=selected;resolveDeclaredAttackDamage(declared);
                });return;
            }
            var targets=new ArrayList<>(originalTargets);
            if(attackCheckpoint.firstCoinTarget!=null) {
                require(targets.remove(attackCheckpoint.firstCoinTarget),"首先投币的宝可梦已不在本次攻击目标中");
                targets.addFirst(attackCheckpoint.firstCoinTarget);
            }
            require(!targets.isEmpty(),"逐目标掷币攻击没有对手宝可梦");
            var context=new AttackDamageEffectContext(player,attackerView.pokemonId(),attack.id(),0,attack.damageTarget(),null,attackCheckpoint.costAttack);
            context.resumableCoins=true;
            var effects=new ArrayList<EffectDefinition>();
            for(int index=0;index<targets.size();index++)
                effects.add(new EffectDefinition("coin_flip",EffectTarget.SELF,
                    Map.of("flips","1","bind","target-coin-"+index),List.of(),List.of()));
            beginDamageCoinComputation(player,attack,context,effects,()->{
                context.preparedCoins.requireConsumed();
                var results=new LinkedHashMap<UUID,Integer>();
                for(int index=0;index<targets.size();index++)
                    results.put(targets.get(index),context.namedCoinResult("target-coin-"+index).heads()*150);
                attackCheckpoint.perTargetCoinDamage=Map.copyOf(results);
                resolveDeclaredAttackDamage(declared);
            });
            return;
        }
        if(attack.coinDamage()!=null&&attackCheckpoint.nativeCoinDamage==null&&battlefield.nextTurnAttackBase(player,attackerView.pokemonId(),attack.id()).isEmpty()
            &&(coinChoiceAvailable(player)||eligibleAttackCoinRetrySource(player,attackerView.pokemonId())!=null||!attackTailsDrawTools(player,attackerView.pokemonId()).isEmpty())) {
            openNativeAttackCoin(player,attack,EffectTrigger.ON_ATTACK,"native-base",attack.coinDamage().flips(),result->{
                attackCheckpoint.nativeCoinDamage=attack.baseDamage()+result.heads()*attack.coinDamage().perHeads();
                resolveDeclaredAttackDamage(declared);
            });return;
        }
        int baseRolledDamage=attackCheckpoint.nativeCoinDamage!=null?attackCheckpoint.nativeCoinDamage:
            battlefield.nextTurnAttackBase(player,attackerView.pokemonId(),attack.id()).orElseGet(()->attack.resolveBaseDamage(random,forceCoinTails(player)));
        if(dev.hua.ptcglive.engine.effect.AttackCoinRetry.hasDamageCoin(attack)&&attackCheckpoint.computedCoinDamage==null
            &&(coinChoiceAvailable(player)||eligibleAttackCoinRetrySource(player,attackerView.pokemonId())!=null)) {
            var target=defenderViews.getFirst();UUID owner=fieldOwner(target.pokemonId());
            int initial=initialAttackDamage(player,owner,attacker,attackerView,target,attack,baseRolledDamage);
            var primary=attack.damageTarget()==AttackDefinition.DamageTarget.OPPONENT_ACTIVE?null:
                new PokemonCandidate(new EffectTargetResolution.PokemonTarget(owner,target.pokemonId()),battlefield.pokemonEntrySequence(owner,target.pokemonId()));
            var context=new AttackDamageEffectContext(player,attackerView.pokemonId(),attack.id(),initial,attack.damageTarget(),primary,attackCheckpoint.costAttack);
            context.resumableCoins=true;var effects=new ArrayList<EffectDefinition>();
            for(var binding:attack.effectProgram().forTrigger(EffectTrigger.ON_ATTACK))
                effects.addAll(binding.conditions().isEmpty()?binding.effects():List.of(new EffectDefinition("conditional",EffectTarget.SELF,Map.of(),binding.conditions(),binding.effects())));
            beginDamageCoinComputation(player,attack,context,effects,()->{
                    context.preparedCoins.requireConsumed();
                    attackCheckpoint.computedCoinDamage=new ComputedAttackDamage(context.currentDamage,context.ignoresResistance);
                    resolveDeclaredAttackDamage(declared);
                });return;
        }
        int rolledDamage=baseRolledDamage;
        var rolledDamageByTarget=new LinkedHashMap<UUID,Integer>();
        var ignoreResistanceTargets=new java.util.HashSet<UUID>();
        PokemonProfile defender = null;
        for (var defenderView : defenderViews) {
            UUID targetOwner=fieldOwner(defenderView.pokemonId());
            var profile=battlefield.pokemonProfile(targetOwner,defenderView.pokemonId());
            if(defender==null)defender=profile;
            int initialDamage=initialAttackDamage(player,targetOwner,attacker,attackerView,defenderView,attack,baseRolledDamage);
            var primaryDamageTarget=attack.damageTarget()==AttackDefinition.DamageTarget.OPPONENT_ACTIVE?null
                :new PokemonCandidate(new EffectTargetResolution.PokemonTarget(targetOwner,defenderView.pokemonId()),
                    battlefield.pokemonEntrySequence(targetOwner,defenderView.pokemonId()));
            var resolved=attackCheckpoint.computedCoinDamage!=null?attackCheckpoint.computedCoinDamage:
                resolveAttackProgramDamage(player,attackerView.pokemonId(),attack,initialDamage,primaryDamageTarget);
            rolledDamageByTarget.put(defenderView.pokemonId(),resolved.damage());
            if(resolved.ignoresResistance())ignoreResistanceTargets.add(defenderView.pokemonId());
            if(rolledDamageByTarget.size()==1)rolledDamage=resolved.damage();
        }
        var attackOrigin = new EffectOrigin(EffectOrigin.Kind.ATTACK,player,attackerView.pokemonId());
        // Ongoing attacking-source modifiers precede Weakness/Resistance, and never turn a zero-damage attack into damage.
        if(attack.damageTarget()==AttackDefinition.DamageTarget.OPPONENT_ACTIVE&&rolledDamage>0)
            rolledDamage=Math.max(0,rolledDamage+attackCheckpoint.damageSource.modifiers().damageDealtChange(true)
                +attackCheckpoint.damageSource.modifiers().activeDamageDealtChange()+playerTurnAttackBonus(player,attackerView)
                -attackCheckpoint.damageSource.penalty()+battlefield.attackDamageBonus(player,attackerView.pokemonId(),attackCheckpoint.costAttack.id()));
        boolean nativeBypass = attack.ignoresActiveDefenderDamageEffects()
            || pokemonHasPassiveRule(player,attackerView.pokemonId(),"ignore_defender_damage_effects");
        boolean turnBypass=playerTurnAttackBypass(player,attackerView.pokemonId());
        // Only an Active-only attack shares this Weakness/Resistance computation.
        // A protected first Bench target must not zero damage to every other target.
        boolean preventsDamage = !nativeBypass&&!turnBypass && attack.damageTarget() == AttackDefinition.DamageTarget.OPPONENT_ACTIVE
            && !defenderViews.isEmpty() && (preventsImpact(defenderId,defenderViews.getFirst().pokemonId(),attackOrigin,EffectProtection.Impact.DAMAGE)
                || passivelyPreventsAttackDamage(defenderId,defenderViews.getFirst().pokemonId(),attackOrigin)
                || stadiumPreventsAttackDamage(defenderId,defenderViews.getFirst().pokemonId(),attackOrigin));
        int damage = preventsDamage ? 0 : rolledDamage;
        var attackTypes=attackDamageTypes(player,attackerView.pokemonId(),attack);
        boolean weakness = false, resistance = false;
        EnergyType weaknessType=defenderViews.isEmpty()||!attack.damageTarget().appliesWeaknessAndResistance()
            ?null:currentWeaknessType(defenderId,defenderViews.getFirst().pokemonId());
        if (!preventsDamage && !attack.ignoresWeaknessAndResistance() && !attack.ignoresWeakness() && defender != null && attack.damageTarget().appliesWeaknessAndResistance() && !removesWeakness(defenderId,defenderViews.getFirst().pokemonId()) && weaknessType!=null && attackTypes.contains(weaknessType)) {
            damage = dev.hua.ptcglive.engine.field.DamageArithmetic.weakness(damage,currentWeaknessMultiplier(defenderId,defenderViews.getFirst().pokemonId(),currentWeaknessBaseMultiplier(defenderId,defenderViews.getFirst().pokemonId())));
            weakness = true;
        }
        if (!preventsDamage && !attack.ignoresWeaknessAndResistance() && !attack.ignoresResistance() && ignoreResistanceTargets.isEmpty() && defender != null && attack.damageTarget().appliesWeaknessAndResistance() && !stadiumHasPassiveRule("no_resistance") && defender.resistanceType()!=null && attackTypes.contains(defender.resistanceType())) {
            // A nonpositive result ends this target's calculation before receiving-side modifiers.
            damage = dev.hua.ptcglive.engine.field.DamageArithmetic.resistance(damage,defender.resistanceAmount());
            resistance = true;
        }
        final int damageBase=damage,rolledBase=rolledDamage;
        final boolean initialWeakness=weakness,initialResistance=resistance;
        // Each committed target is visited once; an Ability coin can pause before the next damage packet.
        class TargetDamageRun {
            final List<Knockout> knocked=new ArrayList<>();
            boolean knockedOut,firstTarget=true,weakness=initialWeakness,resistance=initialResistance;
            int auditedFinalDamage=defenderViews.isEmpty()?0:damageBase,index;
            void advance() {
                for(;index<defenderViews.size();index++) {
                    var target=defenderViews.get(index);
            UUID targetOwner=fieldOwner(target.pokemonId());
            int targetRolledDamage=attack.damageTarget()==AttackDefinition.DamageTarget.OPPONENT_ACTIVE?rolledBase
                :rolledDamageByTarget.get(target.pokemonId());
            if(attack.damageTarget()!=AttackDefinition.DamageTarget.OPPONENT_ACTIVE&&targetRolledDamage>0)
                targetRolledDamage=Math.max(0,targetRolledDamage+attackCheckpoint.damageSource.modifiers().damageDealtChange(!targetOwner.equals(player))
                    -attackCheckpoint.damageSource.penalty()
                    +opponentBenchAttackBonus(player,targetOwner,target.pokemonId())
                    // “… do N more damage to your opponent's Active Pokémon”: only the opponent's Active among several targets.
                    +(!targetOwner.equals(player)&&battlefield.hasActive(targetOwner)&&battlefield.activeView(targetOwner).pokemonId().equals(target.pokemonId())
                        ?battlefield.attackDamageBonus(player,attackerView.pokemonId(),attackCheckpoint.costAttack.id())+attackCheckpoint.damageSource.modifiers().activeDamageDealtChange()+playerTurnAttackBonus(player,attackerView)
                        :targetOwner.equals(player)&&battlefield.hasActive(player)&&battlefield.activeView(player).pokemonId().equals(target.pokemonId())?playerTurnAttackBonus(player,attackerView,true)+attackCheckpoint.damageSource.modifiers().ownActiveDamageDealtChange():0));
            boolean bypassesDefenderDamageEffects=nativeBypass||turnBypass&&!targetOwner.equals(player)
                &&battlefield.hasActive(targetOwner)&&battlefield.activeView(targetOwner).pokemonId().equals(target.pokemonId());
            boolean targetProtected = !bypassesDefenderDamageEffects
                && preventsImpact(targetOwner,target.pokemonId(),attackOrigin,EffectProtection.Impact.DAMAGE);
            boolean targetPassivelyImmune = !bypassesDefenderDamageEffects
                && passivelyPreventsAttackDamage(targetOwner, target.pokemonId(),attackOrigin);
            boolean targetStadiumImmune=!bypassesDefenderDamageEffects&&stadiumPreventsAttackDamage(targetOwner,target.pokemonId(),attackOrigin);
            int reduction = bypassesDefenderDamageEffects ? 0
                : battlefield.attackDamageReduction(targetOwner, target.pokemonId(), player)
                    + playerTurnDamageReduction(targetOwner,target.pokemonId(),player);
            int passiveReduction = bypassesDefenderDamageEffects ? 0 : passiveAttackDamageReduction(targetOwner, target.pokemonId(),attackOrigin);
            int persistentChange=bypassesDefenderDamageEffects||targetRolledDamage==0?0:passiveModifiers(targetOwner,target.pokemonId()).damageReceivedChange(!targetOwner.equals(player));
            // “During your next turn, the Defending Pokémon takes N more damage from attacks.”: after Weakness/Resistance.
            int takenIncrease=bypassesDefenderDamageEffects||targetRolledDamage==0?0:battlefield.damageTakenIncrease(targetOwner,target.pokemonId());
            int temporaryChange=bypassesDefenderDamageEffects||targetRolledDamage==0?0:
                battlefield.attackDamageReceivedChange(targetOwner,target.pokemonId(),player,attackCheckpoint.damageSource.facts());
            int targetBaseDamage=attack.damageTarget()==AttackDefinition.DamageTarget.OPPONENT_ACTIVE?damageBase:targetRolledDamage;
            // Mixed-target damage ordinarily uses Weakness/Resistance only for the Active. Psychic Arrow explicitly includes its chosen Bench target.
            if((attack.damageTarget().mixedTargets()||toolAppliesBenchWeakness(targetOwner,target.pokemonId()))&&!attack.ignoresWeaknessAndResistance()&&!attackTypes.isEmpty()
                &&(attack.applyWeaknessResistanceToBench()||toolAppliesBenchWeakness(targetOwner,target.pokemonId())||battlefield.hasActive(targetOwner)
                    &&battlefield.activeView(targetOwner).pokemonId().equals(target.pokemonId()))) {
                var victim=battlefield.pokemonProfile(targetOwner,target.pokemonId());
                EnergyType targetWeakness=currentWeaknessType(targetOwner,target.pokemonId());
                if(!attack.ignoresWeakness()&&!removesWeakness(targetOwner,target.pokemonId())&&targetWeakness!=null&&attackTypes.contains(targetWeakness)){targetBaseDamage*=currentWeaknessMultiplier(targetOwner,target.pokemonId(),currentWeaknessBaseMultiplier(targetOwner,target.pokemonId()));weakness=true;}
                if(!attack.ignoresResistance()&&!ignoreResistanceTargets.contains(target.pokemonId())&&!stadiumHasPassiveRule("no_resistance")&&victim.resistanceType()!=null&&attackTypes.contains(victim.resistanceType())){targetBaseDamage-=victim.resistanceAmount();resistance=true;}
            }
            int targetDamage = targetBaseDamage <= 0 || targetProtected || targetPassivelyImmune || targetStadiumImmune || benchedPreventsAttackDamage(targetOwner, target.pokemonId())
                ? 0 : Math.max(0, targetBaseDamage - reduction - passiveReduction + persistentChange + takenIncrease + temporaryChange);
            if(!bypassesDefenderDamageEffects&&passiveAttackGuard(targetOwner,target.pokemonId(),attackOrigin).prevents(targetDamage))targetDamage=0;
            if(!bypassesDefenderDamageEffects&&coinChoiceAvailable(targetOwner)
                &&hasDamagePreventionCoin(targetOwner,target.pokemonId(),targetDamage)
                &&pauseForCoinChoice(targetOwner,this::advance))return;
            if (!bypassesDefenderDamageEffects && coinPreventsAttackDamage(targetOwner, target.pokemonId(), targetDamage)) targetDamage = 0;
            int maximumGuard=bypassesDefenderDamageEffects?0:battlefield.attackDamageMaximumGuard(targetOwner,target.pokemonId(),player);
            if(targetDamage>0&&maximumGuard>0&&targetDamage<=maximumGuard)targetDamage=0;
            if (firstTarget) { auditedFinalDamage = targetDamage; firstTarget = false; }
            boolean hadFullHp=battlefield.pokemonView(targetOwner,target.pokemonId()).damage()==0;
            BattlefieldState.DamageResult damageResult = battlefield.damagePokemon(targetOwner, target.pokemonId(), targetDamage);
            boolean activeDefender=battlefield.activeView(targetOwner).pokemonId().equals(target.pokemonId());
            boolean lethal=damageResult.knockedOut();
            if(lethal&&(!nativeBypass||!activeDefender))
                lethal=!surviveFullHpAttackDamage(targetOwner,target.pokemonId(),player,hadFullHp,true);
            if(targetDamage>0) {
                EnergyType opponentActiveType = null;
                if (!targetOwner.equals(player) && battlefield.hasActive(player))
                    opponentActiveType = currentPrimaryPokemonType(player,battlefield.activeView(player).pokemonId());
                recordAttackDamage(new AttackDamageEvent(targetOwner,target.pokemonId(),targetDamage,
                    activeDefender,lethal,battlefield.pokemonEntrySequence(targetOwner,target.pokemonId()),hadFullHp,opponentActiveType));
            }
            if (lethal) { knocked.add(new Knockout(targetOwner, target.pokemonId())); knockedOut = true; }
        }
        continueNativeAttackEffects(new NativeAttackTail(declared,attackerView,List.copyOf(knocked),knockedOut,rolledBase,auditedFinalDamage,weakness,resistance),0);
            }
        }
        new TargetDamageRun().advance();
    }
    /** B-09: self attack damage follows source effects, Active W/R, then receiving effects. */
    private int calculateAttackSelfDamage(int printedDamage) {
        return calculateAttackSelfDamage(printedDamage,true);
    }
    private int calculateAttackSelfDamage(int printedDamage,boolean flipPreventionCoin) {
        if (printedDamage <= 0) return 0;
        require(attackCheckpoint != null && attackCheckpoint.damageSource != null,
            "自伤缺少当前攻击的伤害计算状态");
        var checkpoint = attackCheckpoint;
        var attacker = checkpoint.attacker;
        UUID owner = attacker.owner(), pokemon = attacker.pokemonId();
        if (!sameFieldEntry(owner, pokemon, checkpoint.attackerEntrySequence)) return 0;
        var origin = new EffectOrigin(EffectOrigin.Kind.ATTACK, owner, pokemon);
        // Capture outgoing effects once after BEFORE_ATTACK, as for independent Bench damage.
        // SELF is never an opponent or opponent's Active recipient.
        boolean active = battlefield.hasActive(owner) && battlefield.activeView(owner).pokemonId().equals(pokemon);
        int damage = printedDamage + checkpoint.damageSource.modifiers().damageDealtChange(false)
            +(active?playerTurnAttackBonus(owner,battlefield.pokemonView(owner,pokemon),true)+checkpoint.damageSource.modifiers().ownActiveDamageDealtChange():0)-checkpoint.damageSource.penalty();
        if (damage <= 0) return 0;
        var attack = checkpoint.bodyAttack;
        var profile = battlefield.pokemonProfile(owner, pokemon);
        // The server materializes copied/borrowed bodies with the actual attacker's type.
        var types=attackDamageTypes(owner,pokemon,attack);
        if (active && !types.isEmpty() && !attack.ignoresWeaknessAndResistance()) {
            EnergyType weaknessType=currentWeaknessType(owner,pokemon);
            if (!attack.ignoresWeakness() && !removesWeakness(owner,pokemon)
                && weaknessType!=null && types.contains(weaknessType))
                damage *= currentWeaknessMultiplier(owner,pokemon,currentWeaknessBaseMultiplier(owner,pokemon));
            if (!attack.ignoresResistance() && !stadiumHasPassiveRule("no_resistance") && profile.resistanceType()!=null && types.contains(profile.resistanceType())) damage -= profile.resistanceAmount();
        }
        // Resistance ending damage cannot be revived by positive receiving effects.
        if (damage <= 0) return 0;
        damage = Math.max(0, damage + passiveModifiers(owner,pokemon).damageReceivedChange(false)
            + battlefield.damageTakenIncrease(owner,pokemon)
            + battlefield.attackDamageReceivedChange(owner,pokemon,owner,checkpoint.damageSource.facts())
            - battlefield.attackDamageReduction(owner,pokemon,owner)
            - playerTurnDamageReduction(owner,pokemon,owner)
            - passiveAttackDamageReduction(owner,pokemon,origin));
        // Opponent-defender bypass text does not bypass protection on the attacker itself.
        if (preventsImpact(owner,pokemon,origin,EffectProtection.Impact.DAMAGE)
            || passivelyPreventsAttackDamage(owner,pokemon,origin) || benchedPreventsAttackDamage(owner,pokemon)) return 0;
        return flipPreventionCoin&&coinPreventsAttackDamage(owner,pokemon,damage) ? 0 : damage;
    }
    private record NativeAttackTail(DeclaredAttack declared,BattlefieldState.PokemonView attackerView,List<Knockout> knocked,
                                    boolean knockedOut,int rolledDamage,int finalDamage,boolean weakness,boolean resistance) { }
    private void continueNativeAttackEffects(NativeAttackTail tail,int firstCondition) {
        var declared=tail.declared();var attack=declared.attack();UUID player=declared.actor(),defenderId=other(player).id;
        var attackerView=tail.attackerView();var origin=new EffectOrigin(EffectOrigin.Kind.ATTACK,player,attackerView.pokemonId());
        for(int index=firstCondition;index<attack.conditions().size();index++) {
            var effect=attack.conditions().get(index);
            UUID affected=effect.target()==dev.hua.ptcglive.engine.field.ConditionEffect.Target.SELF?player:defenderId;
            if(!battlefield.hasActive(affected))continue;
            UUID subject=effect.target()==dev.hua.ptcglive.engine.field.ConditionEffect.Target.SELF?attackerView.pokemonId():battlefield.activeView(affected).pokemonId();
            if(!battlefield.activeView(affected).pokemonId().equals(subject)||preventsImpact(affected,subject,origin,EffectProtection.Impact.OTHER_EFFECTS))continue;
            if(effect.coinCondition()!=null&&(coinChoiceAvailable(player)||eligibleAttackCoinRetrySource(player,attackerView.pokemonId())!=null||!attackTailsDrawTools(player,attackerView.pokemonId()).isEmpty())) {
                int next=index+1;
                openNativeAttackCoin(player,attack,EffectTrigger.AFTER_ATTACK,"native-condition-"+index,effect.coinCondition().flips(),result->{
                    if(result.heads()>=effect.coinCondition().requiredHeads()&&!passivelyPreventsSpecialConditions(affected,effect.condition()))
                        battlefield.applySpecialCondition(affected,effect.condition());
                    continueNativeAttackEffects(tail,next);
                });return;
            }
            if(effect.resolves(random,attack.id(),index,forceCoinTails(player))&&!passivelyPreventsSpecialConditions(affected,effect.condition()))battlefield.applySpecialCondition(affected,effect.condition());
        }
        if(attack.coinProtection()!=null&&(coinChoiceAvailable(player)||eligibleAttackCoinRetrySource(player,attackerView.pokemonId())!=null||!attackTailsDrawTools(player,attackerView.pokemonId()).isEmpty())) {
            openNativeAttackCoin(player,attack,EffectTrigger.AFTER_ATTACK,"native-protection",attack.coinProtection().flips(),result->{
                if(result.heads()>=attack.coinProtection().requiredHeads())battlefield.protectFromOpponentNextTurn(player,attackerView.pokemonId(),defenderId,attack.coinProtection().scope());
                finishNativeAttackTail(tail);
            });return;
        }
        if(attack.resolvesProtection(random,forceCoinTails(player)))battlefield.protectFromOpponentNextTurn(player,attackerView.pokemonId(),defenderId,attack.coinProtection().scope());
        finishNativeAttackTail(tail);
    }
    private void finishNativeAttackTail(NativeAttackTail tail) {
        var declared=tail.declared();var attack=declared.attack();var energyInstanceIds=declared.energyDiscards();
        UUID player=declared.actor(),defenderId=other(player).id;var attackerView=tail.attackerView();
        if(coinChoiceAvailable(player)&&hasDamagePreventionCoin(player,attackerView.pokemonId(),calculateAttackSelfDamage(attack.selfDamage(),false))
            &&pauseForCoinChoice(player,()->finishNativeAttackTail(tail)))return;
        var attackOrigin=new EffectOrigin(EffectOrigin.Kind.ATTACK,player,attackerView.pokemonId());
        var knocked=new ArrayList<>(tail.knocked());boolean knockedOut=tail.knockedOut();
        int rolledDamage=tail.rolledDamage(),auditedFinalDamage=tail.finalDamage();boolean weakness=tail.weakness(),resistance=tail.resistance();
        if (attack.damageReductionFromOpponentNextTurn() > 0)
            battlefield.reduceDamageFromOpponentNextTurn(player, attackerView.pokemonId(), defenderId,
                attack.damageReductionFromOpponentNextTurn());
        if (attack.cannotUseSameAttackDuringNextTurn())
            battlefield.lockAttackUntilAfterOwnerNextTurn(player, attackerView.pokemonId(), attack);
        if (attack.selfDamage() > 0) preflightDamageReactions(player,List.of(attackerView));
        int selfDamage = calculateAttackSelfDamage(attack.selfDamage());
        if (selfDamage > 0) {
            boolean hadFullHp=battlefield.pokemonView(player,attackerView.pokemonId()).damage()==0;
            BattlefieldState.DamageResult result = battlefield.damagePokemon(player,attackerView.pokemonId(),selfDamage);
            recordAttackDamage(new AttackDamageEvent(player,attackerView.pokemonId(),selfDamage,battlefield.hasActive(player)&&battlefield.activeView(player).pokemonId().equals(attackerView.pokemonId()),result.knockedOut(),battlefield.pokemonEntrySequence(player,attackerView.pokemonId()),hadFullHp));
            if (result.knockedOut()) { knocked.add(new Knockout(player, attackerView.pokemonId())); knockedOut = true; }
        }
        var discardReturns=fieldDiscardReturnCards();
        if (attack.discardAllAttachedEnergyAfterAttack()) {
            List<UUID> allAttachedEnergy = battlefield.attachedEnergy(player, attackerView.pokemonId()).stream()
                .map(CardInstance::instanceId).toList();
            if (!allAttachedEnergy.isEmpty()) {
                List<CardInstance> returned = nitroEnergyReturnedAfterAttackDiscard(player,attackerView.pokemonId(),
                    battlefield.attachedEnergy(player,attackerView.pokemonId()).stream().filter(c->allAttachedEnergy.contains(c.instanceId())).toList());
                List<CardInstance> discarded = battlefield.detachEnergy(player, attackerView.pokemonId(), allAttachedEnergy);
                attackCheckpoint.nitroEnergy.addAll(returned);
                moveCardsToOwnerDiscard(discarded,discardReturns);
            }
        }
        if (attack.discardSelectedAttachedEnergyAfterAttack() > 0 && !energyInstanceIds.isEmpty()) {
            List<CardInstance> returned = nitroEnergyReturnedAfterAttackDiscard(player,attackerView.pokemonId(),
                battlefield.attachedEnergy(player,attackerView.pokemonId()).stream().filter(c->energyInstanceIds.contains(c.instanceId())).toList());
            List<CardInstance> discarded = battlefield.detachEnergy(player, attackerView.pokemonId(), energyInstanceIds);
            attackCheckpoint.nitroEnergy.addAll(returned);
            moveCardsToOwnerDiscard(discarded,discardReturns);
        }
        if (attack.selfHealAfterAttack() > 0 && !healingBlocked(player,attackerView.pokemonId()) && !preventsImpact(player,attackerView.pokemonId(),attackOrigin,EffectProtection.Impact.OTHER_EFFECTS)) {
            battlefield.healByEffect(player, attackerView.pokemonId(), attack.selfHealAfterAttack()*(legendaryHealing()?2:1));
            var healed=battlefield.pokemonView(player,attackerView.pokemonId());
            if(healed.damage()<healed.hitPoints())attackCheckpoint.attackDamageKnockouts.remove(new Knockout(player,attackerView.pokemonId()));
        }
        lastAttack = new AttackResolution(player, defenderId, attack.id(), rolledDamage, auditedFinalDamage, selfDamage, weakness, resistance, knockedOut);
        if(auditedFinalDamage==0&&attack.damageTarget()==AttackDefinition.DamageTarget.OPPONENT_ACTIVE)
            recordReplay(player,"公开零伤害：对战斗宝可梦的攻击伤害为 0；其他效果另行结算");
        recordReplay(player, "使用攻击");
        var afterDamage = dev.hua.ptcglive.engine.effect.AttackProgramRules.afterDamage(attack);
        if (!afterDamage.triggers().isEmpty()) {
            var context = attackContinuationContext(player, attackerView.pokemonId());
            resolvingEffectProgram = true;
            pendingEffectKnockouts.addAll(knocked);
            pendingResolution = new PendingResolution(UUID.randomUUID(),player,null,null,
                new dev.hua.ptcglive.engine.effect.EffectContinuation(afterDamage.triggers().getFirst(),context),null,
                new MatchClientView.AttackResolution(attackerView.pokemonId(),attack.id(),attack.nameZh()));
            advancePendingResolution();
        } else {
            attackCheckpoint.textComplete=true;endingResumableAttack=true;drainTriggeredAbilities();
        }
    }

    /** Creates one public target's pre-damage facts; random base damage is rolled once per declared attack. */
    private int initialAttackDamage(UUID player,UUID defenderId,PlayerState attacker,BattlefieldState.PokemonView attackerView,
                                    BattlefieldState.PokemonView defenderView,AttackDefinition attack,int baseRolledDamage) {
        DamageContext damageContext = new DamageContext(attackerView.damage(), defenderView.damage(),
            battlefield.benchView(player).size(), battlefield.benchView(defenderId).size(),
            attacker.prizes.size(), state(defenderId).prizes.size(),
            attackerView.conditions().size(), defenderView.conditions().size(),
            currentEnergyUnits(player,attackerView.pokemonId()), currentEnergyUnits(defenderId,defenderView.pokemonId()),
            attackerView.attachedTools().size(), defenderView.attachedTools().size(),
            attacker.hand.size(), state(defenderId).hand.size(), attacker.deck.size(), state(defenderId).deck.size(),
            attacker.discard.size(), state(defenderId).discard.size(), attacker.lostZone.size(), state(defenderId).lostZone.size(),
            battlefield.hasActive(defenderId) ? battlefield.activeRetreatCost(defenderId) : 0);
        return Math.max(0,baseRolledDamage+attack.resolveDamageModifiers(damageContext));
    }

    private void preflightDamageReactions(UUID defender,List<BattlefieldState.PokemonView> targets) {
        preflightDamageReactions(defender,targets,attackCheckpoint!=null?attackCheckpoint.attacker.pokemonId():battlefield.activeView(currentPlayer).pokemonId());
    }
    private void preflightDamageReactions(UUID defender,List<BattlefieldState.PokemonView> targets,UUID attackerPokemonId) {
        var observers=new ArrayList<>(battlefield.benchView(defender));
        if(battlefield.hasActive(defender))observers.add(battlefield.activeView(defender));
        for(var target:targets) for(var observer:observers) for(var ability:activeAbilities(defender,observer.pokemonId())) {
            if(!(ability.eventPolicy() instanceof DamageTriggerPolicy policy)||policy.opponentOnly()&&defender.equals(currentPlayer)
                ||!policy.watches(observer.pokemonId(),target.pokemonId(),battlefield.pokemonProfile(defender,target.pokemonId()).pokemonName()))continue;
            require(ruleset.triggerTiming()==dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,"此规则包的受伤触发时序尚未核验");
            TriggeredAbilityRules.validate(ability);
            automaticPreviewContext(defender,observer.pokemonId(),bindSourceEvent(defender,observer.pokemonId(),bindEvent(new EffectTargetResolution.PokemonTarget(defender,target.pokemonId()),
                new EffectTargetResolution.PokemonTarget(currentPlayer,attackerPokemonId))),ability.effectProgram())
                .preflight(ability.effectProgram(),EffectTrigger.ON_DAMAGE);
        }
        for(var listener:persistentListeners())for(var effect:listener.effects()) {
            if(!(effect.eventPolicy() instanceof DamageTriggerPolicy policy)||policy.opponentOnly()&&defender.equals(currentPlayer)||!listener.owner().equals(defender)
                ||targets.stream().noneMatch(p->p.pokemonId().equals(listener.host())))continue;
            var entry=persistentCandidate(listener,effect,bindEvent(new EffectTargetResolution.PokemonTarget(defender,listener.host()),
                new EffectTargetResolution.PokemonTarget(currentPlayer,attackerPokemonId)));
            automaticContext(entry).preflight(effect.effectProgram(),EffectTrigger.ON_DAMAGE);
        }
    }
    /** A healed/revived target must not inherit an earlier lethal hit's full-HP predicate. */
    private void recordAttackDamage(AttackDamageEvent damage) {
        attackCheckpoint.damage.add(damage);
        attackCheckpoint.damageCardListeners.put(damage,persistentListeners().stream()
            .filter(listener->listener.owner().equals(damage.owner())&&Objects.equals(listener.host(),damage.pokemonId()))
            .filter(listener->listener.effects().stream().anyMatch(effect->effect.eventPolicy() instanceof DamageTriggerPolicy))
            .toList());
        if(damage.amount()>0) {
            var source=attackCheckpoint.attacker;
            var type=!damage.owner().equals(source.owner())
                &&sameFieldEntry(source.owner(),source.pokemonId(),attackCheckpoint.attackerEntrySequence)
                ?currentPrimaryPokemonType(source.owner(),source.pokemonId()):null;
            recordReplay(damage.owner(),"公开招式伤害·"+damage.owner()+"·"+damage.pokemonId()+"·"+damage.amount()+"·"+(type==null?"":type.name()));
        }
        if(damage.amount()>0&&phase==MatchPhase.TURN&&!damage.owner().equals(currentPlayer)
            &&attackCheckpoint.attacker.owner().equals(currentPlayer))
            battlefield.recordOpponentAttackDamage(damage.owner(),damage.pokemonId(),turnNumber,damage.amount());
        var observers=new ArrayList<>(battlefield.benchView(damage.owner()));
        if(battlefield.hasActive(damage.owner()))observers.add(battlefield.activeView(damage.owner()));
        String name=battlefield.pokemonProfile(damage.owner(),damage.pokemonId()).pokemonName();
        for(var observer:observers)for(var ability:activeAbilities(damage.owner(),observer.pokemonId())) {
            if(!(ability.eventPolicy() instanceof DamageTriggerPolicy policy)||policy.watch()!=dev.hua.ptcglive.engine.effect.EventPokemonScope.OWN_FIELD
                ||!policy.watches(observer.pokemonId(),damage.pokemonId(),name)||!damageReactionMatches(policy,damage))continue;
            var source=abilitySource(damage.owner(),observer.pokemonId(),ability);
            var bindings=bindSourceEvent(damage.owner(),observer.pokemonId(),new EffectEventBindings(
                new EffectTargetResolution.PokemonTarget(damage.owner(),damage.pokemonId()),damage.entrySequence(),
                attackCheckpoint.attacker,attackCheckpoint.attackerEntrySequence).withAttackDamage(damage.amount()));
            attackCheckpoint.damageObservers.add(new QueuedAbility(UUID.randomUUID(),0,damage.owner(),observer.pokemonId(),ability,source,bindings));
        }
        if(damage.lethal()) {
            var ko=new Knockout(damage.owner(),damage.pokemonId());
            if(attackCheckpoint.attackDamageKnockouts.add(ko)) {
                if(damage.wasActive())attackCheckpoint.activeDamageKnockouts.add(ko);
                else attackCheckpoint.activeDamageKnockouts.remove(ko);
                if(damage.hadFullHp())attackCheckpoint.fullHpDamageKnockouts.add(ko);
                else attackCheckpoint.fullHpDamageKnockouts.remove(ko);
            }
        }
    }
    private boolean damageReactionMatches(DamageTriggerPolicy policy,AttackDamageEvent damage) {
        if(policy.opponentOnly()&&damage.owner().equals(attackCheckpoint.attacker.owner()))return false;
        if(!policy.matches(damage.wasActive(),damage.amount(),damage.lethal(),damage.hadFullHp()))return false;
        if(policy.requiresWeaknessToOpponentActive()
            && (damage.opponentActiveType()==null || currentWeaknessType(damage.owner(),damage.pokemonId())!=damage.opponentActiveType()))return false;
        if(!policy.attackerFamilies().isEmpty()&&(attackCheckpoint.damageSource==null||!policy.matchesAttacker(attackCheckpoint.damageSource.facts().card())))return false;
        if(policy.lethalOnly()) {
            if(policy.fullHpOnly()&&!attackCheckpoint.fullHpDamageKnockouts.contains(new Knockout(damage.owner(),damage.pokemonId())))return false;
            var target=battlefield.pokemonView(damage.owner(),damage.pokemonId());
            var ko=new Knockout(damage.owner(),damage.pokemonId());
            return target.damage()>=target.hitPoints()&&attackCheckpoint.attackDamageKnockouts.contains(ko)&&!attackCheckpoint.directKnockouts.contains(ko);
        }
        return true;
    }
    private void captureDamageReactions() {
        applyRetaliations();
        var candidates=new ArrayList<QueuedAbility>();
        // Discover live Abilities after all attack text (e.g. disabling effects) has resolved.
        for(var damage:attackCheckpoint.damage) {
          if(!sameFieldEntry(damage.owner(),damage.pokemonId(),damage.entrySequence()))continue;
          for(var ability:activeAbilities(damage.owner(),damage.pokemonId())) {
            if(!(ability.eventPolicy() instanceof DamageTriggerPolicy policy)||policy.watch()!=dev.hua.ptcglive.engine.effect.EventPokemonScope.SELF||!damageReactionMatches(policy,damage))continue;
            var source=abilitySource(damage.owner(),damage.pokemonId(),ability);
            if(effectLifecycle.usageLimited(source,EffectTrigger.ON_DAMAGE,turnNumber,policy.usage())||sharedUsageExhausted(damage.owner(),ability.usageLimit()))continue;
            candidates.add(new QueuedAbility(UUID.randomUUID(),0,damage.owner(),damage.pokemonId(),ability,source,
                bindSourceEvent(damage.owner(),damage.pokemonId(),new EffectEventBindings(new EffectTargetResolution.PokemonTarget(damage.owner(),damage.pokemonId()),damage.entrySequence(),
                    attackCheckpoint.attacker,attackCheckpoint.attackerEntrySequence).withAttackDamage(damage.amount()))));
        }
        }
        var liveCardListeners=persistentListeners();
        for(var damage:attackCheckpoint.damage)for(var listener:attackCheckpoint.damageCardListeners.getOrDefault(damage,List.of()))for(var effect:listener.effects()) {
            if(!(effect.eventPolicy() instanceof DamageTriggerPolicy policy)||!listener.owner().equals(damage.owner())
                ||!liveCardListeners.contains(listener)
                ||!Objects.equals(listener.host(),damage.pokemonId())||!sameFieldEntry(damage.owner(),damage.pokemonId(),damage.entrySequence())
                ||!damageReactionMatches(policy,damage))continue;
            var entry=persistentCandidate(listener,effect,new EffectEventBindings(new EffectTargetResolution.PokemonTarget(damage.owner(),damage.pokemonId()),damage.entrySequence(),
                attackCheckpoint.attacker,attackCheckpoint.attackerEntrySequence).withAttackDamage(damage.amount()));
            if(triggerUnused(entry))candidates.add(entry);
        }
        for(var entry:attackCheckpoint.damageObservers) {
            // Later text may remove/evolve/suppress an observer. New observers cannot inherit an earlier damage event.
            if(!sameFieldEntry(entry.owner(),entry.pokemonId(),entry.event().sourceEntrySequence())
                ||!activeAbilities(entry.owner(),entry.pokemonId()).contains(entry.ability())||!triggerUnused(entry))continue;
            candidates.add(entry);
        }
        // Damage reactions are part of attack resolution, before KOs and unrelated captured events.
        triggeredAbilities.addAll(0,capturedAbilities(candidates,++triggerEventBatch));
        attackCheckpoint.reactionsCaptured=true;
    }
    /**
     * “During your opponent's next turn, if this Pokémon is damaged by an attack (even if it is Knocked Out), put N damage
     * counters on the Attacking Pokémon.” Read after all attack text, with the other damage reactions; the damaged
     * Pokémon is still in play here even if this damage will Knock it Out. Knock Outs are checked with the attack's.
     */
    private void applyRetaliations() {
        var attacker=attackCheckpoint.attacker;
        for(var damage:attackCheckpoint.damage) {
            if(damage.amount()<=0||damage.owner().equals(attacker.owner())
                ||!sameFieldEntry(damage.owner(),damage.pokemonId(),damage.entrySequence()))continue;
            for(var effect:battlefield.retaliations(damage.owner(),damage.pokemonId(),attacker.owner())) {
                if(!sameFieldEntry(attacker.owner(),attacker.pokemonId(),attackCheckpoint.attackerEntrySequence))return;
                int counters=Math.min(60,effect.retaliationCounters(damage.amount()));
                if(counters<1)continue;
                var origin=new EffectOrigin(EffectOrigin.Kind.ATTACK,damage.owner(),damage.pokemonId());
                if(preventsDamageCounterPlacement(attacker.owner(),attacker.pokemonId(),origin)||preventsImpact(attacker.owner(),attacker.pokemonId(),origin,EffectProtection.Impact.OTHER_EFFECTS)) {
                    recordReplay(damage.owner(),"受击反伤被来源防护阻止；目标="+attacker.pokemonId());continue;
                }
                battlefield.placeDamageCounters(attacker.owner(),attacker.pokemonId(),counters);
                recordReplay(damage.owner(),"受击反伤：在攻击的宝可梦身上放置 "+counters+" 个伤害指示物");
            }
        }
    }
    private void finishAttackCheckpoint() {
        for(var card:attackCheckpoint.nitroEnergy)if(state(card.ownerId()).discard.remove(card))state(card.ownerId()).hand.add(card);
        reattachBoomerangEnergy();
        for(var target:attackCheckpoint.directKnockouts)battlefield.knockOutPokemonByEffect(target.owner(),target.pokemonId());
        var knocked=new ArrayList<Knockout>();
        for(UUID owner:players.keySet()) {
            var field=new ArrayList<>(battlefield.benchView(owner));if(battlefield.hasActive(owner))field.add(battlefield.activeView(owner));
            for(var pokemon:field)if(pokemon.damage()>=pokemon.hitPoints())knocked.add(new Knockout(owner,pokemon.pokemonId()));
        }
        var attackDamageKnockouts=attackCheckpoint.attackDamageKnockouts.stream().filter(ko->attackCheckpoint.damage.stream().anyMatch(d->
            d.owner().equals(ko.owner())&&d.pokemonId().equals(ko.pokemonId())&&sameFieldEntry(d.owner(),d.pokemonId(),d.entrySequence())))
            .collect(java.util.stream.Collectors.toUnmodifiableSet());
        var extraPrizes=new LinkedHashMap<Knockout,Integer>(attackCheckpoint.extraPrizes);extraPrizes.keySet().retainAll(attackDamageKnockouts);
        if(knocked.stream().anyMatch(ko->attackCheckpoint.extraTurnCounterKnockouts.containsKey(ko)
            &&sameFieldEntry(ko.owner(),ko.pokemonId(),attackCheckpoint.extraTurnCounterKnockouts.get(ko))))
            extraTurnPending=currentPlayer;
        var fullHpAttackDamage=attackDamageKnockouts.stream().filter(attackCheckpoint.fullHpDamageKnockouts::contains)
            .collect(java.util.stream.Collectors.toUnmodifiableSet());
        var activeAttackDamage=attackDamageKnockouts.stream().filter(attackCheckpoint.activeDamageKnockouts::contains)
            .collect(java.util.stream.Collectors.toUnmodifiableSet());
        var actualAttacker=attackCheckpoint.attacker;
        long actualAttackerEntry=attackCheckpoint.attackerEntrySequence;
        boolean attackerWasV=attackCheckpoint.damageSource!=null&&attackCheckpoint.damageSource.facts().card()
            .pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.V);
        var koProtection=attackCheckpoint.koProtection;
        historyKoSources.keySet().retainAll(knocked);
        attackCheckpoint=null;
        if(lastAttack!=null)lastAttack=new AttackResolution(lastAttack.attacker(),lastAttack.defender(),lastAttack.attackId(),
            lastAttack.baseDamage(),lastAttack.finalDamage(),lastAttack.selfDamage(),lastAttack.weaknessApplied(),lastAttack.resistanceApplied(),!knocked.isEmpty());
        recordReplay(currentPlayer,"完成攻击与受伤触发，统一检查击倒");
        if(!knocked.isEmpty())resolveKnockouts(knocked,false,true,attackDamageKnockouts,actualAttacker,actualAttackerEntry,extraPrizes,fullHpAttackDamage,activeAttackDamage,koProtection,attackerWasV);
        else {removeAttackKoProtection(koProtection);settleEmptyActives();}
    }
    private void reattachBoomerangEnergy() {
        if(attackCheckpoint.boomerangEnergy.isEmpty()||!sameFieldEntry(attackCheckpoint.attacker.owner(),attackCheckpoint.attacker.pokemonId(),attackCheckpoint.attackerEntrySequence))return;
        int attached=0;
        for(var card:List.copyOf(attackCheckpoint.boomerangEnergy)) {
            var discard=state(card.ownerId()).discard;
            if(discard.remove(card)) {
                battlefield.attachEnergyByEffect(attackCheckpoint.attacker.owner(),attackCheckpoint.attacker.pokemonId(),card);
                attached++;
            }
        }
        if(attached>0) {syncField(attackCheckpoint.attacker.owner());recordReplay(attackCheckpoint.attacker.owner(),"回旋能量在攻击结束后重新附着");}
    }

    /**
     * Resolves composable extra attack damage before Weakness/Resistance and
     * protection.  Only DamageEffect (plus its generic condition, coin and
     * repeat containers) is accepted here; other components need their own
     * declared timing and are rejected before the attack mutates the field.
     */
    private int countFilteredFieldPokemon(UUID actor,UUID source,EffectTarget target,Map<String,String> arguments) {
        dev.hua.ptcglive.engine.effect.PokemonCountEffect.validateNameCountTarget(target);
        var query=dev.hua.ptcglive.engine.effect.PokemonCountEffect.fieldQuery(arguments);
        if(query.names().isEmpty()&&query.families().families().isEmpty()&&query.nameContains()==null
            &&query.types().types().isEmpty()&&!arguments.containsKey("pokemon_stage")&&!arguments.containsKey("has_abilities"))
            throw new IllegalArgumentException("场上计数须提供名称、印刷家族、属性或阶段筛选");
        int count=0;
        UUID owner=(target==EffectTarget.OPPONENT_BENCH||target==EffectTarget.ALL_OPPONENT_POKEMON)?other(actor).id:actor;
        var field=new ArrayList<>(battlefield.printedBenchView(owner));
        if(target!=EffectTarget.OWN_BENCH&&target!=EffectTarget.OPPONENT_BENCH&&battlefield.hasActive(owner))field.add(battlefield.printedActiveView(owner));
        for(var pokemon:field) {
            if("true".equals(arguments.get("has_abilities"))&&!hasPossessedAbilities(owner,pokemon.pokemonId()))continue;
            if(arguments.containsKey("pokemon_stage")
                &&!matchesPokemonStage(arguments.get("pokemon_stage"),evolutionStageDepth(pokemon.topCardId())))continue;
            int counters=query.minimumDamageCounters()==0?0:battlefield.pokemonView(owner,pokemon.pokemonId()).damage()/10;
            if(query.matches(currentFieldDefinition(owner,pokemon.pokemonId()),battlefield.pokemonProfile(owner,pokemon.pokemonId()),0,0,counters,currentPokemonTypes(owner,pokemon.pokemonId())))count++;
        }
        return count;
    }
    private int fieldPokemonCount(UUID actor,UUID source,EffectDefinition effect) {
        var query=dev.hua.ptcglive.engine.effect.PokemonCountEffect.from(effect);
        var targets=resolveEffectTarget(actor,source,effect.target()).fixedTargets().stream().map(EffectTargetResolution.PokemonTarget.class::cast).toList();
        int count=0;var types=java.util.EnumSet.noneOf(EnergyType.class);
        for(var target:targets) {
            var profile=battlefield.pokemonProfile(target.owner(),target.pokemonId());
            var definition=currentFieldDefinition(target.owner(),target.pokemonId());
            int hp=query.maximumHpEquals()==0?0:battlefield.pokemonView(target.owner(),target.pokemonId()).hitPoints();
            int matchingEnergy=query.attachedEnergyType()==null?0:currentEnergyCount(target.owner(),target.pokemonId(),new dev.hua.ptcglive.engine.effect.EnergyCountQuery(query.attachedEnergyType(),dev.hua.ptcglive.engine.effect.EnergyCountQuery.Mode.UNITS));
            int counters=query.minimumDamageCounters()==0&&query.mode()!=dev.hua.ptcglive.engine.effect.PokemonCountEffect.Mode.DAMAGE_COUNTERS?0:battlefield.pokemonView(target.owner(),target.pokemonId()).damage()/10;
            if(effect.arguments().containsKey("pokemon_stage")&&!matchesPokemonStage(effect.arguments().get("pokemon_stage"),evolutionStageDepth(battlefield.topCard(target.owner(),target.pokemonId()).definitionId())))continue;
            if(effect.arguments().containsKey("has_abilities")&&!hasPossessedAbilities(target.owner(),target.pokemonId()))continue;
            if(!query.matches(definition,profile,hp,matchingEnergy,counters,currentPokemonTypes(target.owner(),target.pokemonId())))continue;
            count+=switch(query.mode()) {
                case DAMAGE_COUNTERS -> counters;
                case ATTACHED_TOOLS -> battlefield.pokemonView(target.owner(),target.pokemonId()).attachedTools().size();
                case ATTACHED_ENERGY_UNITS -> matchingEnergy;
                default -> 1;
            };types.addAll(currentPokemonTypes(target.owner(),target.pokemonId()));
        }
        return query.mode()==dev.hua.ptcglive.engine.effect.PokemonCountEffect.Mode.DISTINCT_TYPES?types.size():count;
    }
    private static boolean matchesPokemonStage(String filter,int depth) {
        return switch(filter) {
            case "BASIC","0" -> depth==0;
            case "EVOLUTION" -> depth>0;
            case "1" -> depth==1;
            case "2" -> depth==2;
            default -> false;
        };
    }
    private List<CardInstance> attackTailsDrawTools(UUID actor,UUID source) {
        if(source==null||!actor.equals(currentPlayer)||phase!=MatchPhase.TURN||!publicSourceOnField(actor,source)||toolEffectsDisabled(actor,source))return List.of();
        return battlefield.pokemonView(actor,source).attachedTools().stream()
            .filter(tool->combat.trainer(tool.definitionId()).map(p->dev.hua.ptcglive.engine.effect.AttackTailsDraw.fromProgram(p.ongoingProgram())).orElse(false)).toList();
    }
    private void registerAttackTails(UUID actor,UUID source,EffectExecutionContext.CoinResult result) {
        if(result.heads()==result.flips()||attackCheckpoint==null||!attackCheckpoint.attacker.owner().equals(actor)
            ||!attackCheckpoint.attacker.pokemonId().equals(source)||!sameFieldEntry(actor,source,attackCheckpoint.attackerEntrySequence))return;
        for(var tool:attackTailsDrawTools(actor,source))if(attackTailsDrawUsed.add(tool.instanceId())) {
            var delayed=new ScheduledPlayerEffect(UUID.randomUUID(),actor,turnNumber,
                new EffectOrigin(EffectOrigin.Kind.TRAINER,actor,tool.instanceId()),"打空保险：回合末抽3张",
                dev.hua.ptcglive.engine.effect.AttackTailsDraw.scheduledProgram());
            delayedPlayerEffects.put(delayed.token(),delayed);
            recordReplay(actor,"已触发打空保险，本回合结束时抽3张："+tool.definitionId());
        }
    }
    private CardInstance availableAttackCoinRetrySource(UUID actor,UUID source) {
        if(source==null||!actor.equals(currentPlayer)||phase!=MatchPhase.TURN||!publicSourceOnField(actor,source)
            ||Integer.valueOf(turnNumber).equals(attackCoinRetryUsed.get(actor)))return null;
        var host=battlefield.pokemonView(actor,source);
        var types=currentPokemonTypes(actor,source);var fallback=battlefield.pokemonProfile(actor,source).pokemonType();
        if(!toolEffectsDisabled(actor,source))for(var tool:host.attachedTools()) {
            var profile=combat.trainer(tool.definitionId()).orElse(null);if(profile==null)continue;
            var permission=dev.hua.ptcglive.engine.effect.AttackCoinRetry.fromProgram(profile.ongoingProgram());
            if(permission!=null&&(permission.pokemonType()==null||(types.isEmpty()?permission.pokemonType()==fallback:types.contains(permission.pokemonType()))))return tool;
        }
        // This Stadium grants a player an instruction; immunity to effects on Pokemon cannot prevent it.
        if(stadium!=null) {
            var permission=dev.hua.ptcglive.engine.effect.AttackCoinRetry.fromProgram(combat.trainer(stadium.definitionId()).orElseThrow().ongoingProgram());
            if(permission!=null)return stadium;
        }
        return null;
    }
    private CardInstance eligibleAttackCoinRetrySource(UUID actor,UUID source) {
        if(attackCheckpoint==null||attackCheckpoint.coinRetried||!attackCheckpoint.attacker.owner().equals(actor)
            ||!attackCheckpoint.attacker.pokemonId().equals(source)||!sameFieldEntry(actor,source,attackCheckpoint.attackerEntrySequence))return null;
        var tool=availableAttackCoinRetrySource(actor,source);
        if(tool!=null)dev.hua.ptcglive.engine.effect.AttackCoinRetry.requireSupportedPlan(attackCheckpoint.bodyAttack);
        return tool;
    }
    private void consumeAttackCoinRetry(UUID actor,UUID source) {
        var tool=eligibleAttackCoinRetrySource(actor,source);require(tool!=null,"重投授权或攻击来源已不可用");
        attackCoinRetryUsed.put(actor,turnNumber);attackCheckpoint.coinRetried=true;
        recordReplay(actor,(combat.trainer(tool.definitionId()).orElseThrow().category()==dev.hua.ptcglive.rules.TrainerCategory.STADIUM?"发动重投场地：":"发动重投道具：")+tool.definitionId()+"；本次攻击的原硬币结果作废");
    }
    private void beginAttackComputation(UUID actor,AttackDefinition attack,EffectTrigger phase,
            dev.hua.ptcglive.engine.effect.EffectContinuation cursor,Runnable completed) {
        require(pendingResolution==null&&pendingAttackComputation==null,"攻击硬币计算不能重入");
        UUID id=UUID.randomUUID();pendingAttackComputation=new PendingAttackComputation(id,completed);
        pendingResolution=new PendingResolution(id,actor,null,null,cursor,null,
            new MatchClientView.AttackResolution(attackCheckpoint.attacker.pokemonId(),attack.id(),attack.nameZh(),phase));
        resolvingEffectProgram=true;advancePendingResolution();
    }
    private void beginDamageCoinComputation(UUID actor,AttackDefinition attack,AttackDamageEffectContext context,
                                            List<EffectDefinition> effects,Runnable completed) {
        require(pendingResolution==null&&pendingAttackComputation==null&&pendingDamageCoins==null,"攻击伤害投币不能重入");
        var plan=dev.hua.ptcglive.engine.effect.PerTargetCoinDamage.contains(attack)
            ?new dev.hua.ptcglive.engine.effect.AttackDamageCoinPlan(effects,context)
            :new dev.hua.ptcglive.engine.effect.AttackDamageCoinPlan(attack,context);
        var attempt=new dev.hua.ptcglive.engine.effect.AttackCoinAttempt(plan);
        UUID id=UUID.randomUUID();pendingAttackComputation=new PendingAttackComputation(id,completed);
        pendingDamageCoins=new PendingDamageCoins(id,attempt,context);
        pendingResolution=new PendingResolution(id,actor,null,null,new dev.hua.ptcglive.engine.effect.EffectContinuation(
            new dev.hua.ptcglive.engine.effect.TriggeredEffects(EffectTrigger.ON_ATTACK,List.of(),effects),context),null,
            new MatchClientView.AttackResolution(attackCheckpoint.attacker.pokemonId(),attack.id(),attack.nameZh(),EffectTrigger.ON_ATTACK));
        resolvingEffectProgram=true;advancePendingDamageCoins();
    }
    private void advancePendingDamageCoins() {
        require(!advancingResolution&&pendingDamageCoins!=null,"攻击伤害投币不能重入或已完成");
        var pending=pendingDamageCoins;advancingResolution=true;
        try {pending.attempt().advance(eligibleAttackCoinRetrySource(pendingResolution.actor(),attackCheckpoint.attacker.pokemonId())!=null);}
        finally {advancingResolution=false;}
        if(!pending.attempt().complete())return;
        pending.context().preparedCoins=pending.attempt().claimResults();pendingDamageCoins=null;
        advancePendingResolution();
    }
    private void openNativeAttackCoin(UUID actor,AttackDefinition attack,EffectTrigger phase,String name,int flips,
                                     java.util.function.Consumer<EffectExecutionContext.CoinResult> completed) {
        var context=attackContinuationContext(actor,attackCheckpoint.attacker.pokemonId());
        var effect=new EffectDefinition("coin_flip",EffectTarget.SELF,Map.of("flips",Integer.toString(flips),"bind",name),List.of(),List.of());
        var binding=new dev.hua.ptcglive.engine.effect.TriggeredEffects(phase,List.of(),List.of(effect));
        beginAttackComputation(actor,attack,phase,new dev.hua.ptcglive.engine.effect.EffectContinuation(binding,context),()->completed.accept(context.namedCoinResult(name)));
    }
    private record ComputedAttackDamage(int damage,boolean ignoresResistance) { }
    private ComputedAttackDamage resolveAttackProgramDamage(UUID player, UUID attackerPokemonId, AttackDefinition attack, int initialDamage,
                                           PokemonCandidate primaryDamageTarget) {
        if (attack.effectProgram().forTrigger(EffectTrigger.ON_ATTACK).isEmpty()) return new ComputedAttackDamage(initialDamage,false);
        for (var binding : attack.effectProgram().forTrigger(EffectTrigger.ON_ATTACK))
            for (EffectDefinition effect : binding.effects()) preflightAttackDamageEffect(attack,effect);
        var context = new AttackDamageEffectContext(player, attackerPokemonId, attack.id(), initialDamage,attack.damageTarget(),primaryDamageTarget,attackCheckpoint.costAttack);
        new EffectInterpreter(context).execute(attack.effectProgram(), EffectTrigger.ON_ATTACK);
        return new ComputedAttackDamage(context.currentDamage,context.ignoresResistance);
    }
    /** Reject incomplete attack programs before confusion, printed coin flips or any other mutation. */
    private void preflightAttackProgram(UUID player, UUID attackerPokemonId, AttackDefinition attack, AttackDefinition costAttack,
                                        List<BattlefieldState.PokemonView> defenderViews, AttackPreselection preselection) {
        if(availableAttackCoinRetrySource(player,attackerPokemonId)!=null)dev.hua.ptcglive.engine.effect.AttackCoinRetry.requireSupportedPlan(attack);
        if (attack.effectProgram().triggers().isEmpty()) return;
        dev.hua.ptcglive.engine.effect.AttackProgramRules.validate(attack);
        var beforeDamage=dev.hua.ptcglive.engine.effect.AttackProgramRules.beforeDamage(attack);
        if(!beforeDamage.triggers().isEmpty()) {
            var context=attackContinuationContext(player,attackerPokemonId,preselection);context.costAttack=costAttack;
            context.preflight(beforeDamage,EffectTrigger.BEFORE_ATTACK);
        }
        var afterDamage = dev.hua.ptcglive.engine.effect.AttackProgramRules.afterDamage(attack);
        if (!afterDamage.triggers().isEmpty()) {
            var context=attackContinuationContext(player,attackerPokemonId);context.costAttack=costAttack;
            context.preflight(afterDamage,EffectTrigger.AFTER_ATTACK);
        }
        PokemonCandidate primaryDamageTarget=attack.damageTarget()!=AttackDefinition.DamageTarget.OPPONENT_ACTIVE&&!defenderViews.isEmpty()
            ?new PokemonCandidate(new EffectTargetResolution.PokemonTarget(fieldOwner(defenderViews.getFirst().pokemonId()),defenderViews.getFirst().pokemonId()),
                battlefield.pokemonEntrySequence(fieldOwner(defenderViews.getFirst().pokemonId()),defenderViews.getFirst().pokemonId()))
            :null;
        var context = new AttackDamageEffectContext(player, attackerPokemonId, attack.id(), 0,attack.damageTarget(),primaryDamageTarget,costAttack);
        dev.hua.ptcglive.engine.effect.EffectResolutionPreflight.validate(attack.effectProgram(), EffectTrigger.ON_ATTACK,
            condition -> {
                if(!dev.hua.ptcglive.engine.effect.PokemonSelectionScope.usesChosen(condition))ConditionEvaluator.matches(condition, context);
            }, effect -> {
                preflightAttackDamageEffect(attack,effect);
                // Bound facts do not exist until the server resolves the preceding selection.
                if(effect.target()==EffectTarget.CHOSEN_POKEMON)return;
                switch (effect.type()) {
                    case "damage_per_energy" -> context.count(effect, ConditionType.ENERGY_COUNT);
                    case "damage_per_damage_counter" -> context.count(effect, ConditionType.DAMAGE_COUNTER_COUNT);
                    case "damage_per_bench" -> context.count(effect, ConditionType.BENCH_COUNT);
                    case "damage_per_prize" -> context.prizeCount(effect);
                    case "damage_per_discard_card" -> discardCardCount(player,effect);
                    case "damage_per_hand_card" -> handCardCount(player, effect);
                    case "damage_per_pokemon" -> fieldPokemonCount(player,attackerPokemonId,effect);
                    case "damage_per_tails", "damage_per_special_condition" -> { }
                    case "damage_multiplier" -> {
                        if (effect.target() != EffectTarget.SELF
                            && (attack.damageTarget()!=AttackDefinition.DamageTarget.OPPONENT_ACTIVE||effect.target()!=EffectTarget.OPPONENT_ACTIVE))
                            throw new IllegalStateException("攻击倍率必须作用于本次攻击伤害");
                    }
                    default -> { }
                }
            }, false, true);
    }
    private ServerEffectExecutionContext attackContinuationContext(UUID actor, UUID source) {
        var context = new ServerEffectExecutionContext(actor,source);
        return prepareAttackContinuationContext(context,actor,source);
    }
    private ServerEffectExecutionContext attackContinuationContext(UUID actor, UUID source, AttackPreselection preselection) {
        var context = !preselection.present() ? new ServerEffectExecutionContext(actor,source)
            : new ServerEffectExecutionContext(actor,source,preselection.target(),List.of(preselection.pokemon()));
        return prepareAttackContinuationContext(context,actor,source);
    }
    private ServerEffectExecutionContext prepareAttackContinuationContext(ServerEffectExecutionContext context, UUID actor, UUID source) {
        context.resumable = true;
        context.origin = new EffectOrigin(EffectOrigin.Kind.ATTACK,actor,source);
        context.costAttack=attackCheckpoint==null?null:attackCheckpoint.costAttack;
        if(attackCheckpoint!=null)context.deckDiscardCause=new DeckDiscardCause(actor,
            dev.hua.ptcglive.engine.effect.DeckDiscardTriggerPolicy.SourceKind.POKEMON_ATTACK,source,
            attackCheckpoint.costAttack==null?"declared-attack":attackCheckpoint.costAttack.id(),attackCheckpoint.discardCauseToken);
        context.attackCoins=attackCoinMemory();
        context.pokemonBindings=attackPokemonMemory();
        return context;
    }
    private dev.hua.ptcglive.engine.effect.AttackCoinBindings.Memory attackCoinMemory() {
        // Read-only preflight gets a disposable empty memory; only a declared attack shares one.
        return attackCheckpoint==null?new dev.hua.ptcglive.engine.effect.AttackCoinBindings.Memory():attackCheckpoint.coins;
    }
    private Map<String,PokemonCandidate> attackPokemonMemory() {
        return attackCheckpoint==null?new LinkedHashMap<>():attackCheckpoint.pokemonBindings;
    }
    /** Read-only preflight sees an empty memory (every count 0); only a declared attack shares one. */
    private dev.hua.ptcglive.engine.effect.AttackCountBindings.Memory attackCountMemory() {
        return attackCheckpoint==null?new dev.hua.ptcglive.engine.effect.AttackCountBindings.Memory():attackCheckpoint.counts;
    }
    /** “You may … If you do …”: record how many cards an attack's cost step actually moved, when its data names a count. */
    private void recordAttackCount(EffectDefinition contract, int moved) {
        String name = contract.arguments().get("bind");
        if (name == null) return;
        require(attackCheckpoint != null, "攻击计数只能在服务器攻击结算中记录");
        attackCheckpoint.counts.put(name, moved);
        recordReplay(currentPlayer, "攻击计数绑定：" + name + "；数量=" + moved);
    }
    private void recordAttackCoin(UUID actor,String name,EffectExecutionContext.CoinResult result) {
        recordReplay(actor,"攻击硬币绑定："+name+"；次数="+result.flips()+"；正面="+result.heads());
    }
    private void preflightAttackDamageEffect(AttackDefinition attack,EffectDefinition effect) {
        dev.hua.ptcglive.engine.effect.AttackProgramRules.validateDamage(attack,effect);
    }
    private static int attackAmount(EffectDefinition effect, int minimum, int maximum, boolean requiresDamageUnits) {
        String raw = effect.arguments().get("amount");
        try {
            int amount = Integer.parseInt(raw);
            if (amount < minimum || amount > maximum || (requiresDamageUnits && amount % 10 != 0))
                throw new IllegalArgumentException("攻击 Effect 数值无效");
            return amount;
        } catch (NumberFormatException invalid) { throw new IllegalArgumentException("攻击 Effect 缺少有效 amount", invalid); }
    }
    private final class AttackDamageEffectContext implements EffectExecutionContext {
        private final dev.hua.ptcglive.engine.effect.AttackCoinBindings.Memory coins=attackCoinMemory();
        private final Map<String,PokemonCandidate> pokemonBindings=attackPokemonMemory();
        private AttackDamageEffectContext damageOwner=this;
        private PokemonCandidate chosenPokemon;
        private final AttackDefinition.DamageTarget damageTarget;
        private final PokemonCandidate primaryDamageTarget;
        private final UUID actor;
        private final UUID source;
        private final String attackId;
        private final AttackDefinition costAttack;
        private int currentDamage;
        private boolean ignoresResistance;
        private AttackDamageEffectContext(UUID actor, UUID source, String attackId, int initialDamage,
                                          AttackDefinition.DamageTarget damageTarget,PokemonCandidate primaryDamageTarget,AttackDefinition costAttack) {
            this.actor = actor; this.source = canonicalCapturedPokemon(actor,source); this.attackId = attackId; this.currentDamage = initialDamage;
            this.damageTarget=damageTarget;this.primaryDamageTarget=primaryDamageTarget;this.costAttack=costAttack;
        }
        private boolean resumableCoins;
        private dev.hua.ptcglive.engine.effect.AttackCoinResults preparedCoins;
        @Override public CoinResult preparedAttackCoin(EffectDefinition effect){return damageOwner.preparedCoins==null?null:damageOwner.preparedCoins.take(effect);}
        @Override public void coinResultCommitted(EffectDefinition effect,CoinResult result){registerAttackTails(actor,source,result);}
        @Override public boolean attackCoinRetryAvailable(EffectDefinition effect){return resumableCoins&&eligibleAttackCoinRetrySource(actor,source)!=null;}
        @Override public boolean canChooseNextCoinOutcome(EffectDefinition effect){return coinChoiceAvailable(actor);}
        @Override public void chooseNextCoinOutcome(EffectDefinition effect,boolean heads){selectCoinOutcome(actor,heads);}
        @Override public void consumeAttackCoinRetry(EffectDefinition effect){ServerMatch.this.consumeAttackCoinRetry(actor,source);}
        @Override public boolean supportsCoinBindings() {return true;}
        @Override public boolean supportsPokemonBindings() {return true;}
        @Override public EffectExecutionContext withNamedPokemon(String name) {
            var captured=pokemonBindings.get(dev.hua.ptcglive.engine.effect.AttackPokemonBindings.name(name));
            if(captured==null)return null;
            var child=new AttackDamageEffectContext(actor,source,attackId,0,damageTarget,primaryDamageTarget,costAttack);
            child.damageOwner=damageOwner;child.chosenPokemon=captured;return child;
        }
        @Override public EffectTargetResolution.PokemonTarget namedPokemonTarget(String name) {
            var captured=pokemonBindings.get(dev.hua.ptcglive.engine.effect.AttackPokemonBindings.name(name));
            return captured!=null&&sameFieldEntry(captured.target().owner(),captured.target().pokemonId(),captured.entrySequence())
                ?captured.target():null;
        }
        private boolean chosenStillPresent() {
            return chosenPokemon!=null&&sameFieldEntry(chosenPokemon.target().owner(),chosenPokemon.target().pokemonId(),chosenPokemon.entrySequence());
        }
        @Override public boolean conditionAvailable(ConditionDefinition condition) {
            return !dev.hua.ptcglive.engine.effect.PokemonSelectionScope.usesChosen(condition)||chosenStillPresent();
        }
        private ServerConditionContext conditionContext() {
            var context=new ServerConditionContext(actor,source);context.chosenPokemon=chosenPokemon==null?primaryDamageTarget:chosenPokemon;return context;
        }
        private EffectTarget effectiveTarget(EffectTarget target) {
            return damageTarget!=AttackDefinition.DamageTarget.OPPONENT_ACTIVE&&target==EffectTarget.OPPONENT_BENCH
                ?EffectTarget.CHOSEN_POKEMON:target;
        }
        @Override public CoinResult namedCoinResult(String name) {return coins.get(name);}
        @Override public void rememberCoinResult(String name,CoinResult result) {coins.put(name,result);recordAttackCoin(actor,name,result);}
        @Override public CoinResult flipCoins(EffectDefinition effect, int flips) {
            return flipCoins(effect, flips, "initial");
        }
        @Override public CoinResult flipCoins(EffectDefinition effect, int flips, String operation) {
            int heads = 0;
            for (int index = 0; index < flips; index++) if (flipEffectCoin(actor,"attack-effect-coin:" + attackId + ":" + operation + ":" + index)) heads++;
            recordReplay(actor, "攻击通用 Effect 掷硬币：" + operation);
            return new CoinResult(flips, heads);
        }
        @Override public int choose(EffectDefinition effect, int optionCount) {
            throw new IllegalStateException("攻击 ChoiceEffect 需要服务器选择事务，不能由客户端直接决定");
        }
        @Override public void executeAtomic(EffectDefinition effect) {
            if(effect.target()==EffectTarget.CHOSEN_POKEMON&&!chosenStillPresent())return;
            switch (effect.type()) {
                case "target_filter" -> dev.hua.ptcglive.engine.effect.AttackTargetFilter.validate(effect);
                case "damage" -> {
                    if (effect.target() != (damageTarget!=AttackDefinition.DamageTarget.OPPONENT_ACTIVE
                        ?EffectTarget.OPPONENT_BENCH:EffectTarget.OPPONENT_ACTIVE))
                        throw new IllegalStateException("攻击 DamageEffect 目标无效");
                    int amount=attackAmount(effect, 0, 1_000, true);
                    damageOwner.currentDamage="REPLACE".equals(effect.arguments().get("mode"))
                        ?amount:addDamage(damageOwner.currentDamage,amount);
                }
                case "damage_multiplier" -> damageOwner.currentDamage = multiplyDamage(damageOwner.currentDamage, attackAmount(effect, 0, 10, false));
                case "ignore_resistance" -> damageOwner.ignoresResistance=true;
                case "per_target_coin_damage" -> {
                    dev.hua.ptcglive.engine.effect.PerTargetCoinDamage.validate(effect);
                    require(primaryDamageTarget!=null&&attackCheckpoint!=null&&attackCheckpoint.perTargetCoinDamage!=null,
                        "逐目标伤害缺少本次攻击已确认的硬币结果");
                    Integer result=attackCheckpoint.perTargetCoinDamage.get(primaryDamageTarget.target().pokemonId());
                    require(result!=null,"受击宝可梦不在本次硬币目标快照");
                    damageOwner.currentDamage=addDamage(damageOwner.currentDamage,result);
                }
                case "damage_from_last_opponent_attack" -> {
                    dev.hua.ptcglive.engine.effect.PreviousAttackDamage.validate(effect);
                    damageOwner.currentDamage=addDamage(damageOwner.currentDamage,
                        battlefield.attackDamageReceivedInTurn(actor,source,other(actor).lastCompletedTurnNumber));
                }
                case "damage_per_energy" -> damageOwner.currentDamage = addDamage(damageOwner.currentDamage,
                    multiplyDamage(count(effect, ConditionType.ENERGY_COUNT), attackAmount(effect, 0, 1_000, true)));
                case "damage_per_damage_counter" -> damageOwner.currentDamage = addDamage(damageOwner.currentDamage,
                    multiplyDamage(count(effect, ConditionType.DAMAGE_COUNTER_COUNT), attackAmount(effect, 0, 1_000, true)));
                case "damage_per_bench" -> damageOwner.currentDamage = addDamage(damageOwner.currentDamage,
                    multiplyDamage(count(effect, ConditionType.BENCH_COUNT), attackAmount(effect, 0, 1_000, true)));
                case "damage_per_prize" -> damageOwner.currentDamage = addDamage(damageOwner.currentDamage,
                    multiplyDamage(prizeCount(effect), attackAmount(effect, 0, 1_000, true)));
                case "damage_per_pokemon" -> damageOwner.currentDamage = addDamage(damageOwner.currentDamage,
                    multiplyDamage(fieldPokemonCount(actor,source,effect),attackAmount(effect,10,1000,true)));
                case "damage_per_discard_card" -> damageOwner.currentDamage = addDamage(damageOwner.currentDamage,
                    multiplyDamage(discardCardCount(actor,effect),attackAmount(effect,10,1000,true)));
                case "damage_per_hand_card" -> damageOwner.currentDamage = addDamage(damageOwner.currentDamage,
                    multiplyDamage(handCardCount(actor, effect), attackAmount(effect, 10, 1_000, true)));
                // “… this attack does N more damage for each card you discarded in this way.”
                case "damage_per_bound" -> {
                    if (effect.target() != (damageTarget!=AttackDefinition.DamageTarget.OPPONENT_ACTIVE
                        ?EffectTarget.OPPONENT_BENCH:EffectTarget.OPPONENT_ACTIVE))
                        throw new IllegalStateException("按攻击计数追加的伤害目标无效");
                    damageOwner.currentDamage = addDamage(damageOwner.currentDamage,
                        multiplyDamage(boundCount(effect.arguments().get("bind")), attackAmount(effect, 10, 1_000, true)));
                }
                case "damage_per_tails" -> {
                    var result=namedCoinResult(effect.arguments().get("coin"));
                    require(result!=null,"按反面数量计伤缺少本次攻击的命名硬币结果");
                    damageOwner.currentDamage=addDamage(damageOwner.currentDamage,
                        multiplyDamage(result.flips()-result.heads(),attackAmount(effect,10,1_000,true)));
                }
                case "damage_per_special_condition" -> damageOwner.currentDamage=addDamage(damageOwner.currentDamage,
                    multiplyDamage(effect.target()==EffectTarget.SELF
                        ?battlefield.pokemonView(actor,attackCheckpoint.attacker.pokemonId()).conditions().size()
                        :battlefield.activeView(other(actor).id).conditions().size(),attackAmount(effect,10,1_000,true)));
                case "repeat_target_damage" -> {
                    dev.hua.ptcglive.engine.effect.RepeatTargetDamage.validate(attackCheckpoint.bodyAttack,effect);
                    require(primaryDamageTarget!=null,"重复选目标计伤缺少当前实际目标");
                    int count=attackCheckpoint.repeatedTargetCounts.getOrDefault(primaryDamageTarget.target().pokemonId(),0);
                    require(count>0,"重复选目标计伤缺少宣告次数");
                    damageOwner.currentDamage=addDamage(damageOwner.currentDamage,
                        multiplyDamage(count,attackAmount(effect,10,1_000,true)));
                }
                default -> throw new IllegalStateException("攻击伤害上下文收到未预检 Effect：" + effect.type());
            }
        }
        @Override public int number(ConditionType type, EffectTarget target, Map<String, String> arguments) {
            return conditionContext().number(type, effectiveTarget(target), arguments);
        }
        /** “If you have the same number of cards in your hand as your opponent, … more damage” is read while damage is computed. */
        @Override public int opponentNumber(ConditionType type, Map<String, String> arguments) {
            return conditionContext().opponentNumber(type, arguments);
        }
        @Override public boolean hasStatus(EffectTarget target, String status) {
            return conditionContext().hasStatus(effectiveTarget(target), status);
        }
        @Override public boolean flag(ConditionType type, EffectTarget target, Map<String, String> arguments) {
            return conditionContext().flag(type, effectiveTarget(target), arguments);
        }
        @Override public boolean hasExtraAttackEnergy(dev.hua.ptcglive.engine.effect.ExtraAttackEnergyRequirement requirement) {
            return extraAttackEnergy(actor,source,costAttack,requirement);
        }
        @Override public boolean coinResult(String expected) { return false; }
        @Override public int boundCount(String name) { var result=namedCoinResult(name);return result==null?attackCountMemory().get(name):result.heads(); }
        @Override public boolean customCondition(ConditionDefinition condition) {
            throw new IllegalStateException("Custom 条件尚未注册服务器处理器");
        }
        private int count(EffectDefinition effect, ConditionType type) {
            EffectTarget target=effectiveTarget(effect.target());
            if(target==EffectTarget.CHOSEN_POKEMON)return number(type,target,effect.arguments());
            if(type==ConditionType.ENERGY_COUNT) {
                return countEnergyOnFixedTargets(actor,source,target,dev.hua.ptcglive.engine.effect.EnergyCountQuery.from(effect.arguments()));
            }
            if(type==ConditionType.DAMAGE_COUNTER_COUNT)
                return countDamageCountersOnFixedTargets(actor,source,target,effect.arguments().get("pokemon_types"),effect.arguments().get("pokemon_names"));
            var resolved = resolveEffectTarget(actor, source, target);
            if (resolved.requiresSelection() || resolved.fixedTargets().size() != 1)
                throw new IllegalStateException("攻击计数伤害 Effect 需要恰好一个固定公开目标");
            return number(type, effect.target(), Map.of());
        }
        /** TAKEN is derived from the match's own setup snapshot, never a fixed six-card assumption. */
        private int prizeCount(EffectDefinition effect) {
            int remaining = count(effect, ConditionType.PRIZE_COUNT);
            var mode=dev.hua.ptcglive.engine.effect.PrizeCountEffect.mode(effect);
            if(mode==dev.hua.ptcglive.engine.effect.PrizeCountEffect.Mode.REMAINING)return remaining;
            EffectTarget target = effectiveTarget(effect.target());
            var resolved = resolveEffectTarget(actor, source, target);
            if (resolved.requiresSelection() || resolved.fixedTargets().size() != 1
                || !(resolved.fixedTargets().getFirst() instanceof EffectTargetResolution.PokemonTarget pokemon))
                throw new IllegalStateException("攻击奖赏计数 Effect 需要恰好一个固定公开宝可梦");
            if(mode==dev.hua.ptcglive.engine.effect.PrizeCountEffect.Mode.PREVIOUS_TURN_TAKEN)
                return state(pokemon.owner()).previousTurnPrizesTaken;
            int initial = state(pokemon.owner()).initialPrizeCards;
            if (initial < 0) throw new IllegalStateException("奖赏卡尚未由服务器完成设置");
            return Math.max(0, initial - remaining);
        }
        private static int addDamage(int current, int added) {
            try { return Math.addExact(current, added); }
            catch (ArithmeticException overflow) { throw new IllegalStateException("攻击伤害超过安全上限", overflow); }
        }
        private static int multiplyDamage(int current, int factor) {
            try { return Math.multiplyExact(current, factor); }
            catch (ArithmeticException overflow) { throw new IllegalStateException("攻击伤害超过安全上限", overflow); }
        }
    }

    /** Server-internal compatibility entry point. Clients select a face-down position, never a card identity. */
    public void takePrize(UUID player, UUID prizeInstanceId) {
        require(pendingNativeCoinChoice==null,"请先选择一树的投币结果");
        requireNoToolOverflow();
        requirePhase(MatchPhase.PRIZE_SELECTION);
        require(pendingPrizeClaimOrder==null,"须先选择此次击倒的奖赏结算顺序");
        require(pendingPrizeSearch==null&&pendingPrizeEnergy==null&&pendingPrizeItem==null&&pendingPrizeReactionOrder==null,"须先完成奖赏入手前效果");
        require(pendingLuckyBonus==null,"须先决定是否发动幸运奖励");
        require(prizeClaims.getFirst().player.equals(player), "当前不是你拿取奖赏卡");
        PlayerState p = state(player);
        CardInstance prize = p.prizes.stream().filter(card -> card.instanceId().equals(prizeInstanceId)).findFirst()
            .orElseThrow(() -> new IllegalArgumentException("指定卡牌不是你的奖赏卡"));
        boolean faceDown=!p.faceUpPrizeIds.contains(prize.instanceId());
        p.prizes.remove(prize);
        p.faceUpPrizeIds.remove(prize.instanceId());
        p.currentTurnPrizesTaken++;
        recordReplay(player, "拿取奖赏卡");
        PrizeClaim claim = prizeClaims.removeFirst();
        if (claim.remaining > 1 && !p.prizes.isEmpty()) prizeClaims.addFirst(new PrizeClaim(player, claim.remaining - 1,claim.discard(),true));
        if(claim.discard()) {
            moveCardToOwnerDiscard(prize);
            recordReplay(player,"滚滚浓烟：拿取的奖赏直接弃置 "+prize.definitionId());
            preparePrizeClaims();return;
        }
        if(prizeWindows.isEmpty()||prizeWindows.getFirst().ready)prizeWindows.addFirst(new PrizeWindow(player));
        prizeWindows.getFirst().cards.add(new TakenPrize(prize,faceDown));
        preparePrizeClaims();
    }
    public void takePrizeAt(UUID player, int position) {
        require(pendingNativeCoinChoice==null,"请先选择一树的投币结果");
        requireNoToolOverflow();
        requirePhase(MatchPhase.PRIZE_SELECTION);
        require(pendingPrizeSearch==null&&pendingPrizeEnergy==null&&pendingPrizeItem==null&&pendingLuckyBonus==null&&pendingPrizeReactionOrder==null,"须先完成奖赏入手前效果");
        require(prizeClaims.getFirst().player.equals(player), "当前不是你拿取奖赏卡");
        var prizes = state(player).prizes;
        if (position < 0 || position >= prizes.size()) throw new IllegalArgumentException("奖赏卡位置无效");
        takePrize(player, prizes.get(position).instanceId());
    }

    public boolean hasPendingLuckyBonus(UUID player) {return pendingNativeCoinChoice==null&&pendingLuckyBonus!=null&&pendingLuckyBonus.player().equals(player);}
    public void decideLuckyBonus(UUID player,boolean putOnBench) {
        require(pendingNativeCoinChoice==null,"请先选择一树的投币结果");
        requireNoToolOverflow();requirePhase(MatchPhase.PRIZE_SELECTION);
        var pending=pendingLuckyBonus;
        require(pending!=null&&pending.player().equals(player),"当前没有可决定的幸运奖励");
        var own=state(player);var prize=pending.prize();
        if(!putOnBench) {
            own.hand.add(prize);pendingLuckyBonus=null;recordReplay(player,"不发动幸运奖励，奖赏卡加入手牌");
            preparePrizeClaims();return;
        }
        require(own.bench.size()<benchLimit(player),"备战区已满，不能发动幸运奖励");
        require(hasLuckyBonus(prize)&&definition(prize).basicPokemon(),"该奖赏卡不再符合幸运奖励条件");
        battlefield.placeOnBench(player,prize);own.bench.add(prize);pendingLuckyBonus=null;
        long batch=capturePokemonChangeEvent(EffectTrigger.ON_ENTER_PLAY,player,prize.instanceId(),PokemonChangeTriggerPolicy.Source.PRIZE);
        var events=triggeredAbilities.stream().filter(e->e.batch()==batch).toList();
        triggeredAbilities.removeAll(events);
        var stadiumReaction=benchEntryStadiumReaction(player,prize,PokemonChangeTriggerPolicy.Source.PRIZE);
        Runnable entryReaction=()->resolvePrizeEffect(()->{triggeredAbilities.addAll(events);stadiumReaction.run();});
        if(pauseForCoinChoice(player,()->finishLuckyBonusCoin(player,prize,entryReaction)))return;
        finishLuckyBonusCoin(player,prize,entryReaction);
    }
    private void finishLuckyBonusCoin(UUID player,CardInstance prize,Runnable entryReaction) {
        var own=state(player);
        boolean heads=flipEffectCoin(player,"lucky-bonus:"+player+":"+prize.instanceId());
        recordReplay(player,"发动幸运奖励并将吉利蛋放到备战区；掷币结果："+(heads?"正面，追加1张奖赏":"反面"));
        if(heads&&!own.prizes.isEmpty()) {
            prizeClaims.addFirst(new PrizeClaim(player,1));
            var window=new PrizeWindow(player);window.completed=entryReaction;
            prizeWindows.addFirst(window);
            preparePrizeClaims();
        } else {
            entryReaction.run();
        }
    }
    private void preparePrizeClaims() {
        if(pendingNativeCoinChoice!=null)return;
        prizeClaims.removeIf(claim->state(claim.player()).prizes.isEmpty());
        pendingPrizeClaimOrder=null;
        if(pendingPrizeSearch!=null||pendingPrizeEnergy!=null||pendingPrizeItem!=null||pendingLuckyBonus!=null||pendingPrizeReactionOrder!=null)return;
        while(!prizeWindows.isEmpty()) {
            var window=prizeWindows.getFirst();
            if(!window.ready&&!prizeClaims.isEmpty()&&prizeClaims.getFirst().player().equals(window.owner))break;
            window.ready=true;
            // All Prizes in this award are selected before any face is shown or optional effect begins.
            // A final-Prize win still waits for the other simultaneous player's awards, but has no optional reactions.
            boolean gameEnding=players.values().stream().anyMatch(p->p.prizes.isEmpty());
            var ordinary=window.cards.stream().filter(p->gameEnding||!prizeReactionEligible(window.owner,p)).toList();
            ordinary.forEach(p->state(window.owner).hand.add(p.card()));window.cards.removeAll(ordinary);
            if(window.cards.isEmpty()){
                prizeWindows.removeFirst();
                // Finish the extra award before entry reactions/KO checks, preserving the parent award.
                if(window.completed!=null){window.completed.run();return;}
                continue;
            }
            if(window.cards.size()==1)beginPrizeReaction(window.owner,window.cards.removeFirst().card());
            else pendingPrizeReactionOrder=UUID.randomUUID();
            return;
        }
        if(prizeClaims.isEmpty()){finishPrizeClaims();return;}
        var first=prizeClaims.getFirst();
        if(first.selected())return;
        if(prizeClaims.stream().anyMatch(claim->claim.player().equals(first.player())&&claim.discard()!=first.discard()))
            pendingPrizeClaimOrder=UUID.randomUUID();
        else {prizeClaims.removeFirst();prizeClaims.addFirst(new PrizeClaim(first.player(),first.remaining(),first.discard(),true));}
    }
    private void beginPrizeReaction(UUID owner,CardInstance card) {
        if(treasureEnergy(card))pendingPrizeEnergy=new PendingPrizeEnergy(UUID.randomUUID(),owner,card,treasureHosts(owner,card));
        else if(greedyDice(card)||dreamBall(card))pendingPrizeItem=new PendingPrizeItem(UUID.randomUUID(),owner,card);
        else pendingLuckyBonus=new PendingLuckyBonus(owner,card);
    }
    private boolean treasureEnergy(CardInstance card) {
        // Printed off-field rule: attached Special Energy suppression does not remove this Prize permission.
        return combat.energyProfile(card.definitionId()).stream().flatMap(p->p.passiveProgram().forTrigger(EffectTrigger.PASSIVE).stream())
            .flatMap(b->b.effects().stream()).anyMatch(e->e.type().equals("prize_energy_attach"));
    }
    private List<PokemonCandidate> treasureHosts(UUID owner,CardInstance card) {
        return publicFieldTargets(owner).stream().filter(h->energyHostAllowed(card,owner,h.pokemonId())).map(h->energyCostHost(owner,h.pokemonId())).toList();
    }
    private boolean dreamBall(CardInstance card) {
        return combat.trainer(card.definitionId()).stream().anyMatch(p->p.effect().opcode()==dev.hua.ptcglive.rules.TrainerEffect.Opcode.PRIZE_SEARCH_POKEMON);
    }
    private boolean greedyDice(CardInstance card) {
        return combat.trainer(card.definitionId()).stream().anyMatch(profile->profile.effect().opcode()==dev.hua.ptcglive.rules.TrainerEffect.Opcode.PRIZE_COIN_EXTRA_PRIZE);
    }
    private boolean prizeReactionEligible(UUID owner,TakenPrize prize) {
        return prize.faceDown()&&owner.equals(currentPlayer)&&!resolvingCheckup
            &&(greedyDice(prize.card())||dreamBall(prize.card())&&!state(owner).deck.isEmpty()&&state(owner).bench.size()<benchLimit(owner)||treasureEnergy(prize.card())&&!treasureHosts(owner,prize.card()).isEmpty()||luckyPrizeEligible(owner,prize));
    }
    private boolean luckyPrizeEligible(UUID owner,TakenPrize prize) {
        return prize.faceDown()&&owner.equals(currentPlayer)&&!resolvingCheckup
            &&state(owner).bench.size()<benchLimit(owner)&&hasLuckyBonus(prize.card());
    }
    private boolean hasLuckyBonus(CardInstance card) {
        return combat.pokemon(card.definitionId()).stream().flatMap(profile->profile.abilities().stream())
            .anyMatch(ability->ability.effectSupport()==EffectSupport.SUPPORTED
                &&ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.PrizeTakenTriggerPolicy
                &&ability.effectProgram().triggers().stream().flatMap(trigger->trigger.effects().stream())
                    .anyMatch(effect->effect.type().equals("prize_pokemon_to_bench_coin_extra_prize")));
    }

    /** Selects the replacement Active Pokémon after a Knock Out. */
    public void chooseReplacement(UUID player, UUID benchPokemonId) {
        requireNoToolOverflow();
        requirePhase(MatchPhase.CHOOSE_REPLACEMENT);
        require(replacements.getFirst().equals(player), "当前尚未轮到你选择替补");
        var incoming=benchToActiveBefore(player,benchPokemonId);
        battlefield.promote(player, benchPokemonId);
        syncField(player); replacements.removeFirst();
        captureBenchToActiveEvent(incoming,0);
        recordReplay(player, "选择替补战斗宝可梦");
        if (replacements.isEmpty()) resumeAfterKnockouts();
    }
    public Map<UUID, PublicPlayerView> publicView() {
        Map<UUID, PublicPlayerView> view = new LinkedHashMap<>();
        players.forEach((id, p) -> view.put(id, new PublicPlayerView(id, p.hand.size(), p.deck.size(), p.prizes.size(), p.discard.size(), p.lostZone.size(),
            turnNumber == 0 || p.active == null ? null : p.active.definitionId(), p.bench.size()))); return Map.copyOf(view);
    }
    /** Server inspection/replay ONLY. Must never be serialized to any client, including the owner. */
    public PrivatePlayerView privateView(UUID player) {
        PlayerState p = state(player); return new PrivatePlayerView(player, List.copyOf(p.hand), List.copyOf(p.deck), List.copyOf(p.prizes), List.copyOf(p.discard), List.copyOf(p.lostZone));
    }
    private PlayerState prepare(UUID player, List<CardInstance> cards) {
        if (cards.size() != ruleset.matchSetupRules().deckSize())
            throw new IllegalArgumentException("开局卡组须符合规则包要求的 " + ruleset.matchSetupRules().deckSize() + " 张");
        PlayerState p = new PlayerState(player, cards); if (p.deck.stream().noneMatch(this::setupActiveAllowed)) throw new IllegalArgumentException("卡组没有可作为开局战斗位的宝可梦");
        return p;
    }
    private void dealOpeningHand(PlayerState p) {
        for (int i = 0; i < ruleset.matchSetupRules().openingHandSize(); i++) p.hand.add(drawFromDeck(p, "opening-draw"));
    }
    private boolean needsMulligan(PlayerState p) {
        return turnNumber == 0 && !p.openingReady && p.active == null && p.hand.size() == ruleset.matchSetupRules().openingHandSize()
            && p.hand.stream().noneMatch(this::setupActiveAllowed);
    }
    private void advanceOpening() {
        if (players.values().stream().allMatch(p -> p.openingReady)) {
            for (PlayerState p : players.values()) p.mulliganChoiceMade = mulliganDrawLimit(p.id) == 0;
            if (players.values().stream().allMatch(p -> p.mulliganChoiceMade)) finishOpening();
            else phase = MatchPhase.MULLIGAN_DRAW;
            return;
        }
        var failed = players.values().stream().filter(this::needsMulligan).toList();
        // A single failed player waits until the valid player's field AND Prizes are set.
        if (!failed.isEmpty() && players.values().stream().allMatch(p -> needsMulligan(p) || p.openingReady)) {
            currentMulliganReveals.clear();
            for (PlayerState p : players.values()) p.mulliganAcknowledged = false;
            for (PlayerState p : failed) {
                var reveal = new MatchClientView.MulliganReveal(p.id, ++p.mulligans,
                    p.hand.stream().map(CardInstance::definitionId).toList());
                currentMulliganReveals.add(reveal); mulliganHistory.add(reveal);
            }
            phase = MatchPhase.MULLIGAN_REVEAL;
        } else {
            phase = MatchPhase.OPENING_POKEMON;
        }
    }
    private void finishOpening() {
        for (PlayerState p : players.values()) p.bonusBasics.clear();
        currentMulliganReveals.clear(); phase = MatchPhase.TURN; turnNumber = 1; beginTurn();
    }
    private void beginTurn() {
        attackTailsDrawUsed.clear();
        PlayerState p = state(currentPlayer); p.coinTailsThisTurn=p.coinTailsNextTurn;p.coinTailsNextTurn=false; p.energyAttachments = 0; p.supportersPlayed = 0; p.turnSupporterLimit = -1; p.stadiumsPlayed = 0;p.attacksMadeThisTurn=0;p.lastAttackPokemonId=null;p.handAbilityUses.clear();
        p.pendingOwnTurnAttackEnergyMaximumLocks.forEach((kind,maximum)->p.attackEnergyMaximumLocks.merge(kind,maximum,Math::max));p.pendingOwnTurnAttackEnergyMaximumLocks.clear();
        p.previousTurnAttackers=Set.copyOf(p.currentTurnAttackers);p.currentTurnAttackers.clear();
        p.previousTurnAttackIds=Set.copyOf(p.currentTurnAttackIds);p.currentTurnAttackIds.clear();
        p.previousTurnNamedAttacks=Set.copyOf(p.currentTurnNamedAttacks);p.currentTurnNamedAttacks.clear();
        p.previousTurnSourceAttacks=Set.copyOf(p.currentTurnSourceAttacks);p.currentTurnSourceAttacks.clear();
        for(PlayerState owner:players.values()){owner.attackBonuses.removeIf(b->b.turn()!=turnNumber);owner.attackBypasses.removeIf(b->b.turn()!=turnNumber);owner.gxPermissions.removeIf(b->b.turn()!=turnNumber);}
        // Opposing player restrictions expire at that player's turn end, including consecutive turns.
        activateNoPrizeKos();
        updateDefenderPrizes(false);
        activateFullHpSurvivals();
        if (p.deck.isEmpty()) { finish(other(currentPlayer).id, MatchResult.Reason.DECK_OUT); return; }
        // The field's turn counter must advance before a drawn Emergency Entry
        // Pokemon is placed; otherwise it appears to have entered last turn.
        if (battlefield != null) battlefield.beginTurn(currentPlayer);
        var drawn=drawFromDeck(p,"turn-draw");
        if(!p.deck.isEmpty()&&combat.trainer(drawn.definitionId()).stream().anyMatch(profile->
            profile.effect().opcode()==dev.hua.ptcglive.rules.TrainerEffect.Opcode.DRAW_ON_TURN_DRAW)) {
            pendingDrawnTrainer=new PendingDrawnTrainer(UUID.randomUUID(),currentPlayer,drawn,turnNumber);
            return;
        }
        if(battlefield!=null && p.bench.size()<benchLimit(currentPlayer)
            &&combat.pokemon(drawn.definitionId()).stream().anyMatch(profile->
                profile.placementRule()==dev.hua.ptcglive.engine.field.PokemonPlacementRule.EMERGENCY_ENTRY)) {
            pendingEmergencyEntry=new PendingEmergencyEntry(currentPlayer,drawn,turnNumber);
            recordReplay(currentPlayer,"回合开始抽到紧急入场宝可梦，入手前等待上场选择");
            return;
        }
        p.hand.add(drawn);
        completeTurnDraw();
    }
    public boolean hasPendingTurnDraw() {return pendingEmergencyEntry!=null||pendingDrawnTrainer!=null;}
    public boolean hasPendingDrawnTrainer() {return pendingDrawnTrainer!=null;}
    public boolean hasPendingDrawnTrainer(UUID player) {return pendingDrawnTrainer!=null&&pendingDrawnTrainer.owner().equals(player);}
    public DrawnTrainerPrompt drawnTrainerPrompt(UUID player) {
        require(hasPendingDrawnTrainer(player),"你没有待决定的回合开始抽牌");
        return new DrawnTrainerPrompt(pendingDrawnTrainer.id(),pendingDrawnTrainer.card().definitionId());
    }
    public void decideDrawnTrainer(UUID player,UUID promptId,boolean use) {
        requirePhase(MatchPhase.TURN);
        var pending=pendingDrawnTrainer;
        require(pending!=null&&pending.id().equals(promptId)&&pending.owner().equals(player)
            &&currentPlayer.equals(player)&&pending.turn()==turnNumber,"回合开始抽牌选择已过期或不属于你");
        var own=state(player);var card=pending.card();
        if(use) {
            var profile=combat.trainer(card.definitionId()).orElseThrow();
            require(profile.effect().opcode()==dev.hua.ptcglive.rules.TrainerEffect.Opcode.DRAW_ON_TURN_DRAW&&!own.deck.isEmpty(),"此卡不满足入手前使用条件");
            // This card was never in hand: hand-only locks, coin gates and hand-play listeners do not apply.
            int count=drawEffect(own,profile.effect().amount());moveCardsToOwnerDiscard(List.of(card));
            recordReplay(player,"入手前使用金珠："+card.definitionId()+"，抽取"+count+"张牌");
        } else {
            own.hand.add(card);recordReplay(player,"将回合开始抽到的卡加入手牌");
        }
        pendingDrawnTrainer=null;completeTurnDraw();
    }
    public boolean hasPendingEmergencyEntry() {return pendingEmergencyEntry!=null;}
    public boolean hasPendingEmergencyEntry(UUID player) {
        return pendingEmergencyEntry!=null&&pendingEmergencyEntry.owner().equals(player);
    }
    public String emergencyEntryCardName(UUID player) {
        require(hasPendingEmergencyEntry(player),"当前没有可决定的紧急入场抽牌");
        return definition(pendingEmergencyEntry.card()).nameZh();
    }
    public void decideEmergencyEntry(UUID player,boolean putOnBench) {
        requirePhase(MatchPhase.TURN);
        var pending=pendingEmergencyEntry;
        require(pending!=null&&pending.owner().equals(player)&&currentPlayer.equals(player)
            &&pending.turn()==turnNumber,"紧急入场抽牌选择已过期或不属于你");
        var own=state(player);var drawn=pending.card();
        if(putOnBench) {
            require(own.bench.size()<benchLimit(player),"备战区已满，不能紧急入场");
            require(combat.pokemon(drawn.definitionId()).stream().anyMatch(profile->
                profile.placementRule()==dev.hua.ptcglive.engine.field.PokemonPlacementRule.EMERGENCY_ENTRY),
                "这张抽牌没有紧急入场规则");
            battlefield.placeOnBench(player,drawn);own.bench.add(drawn);
            pendingEmergencyEntry=null;
            capturePokemonChangeEvent(EffectTrigger.ON_ENTER_PLAY,player,drawn.instanceId(),
                PokemonChangeTriggerPolicy.Source.DECK);
            applyBenchEntryStadium(player,drawn,PokemonChangeTriggerPolicy.Source.DECK);
            int extra=drawEffect(own,3);
            recordReplay(player,"紧急入场放置宝可梦到备战区，再抽 "+extra+" 张牌");
        } else {
            own.hand.add(drawn);pendingEmergencyEntry=null;
            recordReplay(player,"放弃紧急入场，正常将回合开始抽到的卡加入手牌");
        }
        completeTurnDraw();
    }
    private void completeTurnDraw() {
        activateAttackKoProtections();
        if(!triggeredAbilities.isEmpty()) {
            emergencyEntryTurnStartPending=true;
            drainTriggeredAbilities();
        } else runTurnStart();
    }
    private void advanceTurn() {
        if (!toolTurnAdvancePending) {
            expireNoPrizeKos();
            updateDefenderPrizes(true);
            expireFullHpSurvivals();
            state(currentPlayer).trainerLocks.clear();state(currentPlayer).specialEnergyHandLocked=false;state(currentPlayer).trainerAttemptCoinGated=false;
            state(currentPlayer).nextCoinChoiceTurn=-1;state(currentPlayer).selectedCoinHeads=null;
            state(currentPlayer).attackEnergyMaximumLocks.clear();
            // Expire after the first opposing turn, including an extra turn; an extra own turn cannot consume it.
            other(currentPlayer).damageReductions.clear();other(currentPlayer).fieldAttackProtections.clear();
            if(battlefield!=null)battlefield.endTurn(currentPlayer);
        }
        if(toolOverflowPrompt()!=null){toolTurnAdvancePending=true;return;}
        var knocked=currentHitPointKnockouts();
        if(!knocked.isEmpty()) {
            // Expiry was already applied. Resume this boundary after prizes/replacements without applying it twice.
            toolTurnAdvancePending=true;
            resolveKnockouts(knocked,true);
            return;
        }
        toolTurnAdvancePending=false;
        state(currentPlayer).lastCompletedTurnNumber=turnNumber;
        var completed=state(currentPlayer);completed.previousTurnPrizesTaken=completed.currentTurnPrizesTaken;completed.currentTurnPrizesTaken=0;
        phase = MatchPhase.TURN; currentPlayer = currentPlayer.equals(extraTurnPending)?currentPlayer:other(currentPlayer).id; extraTurnPending=null; turnNumber++; beginTurn();
    }
    private void requireAttackEnergy(UUID player, UUID activePokemonId, AttackDefinition attack) {
        List<CardInstance> attached = battlefield.attachedEnergy(player, activePokemonId);
        List<dev.hua.ptcglive.engine.field.EnergyProfile> supplied = attached.stream().map(card ->
            currentEnergyProfile(player,activePokemonId,card)).toList();
        if (!dev.hua.ptcglive.engine.field.EnergyProfile.canPay(supplied, currentAttackCost(player, activePokemonId, attack)))
            throw new IllegalStateException("攻击费用不足或特殊能量无法满足所需类型");
    }
    /** Validate every public selected attachment before an attack can consume randomness or deal damage. */
    private void validatePostAttackEnergyDiscard(UUID player, AttackDefinition attack, List<UUID> energyInstanceIds) {
        validatePostAttackEnergyDiscard(player,battlefield.activeView(player).pokemonId(),attack,energyInstanceIds);
    }
    /** Public, current provision: a multi-unit card is still discarded as one indivisible card. */
    public Map<UUID,Integer> attackDiscardEnergyUnits(UUID player,UUID pokemonId) {
        var units=new LinkedHashMap<UUID,Integer>();
        for(var card:battlefield.attachedEnergy(player,pokemonId)) {
            int count=currentEnergyProfile(player,pokemonId,card).unitCount();
            if(count>0)units.put(card.instanceId(),count);
        }
        return java.util.Collections.unmodifiableMap(units);
    }
    private void validatePostAttackEnergyDiscard(UUID player,UUID attackerPokemonId,AttackDefinition attack,List<UUID> energyInstanceIds) {
        List<UUID> selected = List.copyOf(energyInstanceIds == null ? List.of() : energyInstanceIds);
        var units=attack.discardSelectedAttachedEnergyAfterAttack()>0?attackDiscardEnergyUnits(player,attackerPokemonId):Map.<UUID,Integer>of();
        // C-01: choose Energy units, not cards; carry out as much as possible after attacking.
        int required = Math.min(attack.discardSelectedAttachedEnergyAfterAttack(),units.values().stream().mapToInt(Integer::intValue).sum());
        if (required == 0) {
            if (!selected.isEmpty()) throw new IllegalArgumentException("此攻击不需要选择攻击后弃置的能量");
            return;
        }
        if (selected.size()>required) throw new IllegalArgumentException("所选卡牌超过此攻击要求弃置的能量个数");
        if (new java.util.LinkedHashSet<>(selected).size() != selected.size())
            throw new IllegalArgumentException("同一张附着能量不能重复选择");
        if (!units.keySet().containsAll(selected)) throw new IllegalArgumentException("选择的卡牌不是此宝可梦当前提供能量的附着卡");
        if (selected.stream().mapToInt(units::get).sum()<required)
            throw new IllegalArgumentException("所选卡牌提供的能量不足，须满足 " + required + " 个能量");
    }
    private void runTurnEnd() {
        if(battlefield==null){advanceTurn();return;}
        require(phase==MatchPhase.TURN&&!turnEndInProgress,"不能重复进入回合末");
        require(triggeredAbilities.isEmpty()&&triggerOrderPrompt==null&&pendingResolution==null,"先完成原卡效果再结束回合");
        var candidates=new ArrayList<QueuedAbility>();
        delayedPokemonEffects.values().removeIf(effect->!delayedStillApplied(effect));
        for(var delayed:delayedPlayerEffects.values())if(delayed.owner().equals(currentPlayer)&&delayed.dueTurn()==turnNumber) {
            var source=new EffectLifecycleDispatcher.Source(delayed.token(),delayed.id(),delayed.effectProgram());
            var entry=new QueuedAbility(UUID.randomUUID(),0,delayed.owner(),null,delayed,source,EffectEventBindings.NONE,delayed.origin(),0);
            automaticContext(entry).preflight(delayed.effectProgram(),EffectTrigger.ON_TURN_END);candidates.add(entry);
        }
        for(var delayed:delayedPokemonEffects.values())if(delayed.endingPlayer().equals(currentPlayer)&&delayed.dueTurn()<=turnNumber) {
            var event=new EffectEventBindings(delayed.target().target(),delayed.target().entrySequence(),null,0);
            var source=new EffectLifecycleDispatcher.Source(delayed.token(),delayed.id(),delayed.effectProgram());
            var entry=new QueuedAbility(UUID.randomUUID(),0,delayed.owner(),null,delayed,source,event,delayed.origin(),0);
            automaticContext(entry).preflight(delayed.effectProgram(),EffectTrigger.ON_TURN_END);candidates.add(entry);
        }
        // Validate and latch against the ending player's unchanged board before committing the phase.
        for(UUID owner:List.of(currentPlayer,other(currentPlayer).id)) {
            var field=new ArrayList<>(battlefield.benchView(owner));if(battlefield.hasActive(owner))field.add(battlefield.activeView(owner));
            for(var pokemon:field)for(var ability:activeAbilities(owner,pokemon.pokemonId())) {
                if(!ability.triggered()||!(ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.TurnEndTriggerPolicy policy)
                    ||!policy.matches(owner,currentPlayer))continue;
                require(ruleset.triggerTiming()==dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,"此规则包的回合末时序尚未接入");
                TriggeredAbilityRules.validate(ability);
                var entry=new QueuedAbility(UUID.randomUUID(),0,owner,pokemon.pokemonId(),ability,abilitySource(owner,pokemon.pokemonId(),ability),
                    bindSourceEvent(owner,pokemon.pokemonId(),EffectEventBindings.NONE));
                if(!triggerUnused(entry))continue;
                automaticContext(entry).preflight(ability.effectProgram(),EffectTrigger.ON_TURN_END);candidates.add(entry);
            }
        }
        for(var listener:persistentListeners())for(var effect:listener.effects()) {
            if(!(effect.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.TurnEndTriggerPolicy policy)||!policy.matches(listener.owner(),currentPlayer))continue;
            if(policy.sourceAttachedThisTurn()&&!battlefield.energyAttachedThisTurn(listener.owner(),listener.host(),listener.card().instanceId()))continue;
            var entry=persistentCandidate(listener,effect,EffectEventBindings.NONE);if(!triggerUnused(entry))continue;
            automaticContext(entry).preflight(effect.effectProgram(),EffectTrigger.ON_TURN_END);candidates.add(entry);
        }
        var captured=capturedAbilities(candidates,triggerEventBatch+1);
        triggerEventBatch++;triggeredAbilities.addAll(captured);turnEndInProgress=true;phase=MatchPhase.TURN_END;
        recordReplay(currentPlayer,"进入回合末结算；完成后进行回合间检查");
        drainTriggeredAbilities();
    }
    /**
     * Captures all start-of-turn triggers only after the normal draw is
     * complete.  No client may act while this queue or one of its continuations
     * is pending; the normal {@link #requireTurn(UUID)} gate already enforces
     * that invariant for every public intent.
     */
    private void runTurnStart() {
        if (battlefield == null) { settleHitPointChanges(); return; }
        require(phase == MatchPhase.TURN && !turnStartInProgress, "不能重复进入回合开始效果");
        require(triggeredAbilities.isEmpty() && triggerOrderPrompt == null && pendingResolution == null,
            "先完成上一事件的触发效果");
        var candidates = new ArrayList<QueuedAbility>();
        for (UUID owner : List.of(currentPlayer, other(currentPlayer).id)) {
            var field = new ArrayList<>(battlefield.benchView(owner));
            if (battlefield.hasActive(owner)) field.add(battlefield.activeView(owner));
            for (var pokemon : field) for (var ability : activeAbilities(owner, pokemon.pokemonId())) {
                if (!ability.triggered() || !(ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.TurnStartTriggerPolicy policy)
                    || !policy.matches(owner, currentPlayer)) continue;
                require(ruleset.triggerTiming() == dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,
                    "此规则包的回合开始触发时序尚未核验");
                TriggeredAbilityRules.validate(ability);
                var entry = new QueuedAbility(UUID.randomUUID(), 0, owner, pokemon.pokemonId(), ability,
                    abilitySource(owner, pokemon.pokemonId(), ability), bindSourceEvent(owner, pokemon.pokemonId(), EffectEventBindings.NONE));
                if (!triggerUnused(entry)) continue;
                automaticContext(entry).preflight(ability.effectProgram(), EffectTrigger.ON_TURN_START);
                candidates.add(entry);
            }
        }
        for (var listener : persistentListeners()) for (var effect : listener.effects()) {
            if (!(effect.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.TurnStartTriggerPolicy policy)
                || !policy.matches(listener.owner(), currentPlayer)) continue;
            var entry = persistentCandidate(listener, effect, EffectEventBindings.NONE);
            if (!triggerUnused(entry)) continue;
            automaticContext(entry).preflight(effect.effectProgram(), EffectTrigger.ON_TURN_START);
            candidates.add(entry);
        }
        triggerEventBatch++;
        triggeredAbilities.addAll(capturedAbilities(candidates, triggerEventBatch));
        turnStartInProgress = true;
        recordReplay(currentPlayer, "进入回合开始结算；普通行动将在全部触发效果完成后开放");
        drainTriggeredAbilities();
    }
    private void runCheckup() {
        state(currentPlayer).activeAbilitySuppression=null;
        for(var owner:players.values())if(owner.globalAbilitySuppression!=null&&owner.globalAbilitySuppression.endingPlayer().equals(currentPlayer))owner.globalAbilitySuppression=null;
        if(currentPlayer.equals(extraTurnPending)){recordReplay(currentPlayer,"获得额外回合，跳过宝可梦检查");advanceTurn();return;}
        if (battlefield == null) { advanceTurn(); return; }
        require(phase != MatchPhase.POKEMON_CHECKUP, "不能重复进入回合间检查");
        require(triggeredAbilities.isEmpty() && triggerOrderPrompt == null, "请先完成原卡触发效果");
        phase = MatchPhase.POKEMON_CHECKUP;
        var candidates = new ArrayList<QueuedAbility>();
        try {
            for (UUID owner : players.keySet()) {
                var field = new ArrayList<>(battlefield.benchView(owner));
                if (battlefield.hasActive(owner)) field.add(battlefield.activeView(owner));
                for (var pokemon : field) for (var ability : activeAbilities(owner,pokemon.pokemonId())) {
                    if (!ability.triggered() || ability.eventPolicy().trigger()!=EffectTrigger.ON_POKEMON_CHECKUP) continue;
                    require(ruleset.triggerTiming()==dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,"此规则包的回合间触发时序尚未核验");
                    TriggeredAbilityRules.validate(ability);
                    if(ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.CheckupTriggerPolicy checkup&&checkup.afterFailedSleepRecovery())continue;
                    var source = abilitySource(owner,pokemon.pokemonId(),ability);
                    if (effectLifecycle.usageLimited(source,EffectTrigger.ON_POKEMON_CHECKUP,turnNumber,ability.eventPolicy().usage())
                        || sharedUsageExhausted(owner,ability.usageLimit())) continue;
                    var context = automaticPreviewContext(owner,pokemon.pokemonId(),bindSourceEvent(owner,pokemon.pokemonId(),EffectEventBindings.NONE),ability.effectProgram());
                    context.preflight(ability.effectProgram(),EffectTrigger.ON_POKEMON_CHECKUP);
                    candidates.add(new QueuedAbility(UUID.randomUUID(),0,owner,pokemon.pokemonId(),ability,source,
                        bindSourceEvent(owner,pokemon.pokemonId(),EffectEventBindings.NONE)));
                }
            }
            for(var listener:persistentListeners())for(var effect:listener.effects()) {
                if(effect.eventPolicy().trigger()!=EffectTrigger.ON_POKEMON_CHECKUP)continue;
                var entry=persistentCandidate(listener,effect,EffectEventBindings.NONE);if(!triggerUnused(entry))continue;
                automaticContext(entry).preflight(effect.effectProgram(),EffectTrigger.ON_POKEMON_CHECKUP);candidates.add(entry);
            }
            captureTriggeredAbilities(candidates,++triggerEventBatch);
        } catch (RuntimeException invalid) { triggeredAbilities.clear(); phase=MatchPhase.TURN; throw invalid; }
        checkupStatusStep=UUID.randomUUID();
        recordReplay(other(currentPlayer).id,"进入回合间检查；下一回合玩家排列效果；全部完成后检查击倒");
        drainTriggeredAbilities();
    }
    private void resolveCheckupStatuses() {
        require(phase==MatchPhase.POKEMON_CHECKUP && checkupStatusStep!=null,"异常状态检查不存在或已结算");
        checkupStatusStep=null;
        var result=battlefield.pokemonCheckup(this::preventsCheckupRecovery,this::checkupPoisonBonus,this::sleepRecoveryCoins);
        twoCoinSleepEntries.entrySet().removeIf(entry->!battlefield.hasActive(entry.getKey())
            ||battlefield.pokemonEntrySequence(entry.getKey(),battlefield.activeView(entry.getKey()).pokemonId())!=entry.getValue()
            ||!battlefield.activeView(entry.getKey()).conditions().contains(SpecialCondition.ASLEEP));
        var candidates=new ArrayList<QueuedAbility>();
        for(var event:result.events()) {
            if(event.condition()!=SpecialCondition.ASLEEP||event.coin()!=CoinSide.TAILS)continue;
            UUID owner=event.player();
            if(!battlefield.hasActive(owner))continue;
            var pokemon=battlefield.activeView(owner);
            if(!pokemon.conditions().contains(SpecialCondition.ASLEEP))continue;
            for(var ability:activeAbilities(owner,pokemon.pokemonId())) {
                if(!ability.triggered()||!(ability.eventPolicy() instanceof dev.hua.ptcglive.engine.effect.CheckupTriggerPolicy policy)||!policy.afterFailedSleepRecovery())continue;
                TriggeredAbilityRules.validate(ability);
                var source=abilitySource(owner,pokemon.pokemonId(),ability);
                if(effectLifecycle.usageLimited(source,EffectTrigger.ON_POKEMON_CHECKUP,turnNumber,policy.usage())||sharedUsageExhausted(owner,ability.usageLimit()))continue;
                var bindings=bindSourceEvent(owner,pokemon.pokemonId(),EffectEventBindings.NONE);
                var context=automaticPreviewContext(owner,pokemon.pokemonId(),bindings,ability.effectProgram());
                context.preflight(ability.effectProgram(),EffectTrigger.ON_POKEMON_CHECKUP);
                candidates.add(new QueuedAbility(UUID.randomUUID(),0,owner,pokemon.pokemonId(),ability,source,bindings));
            }
        }
        // The failed recovery is latched after the indivisible status block; KOs still wait until Checkup ends.
        captureTriggeredAbilities(candidates,triggeredAbilities.isEmpty()?++triggerEventBatch:triggeredAbilities.getFirst().batch());
        recordReplay(other(currentPlayer).id,"回合间完成双方异常状态：中毒→灼伤→睡眠→麻痹",result.events());
    }
    private void finishCheckup() {
        require(checkupStatusStep==null && triggeredAbilities.isEmpty() && triggerOrderPrompt==null,"回合间尚有未结算效果");
        var knocked = new ArrayList<Knockout>();
        for (UUID owner : players.keySet()) {
            var field = new ArrayList<>(battlefield.benchView(owner));
            if (battlefield.hasActive(owner)) field.add(battlefield.activeView(owner));
            for (var pokemon : field) if(pokemon.damage()>=pokemon.hitPoints())knocked.add(new Knockout(owner,pokemon.pokemonId()));
        }
        recordReplay(other(currentPlayer).id,"回合间统一检查击倒");
        if (knocked.isEmpty()) advanceTurn(); else resolveKnockouts(knocked, true);
    }
    private void resolveKnockouts(List<Knockout> knockedPokemon, boolean checkup) {
        resolveKnockouts(knockedPokemon, checkup, false);
    }
    /** Abilities and Trainer effects do not end the turn merely because they caused a KO. */
    private void resolveEffectKnockouts(List<Knockout> knockedPokemon) {
        rememberHistoryKnockouts(knockedPokemon,historySource(effectOrigin(currentPlayer)));
        if (resolvingEffectProgram) {
            pendingEffectKnockouts.addAll(knockedPokemon);
            return;
        }
        boolean checkup = phase == MatchPhase.POKEMON_CHECKUP;
        resolveKnockouts(knockedPokemon, checkup, !checkup);
    }
    private void resolveKnockouts(List<Knockout> knockedPokemon, boolean checkup, boolean continueCurrentTurn) {
        resolveKnockouts(knockedPokemon,checkup,continueCurrentTurn,Set.of(),null,0);
    }
    private void resolveKnockouts(List<Knockout> knockedPokemon, boolean checkup, boolean continueCurrentTurn, Set<Knockout> attackDamage,EffectTargetResolution.PokemonTarget attacker,long attackerEntrySequence) {
        resolveKnockouts(knockedPokemon,checkup,continueCurrentTurn,attackDamage,attacker,attackerEntrySequence,Map.of());
    }
    private void resolveKnockouts(List<Knockout> knockedPokemon, boolean checkup, boolean continueCurrentTurn, Set<Knockout> attackDamage,EffectTargetResolution.PokemonTarget attacker,long attackerEntrySequence,Map<Knockout,Integer> extraPrizes) {
        resolveKnockouts(knockedPokemon,checkup,continueCurrentTurn,attackDamage,attacker,attackerEntrySequence,extraPrizes,Set.of(),Set.of());
    }
    private void resolveKnockouts(List<Knockout> knockedPokemon, boolean checkup, boolean continueCurrentTurn, Set<Knockout> attackDamage,EffectTargetResolution.PokemonTarget attacker,long attackerEntrySequence,Map<Knockout,Integer> extraPrizes,Set<Knockout> fullHpAttackDamage,Set<Knockout> activeAttackDamage) {
        resolveKnockouts(knockedPokemon,checkup,continueCurrentTurn,attackDamage,attacker,attackerEntrySequence,extraPrizes,fullHpAttackDamage,activeAttackDamage,null);
    }
    private void resolveKnockouts(List<Knockout> knockedPokemon, boolean checkup, boolean continueCurrentTurn, Set<Knockout> attackDamage,EffectTargetResolution.PokemonTarget attacker,long attackerEntrySequence,Map<Knockout,Integer> extraPrizes,Set<Knockout> fullHpAttackDamage,Set<Knockout> activeAttackDamage,PendingAttackKoProtection koProtection) {
        resolveKnockouts(knockedPokemon,checkup,continueCurrentTurn,attackDamage,attacker,attackerEntrySequence,
            extraPrizes,fullHpAttackDamage,activeAttackDamage,koProtection,false);
    }
    private void resolveKnockouts(List<Knockout> knockedPokemon, boolean checkup, boolean continueCurrentTurn, Set<Knockout> attackDamage,EffectTargetResolution.PokemonTarget attacker,long attackerEntrySequence,Map<Knockout,Integer> extraPrizes,Set<Knockout> fullHpAttackDamage,Set<Knockout> activeAttackDamage,PendingAttackKoProtection koProtection,boolean attackerWasV) {
        require(knockoutCheckpoint==null,"击倒结算不可递归开始");
        knockoutCheckpoint=new KnockoutCheckpoint(checkup,continueCurrentTurn,++triggerEventBatch,attackDamage,attacker,attackerEntrySequence,attackerWasV);
        if(!checkup&&attacker!=null)rememberHistoryKnockouts(knockedPokemon,historySource(new EffectOrigin(EffectOrigin.Kind.ATTACK,attacker.owner(),attacker.pokemonId())));
        knockoutCheckpoint.extraPrizes=Map.copyOf(extraPrizes);
        knockoutCheckpoint.fullHpAttackDamage=Set.copyOf(fullHpAttackDamage);
        knockoutCheckpoint.activeAttackDamage=Set.copyOf(activeAttackDamage);
        knockoutCheckpoint.koProtection=koProtection;
        captureKnockoutReactions(knockedPokemon);
        drainTriggeredAbilities();
    }
    /** Keep the complete public board until all KO-triggered effects (including newly caused KOs) resolve. */
    private void captureKnockoutReactions(List<Knockout> knockedPokemon) {
        var candidates=new ArrayList<QueuedAbility>();
        var listeners=new ArrayList<EffectTargetResolution.PokemonTarget>();
        for(UUID owner:players.keySet()) {
            if(battlefield.hasActive(owner))listeners.add(new EffectTargetResolution.PokemonTarget(owner,battlefield.activeView(owner).pokemonId()));
            for(var bench:battlefield.benchView(owner))listeners.add(new EffectTargetResolution.PokemonTarget(owner,bench.pokemonId()));
        }
        for(var knockout:knockedPokemon) {
            if(!knockoutCheckpoint.confirmed.add(knockout))continue;
            UUID subjectOwner=knockout.owner(),subject=knockout.pokemonId();
            // Confirm after complete attack text, before KO reactions such as Exp. Share move attached Energy.
            knockoutCheckpoint.printedAndPassivePrizes.put(knockout,prizeCardsForKnockout(subjectOwner,subject));
            if(stadium!=null&&combat.trainer(stadium.definitionId()).map(profile->programHasRule(profile.ongoingProgram(),"knockout_pokemon_to_lost_zone")).orElse(false)
                &&!preventsImpact(subjectOwner,subject,new EffectOrigin(EffectOrigin.Kind.TRAINER,stadiumController,stadium.instanceId()),EffectProtection.Impact.OTHER_EFFECTS))
                knockoutCheckpoint.lostCity.add(knockout);
            boolean attackDamage=knockoutCheckpoint.attackDamage.contains(knockout);
            if(attackDamage&&knockoutCheckpoint.attacker!=null&&!knockoutCheckpoint.attacker.owner().equals(subjectOwner)
                &&!toolEffectsDisabled(subjectOwner,subject)&&battlefield.printedPokemonView(subjectOwner,subject).attachedTools().stream()
                    .anyMatch(tool->programHasRule(combat.trainer(tool.definitionId()).orElseThrow().ongoingProgram(),"knockout_prizes_to_discard")))
                knockoutCheckpoint.prizesToDiscard.add(knockout);
            // Attack text can switch the damaged Pokemon before KO resolution (e.g. Push Down).
            boolean active=attackDamage?knockoutCheckpoint.activeAttackDamage.contains(knockout)
                :battlefield.hasActive(subjectOwner)&&battlefield.activeView(subjectOwner).pokemonId().equals(subject);
            // “If any of your Pokémon were Knocked Out by damage from an attack during your opponent's last turn, …”
            if(!knockoutCheckpoint.checkup && !subjectOwner.equals(currentPlayer)) {
                var subjectState=state(subjectOwner);
                if(subjectState.lastKnockedOutDuringOpponentTurn!=turnNumber) {
                    subjectState.lastKnockedOutNamesDuringOpponentTurn.clear();
                    subjectState.lastKnockedOutTypesDuringOpponentTurn.clear();
                }
                subjectState.lastKnockedOutTypesDuringOpponentTurn.addAll(currentPokemonTypes(subjectOwner,subject));
                var knockedName=battlefield.pokemonProfile(subjectOwner,subject).pokemonName();
                if(knockedName!=null)subjectState.lastKnockedOutNamesDuringOpponentTurn.add(knockedName);
                state(subjectOwner).lastKnockedOutDuringOpponentTurn=turnNumber;
                if(attackDamage) {
                    if(subjectState.lastKnockedOutByAttackTurn!=turnNumber) {subjectState.lastKnockedOutByAttackNames.clear();subjectState.lastKnockedOutByAttackTypes.clear();}
                    if(knockedName!=null)subjectState.lastKnockedOutByAttackNames.add(knockedName);
                    subjectState.lastKnockedOutByAttackTypes.addAll(currentPokemonTypes(subjectOwner,subject));
                    subjectState.lastKnockedOutByAttackTurn=turnNumber;
                }
            }
            var event=new EffectEventBindings(new EffectTargetResolution.PokemonTarget(subjectOwner,subject),battlefield.pokemonEntrySequence(subjectOwner,subject),
                attackDamage?knockoutCheckpoint.attacker:null,attackDamage?knockoutCheckpoint.attackerEntrySequence:0);
            for(var listener:listeners) for(var ability:activeAbilities(listener.owner(),listener.pokemonId())) {
                UUID owner=listener.owner(),pokemonId=listener.pokemonId();
                if(!(ability.eventPolicy() instanceof KnockoutTriggerPolicy policy)
                    || !policy.matches(owner,pokemonId,subjectOwner,subject,active,attackDamage,event.attackingPokemon(),knockoutCheckpoint.fullHpAttackDamage.contains(knockout)))continue;
                if(!knockoutCheckpoint.attackerWasV&&programHasRule(ability.effectProgram(),"prevent_prize_take"))continue;
                require(ruleset.triggerTiming()==dev.hua.ptcglive.rules.TriggerTiming.AFTER_CARD_ACTIVE_PLAYER_V1,"此规则包的击倒触发时序尚未核验");
                TriggeredAbilityRules.validate(ability);
                var source=abilitySource(owner,pokemonId,ability);
                if(effectLifecycle.usageLimited(source,EffectTrigger.ON_KNOCKOUT,turnNumber,policy.usage())||sharedUsageExhausted(owner,ability.usageLimit()))continue;
                var context=automaticPreviewContext(owner,pokemonId,event,ability.effectProgram());
                context.preflight(ability.effectProgram(),EffectTrigger.ON_KNOCKOUT);
                candidates.add(new QueuedAbility(UUID.randomUUID(),0,owner,pokemonId,ability,source,bindSourceEvent(owner,pokemonId,event)));
            }
            for(var listener:persistentListeners())for(var effect:listener.effects()) {
                if(!(effect.eventPolicy() instanceof KnockoutTriggerPolicy policy)
                    ||!policy.matches(listener.owner(),listener.host(),subjectOwner,subject,active,attackDamage,event.attackingPokemon(),knockoutCheckpoint.fullHpAttackDamage.contains(knockout)))continue;
                var entry=persistentCandidate(listener,effect,event);if(!triggerUnused(entry))continue;
                automaticContext(entry).preflight(effect.effectProgram(),EffectTrigger.ON_KNOCKOUT);candidates.add(entry);
            }
        }
        // All pending KO reactions share ordering, ahead of unrelated events captured by the original card.
        triggeredAbilities.addAll(0,capturedAbilities(candidates,knockoutCheckpoint.batch));
    }
    private Set<UUID> pokemonStackIds(UUID owner,UUID host) {
        var ids=new LinkedHashSet<UUID>();ids.add(battlefield.topCard(owner,host).instanceId());
        battlefield.previousEvolutionCards(owner,host).stream().map(CardInstance::instanceId).forEach(ids::add);
        return ids;
    }
    private Set<UUID> knockoutHandIds(KnockoutCheckpoint checkpoint,Knockout knockout) {
        UUID owner=knockout.owner(),host=knockout.pokemonId();var ids=new LinkedHashSet<UUID>();
        var top=checkpoint.topCardsToHand.get(knockout);
        // The legacy effect name refers to the Pokemon, including its lower evolution cards.
        if(top!=null&&sameFieldEntry(owner,host,top.entrySequence())&&battlefield.topCard(owner,host).instanceId().equals(top.cardId()))
            ids.addAll(pokemonStackIds(owner,host));
        var cards=checkpoint.cardsToHand.get(knockout);
        if(cards!=null&&sameFieldEntry(owner,host,cards.entrySequence()))ids.addAll(cards.cardIds());
        return ids;
    }
    private void commitKnockoutCheckpoint() {
        var checkpoint=knockoutCheckpoint;
        // Resolve competing replacements before any simultaneous KO moves cards or grants Prizes.
        for(var knockout:checkpoint.confirmed)if(!checkpoint.removed.contains(knockout)&&checkpoint.lostCity.contains(knockout)&&!checkpoint.disposalDecided.contains(knockout)) {
            var hand=knockoutHandIds(checkpoint,knockout);var pokemon=pokemonStackIds(knockout.owner(),knockout.pokemonId());
            if(pokemon.stream().anyMatch(hand::contains)) {
                pendingKnockoutDisposal=new KnockoutDisposalChoice(UUID.randomUUID(),knockout,definition(battlefield.topCard(knockout.owner(),knockout.pokemonId())).nameZh());
                return;
            }
        }
        resolvingCheckup = checkpoint.checkup;
        resumeCurrentTurnAfterReplacement = checkpoint.continueCurrentTurn;
        prizeClaims.clear(); replacements.clear();
        var awards=checkpoint.awards;
        var batch=checkpoint.confirmed.stream().filter(k->!checkpoint.removed.contains(k)).toList();
        // These Abilities apply to any cause of Knock Out. Finish every coin before committing awards or removals.
        for(var knockout:batch)for(var ability:activeAbilities(knockout.owner(),knockout.pokemonId())) {
            if(ability.kind()!=AbilityDefinition.Kind.PASSIVE||!ability.composed()||ability.effectSupport()!=EffectSupport.SUPPORTED)continue;
            var context=new ServerConditionContext(knockout.owner(),knockout.pokemonId());
            boolean all=dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),context,
                e->e.type().equals("coin_prize_reduction")&&"true".equals(e.arguments().get("all_prizes")));
            boolean reduce=battlefield.hasActive(knockout.owner())&&battlefield.printedActiveView(knockout.owner()).pokemonId().equals(knockout.pokemonId())
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),context,
                    e->e.type().equals("coin_prize_reduction")&&"true".equals(e.arguments().get("source_active_only")));
            if(!all&&!reduce)continue;
            var resolved=checkpoint.prizeCoinAbilitiesResolved.computeIfAbsent(knockout,k->new LinkedHashSet<>());
            if(resolved.contains(ability.id()))continue;
            if(pauseForCoinChoice(knockout.owner(),this::commitKnockoutCheckpoint))return;
            boolean heads=flipEffectCoin(knockout.owner(),"coin-prize-reduction:"+knockout.owner()+":"+knockout.pokemonId()+":"+turnNumber);
            resolved.add(ability.id());
            if(heads){if(all)checkpoint.blockedPrizes.add(knockout);else checkpoint.coinPrizeReductions.merge(knockout,1,Integer::sum);}
            recordReplay(knockout.owner(),ability.nameZh()+"掷硬币："+(heads?(all?"正面，不拿取此次昏厥的奖赏":"正面，少拿1张奖赏"):"反面"));
        }
        // Freeze every prize value before removing even one simultaneous source.
        for (Knockout knockout : batch) {
            int count=battlefield.pokemonProfile(knockout.owner(),knockout.pokemonId()).printedRules().preventsPrizeTake()
                ||noPrizeKoApplies(knockout)||checkpoint.blockedPrizes.contains(knockout)?0:Math.max(0,Math.min(6,checkpoint.printedAndPassivePrizes.get(knockout)
                +checkpoint.extraPrizes.getOrDefault(knockout,0)+turnExtraPrizeBonus(checkpoint,knockout)+defenderPrizeBonus(knockout,checkpoint.checkup)
                -checkpoint.coinPrizeReductions.getOrDefault(knockout,0)-prizeReductionAura(checkpoint,knockout)));
            awards.merge(other(knockout.owner()).id,count,Integer::sum);
            if(checkpoint.prizesToDiscard.contains(knockout))checkpoint.discardPrizeAwards.merge(other(knockout.owner()).id,count,Integer::sum);
        }
        var discardReturns=fieldDiscardReturnCards();
        for (Knockout knockout : batch) {
            UUID owner = knockout.owner();
            // KO is already confirmed; incidental healing during another KO reaction cannot revoke it.
            var handIds=knockoutHandIds(checkpoint,knockout);
            var lostIds=checkpoint.lostCity.contains(knockout)?pokemonStackIds(owner,knockout.pokemonId()):new LinkedHashSet<UUID>();
            if(checkpoint.lostCityFirst.contains(knockout))handIds.removeAll(lostIds);else lostIds.removeAll(handIds);
            battlefield.knockOutPokemonByEffect(owner,knockout.pokemonId());
            var removedCards=battlefield.takeKnockedOut(owner,knockout.pokemonId()).discardedCards();
            moveCardsToOwnerHand(removedCards.stream().filter(card->handIds.contains(card.instanceId())).toList());
            for(var card:removedCards)if(lostIds.contains(card.instanceId()))moveCardToOwnerLostZone(card);
            moveCardsToOwnerDiscard(removedCards.stream().filter(card->!handIds.contains(card.instanceId())&&!lostIds.contains(card.instanceId())).toList(),discardReturns);
            syncField(owner);
            checkpoint.removed.add(knockout);
            var historySource=historyKoSources.remove(knockout);
            if(historySource!=null)historyKnockouts.merge(historySource,1L,(a,b)->a==Long.MAX_VALUE?a:a+b);
            recordReplay(owner,"公开击倒·"+owner+"·"+knockout.pokemonId());
        }
        var cascade=currentHitPointKnockouts().stream().filter(k->!checkpoint.confirmed.contains(k)).toList();
        if(!cascade.isEmpty()) {
            recordReplay(currentPlayer,"HP 来源离场引发后续击倒；保留累计奖赏并检查触发");
            captureKnockoutReactions(cascade);
            return;
        }
        qualifyAttackKoProtection(checkpoint);
        knockoutCheckpoint=null;
        recordReplay(currentPlayer,"击倒触发全部完成；同时移场并结算奖赏");
        // An unambiguous no-Pokémon loss needs no Prize or replacement prompt.
        // Do not shortcut simultaneous wins: the eliminated player may still
        // earn their last Prize from the same batch (recoil, reactions, auras).
        // Those claims must settle before comparing both winning conditions.
        var eliminated = players.keySet().stream()
            .filter(player -> !battlefield.hasActive(player) && !battlefield.hasBench(player)).toList();
        if (eliminated.size() == 1) {
            UUID loser = eliminated.getFirst();
            boolean canTakeLastPrize = awards.getOrDefault(loser, 0) >= state(loser).prizes.size();
            if (!canTakeLastPrize) {
                finish(other(loser).id, MatchResult.Reason.NO_POKEMON);
                return;
            }
        }
        // The player whose turn comes next chooses first for simultaneous Knock Outs.
        for (UUID player : List.of(other(currentPlayer).id, currentPlayer)) {
            int discarded=checkpoint.discardPrizeAwards.getOrDefault(player,0);
            int normal=awards.getOrDefault(player,0)-discarded;
            if(normal>0)prizeClaims.addLast(new PrizeClaim(player,normal));
            if(discarded>0)prizeClaims.addLast(new PrizeClaim(player,discarded,true,false));
            if (!battlefield.hasActive(player) && battlefield.hasBench(player)) replacements.addLast(player);
        }
        if(!prizeEffectFrames.isEmpty())replacements.removeAll(prizeEffectFrames.getFirst().promotions);
        if (prizeClaims.isEmpty()) finishPrizeClaims(); else {phase = MatchPhase.PRIZE_SELECTION;preparePrizeClaims();}
    }
    private int prizeReductionAura(KnockoutCheckpoint checkpoint,Knockout knockout) {
        if(!checkpoint.attackDamage.contains(knockout)||checkpoint.attacker==null)return 0;
        var legacyLimit=new dev.hua.ptcglive.engine.effect.SharedUsageLimit("legacy-energy",dev.hua.ptcglive.engine.effect.SharedUsageLimit.Period.GAME);
        if(!sharedUsageExhausted(knockout.owner(),legacyLimit)&&battlefield.attachedEnergy(knockout.owner(),knockout.pokemonId()).stream()
            .anyMatch(card->"sv6_en_167".equals(card.definitionId()))) {
            consumeSharedUsage(knockout.owner(),legacyLimit);return 1;
        }
        for(var ability:activeAbilities(knockout.owner(),knockout.pokemonId()))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()&&ability.effectSupport()==EffectSupport.SUPPORTED) {
                var context=new ServerConditionContext(knockout.owner(),knockout.pokemonId());
                if(dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),context,
                    effect->effect.type().equals("prize_reduction_aura")&&effect.target()==EffectTarget.SELF))return 1;
            }
        if(!currentPokemonTypes(knockout.owner(),knockout.pokemonId()).contains(EnergyType.DARKNESS)
            ||!sameFieldEntry(checkpoint.attacker.owner(),checkpoint.attacker.pokemonId(),checkpoint.attackerEntrySequence)
            ||!fieldCardDefinition(battlefield.printedPokemonView(checkpoint.attacker.owner(),checkpoint.attacker.pokemonId()).topCardId())
                .pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.EX))return 0;
        for(var host:publicFieldTargets(knockout.owner()))for(var ability:activeAbilities(knockout.owner(),host.pokemonId()))
            if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()&&ability.effectSupport()==EffectSupport.SUPPORTED
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(knockout.owner(),host.pokemonId()),
                    effect->effect.type().equals("prize_reduction_aura")))return 1;
        return 0;
    }
    private int turnExtraPrizeBonus(KnockoutCheckpoint checkpoint,Knockout knockout) {
        if(!checkpoint.attackDamage.contains(knockout)||!checkpoint.activeAttackDamage.contains(knockout)||checkpoint.attacker==null
            ||checkpoint.attacker.owner().equals(knockout.owner())
            ||!sameFieldEntry(checkpoint.attacker.owner(),checkpoint.attacker.pokemonId(),checkpoint.attackerEntrySequence))return 0;
        var name=battlefield.pokemonProfile(checkpoint.attacker.owner(),checkpoint.attacker.pokemonId()).pokemonName();
        var definition=fieldCardDefinition(battlefield.printedPokemonView(checkpoint.attacker.owner(),checkpoint.attacker.pokemonId()).topCardId());
        var defender=fieldCardDefinition(battlefield.printedPokemonView(knockout.owner(),knockout.pokemonId()).topCardId());
        return state(checkpoint.attacker.owner()).extraPrizeBonuses.stream().filter(bonus->bonus.turn()==turnNumber
            &&(bonus.rule().attackerNameContains()==null||name!=null&&name.contains(bonus.rule().attackerNameContains()))
            &&bonus.rule().attackerFamilies().matches(definition)
            &&(!bonus.rule().attackerBasicOnly()||definition.basicPokemon())
            &&bonus.rule().defenderFamilies().matches(defender)).mapToInt(bonus->bonus.rule().amount()).sum();
    }
    /** Computes this Knock Out's Prize value from the current public top card before it leaves play. */
    private int prizeCardsForKnockout(UUID owner, UUID pokemonId) {
        int base = battlefield.pokemonProfile(owner, pokemonId).prizeCards();
        int modifier = passiveModifiers(owner,pokemonId).prizeCardsChange() + activeAbilities(owner, pokemonId).stream()
            .filter(ability -> ability.kind() == AbilityDefinition.Kind.PASSIVE && ability.effectSupport() == EffectSupport.SUPPORTED
                && ability.effect().opcode() == AbilityEffect.Opcode.PASSIVE_PRIZE_CARD_MODIFIER)
            .mapToInt(ability -> ability.effect().amount()).sum();
        // Fossil-item Pokémon may explicitly award zero Prizes; ordinary Pokémon data cannot use a zero base.
        // Clamp only after all bonuses/reductions are combined in the KO checkpoint.
        return base + modifier;
    }
    private void finishPrizeClaims() {
        if(effectPrizeResume!=null) {
            var resume=effectPrizeResume;var taking=resume.taking();
            if(state(taking.owner()).prizes.isEmpty()){finish(taking.owner(),MatchResult.Reason.PRIZES);return;}
            effectPrizeResume=null;pendingResolution=resume.resolution();phase=resume.phase();resolvingEffectProgram=resume.program();
            pendingResolution.continuation().pendingInteractionContext(EffectExecutionContext.InteractionKind.PRIZE_TAKE)
                .rememberCount(taking.effect().arguments().get("bind"),taking.taken());
            pendingResolution.continuation().completeInteraction(taking.step(),EffectExecutionContext.InteractionKind.PRIZE_TAKE);
            advancePendingResolution();return;
        }
        List<UUID> seats = List.copyOf(players.keySet());
        int a = winConditions(seats.get(0)), b = winConditions(seats.get(1));
        if (a > 0 || b > 0) {
            if (a == b) finish(null, MatchResult.Reason.DRAW);
            else {
                UUID winner = a > b ? seats.get(0) : seats.get(1);
                finish(winner, state(winner).prizes.isEmpty() ? MatchResult.Reason.PRIZES : MatchResult.Reason.NO_POKEMON);
            }
            return;
        }
        if (!replacements.isEmpty()) phase = MatchPhase.CHOOSE_REPLACEMENT;
        else resumeAfterKnockouts();
    }
    private int winConditions(UUID player) {
        UUID opponent = other(player).id;
        return (state(player).prizes.isEmpty() ? 1 : 0)
            + (!battlefield.hasActive(opponent) && !battlefield.hasBench(opponent) ? 1 : 0);
    }
    private void resumeAfterKnockouts() {
        // Promotion can itself remove Bench-only HP or change another live source condition.
        phase=resolvingCheckup?MatchPhase.POKEMON_CHECKUP:turnEndInProgress?MatchPhase.TURN_END:MatchPhase.TURN;
        // Latch before HP/Tool corrections can replace continueCurrentTurn with true.
        if(!resolvingCheckup&&!turnEndInProgress&&!resumeCurrentTurnAfterReplacement&&hasBenchToActiveOpportunity())
            endingPromotionTurn=true;
        if(endingPromotionTurn&&toolOverflowPrompt()!=null)return;
        var knocked=currentHitPointKnockouts();
        if(!knocked.isEmpty()) {
            resolveKnockouts(knocked,resolvingCheckup,resumeCurrentTurnAfterReplacement);
            return;
        }
        if (resumeCurrentTurnAfterReplacement || endingPromotionTurn) {
            resumeCurrentTurnAfterReplacement = false;
            phase = turnEndInProgress?MatchPhase.TURN_END:MatchPhase.TURN;
            drainTriggeredAbilities();
        } else if (resolvingCheckup) advanceTurn(); else runTurnEnd();
    }
    private void syncField(UUID player) {
        PlayerState p = state(player);
        p.active = battlefield.hasActive(player) ? battlefield.topCard(player, battlefield.activeView(player).pokemonId()) : null;
        p.bench.clear();
        for (var pokemon : battlefield.benchView(player)) p.bench.add(battlefield.topCard(player, pokemon.pokemonId()));
        refreshStadiumAbilityImmunity();
    }
    public void concede(UUID player) {
        state(player); require(phase != MatchPhase.FINISHED, "本局已经结束");
        recordReplay(player, "认输");
        finish(other(player).id, MatchResult.Reason.CONCESSION);
    }
    private void draw(PlayerState p, String operation) { p.hand.add(drawFromDeck(p, operation)); }
    private CardInstance drawFromDeck(PlayerState p, String operation) {
        if (p.deck.isEmpty()) throw new IllegalStateException("牌库已空，无法继续抽牌");
        CardInstance card = p.deck.remove(p.deck.size() - 1);
        recordReplay(p.id, "服务器抽牌：" + operation);
        return card;
    }
    private void shuffle(List<CardInstance> deck, String operation) {
        for (int i = deck.size() - 1; i > 0; i--) {
            int j = random.nextInt(operation, i + 1);
            CardInstance t = deck.get(i); deck.set(i, deck.get(j)); deck.set(j, t);
        }
        // A deck shuffle is public, but its operation label, order and card identities are not.
        for (var player:players.values()) if (player.deck==deck) {
            recordReplay(player.id,"公开洗牌");
            break;
        }
    }
    private void finish(UUID winner, MatchResult.Reason reason) {
        if(pendingPrizeSearch!=null){moveCardToOwnerDiscard(pendingPrizeSearch.card());pendingPrizeSearch=null;}
        if(pendingPrizeEnergy!=null){state(pendingPrizeEnergy.owner()).hand.add(pendingPrizeEnergy.card());pendingPrizeEnergy=null;}
        for(var frame:prizeEffectFrames) {
            for(var window:frame.windows)window.cards.forEach(p->state(window.owner).hand.add(p.card()));
            if(frame.effect!=null&&frame.effect.resolution().consumesHandCard())disposePlayedTrainers(frame.effect.resolution());
            if(frame.attack!=null)removeAttackKoProtection(frame.attack.koProtection);
        }
        prizeEffectFrames.clear();
        if(pendingQuiz!=null){state(pendingQuiz.owner()).hand.add(pendingQuiz.card());pendingQuiz=null;}
        if(pendingLuckyBonus!=null){state(pendingLuckyBonus.player()).hand.add(pendingLuckyBonus.prize());pendingLuckyBonus=null;}
        for(var window:prizeWindows)window.cards.forEach(p->state(window.owner).hand.add(p.card()));
        prizeWindows.clear();pendingPrizeReactionOrder=null;
        if(pendingPrizeItem!=null){state(pendingPrizeItem.owner()).hand.add(pendingPrizeItem.card());pendingPrizeItem=null;}
        if(effectPrizeResume!=null){pendingResolution=effectPrizeResume.resolution();effectPrizeResume=null;}
        if(attackCheckpoint!=null)removeAttackKoProtection(attackCheckpoint.koProtection);
        if(knockoutCheckpoint!=null)removeAttackKoProtection(knockoutCheckpoint.koProtection);
        for(var protection:List.copyOf(pendingAttackKoProtections.values()))removeAttackKoProtection(protection);
        for(var effect:List.copyOf(pendingNoPrizeKos.values()))removeNoPrizeKo(effect);
        for(var effect:List.copyOf(pendingFullHpSurvivals.values()))removeFullHpSurvival(effect);
        for(var delayed:List.copyOf(delayedPokemonEffects.values()))removeDelayedEffect(delayed);
        handEnergyCounterTraps.clear();handEnergyEndTurnTraps.clear();
        turnEndInProgress=false;
        pendingNativeCoinChoice=null;
        if(pendingDrawnTrainer!=null){state(pendingDrawnTrainer.owner()).hand.add(pendingDrawnTrainer.card());pendingDrawnTrainer=null;}
        pendingEmergencyEntry=null;emergencyEntryTurnStartPending=false;
        deferEmptyActiveSettlement=false;
        toolTurnAdvancePending=false;toolEffectCheckpointPending=false;
        toolDeferredKnockouts.clear();toolDeferredDirectKnockouts.clear();
        deckDiscardCheckpointPending=false;deckDiscardDeferredKnockouts.clear();deckDiscardDeferredDirectKnockouts.clear();
        delayedPlayerEffects.clear();
        pendingDefenderPrizes.clear();
        firstDepartureReplacement=null;
        result = new MatchResult(winner, reason); phase = MatchPhase.FINISHED;
        endingResumableAttack = false;
        endingResumableCardTurn = false;
        endingPromotionTurn = false;
        attackCheckpoint = null;pendingAttackComputation=null;pendingDamageCoins=null;attackCoinRetryUsed.clear();attackTailsDrawUsed.clear();extraTurnPending=null;pendingPrizeSwap=null;pendingPrizeTake=null;pendingPrizeInspect=null;pendingPrizeRandomSwap=null;pendingLuckyBonus=null;pendingTopDeckAttackCopy=null;pendingPrizeSlots.clear();
        endTurnAfterCardResolution = null;
        knockoutCheckpoint = null;pendingPrizeClaimOrder=null;prizeClaims.clear();pendingEnergyHandCost=null;pendingKnockoutDisposal=null;pendingRockPaperScissors=null;preparedBenchEnergy=null;pendingEnergyDeckSwap=null;pendingTopPrizeSwap=null;
        checkupStatusStep = null;
        triggeredAbilities.clear(); optionalTriggeredAbility = null; triggerOrderPrompt = null;
        pendingAllocation = null; allocatedCounters.clear(); pendingCounterMove=null;
        pendingPokemon = null;
        pendingDragonLauncher = null;
        if (pendingResolution != null) {
            if (pendingResolution.consumesHandCard()) disposePlayedTrainers(pendingResolution);
            pendingReveal = null; completingReveal = false; revealedDeckChoice=null;
            if(pendingOpponentDiscard!=null){pendingOpponentDiscard.transaction().invalidate();pendingOpponentDiscard=null;pendingZoneSelected.clear();}
            if (pendingZone != null) {
                pendingZone.transaction().invalidate(); effectSelections.remove(pendingResolution.actor());
                pendingZone = null; pendingZoneSelected.clear();
            }
            if(pendingCustomCards!=null) {
                pendingCustomCards.transaction().invalidate();effectSelections.remove(pendingResolution.actor());pendingCustomCards=null;pendingZoneSelected.clear();
            }
            if (pendingEnergyDistribution != null) {
                pendingEnergyDistribution = null;
                pendingEnergyDistributionTargets.clear();
            }
            if (pendingAttachedEnergy != null) {
                pendingAttachedEnergy.transaction().invalidate(); effectSelections.remove(pendingResolution.actor());
                pendingAttachedEnergy = null; pendingZoneSelected.clear();
            }
            if (pendingAttachedTool != null) {
                pendingAttachedTool.transaction().invalidate(); effectSelections.remove(pendingResolution.actor());
                pendingAttachedTool = null; pendingZoneSelected.clear();
            }
            if (pendingEnergyMoveTarget != null) pendingEnergyMoveTarget = null;
            pendingResolution = null; pendingAttachment = null;pendingTopEnergy=null;pendingDiscardedEnergy=null;pendingRandomHandSupporter=null;pendingCrispinTarget=null;pendingTymeCard=null;
            pendingTrainerBargainCard=null; completingAttachmentTarget = null;
            advancingResolution = false; clearEffectCheckpoint();
        }
        effectLifecycle.clearCompletedMatch();
        effectSelections.values().forEach(binding -> binding.transaction().invalidate());
        effectSelections.clear();
    }
    /** Attached cards retain their actual owner when an effect or Knock Out changes zones. */
    private boolean hasPrismStarRule(CardInstance card) {
        var printed=definition(card);
        return printed.pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.PRISM_STAR)
            ||printed.specialDeckLimits().containsKey("棱镜之星");
    }
    // Remember only successful field attachments. A recovered Gear is an ordinary card in hidden zones.
    private final Set<UUID> attachedFlareGear=new java.util.HashSet<>();
    private boolean redirectFlareGearDeparture(CardInstance card) {
        if(!attachedFlareGear.remove(card.instanceId()))return false;
        state(card.ownerId()).discard.add(card);return true;
    }
    private void moveCardToOwnerLostZone(CardInstance card) {
        var companion=takeStadiumCompanion(card);if(companion!=null)moveCardToOwnerLostZone(companion);
        if(!redirectFlareGearDeparture(card))state(card.ownerId()).lostZone.add(card);
    }
    private boolean toolHostAllowed(CardInstance card,dev.hua.ptcglive.rules.TrainerProfile profile,UUID owner,UUID pokemon) {
        return profile.opponentLegacyExTool()
            ?!card.ownerId().equals(owner)&&currentFieldDefinition(owner,pokemon).pokemonFamilies().contains(dev.hua.ptcglive.rules.PokemonFamily.EX_LEGACY)
            :card.ownerId().equals(owner);
    }
    private void moveCardToOwnerDiscard(CardInstance card) {
        var companion=takeStadiumCompanion(card);if(companion!=null)moveCardToOwnerDiscard(companion);
        attachedFlareGear.remove(card.instanceId());
        var owner=state(card.ownerId());
        // A printed Prism Star rule replaces every discard destination, including costs and Knock Outs.
        if(hasPrismStarRule(card))owner.lostZone.add(card);
        else owner.discard.add(card);
    }
    private void moveCardsToOwnerDiscard(List<CardInstance> cards) {
        for (CardInstance card : cards) moveCardToOwnerDiscard(card);
    }
    /** Capture before any simultaneous detach. Only enabled attached cards can replace their discard destination. */
    private Set<UUID> fieldDiscardReturnCards() {
        var result=new java.util.HashSet<UUID>();
        if(battlefield==null)return Set.of();
        for(UUID owner:players.keySet())for(var host:publicFieldTargets(owner)) {
            for(var tool:battlefield.printedPokemonView(owner,host.pokemonId()).attachedTools())
                if(programHasRule(combat.trainer(tool.definitionId()).orElseThrow().ongoingProgram(),"discard_from_field_to_hand")
                    &&!toolEffectsDisabled(owner,host.pokemonId()))result.add(tool.instanceId());
            for(var energy:battlefield.attachedEnergy(owner,host.pokemonId()))
                if(programHasRule(combat.energyProfile(energy.definitionId()).orElseThrow().passiveProgram(),"discard_from_field_to_hand")
                    &&programHasRule(currentEnergyProfile(owner,host.pokemonId(),energy).passiveProgram(),"discard_from_field_to_hand"))result.add(energy.instanceId());
        }
        return Set.copyOf(result);
    }
    private void moveCardsToOwnerDiscard(List<CardInstance> cards,Set<UUID> returnToHand) {
        for(var card:cards) {
            if(returnToHand.contains(card.instanceId()))state(card.ownerId()).hand.add(card);
            else moveCardToOwnerDiscard(card);
        }
    }
    private List<CardInstance> discardAttachedEnergyCards(UUID owner,UUID host,List<UUID> ids) {
        var returns=fieldDiscardReturnCards();
        var cards=battlefield.detachEnergy(owner,host,ids);moveCardsToOwnerDiscard(cards,returns);return cards;
    }
    private CardInstance discardAttachedToolCard(UUID owner,UUID host,UUID id) {
        var returns=fieldDiscardReturnCards();
        var card=battlefield.detachTool(owner,host,id);moveCardsToOwnerDiscard(List.of(card),returns);return card;
    }
    private void moveCardsToOwnerHand(List<CardInstance> cards) {
        for (CardInstance card : cards) if(!redirectFlareGearDeparture(card)) {
            var companion=takeStadiumCompanion(card);if(companion!=null)state(companion.ownerId()).hand.add(companion);
            state(card.ownerId()).hand.add(card);
        }
    }
    private void moveCardsToOwnerDeckAndShuffle(List<CardInstance> cards, String operationPrefix) {
        Map<UUID, List<CardInstance>> grouped = new LinkedHashMap<>();
        for (CardInstance card : cards) {
            var companion=takeStadiumCompanion(card);
            if(companion!=null)grouped.computeIfAbsent(companion.ownerId(),ignored->new ArrayList<>()).add(companion);
            if(!redirectFlareGearDeparture(card))grouped.computeIfAbsent(card.ownerId(), ignored -> new ArrayList<>()).add(card);
        }
        for (Map.Entry<UUID, List<CardInstance>> entry : grouped.entrySet()) {
            PlayerState owner = state(entry.getKey());
            owner.deck.addAll(entry.getValue());
            shuffle(owner.deck, operationPrefix + entry.getKey());
        }
    }
    private void recordReplay(UUID actor, String operation) {
        recordReplay(actor,operation,List.of());
    }
    private void recordReplay(UUID actor,String operation,List<BattlefieldState.CheckupEvent> checkup) {
        replayTranscript.add(new MatchReplayEvent(++replaySequence, actor, operation, random.transcript().size()));
        if(publicJournal!=null) {
            var transcript=random.transcript();
            var coins=PublicCoinResults.describe(transcript.subList(Math.min(publicRandomIndex,transcript.size()),transcript.size()));
            publicRandomIndex=transcript.size();
            publicJournal.observe(publicCheckpointView(),actor,operation,coins,id->cardDefinition(id).nameZh(),
                card->state(card.ownerId()).hand.contains(card),checkup);
        }
    }
    private BattleEventJournal publicJournal;
    private int publicRandomIndex;
    /** Mid-resolution checkpoints must not inspect a choice queue which is being advanced. */
    private MatchClientView publicCheckpointView() {
        return new MatchClientView(id,null,phase,turnNumber,currentPlayer,null,result,clientPlayers(null),List.of(),List.of(),
            List.of(),List.of(),stadium,publicResolvingTrainer(),null,null,null,null,null,
            publicResolvingAbility(),publicResolvingAttack(),null,
            publicResolvingTrainers(),stadiumCompanion);
    }
    public void enablePublicEvents() {
        if(publicJournal!=null)return;
        publicJournal=new BattleEventJournal();publicRandomIndex=random.transcript().size();
        publicJournal.observe(publicCheckpointView(),currentPlayer,"",List.of(),id->cardDefinition(id).nameZh());
    }
    public List<BattleEventJournal.Event> publicEvents(){return publicJournal==null?List.of():publicJournal.events();}
    public void checkpointPublicEvents(){if(publicJournal!=null)publicJournal.observe(publicCheckpointView(),currentPlayer,"",List.of(),id->cardDefinition(id).nameZh(),
        card->state(card.ownerId()).hand.contains(card));}

    /** Same validation as retreat, before any coin or cost is consumed. */
    public String retreatProblem(UUID player,UUID replacement,List<UUID> paid) {
        try {
            validateRetreat(player,replacement,paid);
            return "";
        } catch(IllegalArgumentException|IllegalStateException e){return e.getMessage();}
    }

    public BattleGuidance battleGuidance(UUID viewer,List<MatchSession.Option> options) {
        var field=new LinkedHashMap<String,List<String>>();
        if(stadium!=null&&stadiumFirstSide!=null) {
            var profile=combat.trainer(stadium.definitionId()).orElseThrow();var sides=new ArrayList<String>();int seat=0;
            for(UUID owner:players.keySet()) {seat++;sides.add((viewer==null?"席位"+seat:owner.equals(viewer)?"我方":"对方")+"："+profile.stadiumSideLabel(owner.equals(stadiumFirstSide)));}
            field.put("stadium:"+stadium.instanceId(),List.copyOf(sides));
        }
        if(battlefield!=null&&turnNumber>0)for(var p:clientPlayers(null))for(var ability:abilityOptions(p.id()))
            field.computeIfAbsent("field:"+ability.pokemonId(),k->new ArrayList<>()).add(ability.ability().nameZh()+
                (ability.ability().kind()==AbilityDefinition.Kind.ACTIVATED_UNLIMITED?"：不限次数":ability.usedThisTurn()?"：次数已使用":"：次数尚未使用"));
        if(viewer==null)return new BattleGuidance(List.of(),Map.of(),Map.copyOf(field),List.of());
        var p=state(viewer);var limits=ruleset.turnActionRules();
        if(battlefield!=null&&battlefield.hasActive(viewer)&&viewer.equals(currentPlayer)&&phase==MatchPhase.TURN) {
            var active=battlefield.activeView(viewer);var payment=suggestedRetreatPayment(viewer);
            String retreat=payment.isEmpty()?"撤退：目前无合法能量支付组合":battlefield.benchView(viewer).isEmpty()?"撤退：没有备战宝可梦":
                retreatProblem(viewer,battlefield.benchView(viewer).getFirst().pokemonId(),payment.get());
            if(!retreat.isEmpty())field.computeIfAbsent("field:"+active.pokemonId(),k->new ArrayList<>()).add(retreat);
        }
        var usage=viewer.equals(currentPlayer)?List.of("手动附能 "+p.energyAttachments+"/"+limits.energyAttachmentsFromHand(),
            "支援者 "+p.supportersPlayed+"/"+supporterLimit(viewer),"常规撤退 "+(retreated()?"次数已用完":"尚有次数"),
            "场地 "+p.stadiumsPlayed+"/"+limits.stadiums()):List.<String>of();
        var blocked=new LinkedHashMap<String,String>();
        for(var card:clientView(viewer).hand()) {
            String key="hand:"+card.instanceId();
            if(options.stream().anyMatch(o->o.enabled()&&o.cardKeys().contains(key)))continue;
            String reason="当前没有合法动作或目标，请完成当前步骤。";
            if(!viewer.equals(currentPlayer))reason="现在不是你的回合。";
            else if(definition(card).category()==dev.hua.ptcglive.rules.CardCategory.ENERGY&&energyAttached(viewer))reason="当前规则允许的手动附能次数已用完。";
            else if(definition(card).category()==dev.hua.ptcglive.rules.CardCategory.TRAINER&&trainerPlayLocked(viewer,card.definitionId()))reason="当前效果禁止使用此类训练家。";
            else if(definition(card).basicPokemon()&&p.bench.size()>=benchLimit(viewer))reason="当前效果决定的备战区容量已满。";
            else if(definition(card).category()==dev.hua.ptcglive.rules.CardCategory.POKEMON)reason="没有满足当前进化时机、名称与效果限制的对象。";
            blocked.put(key,reason);
        }
        return new BattleGuidance(usage,Map.copyOf(blocked),Map.copyOf(field),attackPreviews(viewer));
    }

    /** Conservative coverage: rich/conditional boards deliberately get no exact number. */
    private List<BattleGuidance.AttackPreview> attackPreviews(UUID player) {
        if(turnNumber==0||battlefield==null||!battlefield.hasActive(player)||!battlefield.hasActive(other(player).id))return List.of();
        var source=battlefield.activeView(player);var target=battlefield.activeView(other(player).id);
        var defender=battlefield.activeProfile(other(player).id);var output=new ArrayList<BattleGuidance.AttackPreview>();
        boolean simple=stadium==null && players.values().stream().allMatch(p->p.attackBonuses.isEmpty()&&p.attackBypasses.isEmpty()&&p.damageReductions.isEmpty()&&p.fieldAttackProtections.isEmpty()
            &&p.discard.stream().noneMatch(c->combat.pokemon(c.definitionId()).map(profile->!profile.abilities().isEmpty()).orElse(false)));
        for(var p:clientView(null).players()) {
            var mons=new ArrayList<BattlefieldState.PokemonView>(p.bench());if(p.active()!=null)mons.add(p.active());
            for(var mon:mons) simple &= battlefield.pokemonProfile(p.id(),mon.pokemonId()).abilities().isEmpty()
                &&mon.attachedTools().isEmpty()&&mon.continuousEffectZh().isBlank()
                &&mon.attachedEnergyCardIds().stream().allMatch(id->cardDefinition(id).basicEnergy());
        }
        for(var attack:battlefield.activeProfile(player).attacks()) {
            boolean payable=canPayAttackCost(player,source.pokemonId(),attack);
            String cost=currentAttackCost(player,source.pokemonId(),attack).entrySet().stream().map(e->e.getKey()+"×"+e.getValue()).collect(java.util.stream.Collectors.joining(" / "));
            // Default equality also excludes newly added native attack fields until explicitly reviewed.
            boolean exact=simple&&source.conditions().isEmpty()&&attack.equals(new AttackDefinition(attack.id(),attack.nameZh(),
                attack.energyCost(),attack.baseDamage(),attack.damageType(),dev.hua.ptcglive.rules.EffectSupport.SUPPORTED,null));
            Integer damage=null;String explanation="随机、后续选择或场上效果可能影响结果；不显示精确伤害。";
            if(exact) {
                int d=attack.baseDamage();String formula="基础 "+d;
                boolean wr=!attack.ignoresWeaknessAndResistance();
                var types=attackDamageTypes(player,source.pokemonId(),attack);
                if(d>0&&wr&&!attack.ignoresWeakness()&&defender.weaknessType()!=null&&types.contains(defender.weaknessType())) {d=dev.hua.ptcglive.engine.field.DamageArithmetic.weakness(d,defender.weaknessMultiplier());formula+="，弱点 ×"+defender.weaknessMultiplier();}
                if(d>0&&wr&&!attack.ignoresResistance()&&!stadiumHasPassiveRule("no_resistance")&&defender.resistanceType()!=null&&types.contains(defender.resistanceType())){d=dev.hua.ptcglive.engine.field.DamageArithmetic.resistance(d,defender.resistanceAmount());formula+="，抗性 −"+defender.resistanceAmount();}
                damage=Math.max(0,d);explanation=formula+"；伤害预览不保证击倒或获胜。";
            }
            boolean declarable=mayAttack(player)&&activeAttacks(player).contains(attack);
            if(!declarable)explanation="当前时机或效果限制不能宣告此招式。 "+explanation;
            if(!payable)explanation="当前无法支付能量费用。 "+explanation;
            output.add(new BattleGuidance.AttackPreview("field:"+source.pokemonId(),attack.nameZh(),cost,payable,
                exact?(payable&&declarable?"确定伤害":"条件伤害"):"不确定",damage,explanation));
        }
        return List.copyOf(output);
    }
    private void requireCombatConfigured() {
        if (battlefield == null) throw new IllegalStateException("本局没有已锁定的卡牌战斗数据，不能结算攻击");
    }
    private PlayerState state(UUID id) { PlayerState p = players.get(id); if (p == null) throw new IllegalArgumentException("玩家不在本局对战中"); return p; }
    private PlayerState other(UUID id) { return players.values().stream().filter(p -> !p.id.equals(id)).findFirst().orElseThrow(); }
    private CardDefinition definition(CardInstance card) { return definitions.find(card.definitionId()).orElseThrow(() -> new IllegalStateException("缺少卡牌定义: " + card.definitionId())); }
    private CardInstance cardInHand(PlayerState p, UUID id) { return p.hand.stream().filter(card -> card.instanceId().equals(id)).findFirst().orElseThrow(() -> new IllegalArgumentException("目标卡不在你的手牌中")); }
    private void requireTurn(UUID player) {
        require(pendingNativeCoinChoice==null,"请先选择一树的投币结果");
        if(!resolvingEffectProgram&&!advancingResolution&&!resolvingBenchOverflow)requireNoToolOverflow();
        boolean automatic=executingAutomaticTrigger();
        require(prizeEffectFrames.isEmpty()||automatic||resolvingEffectProgram||advancingResolution,"请先完成奖赏效果及其触发");
        require(phase==MatchPhase.TURN || (phase==MatchPhase.POKEMON_CHECKUP||phase==MatchPhase.TURN_END) && automatic,"当前步骤不允许普通回合操作："+phase);
        require(!hasPendingTurnDraw()||automatic,"请先完成回合开始抽牌的入手前选择");
        require(currentPlayer.equals(player) || automatic && pendingResolution.actor().equals(player), "尚未轮到你");
        require(attackCheckpoint==null || advancingResolution,"请先完成攻击及受伤触发结算");
        require(knockoutCheckpoint==null || automatic,"请先完成击倒触发结算");
        require(!endingResumableAttack || automatic, "请先完成攻击及其触发效果");
        require(!endingResumableCardTurn || automatic || advancingResolution || resolvingEffectProgram, "请先完成卡牌及其结束回合流程");
        require(!endingPromotionTurn || automatic, "请先完成攻击后的补位及其触发效果");
        require(triggerOrderPrompt == null || automatic, "请先完成触发特性的排序或确认");
        require(pendingResolution == null || advancingResolution, "请先完成当前卡牌的效果选择");
        require(pendingEnergyHandCost==null,"请先支付附能费用");
    }
    private void requirePhase(MatchPhase expected) { if (phase != expected) throw new IllegalStateException("当前步骤不允许此操作：" + phase); }
    private static void require(boolean condition, String message) { if (!condition) throw new IllegalStateException(message); }
    public int benchLimit() { return benchLimit(currentPlayer); }
    public int benchLimit(UUID owner) {
        int ordinary=ruleset.matchSetupRules().benchLimit();
        UUID opponent=other(owner).id;
        if(battlefield!=null&&battlefield.hasActive(opponent)) {
            UUID source=battlefield.printedActiveView(opponent).pokemonId();
            for(var ability:activeAbilities(opponent,source))if(ability.kind()==AbilityDefinition.Kind.PASSIVE&&ability.composed()
                &&dev.hua.ptcglive.engine.effect.PassiveRuleProgram.matches(ability.effectProgram(),new ServerConditionContext(opponent,source),
                    e->e.type().equals("bench_limit")&&e.target()==EffectTarget.OPPONENT_BENCH))ordinary=Math.min(ordinary,3);
        }
        var benchRule=stadiumPassiveRule("bench_limit");
        if(benchRule!=null&&(benchRule.target()==EffectTarget.SELF||stadiumScopeController().equals(owner))) {
            int limit=Integer.parseInt(benchRule.arguments().get("amount"));
            ordinary=benchRule.arguments().containsKey("leave_limit")&&ordinary>=ruleset.matchSetupRules().benchLimit()?limit:Math.min(ordinary,limit);
        }
        var rule=stadiumPassiveRule("tera_bench_expansion");
        if(rule==null)return ordinary;
        int normal=Integer.parseInt(rule.arguments().get("normal_limit"));
        int expanded=Integer.parseInt(rule.arguments().get("expanded_limit"));
        int expandedLimit=hasTeraPokemon(owner)?expanded:normal;
        return ordinary<ruleset.matchSetupRules().benchLimit()?Math.min(ordinary,expandedLimit):expandedLimit;
    }
    private boolean hasTeraPokemon(UUID owner) {
        return publicFieldTargets(owner).stream().anyMatch(view->fieldCardDefinition(battlefield.topCard(owner,view.pokemonId()).definitionId()).pokemonFamilies()
            .contains(dev.hua.ptcglive.rules.PokemonFamily.TERA));
    }
    private UUID fieldOwner(UUID pokemonId) {
        for(UUID owner:players.keySet())if(publicFieldTargets(owner).stream().anyMatch(p->p.pokemonId().equals(pokemonId)))return owner;
        throw new IllegalStateException("伤害目标已不在场上");
    }
    /** Shared live public-recipient predicate for the authoritative resolver and server-issued choices. */
    public boolean matchesAttackDamageTargetFilter(UUID owner, UUID pokemonId, AttackDefinition attack) {
        var target = battlefield.pokemonView(owner,pokemonId);
        int minimumCounters=attack.effectProgram().forTrigger(EffectTrigger.ON_ATTACK).stream()
            .flatMap(binding->binding.effects().stream())
            .filter(dev.hua.ptcglive.engine.effect.AttackTargetFilter::handles)
            .mapToInt(dev.hua.ptcglive.engine.effect.AttackTargetFilter::minimumDamageCounters).max().orElse(0);
        return target.damage()/10>=minimumCounters
            &&attack.targetFamilies().matches(fieldCardDefinition(target.topCardId()))
            && (!attack.targetHasSpecialEnergy() || battlefield.attachedEnergy(owner,target.pokemonId()).stream()
                .anyMatch(card -> !definition(card).basicEnergy()));
    }
    private List<BattlefieldState.PokemonView> resolveDamageTargets(UUID defender, AttackDefinition attack, List<UUID> requestedTargets,UUID attackerPokemonId) {
        requestedTargets = List.copyOf(requestedTargets == null ? List.of() : requestedTargets);
        if (attack.damageTarget() == AttackDefinition.DamageTarget.OPPONENT_ACTIVE) {
            var active = battlefield.activeView(defender);
            if (requestedTargets.size() > 1 || (requestedTargets.size() == 1 && !requestedTargets.getFirst().equals(active.pokemonId())))
                throw new IllegalArgumentException("此攻击只能指定对方战斗宝可梦");
            return List.of(active);
        }
        if (attack.damageTarget() == AttackDefinition.DamageTarget.ALL_OPPONENT_BENCH) {
            if (!requestedTargets.isEmpty()) throw new IllegalArgumentException("此攻击自动影响所有对方备战宝可梦，不能指定单一目标");
            return battlefield.benchView(defender);
        }
        if (attack.damageTarget().mixedTargets()) {
            var field = new ArrayList<BattlefieldState.PokemonView>();
            if (battlefield.hasActive(defender)) field.add(battlefield.activeView(defender));
            field.addAll(battlefield.benchView(defender));
            if(attack.damageTarget()==AttackDefinition.DamageTarget.ALL_POKEMON) {
                UUID own=other(defender).id;if(battlefield.hasActive(own))field.add(battlefield.activeView(own));
                field.addAll(battlefield.benchView(own));
            }
            field.removeIf(p->!matchesAttackDamageTargetFilter(fieldOwner(p.pokemonId()),p.pokemonId(),attack));
            if(attack.effectProgram().forTrigger(EffectTrigger.ON_ATTACK).stream().flatMap(b->b.effects().stream())
                .anyMatch(e->dev.hua.ptcglive.engine.effect.AttackTargetFilter.handles(e)&&"true".equals(e.arguments().get("exclude_attacker"))))
                field.removeIf(p->p.pokemonId().equals(attackerPokemonId));
            if (attack.damageTarget() == AttackDefinition.DamageTarget.ALL_OPPONENT_POKEMON || attack.damageTarget()==AttackDefinition.DamageTarget.ALL_POKEMON) {
                if (!requestedTargets.isEmpty()) throw new IllegalArgumentException("此攻击自动影响对方全部宝可梦，不能指定目标");
                return List.copyOf(field);
            }
            if(dev.hua.ptcglive.engine.effect.RepeatTargetDamage.handles(attack)) {
                dev.hua.ptcglive.engine.effect.RepeatTargetDamage.effect(attack);
                if(requestedTargets.size()!=attack.targetCount())throw new IllegalArgumentException("此攻击必须完成全部重复目标选择");
                var unique=new LinkedHashMap<UUID,BattlefieldState.PokemonView>();
                for(var target:requestedTargets)unique.putIfAbsent(target,field.stream().filter(pokemon->pokemon.pokemonId().equals(target)).findFirst()
                    .orElseThrow(()->new IllegalArgumentException("指定目标不是对方场上的宝可梦")));
                return List.copyOf(unique.values());
            }
            // With fewer Pokémon in play than printed, the attack hits as many as there are.
            int required = Math.min(attack.targetCount(), field.size());
            if (requestedTargets.size() != required) throw new IllegalArgumentException("此攻击必须选择 " + required + " 只不同的对方宝可梦");
            if (new java.util.LinkedHashSet<>(requestedTargets).size() != requestedTargets.size())
                throw new IllegalArgumentException("同一只宝可梦不能被重复选择");
            return requestedTargets.stream().map(target -> field.stream().filter(pokemon -> pokemon.pokemonId().equals(target)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("指定目标不是对方场上的宝可梦"))).toList();
        }
        var eligibleBench=battlefield.benchView(defender).stream()
            .filter(pokemon->matchesAttackDamageTargetFilter(defender,pokemon.pokemonId(),attack)).toList();
        int required=Math.min(attack.targetCount(),eligibleBench.size());
        if (requestedTargets.size() != required) throw new IllegalArgumentException("此攻击必须选择 " + required + " 只不同的对方备战宝可梦");
        if (new java.util.LinkedHashSet<>(requestedTargets).size() != requestedTargets.size())
            throw new IllegalArgumentException("同一只备战宝可梦不能被重复选择");
        return requestedTargets.stream().map(target -> eligibleBench.stream()
            .filter(pokemon -> pokemon.pokemonId().equals(target)).findFirst()
            .orElseThrow(() -> new IllegalArgumentException("指定目标不是符合招式条件的对方备战宝可梦"))).toList();
    }
    private boolean matchesOpposingActive(UUID actor,dev.hua.ptcglive.engine.effect.AttackDefenderFilter filter) {
        if(!filter.restricted())return true;
        UUID opponent=other(actor).id;
        if(!battlefield.hasActive(opponent))return false;
        var target=battlefield.printedActiveView(opponent);
        return filter.matches(currentFieldDefinition(opponent,target.pokemonId()),battlefield.pokemonProfile(opponent,target.pokemonId()));
    }
    private int playerTurnDamageReduction(UUID affectedPlayer,UUID pokemonId,UUID attackingPlayer) {
        if(affectedPlayer.equals(attackingPlayer)||!attackingPlayer.equals(currentPlayer))return 0;
        var target=battlefield.pokemonView(affectedPlayer,pokemonId);
        var attackingFacts=attackCheckpoint==null||attackCheckpoint.damageSource==null?null:attackCheckpoint.damageSource.facts();
        return state(affectedPlayer).damageReductions.stream()
            .filter(r->r.recipients().matches(currentFieldDefinition(affectedPlayer,pokemonId),battlefield.pokemonProfile(affectedPlayer,pokemonId)))
            .filter(r->r.attackers().equals(dev.hua.ptcglive.engine.effect.AttackSourceFilter.ANY)
                ||attackingFacts!=null&&r.attackers().matches(attackingFacts))
            .mapToInt(dev.hua.ptcglive.engine.effect.TurnDamageReduction::amount).sum();
    }
    private boolean playerTurnAttackBypass(UUID actor,UUID pokemonId) {
        if(!actor.equals(currentPlayer))return false;
        var card=currentFieldDefinition(actor,pokemonId);
        return state(actor).attackBypasses.stream().anyMatch(rule->rule.turn()==turnNumber&&rule.recipients().matches(card));
    }
    private int playerTurnAttackBonus(UUID actor,BattlefieldState.PokemonView attacker) {return playerTurnAttackBonus(actor,attacker,false);}
    private int playerTurnAttackBonus(UUID actor,BattlefieldState.PokemonView attacker,boolean ownTarget) {
        var opponent=other(actor);int taken=Math.max(0,opponent.initialPrizeCards-opponent.prizes.size());
        return state(actor).attackBonuses.stream().filter(b->b.turn()==turnNumber&&(!ownTarget||b.rule().includeOwnActive())&&b.rule().recipients().matches(fieldCardDefinition(attacker.topCardId()))
                &&(b.source()==null||b.source().equals(attacker.pokemonId())&&sameFieldEntry(actor,b.source(),b.sourceEntry()))
                &&b.rule().recipientTypes().matches(currentFieldDefinition(actor,attacker.pokemonId()),battlefield.pokemonProfile(actor,attacker.pokemonId()))
                &&(ownTarget||matchesOpposingActive(actor,b.rule().defenders())))
            .mapToInt(b->b.rule().amount()*(b.rule().perOpponentPrizeTaken()?taken:1)).sum();
    }
    private boolean playerHasAttackEffects(UUID owner) {
        var p=state(owner);
        return p.trainerLocks.stream().anyMatch(e->e.sourceKind()==EffectOrigin.Kind.ATTACK)
            ||p.specialEnergyHandLocked||p.trainerAttemptCoinGated||p.coinTailsNextTurn||p.coinTailsThisTurn
            ||p.attackEnergyMaximumLocks.containsKey(EffectOrigin.Kind.ATTACK)
            ||p.pendingOwnTurnAttackEnergyMaximumLocks.containsKey(EffectOrigin.Kind.ATTACK)
            ||p.fieldAttackProtections.stream().anyMatch(e->e.rule().sourceActiveBound())
            ||delayedPlayerEffects.values().stream().anyMatch(e->e.owner().equals(owner)&&e.origin().kind()==EffectOrigin.Kind.ATTACK);
    }
    private Set<UUID> attackEffectMarkers(UUID owner,UUID pokemon) {
        var tokens=new LinkedHashSet<UUID>();
        java.util.function.Predicate<PokemonCandidate> matches=c->c.target().owner().equals(owner)
            &&c.target().pokemonId().equals(pokemon)&&sameFieldEntry(owner,pokemon,c.entrySequence());
        delayedPokemonEffects.values().stream().filter(e->e.origin().kind()==EffectOrigin.Kind.ATTACK&&matches.test(e.target())).forEach(e->tokens.add(e.token()));
        pendingAttackKoProtections.values().stream().filter(e->matches.test(e.target())).forEach(e->tokens.add(e.token()));
        pendingNoPrizeKos.values().stream().filter(e->matches.test(e.target())).forEach(e->tokens.add(e.token()));
        pendingFullHpSurvivals.values().stream().filter(e->matches.test(e.target())).forEach(e->tokens.add(e.token()));
        pendingDefenderPrizes.values().stream().filter(e->matches.test(e.target())).forEach(e->tokens.add(e.token()));
        tokens.removeIf(token->!battlefield.hasDelayedMarker(owner,pokemon,token));
        return tokens;
    }
    private boolean hasAttackEnergyTrap(UUID owner,UUID pokemon) {
        return handEnergyCounterTraps.stream().anyMatch(e->e.targetOwner().equals(owner)&&e.pokemonId().equals(pokemon)
                &&e.origin().kind()==EffectOrigin.Kind.ATTACK&&sameFieldEntry(owner,pokemon,e.entry()))
            ||handEnergyEndTurnTraps.stream().anyMatch(e->e.targetOwner().equals(owner)&&e.pokemonId().equals(pokemon)
                &&e.origin().kind()==EffectOrigin.Kind.ATTACK&&sameFieldEntry(owner,pokemon,e.entry()));
    }
    private boolean attackEffectsRemovable(UUID actor,boolean both,EffectOrigin origin) {
        for(UUID owner:both?players.keySet():List.of(actor)) {
            if(playerHasAttackEffects(owner))return true;
            for(var target:publicFieldTargets(owner))if(!preventsImpact(owner,target.pokemonId(),origin,EffectProtection.Impact.OTHER_EFFECTS)
                &&(battlefield.hasAttackEffects(owner,target.pokemonId())||!attackEffectMarkers(owner,target.pokemonId()).isEmpty()
                    ||hasAttackEnergyTrap(owner,target.pokemonId())))return true;
        }
        return false;
    }
    private void removeAttackEffects(UUID actor,boolean both,EffectOrigin origin) {
        // Removal never rewinds actions, damage, Special Conditions, usage quotas or their historical records.
        // Freeze Trainer immunity before removing any effects that could themselves suppress a defending Ability.
        var targets=new ArrayList<EffectTargetResolution.PokemonTarget>();
        for(UUID owner:both?players.keySet():List.of(actor))for(var target:publicFieldTargets(owner))
            if(!preventsImpact(owner,target.pokemonId(),origin,EffectProtection.Impact.OTHER_EFFECTS))targets.add(target);
        for(UUID owner:both?players.keySet():List.of(actor)) {
            var p=state(owner);
            p.trainerLocks.removeIf(e->e.sourceKind()==EffectOrigin.Kind.ATTACK);
            p.specialEnergyHandLocked=false;p.trainerAttemptCoinGated=false;p.coinTailsNextTurn=false;p.coinTailsThisTurn=false;
            p.attackEnergyMaximumLocks.remove(EffectOrigin.Kind.ATTACK);p.pendingOwnTurnAttackEnergyMaximumLocks.remove(EffectOrigin.Kind.ATTACK);
            p.fieldAttackProtections.removeIf(e->e.rule().sourceActiveBound());
            delayedPlayerEffects.values().removeIf(e->e.owner().equals(owner)&&e.origin().kind()==EffectOrigin.Kind.ATTACK);
        }
        for(var target:targets) {
            UUID owner=target.owner(),pokemon=target.pokemonId();
            for(UUID token:attackEffectMarkers(owner,pokemon)) {
                delayedPokemonEffects.remove(token);pendingAttackKoProtections.remove(token);pendingNoPrizeKos.remove(token);
                pendingFullHpSurvivals.remove(token);pendingDefenderPrizes.remove(token);battlefield.removeDelayedMarker(owner,pokemon,token);
            }
            handEnergyCounterTraps.removeIf(e->e.targetOwner().equals(owner)&&e.pokemonId().equals(pokemon)&&e.origin().kind()==EffectOrigin.Kind.ATTACK);
            handEnergyEndTurnTraps.removeIf(e->e.targetOwner().equals(owner)&&e.pokemonId().equals(pokemon)&&e.origin().kind()==EffectOrigin.Kind.ATTACK);
            battlefield.removeAttackEffects(owner,pokemon);
        }
        recordReplay(actor,(both?"双方":"己方")+"玩家与场上宝可梦的招式效果全部消除");
    }
